window.LAW = {"previews": {"dpdp-act-2023:chp_I": {"cite": "DPDP Act Chapter I", "head": "PRELIMINARY", "text": "Short title and commencement This Act may be called the Digital Personal Data Protection Act, 2023. It shall come into force on such date as the Central Government may, by notification in the Official Gazette, appoint and different dates may be appointed for different provisions of this Act and any reference in any such provision to the commencement of this Act shall be construed as a reference to the coming into force of that provision. Definitions In this Act, unless the context otherwise requires,— “Appellate Tribunal” means the Telecom Disputes Settlement and Appellate Tribunal established…"}, "dpdp-act-2023:sec_1": {"cite": "DPDP Act s.1", "head": "Short title and commencement", "text": "This Act may be called the Digital Personal Data Protection Act, 2023. It shall come into force on such date as the Central Government may, by notification in the Official Gazette, appoint and different dates may be appointed for different provisions of this Act and any reference in any such provision to the commencement of this Act shall be construed as a reference to the coming into force of that provision."}, "dpdp-act-2023:sec_1__subsec_1": {"cite": "DPDP Act s.1(1)", "head": "", "text": "This Act may be called the Digital Personal Data Protection Act, 2023."}, "dpdp-act-2023:sec_1__subsec_2": {"cite": "DPDP Act s.1(2)", "head": "", "text": "It shall come into force on such date as the Central Government may, by notification in the Official Gazette, appoint and different dates may be appointed for different provisions of this Act and any reference in any such provision to the commencement of this Act shall be construed as a reference to the coming into force of that provision."}, "dpdp-act-2023:sec_2": {"cite": "DPDP Act s.2", "head": "Definitions", "text": "In this Act, unless the context otherwise requires,— “Appellate Tribunal” means the Telecom Disputes Settlement and Appellate Tribunal established under section 14 of the Telecom Regulatory Authority of India Act, 1997; “automated” means any digital process capable of operating automatically in response to instructions given or otherwise for the purpose of processing data; “Board” means the Data Protection Board of India established by the Central Government under section 18; “certain legitimate uses” means the uses referred to in section 7; “Chairperson” means the Chairperson of the Board; “c…"}, "dpdp-act-2023:sec_2__cl_a": {"cite": "DPDP Act s.2(a)", "head": "", "text": "“Appellate Tribunal” means the Telecom Disputes Settlement and Appellate Tribunal established under section 14 of the Telecom Regulatory Authority of India Act, 1997;"}, "dpdp-act-2023:sec_2__cl_b": {"cite": "DPDP Act s.2(b)", "head": "", "text": "“automated” means any digital process capable of operating automatically in response to instructions given or otherwise for the purpose of processing data;"}, "dpdp-act-2023:sec_2__cl_c": {"cite": "DPDP Act s.2(c)", "head": "", "text": "“Board” means the Data Protection Board of India established by the Central Government under section 18;"}, "dpdp-act-2023:sec_2__cl_d": {"cite": "DPDP Act s.2(d)", "head": "", "text": "“certain legitimate uses” means the uses referred to in section 7;"}, "dpdp-act-2023:sec_2__cl_e": {"cite": "DPDP Act s.2(e)", "head": "", "text": "“Chairperson” means the Chairperson of the Board;"}, "dpdp-act-2023:sec_2__cl_f": {"cite": "DPDP Act s.2(f)", "head": "", "text": "“child” means an individual who has not completed the age of eighteen years;"}, "dpdp-act-2023:sec_2__cl_g": {"cite": "DPDP Act s.2(g)", "head": "", "text": "“Consent Manager” means a person registered with the Board, who acts as a single point of contact to enable a Data Principal to give, manage, review and withdraw her consent through an accessible, transparent and interoperable platform;"}, "dpdp-act-2023:sec_2__cl_h": {"cite": "DPDP Act s.2(h)", "head": "", "text": "“data” means a representation of information, facts, concepts, opinions or instructions in a manner suitable for communication, interpretation or processing by human beings or by automated means;"}, "dpdp-act-2023:sec_2__cl_i": {"cite": "DPDP Act s.2(i)", "head": "", "text": "“Data Fiduciary” means any person who alone or in conjunction with other persons determines the purpose and means of processing of personal data;"}, "dpdp-act-2023:sec_2__cl_j": {"cite": "DPDP Act s.2(j)", "head": "", "text": "“Data Principal” means the individual to whom the personal data relates and where such individual is— a child, includes the parents or lawful guardian of such a child; a person with disability, includes her lawful guardian, acting on her behalf;"}, "dpdp-act-2023:sec_2__cl_j__subcl_i": {"cite": "DPDP Act s.2(j)(i)", "head": "", "text": "a child, includes the parents or lawful guardian of such a child;"}, "dpdp-act-2023:sec_2__cl_j__subcl_ii": {"cite": "DPDP Act s.2(j)(ii)", "head": "", "text": "a person with disability, includes her lawful guardian, acting on her behalf;"}, "dpdp-act-2023:sec_2__cl_k": {"cite": "DPDP Act s.2(k)", "head": "", "text": "“Data Processor” means any person who processes personal data on behalf of a Data Fiduciary;"}, "dpdp-act-2023:sec_2__cl_l": {"cite": "DPDP Act s.2(l)", "head": "", "text": "“Data Protection Officer” means an individual appointed by the Significant Data Fiduciary under clause (a) of sub-section (2) of section 10;"}, "dpdp-act-2023:sec_2__cl_m": {"cite": "DPDP Act s.2(m)", "head": "", "text": "“digital office” means an office that adopts an online mechanism wherein the proceedings, from receipt of intimation or complaint or reference or directions or appeal, as the case may be, to the disposal thereof, are conducted in online or digital mode;"}, "dpdp-act-2023:sec_2__cl_n": {"cite": "DPDP Act s.2(n)", "head": "", "text": "“digital personal data” means personal data in digital form;"}, "dpdp-act-2023:sec_2__cl_o": {"cite": "DPDP Act s.2(o)", "head": "", "text": "“gain” means— a gain in property or supply of services, whether temporary or permanent; or an opportunity to earn remuneration or greater remuneration or to gain a financial advantage otherwise than by way of legitimate remuneration;"}, "dpdp-act-2023:sec_2__cl_o__subcl_i": {"cite": "DPDP Act s.2(o)(i)", "head": "", "text": "a gain in property or supply of services, whether temporary or permanent; or"}, "dpdp-act-2023:sec_2__cl_o__subcl_ii": {"cite": "DPDP Act s.2(o)(ii)", "head": "", "text": "an opportunity to earn remuneration or greater remuneration or to gain a financial advantage otherwise than by way of legitimate remuneration;"}, "dpdp-act-2023:sec_2__cl_p": {"cite": "DPDP Act s.2(p)", "head": "", "text": "“loss” means— a loss in property or interruption in supply of services, whether temporary or permanent; or a loss of opportunity to earn remuneration or greater remuneration or to gain a financial advantage otherwise than by way of legitimate remuneration;"}, "dpdp-act-2023:sec_2__cl_p__subcl_i": {"cite": "DPDP Act s.2(p)(i)", "head": "", "text": "a loss in property or interruption in supply of services, whether temporary or permanent; or"}, "dpdp-act-2023:sec_2__cl_p__subcl_ii": {"cite": "DPDP Act s.2(p)(ii)", "head": "", "text": "a loss of opportunity to earn remuneration or greater remuneration or to gain a financial advantage otherwise than by way of legitimate remuneration;"}, "dpdp-act-2023:sec_2__cl_q": {"cite": "DPDP Act s.2(q)", "head": "", "text": "“Member” means a Member of the Board and includes the Chairperson;"}, "dpdp-act-2023:sec_2__cl_r": {"cite": "DPDP Act s.2(r)", "head": "", "text": "“notification” means a notification published in the Official Gazette and the expressions “notify” and “notified” shall be construed accordingly;"}, "dpdp-act-2023:sec_2__cl_s": {"cite": "DPDP Act s.2(s)", "head": "", "text": "“person” includes— an individual; a Hindu undivided family; a company; a firm; an association of persons or a body of individuals, whether incorporated or not; the State; and every artificial juristic person, not falling within any of the preceding sub-clauses;"}, "dpdp-act-2023:sec_2__cl_s__subcl_i": {"cite": "DPDP Act s.2(s)(i)", "head": "", "text": "an individual;"}, "dpdp-act-2023:sec_2__cl_s__subcl_ii": {"cite": "DPDP Act s.2(s)(ii)", "head": "", "text": "a Hindu undivided family;"}, "dpdp-act-2023:sec_2__cl_s__subcl_iii": {"cite": "DPDP Act s.2(s)(iii)", "head": "", "text": "a company;"}, "dpdp-act-2023:sec_2__cl_s__subcl_iv": {"cite": "DPDP Act s.2(s)(iv)", "head": "", "text": "a firm;"}, "dpdp-act-2023:sec_2__cl_s__subcl_v": {"cite": "DPDP Act s.2(s)(v)", "head": "", "text": "an association of persons or a body of individuals, whether incorporated or not;"}, "dpdp-act-2023:sec_2__cl_s__subcl_vi": {"cite": "DPDP Act s.2(s)(vi)", "head": "", "text": "the State; and"}, "dpdp-act-2023:sec_2__cl_s__subcl_vii": {"cite": "DPDP Act s.2(s)(vii)", "head": "", "text": "every artificial juristic person, not falling within any of the preceding sub-clauses;"}, "dpdp-act-2023:sec_2__cl_t": {"cite": "DPDP Act s.2(t)", "head": "", "text": "“personal data” means any data about an individual who is identifiable by or in relation to such data;"}, "dpdp-act-2023:sec_2__cl_u": {"cite": "DPDP Act s.2(u)", "head": "", "text": "“personal data breach” means any unauthorised processing of personal data or accidental disclosure, acquisition, sharing, use, alteration, destruction or loss of access to personal data, that compromises the confidentiality, integrity or availability of personal data;"}, "dpdp-act-2023:sec_2__cl_v": {"cite": "DPDP Act s.2(v)", "head": "", "text": "“prescribed” means prescribed by rules made under this Act;"}, "dpdp-act-2023:sec_2__cl_w": {"cite": "DPDP Act s.2(w)", "head": "", "text": "“proceeding” means any action taken by the Board under the provisions of this Act;"}, "dpdp-act-2023:sec_2__cl_x": {"cite": "DPDP Act s.2(x)", "head": "", "text": "“processing” in relation to personal data, means a wholly or partly automated operation or set of operations performed on digital personal data, and includes operations such as collection, recording, organisation, structuring, storage, adaptation, retrieval, use, alignment or combination, indexing, sharing, disclosure by transmission, dissemination or otherwise making available, restriction, erasure or destruction;"}, "dpdp-act-2023:sec_2__cl_y": {"cite": "DPDP Act s.2(y)", "head": "", "text": "“she” in relation to an individual includes the reference to such individual irrespective of gender;"}, "dpdp-act-2023:sec_2__cl_z": {"cite": "DPDP Act s.2(z)", "head": "", "text": "“Significant Data Fiduciary” means any Data Fiduciary or class of Data Fiduciaries as may be notified by the Central Government under section 10;"}, "dpdp-act-2023:sec_2__cl_za": {"cite": "DPDP Act s.2(za)", "head": "", "text": "“specified purpose” means the purpose mentioned in the notice given by the Data Fiduciary to the Data Principal in accordance with the provisions of this Act and the rules made thereunder; and"}, "dpdp-act-2023:sec_2__cl_zb": {"cite": "DPDP Act s.2(zb)", "head": "", "text": "“State” means the State as defined under article 12 of the Constitution."}, "dpdp-act-2023:sec_3": {"cite": "DPDP Act s.3", "head": "Application of Act", "text": "Subject to the provisions of this Act, it shall— apply to the processing of digital personal data within the territory of India where the personal data is collected–– in digital form; or in non-digital form and digitised subsequently; also apply to processing of digital personal data outside the territory of India, if such processing is in connection with any activity related to offering of goods or services to Data Principals within the territory of India; not apply to— personal data processed by an individual for any personal or domestic purpose; and personal data that is made or caused to b…"}, "dpdp-act-2023:sec_3__cl_a": {"cite": "DPDP Act s.3(a)", "head": "", "text": "apply to the processing of digital personal data within the territory of India where the personal data is collected–– in digital form; or in non-digital form and digitised subsequently;"}, "dpdp-act-2023:sec_3__cl_a__subcl_i": {"cite": "DPDP Act s.3(a)(i)", "head": "", "text": "in digital form; or"}, "dpdp-act-2023:sec_3__cl_a__subcl_ii": {"cite": "DPDP Act s.3(a)(ii)", "head": "", "text": "in non-digital form and digitised subsequently;"}, "dpdp-act-2023:sec_3__cl_b": {"cite": "DPDP Act s.3(b)", "head": "", "text": "also apply to processing of digital personal data outside the territory of India, if such processing is in connection with any activity related to offering of goods or services to Data Principals within the territory of India;"}, "dpdp-act-2023:sec_3__cl_c": {"cite": "DPDP Act s.3(c)", "head": "", "text": "not apply to— personal data processed by an individual for any personal or domestic purpose; and personal data that is made or caused to be made publicly available by— the Data Principal to whom such personal data relates; or any other person who is under an obligation under any law for the time being in force in India to make such personal data publicly available. Illustration X, an individual, while blogging her views, has publicly made available her personal data on social media. In such case, the provisions of this Act shall not apply."}, "dpdp-act-2023:sec_3__cl_c__subcl_i": {"cite": "DPDP Act s.3(c)(i)", "head": "", "text": "personal data processed by an individual for any personal or domestic purpose; and"}, "dpdp-act-2023:sec_3__cl_c__subcl_ii": {"cite": "DPDP Act s.3(c)(ii)", "head": "", "text": "personal data that is made or caused to be made publicly available by— the Data Principal to whom such personal data relates; or any other person who is under an obligation under any law for the time being in force in India to make such personal data publicly available. Illustration X, an individual, while blogging her views, has publicly made available her personal data on social media. In such case, the provisions of this Act shall not apply."}, "dpdp-act-2023:sec_3__cl_c__subcl_ii__point_A": {"cite": "DPDP Act s.3(c)(ii)(A)", "head": "", "text": "the Data Principal to whom such personal data relates; or"}, "dpdp-act-2023:sec_3__cl_c__subcl_ii__point_B": {"cite": "DPDP Act s.3(c)(ii)(B)", "head": "", "text": "any other person who is under an obligation under any law for the time being in force in India to make such personal data publicly available. Illustration X, an individual, while blogging her views, has publicly made available her personal data on social media. In such case, the provisions of this Act shall not apply."}, "dpdp-act-2023:sec_3__cl_c__subcl_ii__point_B__hcontainer_1": {"cite": "DPDP Act s.3(c)(ii)(B)", "head": "Illustration", "text": "X, an individual, while blogging her views, has publicly made available her personal data on social media. In such case, the provisions of this Act shall not apply."}, "dpdp-act-2023:chp_II": {"cite": "DPDP Act Chapter II", "head": "OBLIGATIONS OF DATA FIDUCIARY", "text": "Grounds for processing personal data A person may process the personal data of a Data Principal only in accordance with the provisions of this Act and for a lawful purpose,— for which the Data Principal has given her consent; or for certain legitimate uses. For the purposes of this section, the expression “lawful purpose” means any purpose which is not expressly forbidden by law. Notice Every request made to a Data Principal under section 6 for consent shall be accompanied or preceded by a notice given by the Data Fiduciary to the Data Principal, informing her,— the personal data and the purpo…"}, "dpdp-act-2023:sec_4": {"cite": "DPDP Act s.4", "head": "Grounds for processing personal data", "text": "A person may process the personal data of a Data Principal only in accordance with the provisions of this Act and for a lawful purpose,— for which the Data Principal has given her consent; or for certain legitimate uses. For the purposes of this section, the expression “lawful purpose” means any purpose which is not expressly forbidden by law."}, "dpdp-act-2023:sec_4__subsec_1": {"cite": "DPDP Act s.4(1)", "head": "", "text": "A person may process the personal data of a Data Principal only in accordance with the provisions of this Act and for a lawful purpose,— for which the Data Principal has given her consent; or for certain legitimate uses."}, "dpdp-act-2023:sec_4__subsec_1__cl_a": {"cite": "DPDP Act s.4(1)(a)", "head": "", "text": "for which the Data Principal has given her consent; or"}, "dpdp-act-2023:sec_4__subsec_1__cl_b": {"cite": "DPDP Act s.4(1)(b)", "head": "", "text": "for certain legitimate uses."}, "dpdp-act-2023:sec_4__subsec_2": {"cite": "DPDP Act s.4(2)", "head": "", "text": "For the purposes of this section, the expression “lawful purpose” means any purpose which is not expressly forbidden by law."}, "dpdp-act-2023:sec_5": {"cite": "DPDP Act s.5", "head": "Notice", "text": "Every request made to a Data Principal under section 6 for consent shall be accompanied or preceded by a notice given by the Data Fiduciary to the Data Principal, informing her,— the personal data and the purpose for which the same is proposed to be processed; the manner in which she may exercise her rights under sub-section (4) of section 6 and section 13; and the manner in which the Data Principal may make a complaint to the Board, in such manner and as may be prescribed. Illustration X, an individual, opens a bank account using the mobile app or website of Y, a bank. To complete the Know-Yo…"}, "dpdp-act-2023:sec_5__subsec_1": {"cite": "DPDP Act s.5(1)", "head": "", "text": "Every request made to a Data Principal under section 6 for consent shall be accompanied or preceded by a notice given by the Data Fiduciary to the Data Principal, informing her,— the personal data and the purpose for which the same is proposed to be processed; the manner in which she may exercise her rights under sub-section (4) of section 6 and section 13; and the manner in which the Data Principal may make a complaint to the Board, in such manner and as may be prescribed. Illustration X, an individual, opens a bank account using the mobile app or website of Y, a bank. To complete the Know-Yo…"}, "dpdp-act-2023:sec_5__subsec_1__subcl_i": {"cite": "DPDP Act s.5(1)(i)", "head": "", "text": "the personal data and the purpose for which the same is proposed to be processed;"}, "dpdp-act-2023:sec_5__subsec_1__subcl_ii": {"cite": "DPDP Act s.5(1)(ii)", "head": "", "text": "the manner in which she may exercise her rights under sub-section (4) of section 6 and section 13; and"}, "dpdp-act-2023:sec_5__subsec_1__subcl_iii": {"cite": "DPDP Act s.5(1)(iii)", "head": "", "text": "the manner in which the Data Principal may make a complaint to the Board,"}, "dpdp-act-2023:sec_5__subsec_1__wrap_1": {"cite": "DPDP Act s.5(1)", "head": "", "text": "in such manner and as may be prescribed."}, "dpdp-act-2023:sec_5__subsec_1__hcontainer_1": {"cite": "DPDP Act s.5(1)", "head": "Illustration", "text": "X, an individual, opens a bank account using the mobile app or website of Y, a bank. To complete the Know-Your-Customer requirements under law for opening of bank account, X opts for processing of her personal data by Y in a live, video-based customer identification process. Y shall accompany or precede the request for the personal data with notice to X, describing the personal data and the purpose of its processing."}, "dpdp-act-2023:sec_5__subsec_2": {"cite": "DPDP Act s.5(2)", "head": "", "text": "Where a Data Principal has given her consent for the processing of her personal data before the date of commencement of this Act,— the Data Fiduciary shall, as soon as it is reasonably practicable, give to the Data Principal a notice informing her,–– the personal data and the purpose for which the same has been processed; the manner in which she may exercise her rights under sub-section (4) of section 6 and section 13; and the manner in which the Data Principal may make a complaint to the Board, in such manner and as may be prescribed. the Data Fiduciary may continue to process the personal da…"}, "dpdp-act-2023:sec_5__subsec_2__cl_a": {"cite": "DPDP Act s.5(2)(a)", "head": "", "text": "the Data Fiduciary shall, as soon as it is reasonably practicable, give to the Data Principal a notice informing her,–– the personal data and the purpose for which the same has been processed; the manner in which she may exercise her rights under sub-section (4) of section 6 and section 13; and the manner in which the Data Principal may make a complaint to the Board, in such manner and as may be prescribed."}, "dpdp-act-2023:sec_5__subsec_2__cl_a__subcl_i": {"cite": "DPDP Act s.5(2)(a)(i)", "head": "", "text": "the personal data and the purpose for which the same has been processed;"}, "dpdp-act-2023:sec_5__subsec_2__cl_a__subcl_ii": {"cite": "DPDP Act s.5(2)(a)(ii)", "head": "", "text": "the manner in which she may exercise her rights under sub-section (4) of section 6 and section 13; and"}, "dpdp-act-2023:sec_5__subsec_2__cl_a__subcl_iii": {"cite": "DPDP Act s.5(2)(a)(iii)", "head": "", "text": "the manner in which the Data Principal may make a complaint to the Board,"}, "dpdp-act-2023:sec_5__subsec_2__cl_b": {"cite": "DPDP Act s.5(2)(b)", "head": "", "text": "the Data Fiduciary may continue to process the personal data until and unless the Data Principal withdraws her consent. Illustration X, an individual, gave her consent to the processing of her personal data for an online shopping app or website operated by Y, an e-commerce service provider, before the commencement of this Act. Upon commencement of the Act, Y shall, as soon as practicable, give through email, in-app notification or other effective method information to X, describing the personal data and the purpose of its processing."}, "dpdp-act-2023:sec_5__subsec_2__cl_b__hcontainer_1": {"cite": "DPDP Act s.5(2)(b)", "head": "Illustration", "text": "X, an individual, gave her consent to the processing of her personal data for an online shopping app or website operated by Y, an e-commerce service provider, before the commencement of this Act. Upon commencement of the Act, Y shall, as soon as practicable, give through email, in-app notification or other effective method information to X, describing the personal data and the purpose of its processing."}, "dpdp-act-2023:sec_5__subsec_3": {"cite": "DPDP Act s.5(3)", "head": "", "text": "The Data Fiduciary shall give the Data Principal the option to access the contents of the notice referred to in sub-sections (1) and (2) in English or any language specified in the Eighth Schedule to the Constitution."}, "dpdp-act-2023:sec_6": {"cite": "DPDP Act s.6", "head": "Consent", "text": "The consent given by the Data Principal shall be free, specific, informed, unconditional and unambiguous with a clear affirmative action, and shall signify an agreement to the processing of her personal data for the specified purpose and be limited to such personal data as is necessary for such specified purpose. Illustration X, an individual, downloads Y, a telemedicine app. Y requests the consent of X for (i) the processing of her personal data for making available telemedicine services, and (ii) accessing her mobile phone contact list, and X signifies her consent to both. Since phone contac…"}, "dpdp-act-2023:sec_6__subsec_1": {"cite": "DPDP Act s.6(1)", "head": "", "text": "The consent given by the Data Principal shall be free, specific, informed, unconditional and unambiguous with a clear affirmative action, and shall signify an agreement to the processing of her personal data for the specified purpose and be limited to such personal data as is necessary for such specified purpose. Illustration X, an individual, downloads Y, a telemedicine app. Y requests the consent of X for (i) the processing of her personal data for making available telemedicine services, and (ii) accessing her mobile phone contact list, and X signifies her consent to both. Since phone contac…"}, "dpdp-act-2023:sec_6__subsec_1__hcontainer_1": {"cite": "DPDP Act s.6(1)", "head": "Illustration", "text": "X, an individual, downloads Y, a telemedicine app. Y requests the consent of X for (i) the processing of her personal data for making available telemedicine services, and (ii) accessing her mobile phone contact list, and X signifies her consent to both. Since phone contact list is not necessary for making available telemedicine services, her consent shall be limited to the processing of her personal data for making available telemedicine services."}, "dpdp-act-2023:sec_6__subsec_2": {"cite": "DPDP Act s.6(2)", "head": "", "text": "Any part of consent referred in sub-section (1) which constitutes an infringement of the provisions of this Act or the rules made thereunder or any other law for the time being in force shall be invalid to the extent of such infringement. Illustration X, an individual, buys an insurance policy using the mobile app or website of Y, an insurer. She gives to Y her consent for (i) the processing of her personal data by Y for the purpose of issuing the policy, and (ii) waiving her right to file a complaint to the Data Protection Board of India. Part (ii) of the consent, relating to waiver of her ri…"}, "dpdp-act-2023:sec_6__subsec_2__hcontainer_1": {"cite": "DPDP Act s.6(2)", "head": "Illustration", "text": "X, an individual, buys an insurance policy using the mobile app or website of Y, an insurer. She gives to Y her consent for (i) the processing of her personal data by Y for the purpose of issuing the policy, and (ii) waiving her right to file a complaint to the Data Protection Board of India. Part (ii) of the consent, relating to waiver of her right to file a complaint, shall be invalid."}, "dpdp-act-2023:sec_6__subsec_3": {"cite": "DPDP Act s.6(3)", "head": "", "text": "Every request for consent under the provisions of this Act or the rules made thereunder shall be presented to the Data Principal in a clear and plain language, giving her the option to access such request in English or any language specified in the Eighth Schedule to the Constitution and providing the contact details of a Data Protection Officer, where applicable, or of any other person authorised by the Data Fiduciary to respond to any communication from the Data Principal for the purpose of exercise of her rights under the provisions of this Act."}, "dpdp-act-2023:sec_6__subsec_4": {"cite": "DPDP Act s.6(4)", "head": "", "text": "Where consent given by the Data Principal is the basis of processing of personal data, such Data Principal shall have the right to withdraw her consent at any time, with the ease of doing so being comparable to the ease with which such consent was given."}, "dpdp-act-2023:sec_6__subsec_5": {"cite": "DPDP Act s.6(5)", "head": "", "text": "The consequences of the withdrawal referred to in sub-section (4) shall be borne by the Data Principal, and such withdrawal shall not affect the legality of processing of the personal data based on consent before its withdrawal. Illustration X, an individual, is the user of an online shopping app or website operated by Y, an e-commerce service provider. X consents to the processing of her personal data by Y for the purpose of fulfilling her supply order and places an order for supply of a good while making payment for the same. If X withdraws her consent, Y may stop enabling X to use the app o…"}, "dpdp-act-2023:sec_6__subsec_5__hcontainer_1": {"cite": "DPDP Act s.6(5)", "head": "Illustration", "text": "X, an individual, is the user of an online shopping app or website operated by Y, an e-commerce service provider. X consents to the processing of her personal data by Y for the purpose of fulfilling her supply order and places an order for supply of a good while making payment for the same. If X withdraws her consent, Y may stop enabling X to use the app or website for placing orders, but may not stop the processing for supply of the goods already ordered and paid for by X."}, "dpdp-act-2023:sec_6__subsec_6": {"cite": "DPDP Act s.6(6)", "head": "", "text": "If a Data Principal withdraws her consent to the processing of personal data under sub-section (5), the Data Fiduciary shall, within a reasonable time, cease and cause its Data Processors to cease processing the personal data of such Data Principal unless such processing without her consent is required or authorised under the provisions of this Act or the rules made thereunder or any other law for the time being in force in India. Illustration X, a telecom service provider, enters into a contract with Y, a Data Processor, for emailing telephone bills to the customers of X. Z, a customer of X, …"}, "dpdp-act-2023:sec_6__subsec_6__hcontainer_1": {"cite": "DPDP Act s.6(6)", "head": "Illustration", "text": "X, a telecom service provider, enters into a contract with Y, a Data Processor, for emailing telephone bills to the customers of X. Z, a customer of X, who had earlier given her consent to X for the processing of her personal data for emailing of bills, downloads the mobile app of X and opts to receive bills only on the app. X shall itself cease, and shall cause Y to cease, the processing of the personal data of Z for emailing bills."}, "dpdp-act-2023:sec_6__subsec_7": {"cite": "DPDP Act s.6(7)", "head": "", "text": "The Data Principal may give, manage, review or withdraw her consent to the Data Fiduciary through a Consent Manager."}, "dpdp-act-2023:sec_6__subsec_8": {"cite": "DPDP Act s.6(8)", "head": "", "text": "The Consent Manager shall be accountable to the Data Principal and shall act on her behalf in such manner and subject to such obligations as may be prescribed."}, "dpdp-act-2023:sec_6__subsec_9": {"cite": "DPDP Act s.6(9)", "head": "", "text": "Every Consent Manager shall be registered with the Board in such manner and subject to such technical, operational, financial and other conditions as may be prescribed."}, "dpdp-act-2023:sec_6__subsec_10": {"cite": "DPDP Act s.6(10)", "head": "", "text": "Where a consent given by the Data Principal is the basis of processing of personal data and a question arises in this regard in a proceeding, the Data Fiduciary shall be obliged to prove that a notice was given by her to the Data Principal and consent was given by such Data Principal to the Data Fiduciary in accordance with the provisions of this Act and the rules made thereunder."}, "dpdp-act-2023:sec_7": {"cite": "DPDP Act s.7", "head": "Certain legitimate uses", "text": "A Data Fiduciary may process personal data of a Data Principal for any of following uses, namely:— for the specified purpose for which the Data Principal has voluntarily provided her personal data to the Data Fiduciary, and in respect of which she has not indicated to the Data Fiduciary that she does not consent to the use of her personal data. Illustrations (I) X, an individual, makes a purchase at Y, a pharmacy. She voluntarily provides Y her personal data and requests Y to acknowledge receipt of the payment made for the purchase by sending a message to her mobile phone. Y may process the pe…"}, "dpdp-act-2023:sec_7__cl_a": {"cite": "DPDP Act s.7(a)", "head": "", "text": "for the specified purpose for which the Data Principal has voluntarily provided her personal data to the Data Fiduciary, and in respect of which she has not indicated to the Data Fiduciary that she does not consent to the use of her personal data. Illustrations (I) X, an individual, makes a purchase at Y, a pharmacy. She voluntarily provides Y her personal data and requests Y to acknowledge receipt of the payment made for the purchase by sending a message to her mobile phone. Y may process the personal data of X for the purpose of sending the receipt. (II) X, an individual, electronically mess…"}, "dpdp-act-2023:sec_7__cl_a__hcontainer_1": {"cite": "DPDP Act s.7(a)", "head": "Illustrations", "text": "(I) X, an individual, makes a purchase at Y, a pharmacy. She voluntarily provides Y her personal data and requests Y to acknowledge receipt of the payment made for the purchase by sending a message to her mobile phone. Y may process the personal data of X for the purpose of sending the receipt. (II) X, an individual, electronically messages Y, a real estate broker, requesting Y to help identify a suitable rented accommodation for her and shares her personal data for this purpose. Y may process her personal data to identify and intimate to her the details of accommodation available on rent. Sub…"}, "dpdp-act-2023:sec_7__cl_b": {"cite": "DPDP Act s.7(b)", "head": "", "text": "for the State and any of its instrumentalities to provide or issue to the Data Principal such subsidy, benefit, service, certificate, licence or permit as may be prescribed, where–– she has previously consented to the processing of her personal data by the State or any of its instrumentalities for any subsidy, benefit, service, certificate, licence or permit; or such personal data is available in digital form in, or in non-digital form and digitised subsequently from, any database, register, book or other document which is maintained by the State or any of its instrumentalities and is notified…"}, "dpdp-act-2023:sec_7__cl_b__subcl_i": {"cite": "DPDP Act s.7(b)(i)", "head": "", "text": "she has previously consented to the processing of her personal data by the State or any of its instrumentalities for any subsidy, benefit, service, certificate, licence or permit; or"}, "dpdp-act-2023:sec_7__cl_b__subcl_ii": {"cite": "DPDP Act s.7(b)(ii)", "head": "", "text": "such personal data is available in digital form in, or in non-digital form and digitised subsequently from, any database, register, book or other document which is maintained by the State or any of its instrumentalities and is notified by the Central Government,"}, "dpdp-act-2023:sec_7__cl_b__wrap_1": {"cite": "DPDP Act s.7(b)", "head": "", "text": "subject to standards followed for processing being in accordance with the policy issued by the Central Government or any law for the time being in force for governance of personal data."}, "dpdp-act-2023:sec_7__cl_b__hcontainer_1": {"cite": "DPDP Act s.7(b)", "head": "Illustration", "text": "X. a pregnant woman, enrols herself on an app or website to avail of government’s maternity benefits programme, while consenting to provide her personal data for the purpose of availing of such benefits. Government may process the personal data of X processing to determine her eligibility to receive any other prescribed benefit from the government;"}, "dpdp-act-2023:sec_7__cl_c": {"cite": "DPDP Act s.7(c)", "head": "", "text": "for the performance by the State or any of its instrumentalities of any function under any law for the time being in force in India or in the interest of sovereignty and integrity of India or security of the State;"}, "dpdp-act-2023:sec_7__cl_d": {"cite": "DPDP Act s.7(d)", "head": "", "text": "for fulfilling any obligation under any law for the time being in force in India on any person to disclose any information to the State or any of its instrumentalities, subject to such processing being in accordance with the provisions regarding disclosure of such information in any other law for the time being in force;"}, "dpdp-act-2023:sec_7__cl_e": {"cite": "DPDP Act s.7(e)", "head": "", "text": "for compliance with any judgment or decree or order issued under any law for the time being in force in India, or any judgment or order relating to claims of a contractual or civil nature under any law for the time being in force outside India;"}, "dpdp-act-2023:sec_7__cl_f": {"cite": "DPDP Act s.7(f)", "head": "", "text": "for responding to a medical emergency involving a threat to the life or immediate threat to the health of the Data Principal or any other individual;"}, "dpdp-act-2023:sec_7__cl_g": {"cite": "DPDP Act s.7(g)", "head": "", "text": "for taking measures to provide medical treatment or health services to any individual during an epidemic, outbreak of disease, or any other threat to public health;"}, "dpdp-act-2023:sec_7__cl_h": {"cite": "DPDP Act s.7(h)", "head": "", "text": "for taking measures to ensure safety of, or provide assistance or services to, any individual during any disaster, or any breakdown of public order. For the purposes of this clause, the expression “disaster” shall have the same meaning as assigned to it in clause (d) of section 2 of the Disaster Management Act, 2005; or"}, "dpdp-act-2023:sec_7__cl_h__hcontainer_1": {"cite": "DPDP Act s.7(h)", "head": "", "text": "For the purposes of this clause, the expression “disaster” shall have the same meaning as assigned to it in clause (d) of section 2 of the Disaster Management Act, 2005; or"}, "dpdp-act-2023:sec_7__cl_i": {"cite": "DPDP Act s.7(i)", "head": "", "text": "for the purposes of employment or those related to safeguarding the employer from loss or liability, such as prevention of corporate espionage, maintenance of confidentiality of trade secrets, intellectual property, classified information or provision of any service or benefit sought by a Data Principal who is an employee."}, "dpdp-act-2023:sec_8": {"cite": "DPDP Act s.8", "head": "General obligations of Data Fiduciary", "text": "A Data Fiduciary shall, irrespective of any agreement to the contrary or failure of a Data Principal to carry out the duties provided under this Act, be responsible for complying with the provisions of this Act and the rules made thereunder in respect of any processing undertaken by it or on its behalf by a Data Processor. A Data Fiduciary may engage, appoint, use or otherwise involve a Data Processor to process personal data on its behalf for any activity related to offering of goods or services to Data Principals only under a valid contract. Where personal data processed by a Data Fiduciary …"}, "dpdp-act-2023:sec_8__subsec_1": {"cite": "DPDP Act s.8(1)", "head": "", "text": "A Data Fiduciary shall, irrespective of any agreement to the contrary or failure of a Data Principal to carry out the duties provided under this Act, be responsible for complying with the provisions of this Act and the rules made thereunder in respect of any processing undertaken by it or on its behalf by a Data Processor."}, "dpdp-act-2023:sec_8__subsec_2": {"cite": "DPDP Act s.8(2)", "head": "", "text": "A Data Fiduciary may engage, appoint, use or otherwise involve a Data Processor to process personal data on its behalf for any activity related to offering of goods or services to Data Principals only under a valid contract."}, "dpdp-act-2023:sec_8__subsec_3": {"cite": "DPDP Act s.8(3)", "head": "", "text": "Where personal data processed by a Data Fiduciary is likely to be— used to make a decision that affects the Data Principal; or disclosed to another Data Fiduciary, the Data Fiduciary processing such personal data shall ensure its completeness, accuracy and consistency."}, "dpdp-act-2023:sec_8__subsec_3__cl_a": {"cite": "DPDP Act s.8(3)(a)", "head": "", "text": "used to make a decision that affects the Data Principal; or"}, "dpdp-act-2023:sec_8__subsec_3__cl_b": {"cite": "DPDP Act s.8(3)(b)", "head": "", "text": "disclosed to another Data Fiduciary,"}, "dpdp-act-2023:sec_8__subsec_4": {"cite": "DPDP Act s.8(4)", "head": "", "text": "A Data Fiduciary shall implement appropriate technical and organisational measures to ensure effective observance of the provisions of this Act and the rules made thereunder."}, "dpdp-act-2023:sec_8__subsec_5": {"cite": "DPDP Act s.8(5)", "head": "", "text": "A Data Fiduciary shall protect personal data in its possession or under its control, including in respect of any processing undertaken by it or on its behalf by a Data Processor, by taking reasonable security safeguards to prevent personal data breach."}, "dpdp-act-2023:sec_8__subsec_6": {"cite": "DPDP Act s.8(6)", "head": "", "text": "In the event of a personal data breach, the Data Fiduciary shall give the Board and each affected Data Principal, intimation of such breach in such form and manner as may be prescribed."}, "dpdp-act-2023:sec_8__subsec_7": {"cite": "DPDP Act s.8(7)", "head": "", "text": "A Data Fiduciary shall, unless retention is necessary for compliance with any law for the time being in force,— erase personal data, upon the Data Principal withdrawing her consent or as soon as it is reasonable to assume that the specified purpose is no longer being served, whichever is earlier; and cause its Data Processor to erase any personal data that was made available by the Data Fiduciary for processing to such Data Processor. Illustrations (I) X, an individual, registers herself on an online marketplace operated by Y, an e-commerce service provider. X gives her consent to Y for the pr…"}, "dpdp-act-2023:sec_8__subsec_7__cl_a": {"cite": "DPDP Act s.8(7)(a)", "head": "", "text": "erase personal data, upon the Data Principal withdrawing her consent or as soon as it is reasonable to assume that the specified purpose is no longer being served, whichever is earlier; and"}, "dpdp-act-2023:sec_8__subsec_7__cl_b": {"cite": "DPDP Act s.8(7)(b)", "head": "", "text": "cause its Data Processor to erase any personal data that was made available by the Data Fiduciary for processing to such Data Processor. Illustrations (I) X, an individual, registers herself on an online marketplace operated by Y, an e-commerce service provider. X gives her consent to Y for the processing of her personal data for selling her used car. The online marketplace helps conclude the sale. Y shall no longer retain her personal data. (II) X, an individual, decides to close her savings account with Y, a bank. Y is required by law applicable to banks to maintain the record of the identit…"}, "dpdp-act-2023:sec_8__subsec_7__cl_b__hcontainer_1": {"cite": "DPDP Act s.8(7)(b)", "head": "Illustrations", "text": "(I) X, an individual, registers herself on an online marketplace operated by Y, an e-commerce service provider. X gives her consent to Y for the processing of her personal data for selling her used car. The online marketplace helps conclude the sale. Y shall no longer retain her personal data. (II) X, an individual, decides to close her savings account with Y, a bank. Y is required by law applicable to banks to maintain the record of the identity of its clients for a period of ten years beyond closing of accounts. Since retention is necessary for compliance with law, Y shall retain X’s persona…"}, "dpdp-act-2023:sec_8__subsec_8": {"cite": "DPDP Act s.8(8)", "head": "", "text": "The purpose referred to in clause (a) of sub-section (7) shall be deemed to no longer be served, if the Data Principal does not–– approach the Data Fiduciary for the performance of the specified purpose; and exercise any of her rights in relation to such processing, for such time period as may be prescribed, and different time periods may be prescribed for different classes of Data Fiduciaries and for different purposes."}, "dpdp-act-2023:sec_8__subsec_8__cl_a": {"cite": "DPDP Act s.8(8)(a)", "head": "", "text": "approach the Data Fiduciary for the performance of the specified purpose; and"}, "dpdp-act-2023:sec_8__subsec_8__cl_b": {"cite": "DPDP Act s.8(8)(b)", "head": "", "text": "exercise any of her rights in relation to such processing,"}, "dpdp-act-2023:sec_8__subsec_9": {"cite": "DPDP Act s.8(9)", "head": "", "text": "A Data Fiduciary shall publish, in such manner as may be prescribed, the business contact information of a Data Protection Officer, if applicable, or a person who is able to answer on behalf of the Data Fiduciary, the questions, if any, raised by the Data Principal about the processing of her personal data."}, "dpdp-act-2023:sec_8__subsec_10": {"cite": "DPDP Act s.8(10)", "head": "", "text": "A Data Fiduciary shall establish an effective mechanism to redress the grievances of Data Principals."}, "dpdp-act-2023:sec_8__subsec_11": {"cite": "DPDP Act s.8(11)", "head": "", "text": "For the purposes of this section, it is hereby clarified that a Data Principal shall be considered as not having approached the Data Fiduciary for the performance of the specified purpose, in any period during which she has not initiated contact with the Data Fiduciary for such performance, in person or by way of communication in electronic or physical form."}, "dpdp-act-2023:sec_9": {"cite": "DPDP Act s.9", "head": "Processing of personal data of children", "text": "The Data Fiduciary shall, before processing any personal data of a child or a person with disability who has a lawful guardian obtain verifiable consent of the parent of such child or the lawful guardian, as the case may be, in such manner as may be prescribed. For the purpose of this sub-section, the expression “consent of the parent” includes the consent of lawful guardian, wherever applicable. A Data Fiduciary shall not undertake such processing of personal data that is likely to cause any detrimental effect on the well-being of a child. A Data Fiduciary shall not undertake tracking or beha…"}, "dpdp-act-2023:sec_9__subsec_1": {"cite": "DPDP Act s.9(1)", "head": "", "text": "The Data Fiduciary shall, before processing any personal data of a child or a person with disability who has a lawful guardian obtain verifiable consent of the parent of such child or the lawful guardian, as the case may be, in such manner as may be prescribed. For the purpose of this sub-section, the expression “consent of the parent” includes the consent of lawful guardian, wherever applicable."}, "dpdp-act-2023:sec_9__subsec_1__hcontainer_1": {"cite": "DPDP Act s.9(1)", "head": "", "text": "For the purpose of this sub-section, the expression “consent of the parent” includes the consent of lawful guardian, wherever applicable."}, "dpdp-act-2023:sec_9__subsec_2": {"cite": "DPDP Act s.9(2)", "head": "", "text": "A Data Fiduciary shall not undertake such processing of personal data that is likely to cause any detrimental effect on the well-being of a child."}, "dpdp-act-2023:sec_9__subsec_3": {"cite": "DPDP Act s.9(3)", "head": "", "text": "A Data Fiduciary shall not undertake tracking or behavioural monitoring of children or targeted advertising directed at children."}, "dpdp-act-2023:sec_9__subsec_4": {"cite": "DPDP Act s.9(4)", "head": "", "text": "The provisions of sub-sections (1) and (3) shall not be applicable to processing of personal data of a child by such classes of Data Fiduciaries or for such purposes, and subject to such conditions, as may be prescribed."}, "dpdp-act-2023:sec_9__subsec_5": {"cite": "DPDP Act s.9(5)", "head": "", "text": "The Central Government may, if satisfied that a Data Fiduciary has ensured that its processing of personal data of children is done in a manner that is verifiably safe, notify for such processing by such Data Fiduciary the age above which that Data Fiduciary shall be exempt from the applicability of all or any of the obligations under sub-sections (1) and (3) in respect of processing by that Data Fiduciary as the notification may specify."}, "dpdp-act-2023:sec_10": {"cite": "DPDP Act s.10", "head": "Additional obligations of Significant Data Fiduciary", "text": "The Central Government may notify any Data Fiduciary or class of Data Fiduciaries as Significant Data Fiduciary, on the basis of an assessment of such relevant factors as it may determine, including— the volume and sensitivity of personal data processed; risk to the rights of Data Principal; potential impact on the sovereignty and integrity of India; risk to electoral democracy; security of the State; and public order. The Significant Data Fiduciary shall— appoint a Data Protection Officer who shall— represent the Significant Data Fiduciary under the provisions of this Act; be based in India; …"}, "dpdp-act-2023:sec_10__subsec_1": {"cite": "DPDP Act s.10(1)", "head": "", "text": "The Central Government may notify any Data Fiduciary or class of Data Fiduciaries as Significant Data Fiduciary, on the basis of an assessment of such relevant factors as it may determine, including— the volume and sensitivity of personal data processed; risk to the rights of Data Principal; potential impact on the sovereignty and integrity of India; risk to electoral democracy; security of the State; and public order."}, "dpdp-act-2023:sec_10__subsec_1__cl_a": {"cite": "DPDP Act s.10(1)(a)", "head": "", "text": "the volume and sensitivity of personal data processed;"}, "dpdp-act-2023:sec_10__subsec_1__cl_b": {"cite": "DPDP Act s.10(1)(b)", "head": "", "text": "risk to the rights of Data Principal;"}, "dpdp-act-2023:sec_10__subsec_1__cl_c": {"cite": "DPDP Act s.10(1)(c)", "head": "", "text": "potential impact on the sovereignty and integrity of India;"}, "dpdp-act-2023:sec_10__subsec_1__cl_d": {"cite": "DPDP Act s.10(1)(d)", "head": "", "text": "risk to electoral democracy;"}, "dpdp-act-2023:sec_10__subsec_1__cl_e": {"cite": "DPDP Act s.10(1)(e)", "head": "", "text": "security of the State; and"}, "dpdp-act-2023:sec_10__subsec_1__cl_f": {"cite": "DPDP Act s.10(1)(f)", "head": "", "text": "public order."}, "dpdp-act-2023:sec_10__subsec_2": {"cite": "DPDP Act s.10(2)", "head": "", "text": "The Significant Data Fiduciary shall— appoint a Data Protection Officer who shall— represent the Significant Data Fiduciary under the provisions of this Act; be based in India; be an individual responsible to the Board of Directors or similar governing body of the Significant Data Fiduciary; and be the point of contact for the grievance redressal mechanism under the provisions of this Act; appoint an independent data auditor to carry out data audit, who shall evaluate the compliance of the Significant Data Fiduciary in accordance with the provisions of this Act; and undertake the following oth…"}, "dpdp-act-2023:sec_10__subsec_2__cl_a": {"cite": "DPDP Act s.10(2)(a)", "head": "", "text": "appoint a Data Protection Officer who shall— represent the Significant Data Fiduciary under the provisions of this Act; be based in India; be an individual responsible to the Board of Directors or similar governing body of the Significant Data Fiduciary; and be the point of contact for the grievance redressal mechanism under the provisions of this Act;"}, "dpdp-act-2023:sec_10__subsec_2__cl_a__subcl_i": {"cite": "DPDP Act s.10(2)(a)(i)", "head": "", "text": "represent the Significant Data Fiduciary under the provisions of this Act;"}, "dpdp-act-2023:sec_10__subsec_2__cl_a__subcl_ii": {"cite": "DPDP Act s.10(2)(a)(ii)", "head": "", "text": "be based in India;"}, "dpdp-act-2023:sec_10__subsec_2__cl_a__subcl_iii": {"cite": "DPDP Act s.10(2)(a)(iii)", "head": "", "text": "be an individual responsible to the Board of Directors or similar governing body of the Significant Data Fiduciary; and"}, "dpdp-act-2023:sec_10__subsec_2__cl_a__subcl_iv": {"cite": "DPDP Act s.10(2)(a)(iv)", "head": "", "text": "be the point of contact for the grievance redressal mechanism under the provisions of this Act;"}, "dpdp-act-2023:sec_10__subsec_2__cl_b": {"cite": "DPDP Act s.10(2)(b)", "head": "", "text": "appoint an independent data auditor to carry out data audit, who shall evaluate the compliance of the Significant Data Fiduciary in accordance with the provisions of this Act; and"}, "dpdp-act-2023:sec_10__subsec_2__cl_c": {"cite": "DPDP Act s.10(2)(c)", "head": "", "text": "undertake the following other measures, namely:— periodic Data Protection Impact Assessment, which shall be a process comprising a description of the rights of Data Principals and the purpose of processing of their personal data, assessment and management of the risk to the rights of the Data Principals, and such other matters regarding such process as may be prescribed; periodic audit; and such other measures, consistent with the provisions of this Act, as may be prescribed."}, "dpdp-act-2023:sec_10__subsec_2__cl_c__subcl_i": {"cite": "DPDP Act s.10(2)(c)(i)", "head": "", "text": "periodic Data Protection Impact Assessment, which shall be a process comprising a description of the rights of Data Principals and the purpose of processing of their personal data, assessment and management of the risk to the rights of the Data Principals, and such other matters regarding such process as may be prescribed;"}, "dpdp-act-2023:sec_10__subsec_2__cl_c__subcl_ii": {"cite": "DPDP Act s.10(2)(c)(ii)", "head": "", "text": "periodic audit; and"}, "dpdp-act-2023:sec_10__subsec_2__cl_c__subcl_iii": {"cite": "DPDP Act s.10(2)(c)(iii)", "head": "", "text": "such other measures, consistent with the provisions of this Act, as may be prescribed."}, "dpdp-act-2023:chp_III": {"cite": "DPDP Act Chapter III", "head": "RIGHTS AND DUTIES OF DATA PRINCIPAL", "text": "Right to access information about personal data The Data Principal shall have the right to obtain from the Data Fiduciary to whom she has previously given consent, including consent as referred to in clause (a) of section 7 (hereinafter referred to as the said Data Fiduciary), for processing of personal data, upon making to it a request in such manner as may be prescribed,— a summary of personal data which is being processed by such Data Fiduciary and the processing activities undertaken by that Data Fiduciary with respect to such personal data; the identities of all other Data Fiduciaries and…"}, "dpdp-act-2023:sec_11": {"cite": "DPDP Act s.11", "head": "Right to access information about personal data", "text": "The Data Principal shall have the right to obtain from the Data Fiduciary to whom she has previously given consent, including consent as referred to in clause (a) of section 7 (hereinafter referred to as the said Data Fiduciary), for processing of personal data, upon making to it a request in such manner as may be prescribed,— a summary of personal data which is being processed by such Data Fiduciary and the processing activities undertaken by that Data Fiduciary with respect to such personal data; the identities of all other Data Fiduciaries and Data Processors with whom the personal data has…"}, "dpdp-act-2023:sec_11__subsec_1": {"cite": "DPDP Act s.11(1)", "head": "", "text": "The Data Principal shall have the right to obtain from the Data Fiduciary to whom she has previously given consent, including consent as referred to in clause (a) of section 7 (hereinafter referred to as the said Data Fiduciary), for processing of personal data, upon making to it a request in such manner as may be prescribed,— a summary of personal data which is being processed by such Data Fiduciary and the processing activities undertaken by that Data Fiduciary with respect to such personal data; the identities of all other Data Fiduciaries and Data Processors with whom the personal data has…"}, "dpdp-act-2023:sec_11__subsec_1__cl_a": {"cite": "DPDP Act s.11(1)(a)", "head": "", "text": "a summary of personal data which is being processed by such Data Fiduciary and the processing activities undertaken by that Data Fiduciary with respect to such personal data;"}, "dpdp-act-2023:sec_11__subsec_1__cl_b": {"cite": "DPDP Act s.11(1)(b)", "head": "", "text": "the identities of all other Data Fiduciaries and Data Processors with whom the personal data has been shared by such Data Fiduciary, along with a description of the personal data so shared; and"}, "dpdp-act-2023:sec_11__subsec_1__cl_c": {"cite": "DPDP Act s.11(1)(c)", "head": "", "text": "any other information related to the personal data of such Data Principal and its processing, as may be prescribed."}, "dpdp-act-2023:sec_11__subsec_2": {"cite": "DPDP Act s.11(2)", "head": "", "text": "Nothing contained in clause (b) or clause (c) of sub-section (1) shall apply in respect of the sharing of any personal data by the said Data Fiduciary with any other Data Fiduciary authorised by law to obtain such personal data, where such sharing is pursuant to a request made in writing by such other Data Fiduciary for the purpose of prevention or detection or investigation of offences or cyber incidents, or for prosecution or punishment of offences."}, "dpdp-act-2023:sec_12": {"cite": "DPDP Act s.12", "head": "Right to correction and erasure of personal data", "text": "A Data Principal shall have the right to correction, completion, updating and erasure of her personal data for the processing of which she has previously given consent, including consent as referred to in clause (a) of section 7, in accordance with any requirement or procedure under any law for the time being in force. A Data Fiduciary shall, upon receiving a request for correction, completion or updating from a Data Principal,— correct the inaccurate or misleading personal data; complete the incomplete personal data; and update the personal data. A Data Principal shall make a request in such …"}, "dpdp-act-2023:sec_12__subsec_1": {"cite": "DPDP Act s.12(1)", "head": "", "text": "A Data Principal shall have the right to correction, completion, updating and erasure of her personal data for the processing of which she has previously given consent, including consent as referred to in clause (a) of section 7, in accordance with any requirement or procedure under any law for the time being in force."}, "dpdp-act-2023:sec_12__subsec_2": {"cite": "DPDP Act s.12(2)", "head": "", "text": "A Data Fiduciary shall, upon receiving a request for correction, completion or updating from a Data Principal,— correct the inaccurate or misleading personal data; complete the incomplete personal data; and update the personal data."}, "dpdp-act-2023:sec_12__subsec_2__cl_a": {"cite": "DPDP Act s.12(2)(a)", "head": "", "text": "correct the inaccurate or misleading personal data;"}, "dpdp-act-2023:sec_12__subsec_2__cl_b": {"cite": "DPDP Act s.12(2)(b)", "head": "", "text": "complete the incomplete personal data; and"}, "dpdp-act-2023:sec_12__subsec_2__cl_c": {"cite": "DPDP Act s.12(2)(c)", "head": "", "text": "update the personal data."}, "dpdp-act-2023:sec_12__subsec_3": {"cite": "DPDP Act s.12(3)", "head": "", "text": "A Data Principal shall make a request in such manner as may be prescribed to the Data Fiduciary for erasure of her personal data, and upon receipt of such a request, the Data Fiduciary shall erase her personal data unless retention of the same is necessary for the specified purpose or for compliance with any law for the time being in force."}, "dpdp-act-2023:sec_13": {"cite": "DPDP Act s.13", "head": "Right of grievance redressal", "text": "A Data Principal shall have the right to have readily available means of grievance redressal provided by a Data Fiduciary or Consent Manager in respect of any act or omission of such Data Fiduciary or Consent Manager regarding the performance of its obligations in relation to the personal data of such Data Principal or the exercise of her rights under the provisions of this Act and the rules made thereunder. The Data Fiduciary or Consent Manager shall respond to any grievances referred to in sub-section (1) within such period as may be prescribed from the date of its receipt for all or any cla…"}, "dpdp-act-2023:sec_13__subsec_1": {"cite": "DPDP Act s.13(1)", "head": "", "text": "A Data Principal shall have the right to have readily available means of grievance redressal provided by a Data Fiduciary or Consent Manager in respect of any act or omission of such Data Fiduciary or Consent Manager regarding the performance of its obligations in relation to the personal data of such Data Principal or the exercise of her rights under the provisions of this Act and the rules made thereunder."}, "dpdp-act-2023:sec_13__subsec_2": {"cite": "DPDP Act s.13(2)", "head": "", "text": "The Data Fiduciary or Consent Manager shall respond to any grievances referred to in sub-section (1) within such period as may be prescribed from the date of its receipt for all or any class of Data Fiduciaries."}, "dpdp-act-2023:sec_13__subsec_3": {"cite": "DPDP Act s.13(3)", "head": "", "text": "The Data Principal shall exhaust the opportunity of redressing her grievance under this section before approaching the Board."}, "dpdp-act-2023:sec_14": {"cite": "DPDP Act s.14", "head": "Right to nominate", "text": "A Data Principal shall have the right to nominate, in such manner as may be prescribed, any other individual, who shall, in the event of death or incapacity of the Data Principal, exercise the rights of the Data Principal in accordance with the provisions of this Act and the rules made thereunder. For the purposes of this section, the expression “incapacity” means inability to exercise the rights of the Data Principal under the provisions of this Act or the rules made thereunder due to unsoundness of mind or infirmity of body."}, "dpdp-act-2023:sec_14__subsec_1": {"cite": "DPDP Act s.14(1)", "head": "", "text": "A Data Principal shall have the right to nominate, in such manner as may be prescribed, any other individual, who shall, in the event of death or incapacity of the Data Principal, exercise the rights of the Data Principal in accordance with the provisions of this Act and the rules made thereunder."}, "dpdp-act-2023:sec_14__subsec_2": {"cite": "DPDP Act s.14(2)", "head": "", "text": "For the purposes of this section, the expression “incapacity” means inability to exercise the rights of the Data Principal under the provisions of this Act or the rules made thereunder due to unsoundness of mind or infirmity of body."}, "dpdp-act-2023:sec_15": {"cite": "DPDP Act s.15", "head": "Duties of Data Principal", "text": "A Data Principal shall perform the following duties, namely:— comply with the provisions of all applicable laws for the time being in force while exercising rights under the provisions of this Act; to ensure not to impersonate another person while providing her personal data for a specified purpose; to ensure not to suppress any material information while providing her personal data for any document, unique identifier, proof of identity or proof of address issued by the State or any of its instrumentalities; to ensure not to register a false or frivolous grievance or complaint with a Data Fidu…"}, "dpdp-act-2023:sec_15__cl_a": {"cite": "DPDP Act s.15(a)", "head": "", "text": "comply with the provisions of all applicable laws for the time being in force while exercising rights under the provisions of this Act;"}, "dpdp-act-2023:sec_15__cl_b": {"cite": "DPDP Act s.15(b)", "head": "", "text": "to ensure not to impersonate another person while providing her personal data for a specified purpose;"}, "dpdp-act-2023:sec_15__cl_c": {"cite": "DPDP Act s.15(c)", "head": "", "text": "to ensure not to suppress any material information while providing her personal data for any document, unique identifier, proof of identity or proof of address issued by the State or any of its instrumentalities;"}, "dpdp-act-2023:sec_15__cl_d": {"cite": "DPDP Act s.15(d)", "head": "", "text": "to ensure not to register a false or frivolous grievance or complaint with a Data Fiduciary or the Board; and"}, "dpdp-act-2023:sec_15__cl_e": {"cite": "DPDP Act s.15(e)", "head": "", "text": "to furnish only such information as is verifiably authentic, while exercising the right to correction or erasure under the provisions of this Act or the rules made thereunder."}, "dpdp-act-2023:chp_IV": {"cite": "DPDP Act Chapter IV", "head": "SPECIAL PROVISIONS", "text": "Processing of personal data outside India The Central Government may, by notification, restrict the transfer of personal data by a Data Fiduciary for processing to such country or territory outside India as may be so notified. Nothing contained in this section shall restrict the applicability of any law for the time being in force in India that provides for a higher degree of protection for or restriction on transfer of personal data by a Data Fiduciary outside India in relation to any personal data or Data Fiduciary or class thereof. Exemptions The provisions of Chapter II, except sub-section…"}, "dpdp-act-2023:sec_16": {"cite": "DPDP Act s.16", "head": "Processing of personal data outside India", "text": "The Central Government may, by notification, restrict the transfer of personal data by a Data Fiduciary for processing to such country or territory outside India as may be so notified. Nothing contained in this section shall restrict the applicability of any law for the time being in force in India that provides for a higher degree of protection for or restriction on transfer of personal data by a Data Fiduciary outside India in relation to any personal data or Data Fiduciary or class thereof."}, "dpdp-act-2023:sec_16__subsec_1": {"cite": "DPDP Act s.16(1)", "head": "", "text": "The Central Government may, by notification, restrict the transfer of personal data by a Data Fiduciary for processing to such country or territory outside India as may be so notified."}, "dpdp-act-2023:sec_16__subsec_2": {"cite": "DPDP Act s.16(2)", "head": "", "text": "Nothing contained in this section shall restrict the applicability of any law for the time being in force in India that provides for a higher degree of protection for or restriction on transfer of personal data by a Data Fiduciary outside India in relation to any personal data or Data Fiduciary or class thereof."}, "dpdp-act-2023:sec_17": {"cite": "DPDP Act s.17", "head": "Exemptions", "text": "The provisions of Chapter II, except sub-sections (1) and (5) of section 8, and those of Chapter III and section 16 shall not apply where— the processing of personal data is necessary for enforcing any legal right or claim; the processing of personal data by any court or tribunal or any other body in India which is entrusted by law with the performance of any judicial or quasi-judicial or regulatory or supervisory function, where such processing is necessary for the performance of such function; personal data is processed in the interest of prevention, detection, investigation or prosecution o…"}, "dpdp-act-2023:sec_17__subsec_1": {"cite": "DPDP Act s.17(1)", "head": "", "text": "The provisions of Chapter II, except sub-sections (1) and (5) of section 8, and those of Chapter III and section 16 shall not apply where— the processing of personal data is necessary for enforcing any legal right or claim; the processing of personal data by any court or tribunal or any other body in India which is entrusted by law with the performance of any judicial or quasi-judicial or regulatory or supervisory function, where such processing is necessary for the performance of such function; personal data is processed in the interest of prevention, detection, investigation or prosecution o…"}, "dpdp-act-2023:sec_17__subsec_1__cl_a": {"cite": "DPDP Act s.17(1)(a)", "head": "", "text": "the processing of personal data is necessary for enforcing any legal right or claim;"}, "dpdp-act-2023:sec_17__subsec_1__cl_b": {"cite": "DPDP Act s.17(1)(b)", "head": "", "text": "the processing of personal data by any court or tribunal or any other body in India which is entrusted by law with the performance of any judicial or quasi-judicial or regulatory or supervisory function, where such processing is necessary for the performance of such function;"}, "dpdp-act-2023:sec_17__subsec_1__cl_c": {"cite": "DPDP Act s.17(1)(c)", "head": "", "text": "personal data is processed in the interest of prevention, detection, investigation or prosecution of any offence or contravention of any law for the time being in force in India;"}, "dpdp-act-2023:sec_17__subsec_1__cl_d": {"cite": "DPDP Act s.17(1)(d)", "head": "", "text": "personal data of Data Principals not within the territory of India is processed pursuant to any contract entered into with any person outside the territory of India by any person based in India;"}, "dpdp-act-2023:sec_17__subsec_1__cl_e": {"cite": "DPDP Act s.17(1)(e)", "head": "", "text": "the processing is necessary for a scheme of compromise or arrangement or merger or amalgamation of two or more companies or a reconstruction by way of demerger or otherwise of a company, or transfer of undertaking of one or more company to another company, or involving division of one or more companies, approved by a court or tribunal or other authority competent to do so by any law for the time being in force; and"}, "dpdp-act-2023:sec_17__subsec_1__cl_f": {"cite": "DPDP Act s.17(1)(f)", "head": "", "text": "the processing is for the purpose of ascertaining the financial information and assets and liabilities of any person who has defaulted in payment due on account of a loan or advance taken from a financial institution, subject to such processing being in accordance with the provisions regarding disclosure of information or data in any other law for the time being in force. For the purposes of this clause, the expressions “default” and “financial institution” shall have the meanings respectively assigned to them in sub-sections (12) and (14) of section 3 of the Insolvency and Bankruptcy Code, 20…"}, "dpdp-act-2023:sec_17__subsec_1__cl_f__hcontainer_1": {"cite": "DPDP Act s.17(1)(f)", "head": "", "text": "For the purposes of this clause, the expressions “default” and “financial institution” shall have the meanings respectively assigned to them in sub-sections (12) and (14) of section 3 of the Insolvency and Bankruptcy Code, 2016. Illustration X, an individual, takes a loan from Y, a bank. X defaults in paying her monthly loan repayment instalment on the date on which it falls due. Y may process the personal data of X for ascertaining her financial information and assets and liabilities."}, "dpdp-act-2023:sec_17__subsec_1__cl_f__hcontainer_1__hcontainer_1": {"cite": "DPDP Act s.17(1)(f)", "head": "Illustration", "text": "X, an individual, takes a loan from Y, a bank. X defaults in paying her monthly loan repayment instalment on the date on which it falls due. Y may process the personal data of X for ascertaining her financial information and assets and liabilities."}, "dpdp-act-2023:sec_17__subsec_2": {"cite": "DPDP Act s.17(2)", "head": "", "text": "The provisions of this Act shall not apply in respect of the processing of personal data— by such instrumentality of the State as the Central Government may notify, in the interests of sovereignty and integrity of India, security of the State, friendly relations with foreign States, maintenance of public order or preventing incitement to any cognizable offence relating to any of these, and the processing by the Central Government of any personal data that such instrumentality may furnish to it; and necessary for research, archiving or statistical purposes if the personal data is not to be used…"}, "dpdp-act-2023:sec_17__subsec_2__cl_a": {"cite": "DPDP Act s.17(2)(a)", "head": "", "text": "by such instrumentality of the State as the Central Government may notify, in the interests of sovereignty and integrity of India, security of the State, friendly relations with foreign States, maintenance of public order or preventing incitement to any cognizable offence relating to any of these, and the processing by the Central Government of any personal data that such instrumentality may furnish to it; and"}, "dpdp-act-2023:sec_17__subsec_2__cl_b": {"cite": "DPDP Act s.17(2)(b)", "head": "", "text": "necessary for research, archiving or statistical purposes if the personal data is not to be used to take any decision specific to a Data Principal and such processing is carried on in accordance with such standards as may be prescribed."}, "dpdp-act-2023:sec_17__subsec_3": {"cite": "DPDP Act s.17(3)", "head": "", "text": "The Central Government may, having regard to the volume and nature of personal data processed, notify certain Data Fiduciaries or class of Data Fiduciaries, including startups, as Data Fiduciaries to whom the provisions of section 5, sub-sections (3) and (7) of section 8 and sections 10 and 11 shall not apply. For the purposes of this sub-section, the term “startup” means a private limited company or a partnership firm or a limited liability partnership incorporated in India, which is eligible to be and is recognised as such in accordance with the criteria and process notified by the departmen…"}, "dpdp-act-2023:sec_17__subsec_3__hcontainer_1": {"cite": "DPDP Act s.17(3)", "head": "", "text": "For the purposes of this sub-section, the term “startup” means a private limited company or a partnership firm or a limited liability partnership incorporated in India, which is eligible to be and is recognised as such in accordance with the criteria and process notified by the department to which matters relating to startups are allocated in the Central Government."}, "dpdp-act-2023:sec_17__subsec_4": {"cite": "DPDP Act s.17(4)", "head": "", "text": "In respect of processing by the State or any instrumentality of the State, the provisions of sub-section (7) of section 8 and sub-section (3) of section 12 and, where such processing is for a purpose that does not include making of a decision that affects the Data Principal, sub-section (2) of section 12 shall not apply."}, "dpdp-act-2023:sec_17__subsec_5": {"cite": "DPDP Act s.17(5)", "head": "", "text": "The Central Government may, before expiry of five years from the date of commencement of this Act, by notification, declare that any provision of this Act shall not apply to such Data Fiduciary or classes of Data Fiduciaries for such period as may be specified in the notification."}, "dpdp-act-2023:chp_V": {"cite": "DPDP Act Chapter V", "head": "DATA PROTECTION BOARD OF INDIA", "text": "Establishment of Board With effect from such date as the Central Government may, by notification, appoint, there shall be established, for the purposes of this Act, a Board to be called the Data Protection Board of India. The Board shall be a body corporate by the name aforesaid, having perpetual succession and a common seal, with power, subject to the provisions of this Act, to acquire, hold and dispose of property, both movable and immovable, and to contract and shall, by the said name, sue or be sued. The headquarters of the Board shall be at such place as the Central Government may notify.…"}, "dpdp-act-2023:sec_18": {"cite": "DPDP Act s.18", "head": "Establishment of Board", "text": "With effect from such date as the Central Government may, by notification, appoint, there shall be established, for the purposes of this Act, a Board to be called the Data Protection Board of India. The Board shall be a body corporate by the name aforesaid, having perpetual succession and a common seal, with power, subject to the provisions of this Act, to acquire, hold and dispose of property, both movable and immovable, and to contract and shall, by the said name, sue or be sued. The headquarters of the Board shall be at such place as the Central Government may notify."}, "dpdp-act-2023:sec_18__subsec_1": {"cite": "DPDP Act s.18(1)", "head": "", "text": "With effect from such date as the Central Government may, by notification, appoint, there shall be established, for the purposes of this Act, a Board to be called the Data Protection Board of India."}, "dpdp-act-2023:sec_18__subsec_2": {"cite": "DPDP Act s.18(2)", "head": "", "text": "The Board shall be a body corporate by the name aforesaid, having perpetual succession and a common seal, with power, subject to the provisions of this Act, to acquire, hold and dispose of property, both movable and immovable, and to contract and shall, by the said name, sue or be sued."}, "dpdp-act-2023:sec_18__subsec_3": {"cite": "DPDP Act s.18(3)", "head": "", "text": "The headquarters of the Board shall be at such place as the Central Government may notify."}, "dpdp-act-2023:sec_19": {"cite": "DPDP Act s.19", "head": "Composition and qualifications for appointment of Chairperson and Members", "text": "The Board shall consist of a Chairperson and such number of other Members as the Central Government may notify. The Chairperson and other Members shall be appointed by the Central Government in such manner as may be prescribed. The Chairperson and other Members shall be a person of ability, integrity and standing who possesses special knowledge or practical experience in the fields of data governance, administration or implementation of laws related to social or consumer protection, dispute resolution, information and communication technology, digital economy, law, regulation or techno-regulat…"}, "dpdp-act-2023:sec_19__subsec_1": {"cite": "DPDP Act s.19(1)", "head": "", "text": "The Board shall consist of a Chairperson and such number of other Members as the Central Government may notify."}, "dpdp-act-2023:sec_19__subsec_2": {"cite": "DPDP Act s.19(2)", "head": "", "text": "The Chairperson and other Members shall be appointed by the Central Government in such manner as may be prescribed."}, "dpdp-act-2023:sec_19__subsec_3": {"cite": "DPDP Act s.19(3)", "head": "", "text": "The Chairperson and other Members shall be a person of ability, integrity and standing who possesses special knowledge or practical experience in the fields of data governance, administration or implementation of laws related to social or consumer protection, dispute resolution, information and communication technology, digital economy, law, regulation or techno-regulation, or in any other field which in the opinion of the Central Government may be useful to the Board, and at least one among them shall be an expert in the field of law."}, "dpdp-act-2023:sec_20": {"cite": "DPDP Act s.20", "head": "Salary, allowances payable to and term of office", "text": "The salary, allowances and other terms and conditions of service of the Chairperson and other Members shall be such as may be prescribed, and shall not be varied to their disadvantage after their appointment. The Chairperson and other Members shall hold office for a term of two years and shall be eligible for re-appointment."}, "dpdp-act-2023:sec_20__subsec_1": {"cite": "DPDP Act s.20(1)", "head": "", "text": "The salary, allowances and other terms and conditions of service of the Chairperson and other Members shall be such as may be prescribed, and shall not be varied to their disadvantage after their appointment."}, "dpdp-act-2023:sec_20__subsec_2": {"cite": "DPDP Act s.20(2)", "head": "", "text": "The Chairperson and other Members shall hold office for a term of two years and shall be eligible for re-appointment."}, "dpdp-act-2023:sec_21": {"cite": "DPDP Act s.21", "head": "Disqualifications for appointment and continuation as Chairperson and Members of Board", "text": "A person shall be disqualified for being appointed and continued as the Chairperson or a Member, if she— has been adjudged as an insolvent; has been convicted of an offence, which in the opinion of the Central Government, involves moral turpitude; has become physically or mentally incapable of acting as a Member; has acquired such financial or other interest, as is likely to affect prejudicially her functions as a Member; or has so abused her position as to render her continuance in office prejudicial to the public interest. The Chairperson or Member shall not be removed from her office by the…"}, "dpdp-act-2023:sec_21__subsec_1": {"cite": "DPDP Act s.21(1)", "head": "", "text": "A person shall be disqualified for being appointed and continued as the Chairperson or a Member, if she— has been adjudged as an insolvent; has been convicted of an offence, which in the opinion of the Central Government, involves moral turpitude; has become physically or mentally incapable of acting as a Member; has acquired such financial or other interest, as is likely to affect prejudicially her functions as a Member; or has so abused her position as to render her continuance in office prejudicial to the public interest."}, "dpdp-act-2023:sec_21__subsec_1__cl_a": {"cite": "DPDP Act s.21(1)(a)", "head": "", "text": "has been adjudged as an insolvent;"}, "dpdp-act-2023:sec_21__subsec_1__cl_b": {"cite": "DPDP Act s.21(1)(b)", "head": "", "text": "has been convicted of an offence, which in the opinion of the Central Government, involves moral turpitude;"}, "dpdp-act-2023:sec_21__subsec_1__cl_c": {"cite": "DPDP Act s.21(1)(c)", "head": "", "text": "has become physically or mentally incapable of acting as a Member;"}, "dpdp-act-2023:sec_21__subsec_1__cl_d": {"cite": "DPDP Act s.21(1)(d)", "head": "", "text": "has acquired such financial or other interest, as is likely to affect prejudicially her functions as a Member; or"}, "dpdp-act-2023:sec_21__subsec_1__cl_e": {"cite": "DPDP Act s.21(1)(e)", "head": "", "text": "has so abused her position as to render her continuance in office prejudicial to the public interest."}, "dpdp-act-2023:sec_21__subsec_2": {"cite": "DPDP Act s.21(2)", "head": "", "text": "The Chairperson or Member shall not be removed from her office by the Central Government unless she has been given an opportunity of being heard in the matter."}, "dpdp-act-2023:sec_22": {"cite": "DPDP Act s.22", "head": "Resignation by Members and filling of vacancy", "text": "The Chairperson or any other Member may give notice in writing to the Central Government of resigning from her office, and such resignation shall be effective from the date on which the Central Government permits her to relinquish office, or upon expiry of a period of three months from the date of receipt of such notice, or upon a duly appointed successor entering upon her office, or upon the expiry of the term of her office, whichever is earliest. A vacancy caused by the resignation or removal or death of the Chairperson or any other Member, or otherwise, shall be filled by fresh appointment …"}, "dpdp-act-2023:sec_22__subsec_1": {"cite": "DPDP Act s.22(1)", "head": "", "text": "The Chairperson or any other Member may give notice in writing to the Central Government of resigning from her office, and such resignation shall be effective from the date on which the Central Government permits her to relinquish office, or upon expiry of a period of three months from the date of receipt of such notice, or upon a duly appointed successor entering upon her office, or upon the expiry of the term of her office, whichever is earliest."}, "dpdp-act-2023:sec_22__subsec_2": {"cite": "DPDP Act s.22(2)", "head": "", "text": "A vacancy caused by the resignation or removal or death of the Chairperson or any other Member, or otherwise, shall be filled by fresh appointment in accordance with the provisions of this Act."}, "dpdp-act-2023:sec_22__subsec_3": {"cite": "DPDP Act s.22(3)", "head": "", "text": "The Chairperson and any other Member shall not, for a period of one year from the date on which they cease to hold such office, except with the previous approval of the Central Government, accept any employment, and shall also disclose to the Central Government any subsequent acceptance of employment with any Data Fiduciary against whom proceedings were initiated by or before such Chairperson or other Member."}, "dpdp-act-2023:sec_23": {"cite": "DPDP Act s.23", "head": "Proceedings of Board", "text": "The Board shall observe such procedure in regard to the holding of and transaction of business at its meetings, including by digital means, and authenticate its orders, directions and instruments in such manner as may be prescribed. No act or proceeding of the Board shall be invalid merely by reason of— any vacancy in or any defect in the constitution of the Board; any defect in the appointment of a person acting as the Chairperson or other Member of the Board; or any irregularity in the procedure of the Board, which does not affect the merits of the case. When the Chairperson is unable to dis…"}, "dpdp-act-2023:sec_23__subsec_1": {"cite": "DPDP Act s.23(1)", "head": "", "text": "The Board shall observe such procedure in regard to the holding of and transaction of business at its meetings, including by digital means, and authenticate its orders, directions and instruments in such manner as may be prescribed."}, "dpdp-act-2023:sec_23__subsec_2": {"cite": "DPDP Act s.23(2)", "head": "", "text": "No act or proceeding of the Board shall be invalid merely by reason of— any vacancy in or any defect in the constitution of the Board; any defect in the appointment of a person acting as the Chairperson or other Member of the Board; or any irregularity in the procedure of the Board, which does not affect the merits of the case."}, "dpdp-act-2023:sec_23__subsec_2__cl_a": {"cite": "DPDP Act s.23(2)(a)", "head": "", "text": "any vacancy in or any defect in the constitution of the Board;"}, "dpdp-act-2023:sec_23__subsec_2__cl_b": {"cite": "DPDP Act s.23(2)(b)", "head": "", "text": "any defect in the appointment of a person acting as the Chairperson or other Member of the Board; or"}, "dpdp-act-2023:sec_23__subsec_2__cl_c": {"cite": "DPDP Act s.23(2)(c)", "head": "", "text": "any irregularity in the procedure of the Board, which does not affect the merits of the case."}, "dpdp-act-2023:sec_23__subsec_3": {"cite": "DPDP Act s.23(3)", "head": "", "text": "When the Chairperson is unable to discharge her functions owing to absence, illness or any other cause, the senior-most Member shall discharge the functions of the Chairperson until the date on which the Chairperson resumes her duties."}, "dpdp-act-2023:sec_24": {"cite": "DPDP Act s.24", "head": "Officers and employees of Board", "text": "The Board may, with previous approval of the Central Government, appoint such officers and employees as it may deem necessary for the efficient discharge of its functions under the provisions of this Act, on such terms and conditions of appointment and service as may be prescribed."}, "dpdp-act-2023:sec_25": {"cite": "DPDP Act s.25", "head": "Members and officers to be public servants", "text": "The Chairperson, Members, officers and employees of the Board shall be deemed, when acting or purporting to act in pursuance of provisions of this Act, to be public servants within the meaning of section 21 of the Indian Penal Code."}, "dpdp-act-2023:sec_26": {"cite": "DPDP Act s.26", "head": "Powers of Chairperson", "text": "The Chairperson shall exercise the following powers, namely:— general superintendence and giving direction in respect of all administrative matters of the Board; authorise any officer of the Board to scrutinise any intimation, complaint, reference or correspondence addressed to the Board; and authorise performance of any of the functions of the Board and conduct any of its proceedings, by an individual Member or groups of Members and to allocate proceedings among them."}, "dpdp-act-2023:sec_26__cl_a": {"cite": "DPDP Act s.26(a)", "head": "", "text": "general superintendence and giving direction in respect of all administrative matters of the Board;"}, "dpdp-act-2023:sec_26__cl_b": {"cite": "DPDP Act s.26(b)", "head": "", "text": "authorise any officer of the Board to scrutinise any intimation, complaint, reference or correspondence addressed to the Board; and"}, "dpdp-act-2023:sec_26__cl_c": {"cite": "DPDP Act s.26(c)", "head": "", "text": "authorise performance of any of the functions of the Board and conduct any of its proceedings, by an individual Member or groups of Members and to allocate proceedings among them."}, "dpdp-act-2023:chp_VI": {"cite": "DPDP Act Chapter VI", "head": "POWERS, FUNCTIONS AND PROCEDURE TO BE FOLLOWED BY BOARD", "text": "Powers and functions of Board The Board shall exercise and perform the following powers and functions, namely:— on receipt of an intimation of personal data breach under sub-section (6) of section 8, to direct any urgent remedial or mitigation measures in the event of a personal data breach, and to inquire into such personal data breach and impose penalty as provided in this Act; on a complaint made by a Data Principal in respect of a personal data breach or a breach in observance by a Data Fiduciary of its obligations in relation to her personal data or the exercise of her rights under the pr…"}, "dpdp-act-2023:sec_27": {"cite": "DPDP Act s.27", "head": "Powers and functions of Board", "text": "The Board shall exercise and perform the following powers and functions, namely:— on receipt of an intimation of personal data breach under sub-section (6) of section 8, to direct any urgent remedial or mitigation measures in the event of a personal data breach, and to inquire into such personal data breach and impose penalty as provided in this Act; on a complaint made by a Data Principal in respect of a personal data breach or a breach in observance by a Data Fiduciary of its obligations in relation to her personal data or the exercise of her rights under the provisions of this Act, or on a …"}, "dpdp-act-2023:sec_27__subsec_1": {"cite": "DPDP Act s.27(1)", "head": "", "text": "The Board shall exercise and perform the following powers and functions, namely:— on receipt of an intimation of personal data breach under sub-section (6) of section 8, to direct any urgent remedial or mitigation measures in the event of a personal data breach, and to inquire into such personal data breach and impose penalty as provided in this Act; on a complaint made by a Data Principal in respect of a personal data breach or a breach in observance by a Data Fiduciary of its obligations in relation to her personal data or the exercise of her rights under the provisions of this Act, or on a …"}, "dpdp-act-2023:sec_27__subsec_1__cl_a": {"cite": "DPDP Act s.27(1)(a)", "head": "", "text": "on receipt of an intimation of personal data breach under sub-section (6) of section 8, to direct any urgent remedial or mitigation measures in the event of a personal data breach, and to inquire into such personal data breach and impose penalty as provided in this Act;"}, "dpdp-act-2023:sec_27__subsec_1__cl_b": {"cite": "DPDP Act s.27(1)(b)", "head": "", "text": "on a complaint made by a Data Principal in respect of a personal data breach or a breach in observance by a Data Fiduciary of its obligations in relation to her personal data or the exercise of her rights under the provisions of this Act, or on a reference made to it by the Central Government or a State Government, or in compliance of the directions of any court, to inquire into such breach and impose penalty as provided in this Act;"}, "dpdp-act-2023:sec_27__subsec_1__cl_c": {"cite": "DPDP Act s.27(1)(c)", "head": "", "text": "on a complaint made by a Data Principal in respect of a breach in observance by a Consent Manager of its obligations in relation to her personal data, to inquire into such breach and impose penalty as provided in this Act;"}, "dpdp-act-2023:sec_27__subsec_1__cl_d": {"cite": "DPDP Act s.27(1)(d)", "head": "", "text": "on receipt of an intimation of breach of any condition of registration of a Consent Manager, to inquire into such breach and impose penalty as provided in this Act; and"}, "dpdp-act-2023:sec_27__subsec_1__cl_e": {"cite": "DPDP Act s.27(1)(e)", "head": "", "text": "on a reference made by the Central Government in respect of the breach in observance of the provisions of sub-section (2) of section 37 by an intermediary, to inquire into such breach and impose penalty as provided in this Act."}, "dpdp-act-2023:sec_27__subsec_2": {"cite": "DPDP Act s.27(2)", "head": "", "text": "The Board may, for the effective discharge of its functions under the provisions of this Act, after giving the person concerned an opportunity of being heard and after recording reasons in writing, issue such directions as it may consider necessary to such person, who shall be bound to comply with the same."}, "dpdp-act-2023:sec_27__subsec_3": {"cite": "DPDP Act s.27(3)", "head": "", "text": "The Board may, on a representation made to it by a person affected by a direction issued under sub-section (1) or sub-section (2), or on a reference made by the Central Government, modify, suspend, withdraw or cancel such direction and, while doing so, impose such conditions as it may deem fit, subject to which the modification, suspension, withdrawal or cancellation shall have effect."}, "dpdp-act-2023:sec_28": {"cite": "DPDP Act s.28", "head": "Procedure to be followed by Board", "text": "The Board shall function as an independent body and shall, as far as practicable, function as a digital office, with the receipt of complaints and the allocation, hearing and pronouncement of decisions in respect of the same being digital by design, and adopt such techno-legal measures as may be prescribed. The Board may, on receipt of an intimation or complaint or reference or directions as referred to in sub-section (1) of section 27, take action in accordance with the provisions of this Act and the rules made thereunder. The Board shall determine whether there are sufficient grounds to proc…"}, "dpdp-act-2023:sec_28__subsec_1": {"cite": "DPDP Act s.28(1)", "head": "", "text": "The Board shall function as an independent body and shall, as far as practicable, function as a digital office, with the receipt of complaints and the allocation, hearing and pronouncement of decisions in respect of the same being digital by design, and adopt such techno-legal measures as may be prescribed."}, "dpdp-act-2023:sec_28__subsec_2": {"cite": "DPDP Act s.28(2)", "head": "", "text": "The Board may, on receipt of an intimation or complaint or reference or directions as referred to in sub-section (1) of section 27, take action in accordance with the provisions of this Act and the rules made thereunder."}, "dpdp-act-2023:sec_28__subsec_3": {"cite": "DPDP Act s.28(3)", "head": "", "text": "The Board shall determine whether there are sufficient grounds to proceed with an inquiry."}, "dpdp-act-2023:sec_28__subsec_4": {"cite": "DPDP Act s.28(4)", "head": "", "text": "In case the Board determines that there are insufficient grounds, it may, for reasons to be recorded in writing, close the proceedings."}, "dpdp-act-2023:sec_28__subsec_5": {"cite": "DPDP Act s.28(5)", "head": "", "text": "In case the Board determines that there are sufficient grounds to proceed with inquiry, it may, for reasons to be recorded in writing, inquire into the affairs of any person for ascertaining whether such person is complying with or has complied with the provisions of this Act."}, "dpdp-act-2023:sec_28__subsec_6": {"cite": "DPDP Act s.28(6)", "head": "", "text": "The Board shall conduct such inquiry following the principles of natural justice and shall record reasons for its actions during the course of such inquiry."}, "dpdp-act-2023:sec_28__subsec_7": {"cite": "DPDP Act s.28(7)", "head": "", "text": "For the purposes of discharging its functions under this Act, the Board shall have the same powers as are vested in a civil court under the Code of Civil Procedure, 1908, in respect of matters relating to— summoning and enforcing the attendance of any person and examining her on oath; receiving evidence of affidavit requiring the discovery and production of documents; inspecting any data, book, document, register, books of account or any other document; and such other matters as may be prescribed."}, "dpdp-act-2023:sec_28__subsec_7__cl_a": {"cite": "DPDP Act s.28(7)(a)", "head": "", "text": "summoning and enforcing the attendance of any person and examining her on oath;"}, "dpdp-act-2023:sec_28__subsec_7__cl_b": {"cite": "DPDP Act s.28(7)(b)", "head": "", "text": "receiving evidence of affidavit requiring the discovery and production of documents;"}, "dpdp-act-2023:sec_28__subsec_7__cl_c": {"cite": "DPDP Act s.28(7)(c)", "head": "", "text": "inspecting any data, book, document, register, books of account or any other document; and"}, "dpdp-act-2023:sec_28__subsec_7__cl_d": {"cite": "DPDP Act s.28(7)(d)", "head": "", "text": "such other matters as may be prescribed."}, "dpdp-act-2023:sec_28__subsec_8": {"cite": "DPDP Act s.28(8)", "head": "", "text": "The Board or its officers shall not prevent access to any premises or take into custody any equipment or any item that may adversely affect the day-to-day functioning of a person."}, "dpdp-act-2023:sec_28__subsec_9": {"cite": "DPDP Act s.28(9)", "head": "", "text": "The Board may require the services of any police officer or any officer of the Central Government or a State Government to assist it for the purposes of this section and it shall be the duty of every such officer to comply with such requisition."}, "dpdp-act-2023:sec_28__subsec_10": {"cite": "DPDP Act s.28(10)", "head": "", "text": "During the course of the inquiry, if the Board considers it necessary, it may for reasons to be recorded in writing, issue interim orders after giving the person concerned an opportunity of being heard."}, "dpdp-act-2023:sec_28__subsec_11": {"cite": "DPDP Act s.28(11)", "head": "", "text": "On completion of the inquiry and after giving the person concerned an opportunity of being heard, the Board may for reasons to be recorded in writing, either close the proceedings or proceed in accordance with section 33."}, "dpdp-act-2023:sec_28__subsec_12": {"cite": "DPDP Act s.28(12)", "head": "", "text": "At any stage after receipt of a complaint, if the Board is of the opinion that the complaint is false or frivolous, it may issue a warning or impose costs on the complainant."}, "dpdp-act-2023:chp_VII": {"cite": "DPDP Act Chapter VII", "head": "APPEAL AND ALTERNATE DISPUTE RESOLUTION", "text": "Appeal to Appellate Tribunal Any person aggrieved by an order or direction made by the Board under this Act may prefer an appeal before the Appellate Tribunal. Every appeal under sub-section (1) shall be filed within a period of sixty days from the date of receipt of the order or direction appealed against and it shall be in such form and manner and shall be accompanied by such fee as may be prescribed. The Appellate Tribunal may entertain an appeal after the expiry of the period specified in sub-section (2), if it is satisfied that there was sufficient cause for not preferring the appeal with…"}, "dpdp-act-2023:sec_29": {"cite": "DPDP Act s.29", "head": "Appeal to Appellate Tribunal", "text": "Any person aggrieved by an order or direction made by the Board under this Act may prefer an appeal before the Appellate Tribunal. Every appeal under sub-section (1) shall be filed within a period of sixty days from the date of receipt of the order or direction appealed against and it shall be in such form and manner and shall be accompanied by such fee as may be prescribed. The Appellate Tribunal may entertain an appeal after the expiry of the period specified in sub-section (2), if it is satisfied that there was sufficient cause for not preferring the appeal within that period. On receipt of…"}, "dpdp-act-2023:sec_29__subsec_1": {"cite": "DPDP Act s.29(1)", "head": "", "text": "Any person aggrieved by an order or direction made by the Board under this Act may prefer an appeal before the Appellate Tribunal."}, "dpdp-act-2023:sec_29__subsec_2": {"cite": "DPDP Act s.29(2)", "head": "", "text": "Every appeal under sub-section (1) shall be filed within a period of sixty days from the date of receipt of the order or direction appealed against and it shall be in such form and manner and shall be accompanied by such fee as may be prescribed."}, "dpdp-act-2023:sec_29__subsec_3": {"cite": "DPDP Act s.29(3)", "head": "", "text": "The Appellate Tribunal may entertain an appeal after the expiry of the period specified in sub-section (2), if it is satisfied that there was sufficient cause for not preferring the appeal within that period."}, "dpdp-act-2023:sec_29__subsec_4": {"cite": "DPDP Act s.29(4)", "head": "", "text": "On receipt of an appeal under sub-section (1), the Appellate Tribunal may, after giving the parties to the appeal, an opportunity of being heard, pass such orders thereon as it thinks fit, confirming, modifying or setting aside the order appealed against."}, "dpdp-act-2023:sec_29__subsec_5": {"cite": "DPDP Act s.29(5)", "head": "", "text": "The Appellate Tribunal shall send a copy of every order made by it to the Board and to the parties to the appeal."}, "dpdp-act-2023:sec_29__subsec_6": {"cite": "DPDP Act s.29(6)", "head": "", "text": "The appeal filed before the Appellate Tribunal under sub-section (1) shall be dealt with by it as expeditiously as possible and endeavour shall be made by it to dispose of the appeal finally within six months from the date on which the appeal is presented to it."}, "dpdp-act-2023:sec_29__subsec_7": {"cite": "DPDP Act s.29(7)", "head": "", "text": "Where any appeal under sub-section (6) could not be disposed of within the period of six months, the Appellate Tribunal shall record its reasons in writing for not disposing of the appeal within that period."}, "dpdp-act-2023:sec_29__subsec_8": {"cite": "DPDP Act s.29(8)", "head": "", "text": "Without prejudice to the provisions of section 14A and section 16 of the Telecom Regulatory Authority of India Act, 1997, the Appellate Tribunal shall deal with an appeal under this section in accordance with such procedure as may be prescribed."}, "dpdp-act-2023:sec_29__subsec_9": {"cite": "DPDP Act s.29(9)", "head": "", "text": "Where an appeal is filed against the orders of the Appellate Tribunal under this Act, the provisions of section 18 of the Telecom Regulatory Authority of India Act, 1997 shall apply."}, "dpdp-act-2023:sec_29__subsec_10": {"cite": "DPDP Act s.29(10)", "head": "", "text": "In respect of appeals filed under the provisions of this Act, the Appellate Tribunal shall, as far as practicable, function as a digital office, with the receipt of appeal, hearing and pronouncement of decisions in respect of the same being digital by design."}, "dpdp-act-2023:sec_30": {"cite": "DPDP Act s.30", "head": "Orders passed by Appellate Tribunal to be executable as decree", "text": "An order passed by the Appellate Tribunal under this Act shall be executable by it as a decree of civil court, and for this purpose, the Appellate Tribunal shall have all the powers of a civil court. Notwithstanding anything contained in sub-section (1), the Appellate Tribunal may transmit any order made by it to a civil court having local jurisdiction and such civil court shall execute the order as if it were a decree made by that court."}, "dpdp-act-2023:sec_30__subsec_1": {"cite": "DPDP Act s.30(1)", "head": "", "text": "An order passed by the Appellate Tribunal under this Act shall be executable by it as a decree of civil court, and for this purpose, the Appellate Tribunal shall have all the powers of a civil court."}, "dpdp-act-2023:sec_30__subsec_2": {"cite": "DPDP Act s.30(2)", "head": "", "text": "Notwithstanding anything contained in sub-section (1), the Appellate Tribunal may transmit any order made by it to a civil court having local jurisdiction and such civil court shall execute the order as if it were a decree made by that court."}, "dpdp-act-2023:sec_31": {"cite": "DPDP Act s.31", "head": "Alternate dispute resolution", "text": "If the Board is of the opinion that any complaint may be resolved by mediation, it may direct the parties concerned to attempt resolution of the dispute through such mediation by such mediator as the parties may mutually agree upon, or as provided for under any law for the time being in force in India."}, "dpdp-act-2023:sec_32": {"cite": "DPDP Act s.32", "head": "Voluntary undertaking", "text": "The Board may accept a voluntary undertaking in respect of any matter related to observance of the provisions of this Act from any person at any stage of a proceeding under section 28. The voluntary undertaking referred to in sub-section (1) may include an undertaking to take such action within such time as may be determined by the Board, or refrain from taking such action, and or publicising such undertaking. The Board may, after accepting the voluntary undertaking and with the consent of the person who gave the voluntary undertaking vary the terms included in the voluntary undertaking. The a…"}, "dpdp-act-2023:sec_32__subsec_1": {"cite": "DPDP Act s.32(1)", "head": "", "text": "The Board may accept a voluntary undertaking in respect of any matter related to observance of the provisions of this Act from any person at any stage of a proceeding under section 28."}, "dpdp-act-2023:sec_32__subsec_2": {"cite": "DPDP Act s.32(2)", "head": "", "text": "The voluntary undertaking referred to in sub-section (1) may include an undertaking to take such action within such time as may be determined by the Board, or refrain from taking such action, and or publicising such undertaking."}, "dpdp-act-2023:sec_32__subsec_3": {"cite": "DPDP Act s.32(3)", "head": "", "text": "The Board may, after accepting the voluntary undertaking and with the consent of the person who gave the voluntary undertaking vary the terms included in the voluntary undertaking."}, "dpdp-act-2023:sec_32__subsec_4": {"cite": "DPDP Act s.32(4)", "head": "", "text": "The acceptance of the voluntary undertaking by the Board shall constitute a bar on proceedings under the provisions of this Act as regards the contents of the voluntary undertaking, except in cases covered by sub-section (5)."}, "dpdp-act-2023:sec_32__subsec_5": {"cite": "DPDP Act s.32(5)", "head": "", "text": "Where a person fails to adhere to any term of the voluntary undertaking accepted by the Board, such breach shall be deemed to be breach of the provisions of this Act and the Board may, after giving such person an opportunity of being heard, proceed in accordance with the provisions of section 33."}, "dpdp-act-2023:chp_VIII": {"cite": "DPDP Act Chapter VIII", "head": "PENALTIES AND ADJUDICATION", "text": "Penalties If the Board determines on conclusion of an inquiry that breach of the provisions of this Act or the rules made thereunder by a person is significant, it may, after giving the person an opportunity of being heard, impose such monetary penalty specified in the Schedule. While determining the amount of monetary penalty to be imposed under sub-section (1), the Board shall have regard to the following matters, namely:— the nature, gravity and duration of the breach; the type and nature of the personal data affected by the breach; repetitive nature of the breach; whether the person, as a …"}, "dpdp-act-2023:sec_33": {"cite": "DPDP Act s.33", "head": "Penalties", "text": "If the Board determines on conclusion of an inquiry that breach of the provisions of this Act or the rules made thereunder by a person is significant, it may, after giving the person an opportunity of being heard, impose such monetary penalty specified in the Schedule. While determining the amount of monetary penalty to be imposed under sub-section (1), the Board shall have regard to the following matters, namely:— the nature, gravity and duration of the breach; the type and nature of the personal data affected by the breach; repetitive nature of the breach; whether the person, as a result of …"}, "dpdp-act-2023:sec_33__subsec_1": {"cite": "DPDP Act s.33(1)", "head": "", "text": "If the Board determines on conclusion of an inquiry that breach of the provisions of this Act or the rules made thereunder by a person is significant, it may, after giving the person an opportunity of being heard, impose such monetary penalty specified in the Schedule."}, "dpdp-act-2023:sec_33__subsec_2": {"cite": "DPDP Act s.33(2)", "head": "", "text": "While determining the amount of monetary penalty to be imposed under sub-section (1), the Board shall have regard to the following matters, namely:— the nature, gravity and duration of the breach; the type and nature of the personal data affected by the breach; repetitive nature of the breach; whether the person, as a result of the breach, has realised a gain or avoided any loss; whether the person took any action to mitigate the effects and consequences of the breach, and the timeliness and effectiveness of such action; whether the monetary penalty to be imposed is proportionate and effective…"}, "dpdp-act-2023:sec_33__subsec_2__cl_a": {"cite": "DPDP Act s.33(2)(a)", "head": "", "text": "the nature, gravity and duration of the breach;"}, "dpdp-act-2023:sec_33__subsec_2__cl_b": {"cite": "DPDP Act s.33(2)(b)", "head": "", "text": "the type and nature of the personal data affected by the breach;"}, "dpdp-act-2023:sec_33__subsec_2__cl_c": {"cite": "DPDP Act s.33(2)(c)", "head": "", "text": "repetitive nature of the breach;"}, "dpdp-act-2023:sec_33__subsec_2__cl_d": {"cite": "DPDP Act s.33(2)(d)", "head": "", "text": "whether the person, as a result of the breach, has realised a gain or avoided any loss;"}, "dpdp-act-2023:sec_33__subsec_2__cl_e": {"cite": "DPDP Act s.33(2)(e)", "head": "", "text": "whether the person took any action to mitigate the effects and consequences of the breach, and the timeliness and effectiveness of such action;"}, "dpdp-act-2023:sec_33__subsec_2__cl_f": {"cite": "DPDP Act s.33(2)(f)", "head": "", "text": "whether the monetary penalty to be imposed is proportionate and effective, having regard to the need to secure observance of and deter breach of the provisions of this Act; and"}, "dpdp-act-2023:sec_33__subsec_2__cl_g": {"cite": "DPDP Act s.33(2)(g)", "head": "", "text": "the likely impact of the imposition of the monetary penalty on the person."}, "dpdp-act-2023:sec_34": {"cite": "DPDP Act s.34", "head": "Crediting sums realised by way of penalties to Consolidated Fund of India", "text": "All sums realised by way of penalties imposed by the Board under this Act, shall be credited to the Consolidated Fund of India."}, "dpdp-act-2023:chp_IX": {"cite": "DPDP Act Chapter IX", "head": "MISCELLANEOUS", "text": "Protection of action taken in good faith No suit, prosecution or other legal proceedings shall lie against the Central Government, the Board, its Chairperson and any Member, officer or employee thereof for anything which is done or intended to be done in good faith under the provisions of this Act or the rules made thereunder. Power to call for information The Central Government may, for the purposes of this Act, require the Board and any Data Fiduciary or intermediary to furnish such information as it may call for. Power of Central Government to issue directions The Central Government or any …"}, "dpdp-act-2023:sec_35": {"cite": "DPDP Act s.35", "head": "Protection of action taken in good faith", "text": "No suit, prosecution or other legal proceedings shall lie against the Central Government, the Board, its Chairperson and any Member, officer or employee thereof for anything which is done or intended to be done in good faith under the provisions of this Act or the rules made thereunder."}, "dpdp-act-2023:sec_36": {"cite": "DPDP Act s.36", "head": "Power to call for information", "text": "The Central Government may, for the purposes of this Act, require the Board and any Data Fiduciary or intermediary to furnish such information as it may call for."}, "dpdp-act-2023:sec_37": {"cite": "DPDP Act s.37", "head": "Power of Central Government to issue directions", "text": "The Central Government or any of its officers specially authorised by it in this behalf may, upon receipt of a reference in writing from the Board that— intimates the imposition of monetary penalty by the Board on a Data Fiduciary in two or more instances; and advises, in the interests of the general public, the blocking for access by the public to any information generated, transmitted, received, stored or hosted, in any computer resource that enables such Data Fiduciary to carry on any activity relating to offering of goods or services to Data Principals within the territory of India, after …"}, "dpdp-act-2023:sec_37__subsec_1": {"cite": "DPDP Act s.37(1)", "head": "", "text": "The Central Government or any of its officers specially authorised by it in this behalf may, upon receipt of a reference in writing from the Board that— intimates the imposition of monetary penalty by the Board on a Data Fiduciary in two or more instances; and advises, in the interests of the general public, the blocking for access by the public to any information generated, transmitted, received, stored or hosted, in any computer resource that enables such Data Fiduciary to carry on any activity relating to offering of goods or services to Data Principals within the territory of India, after …"}, "dpdp-act-2023:sec_37__subsec_1__cl_a": {"cite": "DPDP Act s.37(1)(a)", "head": "", "text": "intimates the imposition of monetary penalty by the Board on a Data Fiduciary in two or more instances; and"}, "dpdp-act-2023:sec_37__subsec_1__cl_b": {"cite": "DPDP Act s.37(1)(b)", "head": "", "text": "advises, in the interests of the general public, the blocking for access by the public to any information generated, transmitted, received, stored or hosted, in any computer resource that enables such Data Fiduciary to carry on any activity relating to offering of goods or services to Data Principals within the territory of India,"}, "dpdp-act-2023:sec_37__subsec_2": {"cite": "DPDP Act s.37(2)", "head": "", "text": "Every intermediary who receives a direction issued under sub-section (1) shall be bound to comply with the same."}, "dpdp-act-2023:sec_37__subsec_3": {"cite": "DPDP Act s.37(3)", "head": "", "text": "For the purposes of this section, the expressions “computer resource”, “information” and “intermediary” shall have the meanings respectively assigned to them in the Information Technology Act, 2000."}, "dpdp-act-2023:sec_38": {"cite": "DPDP Act s.38", "head": "Consistency with other laws", "text": "The provisions of this Act shall be in addition to and not in derogation of any other law for the time being in force. In the event of any conflict between a provision of this Act and a provision of any other law for the time being in force, the provision of this Act shall prevail to the extent of such conflict."}, "dpdp-act-2023:sec_38__subsec_1": {"cite": "DPDP Act s.38(1)", "head": "", "text": "The provisions of this Act shall be in addition to and not in derogation of any other law for the time being in force."}, "dpdp-act-2023:sec_38__subsec_2": {"cite": "DPDP Act s.38(2)", "head": "", "text": "In the event of any conflict between a provision of this Act and a provision of any other law for the time being in force, the provision of this Act shall prevail to the extent of such conflict."}, "dpdp-act-2023:sec_39": {"cite": "DPDP Act s.39", "head": "Bar of jurisdiction", "text": "No civil court shall have the jurisdiction to entertain any suit or proceeding in respect of any matter for which the Board is empowered under the provisions of this Act and no injunction shall be granted by any court or other authority in respect of any action taken or to be taken in pursuance of any power under the provisions of this Act."}, "dpdp-act-2023:sec_40": {"cite": "DPDP Act s.40", "head": "Power to make rules", "text": "The Central Government may, by notification, and subject to the condition of previous publication, make rules not inconsistent with the provisions of this Act, to carry out the purposes of this Act. In particular and without prejudice to the generality of the foregoing power, such rules may provide for all or any of the following matters, namely:— the manner in which the notice given by the Data Fiduciary to a Data Principal shall inform her, under sub-section (1) of section 5; the manner in which the notice given by the Data Fiduciary to a Data Principal shall inform her, under sub-section (2…"}, "dpdp-act-2023:sec_40__subsec_1": {"cite": "DPDP Act s.40(1)", "head": "", "text": "The Central Government may, by notification, and subject to the condition of previous publication, make rules not inconsistent with the provisions of this Act, to carry out the purposes of this Act."}, "dpdp-act-2023:sec_40__subsec_2": {"cite": "DPDP Act s.40(2)", "head": "", "text": "In particular and without prejudice to the generality of the foregoing power, such rules may provide for all or any of the following matters, namely:— the manner in which the notice given by the Data Fiduciary to a Data Principal shall inform her, under sub-section (1) of section 5; the manner in which the notice given by the Data Fiduciary to a Data Principal shall inform her, under sub-section (2) of section 5; the manner of accountability and the obligations of Consent Manager under sub-section (8) of section 6; the manner of registration of Consent Manager and the conditions relating there…"}, "dpdp-act-2023:sec_40__subsec_2__cl_a": {"cite": "DPDP Act s.40(2)(a)", "head": "", "text": "the manner in which the notice given by the Data Fiduciary to a Data Principal shall inform her, under sub-section (1) of section 5;"}, "dpdp-act-2023:sec_40__subsec_2__cl_b": {"cite": "DPDP Act s.40(2)(b)", "head": "", "text": "the manner in which the notice given by the Data Fiduciary to a Data Principal shall inform her, under sub-section (2) of section 5;"}, "dpdp-act-2023:sec_40__subsec_2__cl_c": {"cite": "DPDP Act s.40(2)(c)", "head": "", "text": "the manner of accountability and the obligations of Consent Manager under sub-section (8) of section 6;"}, "dpdp-act-2023:sec_40__subsec_2__cl_d": {"cite": "DPDP Act s.40(2)(d)", "head": "", "text": "the manner of registration of Consent Manager and the conditions relating thereto, under sub-section (9) of section 6;"}, "dpdp-act-2023:sec_40__subsec_2__cl_e": {"cite": "DPDP Act s.40(2)(e)", "head": "", "text": "the subsidy, benefit, service, certificate, licence or permit for the provision or issuance of which, personal data may be processed under clause (b) of section 7;"}, "dpdp-act-2023:sec_40__subsec_2__cl_f": {"cite": "DPDP Act s.40(2)(f)", "head": "", "text": "the form and manner of intimation of personal data breach to the Board under sub-section (6) of section 8;"}, "dpdp-act-2023:sec_40__subsec_2__cl_g": {"cite": "DPDP Act s.40(2)(g)", "head": "", "text": "the time period for the specified purpose to be deemed as no longer being served, under sub-section (8) of section 8;"}, "dpdp-act-2023:sec_40__subsec_2__cl_h": {"cite": "DPDP Act s.40(2)(h)", "head": "", "text": "the manner of publishing the business contact information of a Data Protection Officer under sub-section (9) of section 8;"}, "dpdp-act-2023:sec_40__subsec_2__cl_i": {"cite": "DPDP Act s.40(2)(i)", "head": "", "text": "the manner of obtaining verifiable consent under sub-section (1) of section 9;"}, "dpdp-act-2023:sec_40__subsec_2__cl_j": {"cite": "DPDP Act s.40(2)(j)", "head": "", "text": "the classes of Data Fiduciaries, the purposes of processing of personal data of a child and the conditions relating thereto, under sub-section (4) of section 9;"}, "dpdp-act-2023:sec_40__subsec_2__cl_k": {"cite": "DPDP Act s.40(2)(k)", "head": "", "text": "the other matters comprising the process of Data Protection Impact Assessment under sub-clause (i) of clause (c) of sub-section (2) of section 10;"}, "dpdp-act-2023:sec_40__subsec_2__cl_l": {"cite": "DPDP Act s.40(2)(l)", "head": "", "text": "the other measures that the Significant Data Fiduciary shall undertake under sub-clause (iii) of clause (c) of sub-section (2) of section 10;"}, "dpdp-act-2023:sec_40__subsec_2__cl_m": {"cite": "DPDP Act s.40(2)(m)", "head": "", "text": "the manner in which a Data Principal shall make a request to the Data Fiduciary to obtain information and any other information related to the personal data of such Data Principal and its processing, under sub-section (1) of section 11;"}, "dpdp-act-2023:sec_40__subsec_2__cl_n": {"cite": "DPDP Act s.40(2)(n)", "head": "", "text": "the manner in which a Data Principal shall make a request to the Data Fiduciary for erasure of her personal data under sub-section (3) of section 12;"}, "dpdp-act-2023:sec_40__subsec_2__cl_o": {"cite": "DPDP Act s.40(2)(o)", "head": "", "text": "the period within which the Data Fiduciary shall respond to any grievances under sub-section (2) of section 13;"}, "dpdp-act-2023:sec_40__subsec_2__cl_p": {"cite": "DPDP Act s.40(2)(p)", "head": "", "text": "the manner of nomination of any other individual by the Data Principal under sub-section (1) of section 14;"}, "dpdp-act-2023:sec_40__subsec_2__cl_q": {"cite": "DPDP Act s.40(2)(q)", "head": "", "text": "the standards for processing the personal data for exemption under clause (b) of sub-section (2) of section 17;"}, "dpdp-act-2023:sec_40__subsec_2__cl_r": {"cite": "DPDP Act s.40(2)(r)", "head": "", "text": "the manner of appointment of the Chairperson and other Members of the Board under sub-section (2) of section 19;"}, "dpdp-act-2023:sec_40__subsec_2__cl_s": {"cite": "DPDP Act s.40(2)(s)", "head": "", "text": "the salary, allowances and other terms and conditions of services of the Chairperson and other Members of the Board under sub-section (1) of section 20;"}, "dpdp-act-2023:sec_40__subsec_2__cl_t": {"cite": "DPDP Act s.40(2)(t)", "head": "", "text": "the manner of authentication of orders, directions and instruments under sub-section (1) of section 23;"}, "dpdp-act-2023:sec_40__subsec_2__cl_u": {"cite": "DPDP Act s.40(2)(u)", "head": "", "text": "the terms and conditions of appointment and service of officers and employees of the Board under section 24;"}, "dpdp-act-2023:sec_40__subsec_2__cl_v": {"cite": "DPDP Act s.40(2)(v)", "head": "", "text": "the techno-legal measures to be adopted by the Board under sub-section (1) of section 28;"}, "dpdp-act-2023:sec_40__subsec_2__cl_w": {"cite": "DPDP Act s.40(2)(w)", "head": "", "text": "the other matters under clause (d) of sub-section (7) of section 28;"}, "dpdp-act-2023:sec_40__subsec_2__cl_x": {"cite": "DPDP Act s.40(2)(x)", "head": "", "text": "the form, manner and fee for filing an appeal under sub-section (2) of section 29;"}, "dpdp-act-2023:sec_40__subsec_2__cl_y": {"cite": "DPDP Act s.40(2)(y)", "head": "", "text": "the procedure for dealing an appeal under sub-section (8) of section 29;"}, "dpdp-act-2023:sec_40__subsec_2__cl_z": {"cite": "DPDP Act s.40(2)(z)", "head": "", "text": "any other matter which is to be or may be prescribed or in respect of which provision is to be, or may be, made by rules."}, "dpdp-act-2023:sec_41": {"cite": "DPDP Act s.41", "head": "Laying of rules and certain notifications", "text": "Every rule made and every notification issued under section 16 and section 42 of this Act shall be laid, as soon as may be after it is made, before each House of Parliament, while it is in session, for a total period of thirty days which may be comprised in one session or in two or more successive sessions, and if before the expiry of the session immediately following the session or the successive sessions aforesaid, both Houses agree in making any modification in the rule or notification or both Houses agree that the rule or notification should not be made or issued, the rule or notification …"}, "dpdp-act-2023:sec_42": {"cite": "DPDP Act s.42", "head": "Power to amend Schedule", "text": "The Central Government may, by notification, amend the Schedule, subject to the restriction that no such notification shall have the effect of increasing any penalty specified therein to more than twice of what was specified in it when this Act was originally enacted. Any amendment notified under sub-section (1) shall have effect as if enacted in this Act and shall come into force on the date of the notification."}, "dpdp-act-2023:sec_42__subsec_1": {"cite": "DPDP Act s.42(1)", "head": "", "text": "The Central Government may, by notification, amend the Schedule, subject to the restriction that no such notification shall have the effect of increasing any penalty specified therein to more than twice of what was specified in it when this Act was originally enacted."}, "dpdp-act-2023:sec_42__subsec_2": {"cite": "DPDP Act s.42(2)", "head": "", "text": "Any amendment notified under sub-section (1) shall have effect as if enacted in this Act and shall come into force on the date of the notification."}, "dpdp-act-2023:sec_43": {"cite": "DPDP Act s.43", "head": "Power to remove difficulties", "text": "If any difficulty arises in giving effect to the provisions of this Act, the Central Government may, by order published in the Official Gazette, make such provisions not inconsistent with the provisions of this Act as may appear to it to be necessary or expedient for removing the difficulty. No order as referred to in sub-section (1) shall be made after the expiry of three years from the date of commencement of this Act. Every order made under this section shall be laid, as soon as may be after it is made, before each House of Parliament."}, "dpdp-act-2023:sec_43__subsec_1": {"cite": "DPDP Act s.43(1)", "head": "", "text": "If any difficulty arises in giving effect to the provisions of this Act, the Central Government may, by order published in the Official Gazette, make such provisions not inconsistent with the provisions of this Act as may appear to it to be necessary or expedient for removing the difficulty."}, "dpdp-act-2023:sec_43__subsec_2": {"cite": "DPDP Act s.43(2)", "head": "", "text": "No order as referred to in sub-section (1) shall be made after the expiry of three years from the date of commencement of this Act."}, "dpdp-act-2023:sec_43__subsec_3": {"cite": "DPDP Act s.43(3)", "head": "", "text": "Every order made under this section shall be laid, as soon as may be after it is made, before each House of Parliament."}, "dpdp-act-2023:sec_44": {"cite": "DPDP Act s.44", "head": "Amendments to certain Acts", "text": "In section 14 of the Telecom Regulatory Authority of India Act, 1997, in clause (c), for sub-clauses (i) and (ii), the following sub-clauses shall be substituted, namely:— “(i) the Appellate Tribunal under the Information Technology Act, 2000; (ii) the Appellate Tribunal under the Airports Economic Regulatory Authority of India Act, 2008; and (iii) the Appellate Tribunal under the Digital Personal Data Protection Act, 2023.”. The Information Technology Act, 2000 shall be amended in the following manner, namely:— section 43A shall be omitted; in section 81, in the proviso, after the words and f…"}, "dpdp-act-2023:sec_44__subsec_1": {"cite": "DPDP Act s.44(1)", "head": "", "text": "In section 14 of the Telecom Regulatory Authority of India Act, 1997, in clause (c), for sub-clauses (i) and (ii), the following sub-clauses shall be substituted, namely:— “(i) the Appellate Tribunal under the Information Technology Act, 2000; (ii) the Appellate Tribunal under the Airports Economic Regulatory Authority of India Act, 2008; and (iii) the Appellate Tribunal under the Digital Personal Data Protection Act, 2023.”."}, "dpdp-act-2023:sec_44__subsec_2": {"cite": "DPDP Act s.44(2)", "head": "", "text": "The Information Technology Act, 2000 shall be amended in the following manner, namely:— section 43A shall be omitted; in section 81, in the proviso, after the words and figures “the Patents Act, 1970”, the words and figures “or the Digital Personal Data Protection Act, 2023” shall be inserted; and in section 87, in sub-section (2), clause (ob) shall be omitted."}, "dpdp-act-2023:sec_44__subsec_2__cl_a": {"cite": "DPDP Act s.44(2)(a)", "head": "", "text": "section 43A shall be omitted;"}, "dpdp-act-2023:sec_44__subsec_2__cl_b": {"cite": "DPDP Act s.44(2)(b)", "head": "", "text": "in section 81, in the proviso, after the words and figures “the Patents Act, 1970”, the words and figures “or the Digital Personal Data Protection Act, 2023” shall be inserted; and"}, "dpdp-act-2023:sec_44__subsec_2__cl_c": {"cite": "DPDP Act s.44(2)(c)", "head": "", "text": "in section 87, in sub-section (2), clause (ob) shall be omitted."}, "dpdp-act-2023:sec_44__subsec_3": {"cite": "DPDP Act s.44(3)", "head": "", "text": "In section 8 of the Right to Information Act, 2005, in sub-section (1), for clause (j), the following clause shall be substituted, namely:— “(j) information which relates to personal information;”."}, "dpdp-act-2023:sched_1": {"cite": "DPDP Act Schedule", "head": "", "text": "THE SCHEDULE [See section 33 (1)] Sl. No. Breach of provisions of this Act or rules made thereunder Penalty (1) (2) (3) 1. Breach in observing the obligation of Data Fiduciary to take reasonable security safeguards to prevent personal data breach under sub-section (5) of section 8. May extend to two hundred and fifty crore rupees. 2. Breach in observing the obligation to give the Board or affected Data Principal notice of a personal data breach under sub-section (6) of section 8. May extend to two hundred crore rupees. 3. Breach in observance of additional obligations in relation to children u…"}, "dpdp-act-2023:sched_1__table_1": {"cite": "DPDP Act Schedule", "head": "", "text": "Sl. No. Breach of provisions of this Act or rules made thereunder Penalty (1) (2) (3) 1. Breach in observing the obligation of Data Fiduciary to take reasonable security safeguards to prevent personal data breach under sub-section (5) of section 8. May extend to two hundred and fifty crore rupees. 2. Breach in observing the obligation to give the Board or affected Data Principal notice of a personal data breach under sub-section (6) of section 8. May extend to two hundred crore rupees. 3. Breach in observance of additional obligations in relation to children under section 9. May extend to two …"}, "dpdp-rules-2025:rule_1": {"cite": "DPDP Rules r.1", "head": "Short title and commencement", "text": "These rules may be called the Digital Personal Data Protection Rules, 2025. Rules 1, 2 and 17 to 21 shall come into force on the date of their publication in the Official Gazette. Rule 4 shall come into force one year after the date of publication in the Official Gazette. Rules 3, 5 to 16, 22 and 23 shall come into force eighteen months after the date of publication in the Official Gazette."}, "dpdp-rules-2025:rule_1__subrule_1": {"cite": "DPDP Rules r.1(1)", "head": "", "text": "These rules may be called the Digital Personal Data Protection Rules, 2025."}, "dpdp-rules-2025:rule_1__subrule_2": {"cite": "DPDP Rules r.1(2)", "head": "", "text": "Rules 1, 2 and 17 to 21 shall come into force on the date of their publication in the Official Gazette."}, "dpdp-rules-2025:rule_1__subrule_3": {"cite": "DPDP Rules r.1(3)", "head": "", "text": "Rule 4 shall come into force one year after the date of publication in the Official Gazette."}, "dpdp-rules-2025:rule_1__subrule_4": {"cite": "DPDP Rules r.1(4)", "head": "", "text": "Rules 3, 5 to 16, 22 and 23 shall come into force eighteen months after the date of publication in the Official Gazette."}, "dpdp-rules-2025:rule_2": {"cite": "DPDP Rules r.2", "head": "Definitions", "text": "In these rules, unless the context otherwise requires, – “Act” means the Digital Personal Data Protection Act, 2023 (22 of 2023); “techno-legal measures” means as referred to under rules 20 and 22; “user account” means the online account registered by the Data Principal with the Data Fiduciary, and includes any profiles, pages, handles, email address, mobile number and other similar presences by means of which such Data Principal is able to access the services of such Data Fiduciary; and “verifiable consent” means a consent as specified in rule 10 or 11. The words and expressions used in these…"}, "dpdp-rules-2025:rule_2__subrule_1": {"cite": "DPDP Rules r.2(1)", "head": "", "text": "In these rules, unless the context otherwise requires, – “Act” means the Digital Personal Data Protection Act, 2023 (22 of 2023); “techno-legal measures” means as referred to under rules 20 and 22; “user account” means the online account registered by the Data Principal with the Data Fiduciary, and includes any profiles, pages, handles, email address, mobile number and other similar presences by means of which such Data Principal is able to access the services of such Data Fiduciary; and “verifiable consent” means a consent as specified in rule 10 or 11."}, "dpdp-rules-2025:rule_2__subrule_1__cl_a": {"cite": "DPDP Rules r.2(1)(a)", "head": "", "text": "“Act” means the Digital Personal Data Protection Act, 2023 (22 of 2023);"}, "dpdp-rules-2025:rule_2__subrule_1__cl_b": {"cite": "DPDP Rules r.2(1)(b)", "head": "", "text": "“techno-legal measures” means as referred to under rules 20 and 22;"}, "dpdp-rules-2025:rule_2__subrule_1__cl_c": {"cite": "DPDP Rules r.2(1)(c)", "head": "", "text": "“user account” means the online account registered by the Data Principal with the Data Fiduciary, and includes any profiles, pages, handles, email address, mobile number and other similar presences by means of which such Data Principal is able to access the services of such Data Fiduciary; and"}, "dpdp-rules-2025:rule_2__subrule_1__cl_d": {"cite": "DPDP Rules r.2(1)(d)", "head": "", "text": "“verifiable consent” means a consent as specified in rule 10 or 11."}, "dpdp-rules-2025:rule_2__subrule_2": {"cite": "DPDP Rules r.2(2)", "head": "", "text": "The words and expressions used in these rules and not defined, but defined in the Act, shall have the same meanings respectively assigned to them in the Act."}, "dpdp-rules-2025:rule_3": {"cite": "DPDP Rules r.3", "head": "Notice given by Data Fiduciary to Data Principal", "text": "The notice given by the Data Fiduciary to the Data Principal shall— be presented and be understandable independently of any other information that has been, is or may be made available by such Data Fiduciary; give, in clear and plain language, a fair account of the details necessary to enable the Data Principal to give specific and informed consent for the processing of her personal data, which shall include, at the minimum, — an itemised description of such personal data; and the specified purpose or purposes of, and specific description of the goods or services to be provided or uses to be e…"}, "dpdp-rules-2025:rule_3__cl_a": {"cite": "DPDP Rules r.3(a)", "head": "", "text": "be presented and be understandable independently of any other information that has been, is or may be made available by such Data Fiduciary;"}, "dpdp-rules-2025:rule_3__cl_b": {"cite": "DPDP Rules r.3(b)", "head": "", "text": "give, in clear and plain language, a fair account of the details necessary to enable the Data Principal to give specific and informed consent for the processing of her personal data, which shall include, at the minimum, — an itemised description of such personal data; and the specified purpose or purposes of, and specific description of the goods or services to be provided or uses to be enabled by, such processing; and"}, "dpdp-rules-2025:rule_3__cl_b__subcl_i": {"cite": "DPDP Rules r.3(b)(i)", "head": "", "text": "an itemised description of such personal data; and"}, "dpdp-rules-2025:rule_3__cl_b__subcl_ii": {"cite": "DPDP Rules r.3(b)(ii)", "head": "", "text": "the specified purpose or purposes of, and specific description of the goods or services to be provided or uses to be enabled by, such processing; and"}, "dpdp-rules-2025:rule_3__cl_c": {"cite": "DPDP Rules r.3(c)", "head": "", "text": "give, the particular communication link for accessing the website or app, or both, of such Data Fiduciary, and a description of other means, if any, using which such Data Principal may— withdraw her consent, with the ease of doing so being comparable to that with which such consent was given; exercise her rights under the Act; and make a complaint to the Board."}, "dpdp-rules-2025:rule_3__cl_c__subcl_i": {"cite": "DPDP Rules r.3(c)(i)", "head": "", "text": "withdraw her consent, with the ease of doing so being comparable to that with which such consent was given;"}, "dpdp-rules-2025:rule_3__cl_c__subcl_ii": {"cite": "DPDP Rules r.3(c)(ii)", "head": "", "text": "exercise her rights under the Act; and"}, "dpdp-rules-2025:rule_3__cl_c__subcl_iii": {"cite": "DPDP Rules r.3(c)(iii)", "head": "", "text": "make a complaint to the Board."}, "dpdp-rules-2025:rule_4": {"cite": "DPDP Rules r.4", "head": "Registration and obligations of Consent Manager", "text": "A person who fulfils the conditions for registration of Consent Managers set out in Part A of First Schedule may apply to the Board for registration as a Consent Manager by furnishing such particulars and such other information and documents as the Board may publish in this behalf on its website. On receipt of such application, the Board may make such inquiry as it may deem fit to satisfy itself regarding fulfilment of the conditions set out in Part A of First Schedule, and if it— is satisfied, register the applicant as a Consent Manager, under intimation to the applicant, and publish on its w…"}, "dpdp-rules-2025:rule_4__subrule_1": {"cite": "DPDP Rules r.4(1)", "head": "", "text": "A person who fulfils the conditions for registration of Consent Managers set out in Part A of First Schedule may apply to the Board for registration as a Consent Manager by furnishing such particulars and such other information and documents as the Board may publish in this behalf on its website."}, "dpdp-rules-2025:rule_4__subrule_2": {"cite": "DPDP Rules r.4(2)", "head": "", "text": "On receipt of such application, the Board may make such inquiry as it may deem fit to satisfy itself regarding fulfilment of the conditions set out in Part A of First Schedule, and if it— is satisfied, register the applicant as a Consent Manager, under intimation to the applicant, and publish on its website the particulars of such Consent Manager; or is not satisfied, reject the application and communicate the reasons for the rejection to the applicant."}, "dpdp-rules-2025:rule_4__subrule_2__cl_a": {"cite": "DPDP Rules r.4(2)(a)", "head": "", "text": "is satisfied, register the applicant as a Consent Manager, under intimation to the applicant, and publish on its website the particulars of such Consent Manager; or"}, "dpdp-rules-2025:rule_4__subrule_2__cl_b": {"cite": "DPDP Rules r.4(2)(b)", "head": "", "text": "is not satisfied, reject the application and communicate the reasons for the rejection to the applicant."}, "dpdp-rules-2025:rule_4__subrule_3": {"cite": "DPDP Rules r.4(3)", "head": "", "text": "The Consent Manager shall have obligations as specified in Part B of First Schedule."}, "dpdp-rules-2025:rule_4__subrule_4": {"cite": "DPDP Rules r.4(4)", "head": "", "text": "If the Board is of the opinion that a Consent Manager is not adhering to the conditions and obligations under this rule,it may, after giving an opportunity of being heard, inform the Consent Manager of such non-adherence and direct the Consent Manager to take measures to ensure adherence."}, "dpdp-rules-2025:rule_4__subrule_5": {"cite": "DPDP Rules r.4(5)", "head": "", "text": "The Board may, if it is satisfied that it is necessary so to do in the interests of Data Principals, after giving the Consent Manager an opportunity of being heard, by order, for reasons to be recorded in writing, — suspend or cancel the registration of such Consent Manager; and give such directions as it may deem fit to that Consent Manager, to protect the interests of the Data Principals."}, "dpdp-rules-2025:rule_4__subrule_5__cl_a": {"cite": "DPDP Rules r.4(5)(a)", "head": "", "text": "suspend or cancel the registration of such Consent Manager; and"}, "dpdp-rules-2025:rule_4__subrule_5__cl_b": {"cite": "DPDP Rules r.4(5)(b)", "head": "", "text": "give such directions as it may deem fit to that Consent Manager, to protect the interests of the Data Principals."}, "dpdp-rules-2025:rule_4__subrule_6": {"cite": "DPDP Rules r.4(6)", "head": "", "text": "The Board may, for the purposes of this rule, require the Consent Manager to furnish such information as the Board may call for."}, "dpdp-rules-2025:rule_5": {"cite": "DPDP Rules r.5", "head": "Processing of personal data for provision or issue of subsidy, benefit, service, certificate, licence or permit by State and its instrumentalities", "text": "Processing the personal data of a Data Principal under this rule shall be done following the standards specified in Second Schedule. In this rule and the Second Schedule, the reference to any subsidy, benefit, service, certificate, licence or permit that is provided or issued— under law shall be construed as a reference to provision or issuance of such subsidy, benefit, service, certificate, licence or permit in exercise of any power of or the performance of any function by the State or any of its instrumentalities under any law for the time being in force; under policy shall be construed as a…"}, "dpdp-rules-2025:rule_5__subrule_1": {"cite": "DPDP Rules r.5(1)", "head": "", "text": "Processing the personal data of a Data Principal under this rule shall be done following the standards specified in Second Schedule."}, "dpdp-rules-2025:rule_5__subrule_2": {"cite": "DPDP Rules r.5(2)", "head": "", "text": "In this rule and the Second Schedule, the reference to any subsidy, benefit, service, certificate, licence or permit that is provided or issued— under law shall be construed as a reference to provision or issuance of such subsidy, benefit, service, certificate, licence or permit in exercise of any power of or the performance of any function by the State or any of its instrumentalities under any law for the time being in force; under policy shall be construed as a reference to provision or issuance of such subsidy, benefit, service, certificate, licence or permit under any policy or instruction…"}, "dpdp-rules-2025:rule_5__subrule_2__cl_a": {"cite": "DPDP Rules r.5(2)(a)", "head": "", "text": "under law shall be construed as a reference to provision or issuance of such subsidy, benefit, service, certificate, licence or permit in exercise of any power of or the performance of any function by the State or any of its instrumentalities under any law for the time being in force;"}, "dpdp-rules-2025:rule_5__subrule_2__cl_b": {"cite": "DPDP Rules r.5(2)(b)", "head": "", "text": "under policy shall be construed as a reference to provision or issuance of such subsidy, benefit, service, certificate, licence or permit under any policy or instruction issued by the Central Government or a State Government in exercise of its executive power; and"}, "dpdp-rules-2025:rule_5__subrule_2__cl_c": {"cite": "DPDP Rules r.5(2)(c)", "head": "", "text": "using public funds shall be construed as a reference to provision or issuance of such subsidy, benefit, service, certificate, licence or permit by incurring expenditure on the same from, or with accrual of receipts to, — in case of the Central Government or a State Government, the Consolidated Fund of India or the Consolidated Fund of the State or the public account of India or the public account of the State; or in case of any local or other authority within the territory of India or under the control of the Government of India or of any State, the fund or funds of such authority."}, "dpdp-rules-2025:rule_5__subrule_2__cl_c__subcl_i": {"cite": "DPDP Rules r.5(2)(c)(i)", "head": "", "text": "in case of the Central Government or a State Government, the Consolidated Fund of India or the Consolidated Fund of the State or the public account of India or the public account of the State; or"}, "dpdp-rules-2025:rule_5__subrule_2__cl_c__subcl_ii": {"cite": "DPDP Rules r.5(2)(c)(ii)", "head": "", "text": "in case of any local or other authority within the territory of India or under the control of the Government of India or of any State, the fund or funds of such authority."}, "dpdp-rules-2025:rule_6": {"cite": "DPDP Rules r.6", "head": "Reasonable security safeguards", "text": "A Data Fiduciary shall protect personal data in its possession or under its control, including in respect of any processing undertaken by it or on its behalf by a Data Processor, by taking reasonable security safeguards to prevent personal data breach, which shall include, at the minimum, — appropriate data security measures, such as securing of personal data through encryption, obfuscation, masking or the use of virtual tokens mapped to that personal data; appropriate measures to control access to the computer resources used by such Data Fiduciary or such a Data Processor, wherever applicable…"}, "dpdp-rules-2025:rule_6__subrule_1": {"cite": "DPDP Rules r.6(1)", "head": "", "text": "A Data Fiduciary shall protect personal data in its possession or under its control, including in respect of any processing undertaken by it or on its behalf by a Data Processor, by taking reasonable security safeguards to prevent personal data breach, which shall include, at the minimum, — appropriate data security measures, such as securing of personal data through encryption, obfuscation, masking or the use of virtual tokens mapped to that personal data; appropriate measures to control access to the computer resources used by such Data Fiduciary or such a Data Processor, wherever applicable…"}, "dpdp-rules-2025:rule_6__subrule_1__cl_a": {"cite": "DPDP Rules r.6(1)(a)", "head": "", "text": "appropriate data security measures, such as securing of personal data through encryption, obfuscation, masking or the use of virtual tokens mapped to that personal data;"}, "dpdp-rules-2025:rule_6__subrule_1__cl_b": {"cite": "DPDP Rules r.6(1)(b)", "head": "", "text": "appropriate measures to control access to the computer resources used by such Data Fiduciary or such a Data Processor, wherever applicable;"}, "dpdp-rules-2025:rule_6__subrule_1__cl_c": {"cite": "DPDP Rules r.6(1)(c)", "head": "", "text": "visibility on the accessing of such personal data, through appropriate logs, monitoring and review, for enabling detection of unauthorised access, its investigation and remediation to prevent recurrence;"}, "dpdp-rules-2025:rule_6__subrule_1__cl_d": {"cite": "DPDP Rules r.6(1)(d)", "head": "", "text": "reasonable measures for continued processing in the event of confidentiality, integrity or availability of such personal data being compromised as a result of destruction or loss of access to personal data or otherwise, such as by way of data-backups;"}, "dpdp-rules-2025:rule_6__subrule_1__cl_e": {"cite": "DPDP Rules r.6(1)(e)", "head": "", "text": "for enabling the detection of unauthorised access, its investigation, remediation to prevent recurrence and continued processing in the event of such a compromise, retain such logs and personal data for a period of one year, unless compliance with any law for the time being in force requires otherwise;"}, "dpdp-rules-2025:rule_6__subrule_1__cl_f": {"cite": "DPDP Rules r.6(1)(f)", "head": "", "text": "appropriate provision in the contract entered into between such Data Fiduciary and such a Data Processor, wherever applicable, for taking reasonable security safeguards; and"}, "dpdp-rules-2025:rule_6__subrule_1__cl_g": {"cite": "DPDP Rules r.6(1)(g)", "head": "", "text": "appropriate technical and organisational measures to ensure effective observance of security safeguards."}, "dpdp-rules-2025:rule_6__subrule_2": {"cite": "DPDP Rules r.6(2)", "head": "", "text": "In this rule, the expression “computer resource” shall have the same meaning as is assigned to it in Information Technology Act, 2000 (21 of 2000)."}, "dpdp-rules-2025:rule_7": {"cite": "DPDP Rules r.7", "head": "Intimation of personal data breach", "text": "On becoming aware of any personal data breach, the Data Fiduciary shall, to the best of its knowledge, intimate to each affected Data Principal, in a concise, clear and plain manner and without delay, through her user account or any mode of communication registered by her with the Data Fiduciary, — a description of the breach, including its nature, extent and the timing of its occurrence; the consequences relevant to her, that are likely to arise from the breach; the measures implemented and being implemented by the Data Fiduciary, if any, to mitigate risk; the safety measures that she may tak…"}, "dpdp-rules-2025:rule_7__subrule_1": {"cite": "DPDP Rules r.7(1)", "head": "", "text": "On becoming aware of any personal data breach, the Data Fiduciary shall, to the best of its knowledge, intimate to each affected Data Principal, in a concise, clear and plain manner and without delay, through her user account or any mode of communication registered by her with the Data Fiduciary, — a description of the breach, including its nature, extent and the timing of its occurrence; the consequences relevant to her, that are likely to arise from the breach; the measures implemented and being implemented by the Data Fiduciary, if any, to mitigate risk; the safety measures that she may tak…"}, "dpdp-rules-2025:rule_7__subrule_1__cl_a": {"cite": "DPDP Rules r.7(1)(a)", "head": "", "text": "a description of the breach, including its nature, extent and the timing of its occurrence;"}, "dpdp-rules-2025:rule_7__subrule_1__cl_b": {"cite": "DPDP Rules r.7(1)(b)", "head": "", "text": "the consequences relevant to her, that are likely to arise from the breach;"}, "dpdp-rules-2025:rule_7__subrule_1__cl_c": {"cite": "DPDP Rules r.7(1)(c)", "head": "", "text": "the measures implemented and being implemented by the Data Fiduciary, if any, to mitigate risk;"}, "dpdp-rules-2025:rule_7__subrule_1__cl_d": {"cite": "DPDP Rules r.7(1)(d)", "head": "", "text": "the safety measures that she may take to protect her interests; and"}, "dpdp-rules-2025:rule_7__subrule_1__cl_e": {"cite": "DPDP Rules r.7(1)(e)", "head": "", "text": "business contact information of a person who is able to respond on behalf of the Data Fiduciary, to queries, if any, of the Data Principal."}, "dpdp-rules-2025:rule_7__subrule_2": {"cite": "DPDP Rules r.7(2)", "head": "", "text": "On becoming aware of any personal data breach, the Data Fiduciary shall intimate to the Board, — without delay, a description of the breach, including its nature, extent, timing and location of occurrence and the likely impact; within seventy-two hours of becoming aware of the breach, or within such longer period as the Board may allow on a request made in writing in this behalf, — updated and detailed information in respect of such description; the broad facts related to the events, circumstances and reasons leading to the breach; measures implemented or proposed, if any, to mitigate risk; an…"}, "dpdp-rules-2025:rule_7__subrule_2__cl_a": {"cite": "DPDP Rules r.7(2)(a)", "head": "", "text": "without delay, a description of the breach, including its nature, extent, timing and location of occurrence and the likely impact;"}, "dpdp-rules-2025:rule_7__subrule_2__cl_b": {"cite": "DPDP Rules r.7(2)(b)", "head": "", "text": "within seventy-two hours of becoming aware of the breach, or within such longer period as the Board may allow on a request made in writing in this behalf, — updated and detailed information in respect of such description; the broad facts related to the events, circumstances and reasons leading to the breach; measures implemented or proposed, if any, to mitigate risk; any findings regarding the person who caused the breach; remedial measures taken to prevent recurrence of such breach; and a report regarding the intimations given to affected Data Principals."}, "dpdp-rules-2025:rule_7__subrule_2__cl_b__subcl_i": {"cite": "DPDP Rules r.7(2)(b)(i)", "head": "", "text": "updated and detailed information in respect of such description;"}, "dpdp-rules-2025:rule_7__subrule_2__cl_b__subcl_ii": {"cite": "DPDP Rules r.7(2)(b)(ii)", "head": "", "text": "the broad facts related to the events, circumstances and reasons leading to the breach;"}, "dpdp-rules-2025:rule_7__subrule_2__cl_b__subcl_iii": {"cite": "DPDP Rules r.7(2)(b)(iii)", "head": "", "text": "measures implemented or proposed, if any, to mitigate risk;"}, "dpdp-rules-2025:rule_7__subrule_2__cl_b__subcl_iv": {"cite": "DPDP Rules r.7(2)(b)(iv)", "head": "", "text": "any findings regarding the person who caused the breach;"}, "dpdp-rules-2025:rule_7__subrule_2__cl_b__subcl_v": {"cite": "DPDP Rules r.7(2)(b)(v)", "head": "", "text": "remedial measures taken to prevent recurrence of such breach; and"}, "dpdp-rules-2025:rule_7__subrule_2__cl_b__subcl_vi": {"cite": "DPDP Rules r.7(2)(b)(vi)", "head": "", "text": "a report regarding the intimations given to affected Data Principals."}, "dpdp-rules-2025:rule_8": {"cite": "DPDP Rules r.8", "head": "Time period for specified purpose to be deemed as no longer being served", "text": "A Data Fiduciary, who is of such class and is processing personal data for such corresponding purposes as are specified in Third Schedule, shall erase such personal data, unless its retention is necessary for compliance with any law for the time being in force, or, for the corresponding time period specified in the Third Schedule, if the Data Principal neither approaches such Data Fiduciary for the performance of the specified purpose nor exercises her rights in relation to such processing. At least forty-eight hours before completion of the time period for erasure of personal data under this …"}, "dpdp-rules-2025:rule_8__subrule_1": {"cite": "DPDP Rules r.8(1)", "head": "", "text": "A Data Fiduciary, who is of such class and is processing personal data for such corresponding purposes as are specified in Third Schedule, shall erase such personal data, unless its retention is necessary for compliance with any law for the time being in force, or, for the corresponding time period specified in the Third Schedule, if the Data Principal neither approaches such Data Fiduciary for the performance of the specified purpose nor exercises her rights in relation to such processing."}, "dpdp-rules-2025:rule_8__subrule_2": {"cite": "DPDP Rules r.8(2)", "head": "", "text": "At least forty-eight hours before completion of the time period for erasure of personal data under this rule, the Data Fiduciary shall inform the Data Principal that such personal data shall be erased upon completion of such period, unless she logs into her user account or otherwise initiates contact with the Data Fiduciary for the performance of the specified purpose or exercises her rights in relation to the processing of such personal data."}, "dpdp-rules-2025:rule_8__subrule_3": {"cite": "DPDP Rules r.8(3)", "head": "", "text": "Without prejudice to sub-rules (1) and (2), a Data Fiduciary shall retain, in respect of any processing of personal data undertaken by it or on its behalf by a Data Processor, such personal data, associated traffic data and other logs of the processing for a minimum period of one year from the date of such processing, for the purposes as specified in the Seventh Schedule, after which the Data Fiduciary shall cause such personal data and logs to be erased, unless further retention is required for compliance with any other law for the time being in force or notified by the Government. Illustrati…"}, "dpdp-rules-2025:rule_8__subrule_3__hcontainer_1": {"cite": "DPDP Rules r.8(3)", "head": "Illustration", "text": "Case 1: X, a Data Principal purchases an e-book on an e-book platform Y. Once delivery is completed, the specified purpose of processing is served. The platform Y must retain the order details, personal data, and logs of the processing (such as order confirmation, payment, and delivery events) for at least one year from the date of the transaction, even if X deletes her account. Case 2: X, a company engages a cloud service provider C as its Data Processor to host customer records. X as the Data Fiduciary, is required to ensure that the C also retains the data and associated logs for at least o…"}, "dpdp-rules-2025:rule_9": {"cite": "DPDP Rules r.9", "head": "Contact information of person to answer questions about processing", "text": "Every Data Fiduciary shall prominently publish on its website or app, and mention in every response to a communication for the exercise of the rights of a Data Principal under the Act, the business contact information of the Data Protection Officer, if applicable, or a person who is able to answer on behalf of the Data Fiduciary the questions of the Data Principal about the processing of her personal data."}, "dpdp-rules-2025:rule_10": {"cite": "DPDP Rules r.10", "head": "Verifiable consent for processing of personal data of child", "text": "A Data Fiduciary shall adopt appropriate technical and organisational measures to ensure that verifiable consent of the parent is obtained before the processing of any personal data of a child and shall observe due diligence, for checking that the individual identifying herself as the parent is an adult who is identifiable if required in connection with compliance with any law for the time being in force in India, by reference to— reliable details of identity and age of the individual available with the Data Fiduciary; or details of identity and age, voluntarily provided — by the individual; o…"}, "dpdp-rules-2025:rule_10__subrule_1": {"cite": "DPDP Rules r.10(1)", "head": "", "text": "A Data Fiduciary shall adopt appropriate technical and organisational measures to ensure that verifiable consent of the parent is obtained before the processing of any personal data of a child and shall observe due diligence, for checking that the individual identifying herself as the parent is an adult who is identifiable if required in connection with compliance with any law for the time being in force in India, by reference to— reliable details of identity and age of the individual available with the Data Fiduciary; or details of identity and age, voluntarily provided — by the individual; o…"}, "dpdp-rules-2025:rule_10__subrule_1__cl_a": {"cite": "DPDP Rules r.10(1)(a)", "head": "", "text": "reliable details of identity and age of the individual available with the Data Fiduciary; or"}, "dpdp-rules-2025:rule_10__subrule_1__cl_b": {"cite": "DPDP Rules r.10(1)(b)", "head": "", "text": "details of identity and age, voluntarily provided — by the individual; or through a virtual token mapped to such details, which is issued by an authorised entity."}, "dpdp-rules-2025:rule_10__subrule_1__cl_b__subcl_i": {"cite": "DPDP Rules r.10(1)(b)(i)", "head": "", "text": "by the individual; or"}, "dpdp-rules-2025:rule_10__subrule_1__cl_b__subcl_ii": {"cite": "DPDP Rules r.10(1)(b)(ii)", "head": "", "text": "through a virtual token mapped to such details, which is issued by an authorised entity."}, "dpdp-rules-2025:rule_10__subrule_2": {"cite": "DPDP Rules r.10(2)", "head": "", "text": "In this rule, the expression— “adult” shall mean an individual who has completed the age of eighteen years; “authorised entity\" shall mean — an entity entrusted by law or by the Central Government or by the State Government with the issuance of details of the identity and age or a virtual token mapped to such details; or a person appointed or permitted by the entity specified under clause (i), for such issuance, and also includes details of identity and age or token made available and verified by a Digital Locker Service Provider; “Digital Locker service provider” shall mean such intermediary,…"}, "dpdp-rules-2025:rule_10__subrule_2__cl_a": {"cite": "DPDP Rules r.10(2)(a)", "head": "", "text": "“adult” shall mean an individual who has completed the age of eighteen years;"}, "dpdp-rules-2025:rule_10__subrule_2__cl_b": {"cite": "DPDP Rules r.10(2)(b)", "head": "", "text": "“authorised entity\" shall mean — an entity entrusted by law or by the Central Government or by the State Government with the issuance of details of the identity and age or a virtual token mapped to such details; or a person appointed or permitted by the entity specified under clause (i), for such issuance, and also includes details of identity and age or token made available and verified by a Digital Locker Service Provider;"}, "dpdp-rules-2025:rule_10__subrule_2__cl_b__subcl_i": {"cite": "DPDP Rules r.10(2)(b)(i)", "head": "", "text": "an entity entrusted by law or by the Central Government or by the State Government with the issuance of details of the identity and age or a virtual token mapped to such details; or"}, "dpdp-rules-2025:rule_10__subrule_2__cl_b__subcl_ii": {"cite": "DPDP Rules r.10(2)(b)(ii)", "head": "", "text": "a person appointed or permitted by the entity specified under clause (i), for such issuance, and also includes details of identity and age or token made available and verified by a Digital Locker Service Provider;"}, "dpdp-rules-2025:rule_10__subrule_2__cl_c": {"cite": "DPDP Rules r.10(2)(c)", "head": "", "text": "“Digital Locker service provider” shall mean such intermediary, including a body corporate or an agency of the appropriate Government, as may be notified by the Central Government, in accordance with the rules made in this regard under the Information Technology Act, 2000 (21 of 2000); Illustration C is a child, P is a parent, and DF is a Data Fiduciary. A user account of C is sought to be created on the online platform of DF, by processing the personal data of C. Case 1: C informs DF that she is a child and declares P as her parent. DF shall enable P to identify herself through its website, a…"}, "dpdp-rules-2025:rule_10__subrule_2__cl_c__hcontainer_1": {"cite": "DPDP Rules r.10(2)(c)", "head": "Illustration", "text": "C is a child, P is a parent, and DF is a Data Fiduciary. A user account of C is sought to be created on the online platform of DF, by processing the personal data of C. Case 1: C informs DF that she is a child and declares P as her parent. DF shall enable P to identify herself through its website, app or other appropriate means. P identifies herself as the parent and informs DF that she is a registered user on DF’s platform and has previously made available her identity and age details to DF. Before processing C’s personal data for the creation of her user account, DF shall check to confirm th…"}, "dpdp-rules-2025:rule_11": {"cite": "DPDP Rules r.11", "head": "Verifiable consent for processing of personal data of person with disability who has lawful guardian", "text": "A Data Fiduciary, while obtaining verifiable consent from an individual identifying herself as the lawful guardian of a person with disability, shall observe due diligence to verify that such guardian is appointed by a court of law, or by a designated authority or by a local level committee, under the law applicable to guardianship. In this rule, the expression— “designated authority” shall mean an authority designated under section 15 of the Rights of Persons with Disabilities Act, 2016 (49 of 2016) to support persons with disabilities in exercise of their legal capacity; “law applicable to g…"}, "dpdp-rules-2025:rule_11__subrule_1": {"cite": "DPDP Rules r.11(1)", "head": "", "text": "A Data Fiduciary, while obtaining verifiable consent from an individual identifying herself as the lawful guardian of a person with disability, shall observe due diligence to verify that such guardian is appointed by a court of law, or by a designated authority or by a local level committee, under the law applicable to guardianship."}, "dpdp-rules-2025:rule_11__subrule_2": {"cite": "DPDP Rules r.11(2)", "head": "", "text": "In this rule, the expression— “designated authority” shall mean an authority designated under section 15 of the Rights of Persons with Disabilities Act, 2016 (49 of 2016) to support persons with disabilities in exercise of their legal capacity; “law applicable to guardianship” shall mean, — in relation to an individual who has long term physical, mental, intellectual or sensory impairment which, in interaction with barriers, hinders her full and effective participation in society equally with others and who despite being provided adequate and appropriate support is unable to take legally bindi…"}, "dpdp-rules-2025:rule_11__subrule_2__cl_a": {"cite": "DPDP Rules r.11(2)(a)", "head": "", "text": "“designated authority” shall mean an authority designated under section 15 of the Rights of Persons with Disabilities Act, 2016 (49 of 2016) to support persons with disabilities in exercise of their legal capacity;"}, "dpdp-rules-2025:rule_11__subrule_2__cl_b": {"cite": "DPDP Rules r.11(2)(b)", "head": "", "text": "“law applicable to guardianship” shall mean, — in relation to an individual who has long term physical, mental, intellectual or sensory impairment which, in interaction with barriers, hinders her full and effective participation in society equally with others and who despite being provided adequate and appropriate support is unable to take legally binding decisions, the provisions of law contained in Rights of Persons with Disabilities Act, 2016 (49 of 2016) and the rules made thereunder; and in relation to a person who is suffering from any of the conditions relating to autism, cerebral palsy…"}, "dpdp-rules-2025:rule_11__subrule_2__cl_b__subcl_i": {"cite": "DPDP Rules r.11(2)(b)(i)", "head": "", "text": "in relation to an individual who has long term physical, mental, intellectual or sensory impairment which, in interaction with barriers, hinders her full and effective participation in society equally with others and who despite being provided adequate and appropriate support is unable to take legally binding decisions, the provisions of law contained in Rights of Persons with Disabilities Act, 2016 (49 of 2016) and the rules made thereunder; and"}, "dpdp-rules-2025:rule_11__subrule_2__cl_b__subcl_ii": {"cite": "DPDP Rules r.11(2)(b)(ii)", "head": "", "text": "in relation to a person who is suffering from any of the conditions relating to autism, cerebral palsy, mental retardation or a combination of such conditions and includes a person suffering from severe multiple disability, the provisions of law of the National Trust for the Welfare of Persons with Autism, Cerebral Palsy, Mental Retardation and Multiple Disabilities Act, 1999 (44 of 1999) and the rules made thereunder;"}, "dpdp-rules-2025:rule_11__subrule_2__cl_c": {"cite": "DPDP Rules r.11(2)(c)", "head": "", "text": "“local level committee” shall mean a local level committee constituted under section 13 of the National Trust for the Welfare of Persons with Autism, Cerebral Palsy, Mental Retardation and Multiple Disabilities Act, 1999 (44 of 1999);"}, "dpdp-rules-2025:rule_11__subrule_2__cl_d": {"cite": "DPDP Rules r.11(2)(d)", "head": "", "text": "“person with disability” shall mean and include— an individual who has long term physical, mental, intellectual or sensory impairment which, in interaction with barriers, hinders her full and effective participation in society equally with others and who, despite being provided adequate and appropriate support, is unable to take legally binding decisions; and an individual who is suffering from any of the conditions relating to autism, cerebral palsy, mental retardation or a combination of any two or more of such conditions and includes an individual suffering from severe multiple disability a…"}, "dpdp-rules-2025:rule_11__subrule_2__cl_d__subcl_i": {"cite": "DPDP Rules r.11(2)(d)(i)", "head": "", "text": "an individual who has long term physical, mental, intellectual or sensory impairment which, in interaction with barriers, hinders her full and effective participation in society equally with others and who, despite being provided adequate and appropriate support, is unable to take legally binding decisions; and"}, "dpdp-rules-2025:rule_11__subrule_2__cl_d__subcl_ii": {"cite": "DPDP Rules r.11(2)(d)(ii)", "head": "", "text": "an individual who is suffering from any of the conditions relating to autism, cerebral palsy, mental retardation or a combination of any two or more of such conditions and includes an individual suffering from severe multiple disability and who, despite being provided adequate and appropriate support, is unable to take legally binding decisions."}, "dpdp-rules-2025:rule_12": {"cite": "DPDP Rules r.12", "head": "Exemptions from certain obligations applicable to processing of personal data of child", "text": "The provisions of sub-sections (1) and (3) of section 9 of the Act shall not be applicable to processing of personal data of a child by such class of Data Fiduciaries as are specified in Part A of Fourth Schedule, subject to such conditions as are specified in the said Part. The provisions of sub-sections (1) and (3) of section 9 of the Act shall not be applicable to processing of personal data of a child for such purposes as are specified in Part B of Fourth Schedule, subject to such conditions as are specified in the said Part."}, "dpdp-rules-2025:rule_12__subrule_1": {"cite": "DPDP Rules r.12(1)", "head": "", "text": "The provisions of sub-sections (1) and (3) of section 9 of the Act shall not be applicable to processing of personal data of a child by such class of Data Fiduciaries as are specified in Part A of Fourth Schedule, subject to such conditions as are specified in the said Part."}, "dpdp-rules-2025:rule_12__subrule_2": {"cite": "DPDP Rules r.12(2)", "head": "", "text": "The provisions of sub-sections (1) and (3) of section 9 of the Act shall not be applicable to processing of personal data of a child for such purposes as are specified in Part B of Fourth Schedule, subject to such conditions as are specified in the said Part."}, "dpdp-rules-2025:rule_13": {"cite": "DPDP Rules r.13", "head": "Additional obligations of Significant Data Fiduciary", "text": "A Significant Data Fiduciary shall, once in every period of twelve months from the date on which it is notified as such or is included in the class of Data Fiduciaries notified as such, undertake a Data Protection Impact Assessment and an audit to ensure effective observance of the provisions of this Act and the rules made thereunder. A Significant Data Fiduciary shall cause the person carrying out the Data Protection Impact Assessment and audit to furnish to the Board a report containing significant observations in the Data Protection Impact Assessment and audit. A Significant Data Fiduciary …"}, "dpdp-rules-2025:rule_13__subrule_1": {"cite": "DPDP Rules r.13(1)", "head": "", "text": "A Significant Data Fiduciary shall, once in every period of twelve months from the date on which it is notified as such or is included in the class of Data Fiduciaries notified as such, undertake a Data Protection Impact Assessment and an audit to ensure effective observance of the provisions of this Act and the rules made thereunder."}, "dpdp-rules-2025:rule_13__subrule_2": {"cite": "DPDP Rules r.13(2)", "head": "", "text": "A Significant Data Fiduciary shall cause the person carrying out the Data Protection Impact Assessment and audit to furnish to the Board a report containing significant observations in the Data Protection Impact Assessment and audit."}, "dpdp-rules-2025:rule_13__subrule_3": {"cite": "DPDP Rules r.13(3)", "head": "", "text": "A Significant Data Fiduciary shall observe due diligence to verify that technical measures including algorithmic software adopted by it for hosting, display, uploading, modification, publishing, transmission, storage, updating or sharing of personal data processed by it are not likely to pose a risk to the rights of Data Principals."}, "dpdp-rules-2025:rule_13__subrule_4": {"cite": "DPDP Rules r.13(4)", "head": "", "text": "A Significant Data Fiduciary shall undertake measures to ensure that personal data specified by the Central Government, on the basis of the recommendations of a committee constituted by it, is processed subject to the restriction that the personal data and the traffic data pertaining to its flow is not transferred outside the territory of India."}, "dpdp-rules-2025:rule_13__subrule_5": {"cite": "DPDP Rules r.13(5)", "head": "", "text": "In this rule, “committee” means a committee constituted by the Central Government for the purpose of this rule, which shall include officials from the Ministry of Electronics and Technology and may include officials from other Ministries or Departments of the Central Government."}, "dpdp-rules-2025:rule_14": {"cite": "DPDP Rules r.14", "head": "Rights of Data Principals", "text": "For enabling Data Principals to exercise their rights under the Act, the Data Fiduciary and, where applicable, the Consent Manager, shall prominently publish on its website or app, or both, as the case may be, — the details of the means using which a Data Principal may make a request for the exercise of such rights; and the particulars, if any, such as the username or other identifier of such a Data Principal, which may be required to identify her under its terms of service. To exercise the rights of the Data Principal under the Act, she may make a request to the Data Fiduciary to whom she has…"}, "dpdp-rules-2025:rule_14__subrule_1": {"cite": "DPDP Rules r.14(1)", "head": "", "text": "For enabling Data Principals to exercise their rights under the Act, the Data Fiduciary and, where applicable, the Consent Manager, shall prominently publish on its website or app, or both, as the case may be, — the details of the means using which a Data Principal may make a request for the exercise of such rights; and the particulars, if any, such as the username or other identifier of such a Data Principal, which may be required to identify her under its terms of service."}, "dpdp-rules-2025:rule_14__subrule_1__cl_a": {"cite": "DPDP Rules r.14(1)(a)", "head": "", "text": "the details of the means using which a Data Principal may make a request for the exercise of such rights; and"}, "dpdp-rules-2025:rule_14__subrule_1__cl_b": {"cite": "DPDP Rules r.14(1)(b)", "head": "", "text": "the particulars, if any, such as the username or other identifier of such a Data Principal, which may be required to identify her under its terms of service."}, "dpdp-rules-2025:rule_14__subrule_2": {"cite": "DPDP Rules r.14(2)", "head": "", "text": "To exercise the rights of the Data Principal under the Act, she may make a request to the Data Fiduciary to whom she has previously given consent for processing of her personal data, using the means and furnishing the particulars required by such Data Fiduciary for the exercise of such rights."}, "dpdp-rules-2025:rule_14__subrule_3": {"cite": "DPDP Rules r.14(3)", "head": "", "text": "Every Data Fiduciary and Consent Manager shall prominently publish on its website or app, or both, as the case may be, within a reasonable period not exceeding ninety days under its grievance redressal system for responding to the grievances of Data Principals and shall, for ensuring the effectiveness of the system in responding within such period, implement appropriate technical and organisational measures."}, "dpdp-rules-2025:rule_14__subrule_4": {"cite": "DPDP Rules r.14(4)", "head": "", "text": "To exercise the rights of the Data Principal under the Act, she may, in accordance with the terms of service of the Data Fiduciary and such law as may be applicable, nominate one or more individuals, using the means and furnishing the particulars required by such Data Fiduciary for the exercise of such right."}, "dpdp-rules-2025:rule_14__subrule_5": {"cite": "DPDP Rules r.14(5)", "head": "", "text": "In this rule, the expression “identifier” shall mean any sequence of characters issued by the Data Fiduciary to identify the Data Principal and includes a customer identification file number, customer acquisition form number, application reference number, enrolment ID, email address, mobile number or licence number that enables such identification."}, "dpdp-rules-2025:rule_15": {"cite": "DPDP Rules r.15", "head": "Transfer of personal data outside the territory of India", "text": "Any personal data processed by a Data Fiduciary under the Act may be transferred outside the territory of India subject to the restriction that the Data Fiduciary shall meet such requirements as the Central Government may, by general or special order, specify in respect of making such personal data available to any foreign State, or to any person or entity under the control of or any agency of such a State."}, "dpdp-rules-2025:rule_16": {"cite": "DPDP Rules r.16", "head": "Exemption from Act for research, archiving or statistical purposes", "text": "The provisions of the Act shall not apply to the processing of personal data necessary for research, archiving or statistical purposes if it is carried on in accordance with the standards specified in Second Schedule."}, "dpdp-rules-2025:rule_17": {"cite": "DPDP Rules r.17", "head": "Appointment of Chairperson and other Members", "text": "The Central Government shall constitute a Search-cum-Selection Committee, with the Cabinet Secretary as the chairperson and the Secretaries to the Government of India in charge of the Department of Legal Affairs and the Ministry of Electronics and Information Technology and two experts of repute having special knowledge or practical experience in a field which in the opinion of the Central Government may be useful to the Board as members, to recommend individuals for appointment as Chairperson. The Central Government shall constitute a Search-cum-Selection Committee, with the Secretary to the …"}, "dpdp-rules-2025:rule_17__subrule_1": {"cite": "DPDP Rules r.17(1)", "head": "", "text": "The Central Government shall constitute a Search-cum-Selection Committee, with the Cabinet Secretary as the chairperson and the Secretaries to the Government of India in charge of the Department of Legal Affairs and the Ministry of Electronics and Information Technology and two experts of repute having special knowledge or practical experience in a field which in the opinion of the Central Government may be useful to the Board as members, to recommend individuals for appointment as Chairperson."}, "dpdp-rules-2025:rule_17__subrule_2": {"cite": "DPDP Rules r.17(2)", "head": "", "text": "The Central Government shall constitute a Search-cum-Selection Committee, with the Secretary to the Government of India in the Ministry of Electronics and Information Technology as the chairperson and the Secretary to the Government of India in charge of the Department of Legal Affairs, and two experts of repute having special knowledge or practical experience in a field which in the opinion of the Central Government may be useful to the Board as members, to recommend individuals for appointment as a Member other than the Chairperson."}, "dpdp-rules-2025:rule_17__subrule_3": {"cite": "DPDP Rules r.17(3)", "head": "", "text": "The Central Government shall, after considering the suitability of individuals recommended by the Search-cum-Selection Committee, appoint the Chairperson or other Member, as the case may be."}, "dpdp-rules-2025:rule_17__subrule_4": {"cite": "DPDP Rules r.17(4)", "head": "", "text": "No act or proceeding of the Search-cum-Selection Committee specified in sub-rules (1) and (2) of this rule shall be called in question on the ground merely of the existence of any vacancy or absences in such committee or defect in its constitution."}, "dpdp-rules-2025:rule_18": {"cite": "DPDP Rules r.18", "head": "Salary, allowances and other terms and conditions of service of Chairperson and other Members", "text": "The Chairperson and every other Member shall receive such salary and allowances and shall have such other terms and conditions of service as are specified in Fifth Schedule."}, "dpdp-rules-2025:rule_19": {"cite": "DPDP Rules r.19", "head": "Procedure for meetings of Board and authentication of its orders, directions and instruments", "text": "The Chairperson shall fix the date, time and place of meetings of the Board, approve the items of agenda therefor, and cause notice specifying the same to be issued under her signature or that of such other individual as the Chairperson may authorise by general or special order in writing. Meetings of the Board shall be chaired by the Chairperson and, in her absence, by such other Member as the Members present at the meeting may choose from amongst themselves. One-third of the membership of the Board shall be the quorum for its meetings. All questions which come up before any meeting of the Bo…"}, "dpdp-rules-2025:rule_19__subrule_1": {"cite": "DPDP Rules r.19(1)", "head": "", "text": "The Chairperson shall fix the date, time and place of meetings of the Board, approve the items of agenda therefor, and cause notice specifying the same to be issued under her signature or that of such other individual as the Chairperson may authorise by general or special order in writing."}, "dpdp-rules-2025:rule_19__subrule_2": {"cite": "DPDP Rules r.19(2)", "head": "", "text": "Meetings of the Board shall be chaired by the Chairperson and, in her absence, by such other Member as the Members present at the meeting may choose from amongst themselves."}, "dpdp-rules-2025:rule_19__subrule_3": {"cite": "DPDP Rules r.19(3)", "head": "", "text": "One-third of the membership of the Board shall be the quorum for its meetings."}, "dpdp-rules-2025:rule_19__subrule_4": {"cite": "DPDP Rules r.19(4)", "head": "", "text": "All questions which come up before any meeting of the Board shall be decided by a majority of the votes of Members present and voting, and, in the event of an equality of votes, the Chairperson, or in her absence, the person chairing, shall have a second or casting vote."}, "dpdp-rules-2025:rule_19__subrule_5": {"cite": "DPDP Rules r.19(5)", "head": "", "text": "If a Member has an interest in any item of business to be transacted at a meeting of the Board, she shall not participate in or vote on the same and, in such a case, the decision on such item shall be taken by a majority of the votes of other Members present and voting."}, "dpdp-rules-2025:rule_19__subrule_6": {"cite": "DPDP Rules r.19(6)", "head": "", "text": "In case an emergent situation warrants immediate action by the Board and it is not feasible to call a meeting of the Board, the Chairperson may, while recording the reasons in writing, take such action as may be necessary, which shall be communicated within seven days to all Members and laid before the Board for ratification at its next meeting."}, "dpdp-rules-2025:rule_19__subrule_7": {"cite": "DPDP Rules r.19(7)", "head": "", "text": "If the Chairperson so directs, an item of business or issue which requires decision of the Board may be referred to Members by circulation and such item may be decided with the approval of majority of the Members."}, "dpdp-rules-2025:rule_19__subrule_8": {"cite": "DPDP Rules r.19(8)", "head": "", "text": "The Chairperson or any Member of the Board, or any individual authorised by it,by a general or special order in writing, may, under her signature, authenticate its order, direction or instrument."}, "dpdp-rules-2025:rule_19__subrule_9": {"cite": "DPDP Rules r.19(9)", "head": "", "text": "The inquiry by the Board shall be completed within a period of six months from the date of receipt of the intimation, complaint, reference or direction under section 27 of the Act, unless such period is extended by it, for reasons to be recorded in writing, for a further period not exceeding three months at a time."}, "dpdp-rules-2025:rule_20": {"cite": "DPDP Rules r.20", "head": "Functioning of Board as digital office", "text": "The Board shall function as a digital office, without prejudice to its power to summon and enforce the attendance of any person and examine her on oath, may adopt techno-legal measures to conduct proceedings in a manner that does not require physical presence of any individual."}, "dpdp-rules-2025:rule_21": {"cite": "DPDP Rules r.21", "head": "Terms and conditions of appointment and service of officers and employees of Board", "text": "The Board may, with previous approval of the Central Government, appoint such officers and employees as it may deem necessary for the efficient discharge of its functions under the provisions of the Act. The terms and conditions of service of officers and employees of the Board shall be such as are specified in Sixth Schedule."}, "dpdp-rules-2025:rule_21__subrule_1": {"cite": "DPDP Rules r.21(1)", "head": "", "text": "The Board may, with previous approval of the Central Government, appoint such officers and employees as it may deem necessary for the efficient discharge of its functions under the provisions of the Act."}, "dpdp-rules-2025:rule_21__subrule_2": {"cite": "DPDP Rules r.21(2)", "head": "", "text": "The terms and conditions of service of officers and employees of the Board shall be such as are specified in Sixth Schedule."}, "dpdp-rules-2025:rule_22": {"cite": "DPDP Rules r.22", "head": "Appeal to Appellate Tribunal", "text": "Any person aggrieved by an order or direction of the Board, may prefer an appeal before the Appellate Tribunal, it shall be filed in digital form as the Appellate Tribunal may decide. An appeal filed with the Appellate Tribunal shall be accompanied by fee of like amount as is applicable in respect of an appeal filed under the Telecom Regulatory Authority of India Act, 1997 (24 of 1997), unless reduced or waived by the Chairperson of the Appellate Tribunal at her discretion, and the same shall be payable digitally using the Unified Payments Interface or such other payment system authorised by t…"}, "dpdp-rules-2025:rule_22__subrule_1": {"cite": "DPDP Rules r.22(1)", "head": "", "text": "Any person aggrieved by an order or direction of the Board, may prefer an appeal before the Appellate Tribunal, it shall be filed in digital form as the Appellate Tribunal may decide."}, "dpdp-rules-2025:rule_22__subrule_2": {"cite": "DPDP Rules r.22(2)", "head": "", "text": "An appeal filed with the Appellate Tribunal shall be accompanied by fee of like amount as is applicable in respect of an appeal filed under the Telecom Regulatory Authority of India Act, 1997 (24 of 1997), unless reduced or waived by the Chairperson of the Appellate Tribunal at her discretion, and the same shall be payable digitally using the Unified Payments Interface or such other payment system authorised by the Reserve Bank of India."}, "dpdp-rules-2025:rule_22__subrule_3": {"cite": "DPDP Rules r.22(3)", "head": "", "text": "The Appellate Tribunal— shall not be bound by the procedure laid down by the Code of Civil Procedure, 1908 (5 of 1908), but shall be guided by the principles of natural justice and, subject to the provisions of the Act, may regulate its own procedure; and shall function as a digital office which, without prejudice to its power to summon and enforce the attendance of any person and examine her on oath, may adopt techno-legal measures to conduct proceedings in a manner that does not require physical presence of any individual."}, "dpdp-rules-2025:rule_22__subrule_3__cl_a": {"cite": "DPDP Rules r.22(3)(a)", "head": "", "text": "shall not be bound by the procedure laid down by the Code of Civil Procedure, 1908 (5 of 1908), but shall be guided by the principles of natural justice and, subject to the provisions of the Act, may regulate its own procedure; and"}, "dpdp-rules-2025:rule_22__subrule_3__cl_b": {"cite": "DPDP Rules r.22(3)(b)", "head": "", "text": "shall function as a digital office which, without prejudice to its power to summon and enforce the attendance of any person and examine her on oath, may adopt techno-legal measures to conduct proceedings in a manner that does not require physical presence of any individual."}, "dpdp-rules-2025:rule_23": {"cite": "DPDP Rules r.23", "head": "Calling for information from Data Fiduciary or intermediary", "text": "The Central Government may, for such purposes of the Act as are specified in Seventh Schedule, acting through the corresponding authorised person specified in the said Schedule, require any Data Fiduciary or intermediary to furnish such information as may be called for, within the specified period as may be given in such order. Where the disclosure of furnishing of information as referred to in sub-rule (1) is likely to prejudicially affect the sovereignty and integrity of India or security of the State, the Central Government may require the Data Fiduciary or intermediary to not disclose such…"}, "dpdp-rules-2025:rule_23__subrule_1": {"cite": "DPDP Rules r.23(1)", "head": "", "text": "The Central Government may, for such purposes of the Act as are specified in Seventh Schedule, acting through the corresponding authorised person specified in the said Schedule, require any Data Fiduciary or intermediary to furnish such information as may be called for, within the specified period as may be given in such order."}, "dpdp-rules-2025:rule_23__subrule_2": {"cite": "DPDP Rules r.23(2)", "head": "", "text": "Where the disclosure of furnishing of information as referred to in sub-rule (1) is likely to prejudicially affect the sovereignty and integrity of India or security of the State, the Central Government may require the Data Fiduciary or intermediary to not disclose such furnishing to affected Data Principal or any other person except with the previous permission, in writing, of the authorised person."}, "dpdp-rules-2025:rule_23__subrule_3": {"cite": "DPDP Rules r.23(3)", "head": "", "text": "For the purposes of this rule, the expression “intermediary” shall have the same meaning as assigned to it in the Information Technology Act, 2000 (21 of 2000)."}, "dpdp-rules-2025:sched_1": {"cite": "DPDP Rules Schedule I", "head": "", "text": "FIRST SCHEDULE [See rule 4] Conditions for registration of Consent Manager The applicant is a company incorporated in India. The applicant has sufficient capacity, including technical, operational and financial capacity, to fulfil its obligations as a Consent Manager. The financial condition and the general character of management of the applicant are sound. The net worth of the applicant is not less than two crore rupees. The volume of business likely to be available to and the capital structure and earning prospects of the applicant are adequate. The directors, key managerial personnel and s…"}, "dpdp-rules-2025:sched_1__part_A": {"cite": "DPDP Rules Schedule I, Part A", "head": "Conditions for registration of Consent Manager", "text": "The applicant is a company incorporated in India. The applicant has sufficient capacity, including technical, operational and financial capacity, to fulfil its obligations as a Consent Manager. The financial condition and the general character of management of the applicant are sound. The net worth of the applicant is not less than two crore rupees. The volume of business likely to be available to and the capital structure and earning prospects of the applicant are adequate. The directors, key managerial personnel and senior management of the applicant company are individuals with a general re…"}, "dpdp-rules-2025:sched_1__part_A__para_1": {"cite": "DPDP Rules Schedule I, Part A, para 1", "head": "", "text": "The applicant is a company incorporated in India."}, "dpdp-rules-2025:sched_1__part_A__para_2": {"cite": "DPDP Rules Schedule I, Part A, para 2", "head": "", "text": "The applicant has sufficient capacity, including technical, operational and financial capacity, to fulfil its obligations as a Consent Manager."}, "dpdp-rules-2025:sched_1__part_A__para_3": {"cite": "DPDP Rules Schedule I, Part A, para 3", "head": "", "text": "The financial condition and the general character of management of the applicant are sound."}, "dpdp-rules-2025:sched_1__part_A__para_4": {"cite": "DPDP Rules Schedule I, Part A, para 4", "head": "", "text": "The net worth of the applicant is not less than two crore rupees."}, "dpdp-rules-2025:sched_1__part_A__para_5": {"cite": "DPDP Rules Schedule I, Part A, para 5", "head": "", "text": "The volume of business likely to be available to and the capital structure and earning prospects of the applicant are adequate."}, "dpdp-rules-2025:sched_1__part_A__para_6": {"cite": "DPDP Rules Schedule I, Part A, para 6", "head": "", "text": "The directors, key managerial personnel and senior management of the applicant company are individuals with a general reputation and record of fairness and integrity."}, "dpdp-rules-2025:sched_1__part_A__para_7": {"cite": "DPDP Rules Schedule I, Part A, para 7", "head": "", "text": "The memorandum of association and articles of association of the applicant company contain provisions requiring that the obligations under items 9 and 10 of Part B are adhered to, that policies and procedures are in place to ensure such adherence, and that such provisions may be amended only with the previous approval of the Board."}, "dpdp-rules-2025:sched_1__part_A__para_8": {"cite": "DPDP Rules Schedule I, Part A, para 8", "head": "", "text": "The operations proposed to be undertaken by the applicant are in the interests of Data Principals."}, "dpdp-rules-2025:sched_1__part_A__para_9": {"cite": "DPDP Rules Schedule I, Part A, para 9", "head": "", "text": "It is independently certified that— the interoperable platform of the applicant to enable the Data Principal to give, manage, review and withdraw her consent is consistent with such data protection standards and assurance framework as may be published by the Board on its website from time to time; and appropriate technical and organisational measures are in place to ensure adherence to such standards and framework and effective observance of the obligations under item 11 of Part B."}, "dpdp-rules-2025:sched_1__part_A__para_9__cl_a": {"cite": "DPDP Rules Schedule I, Part A, para 9(a)", "head": "", "text": "the interoperable platform of the applicant to enable the Data Principal to give, manage, review and withdraw her consent is consistent with such data protection standards and assurance framework as may be published by the Board on its website from time to time; and"}, "dpdp-rules-2025:sched_1__part_A__para_9__cl_b": {"cite": "DPDP Rules Schedule I, Part A, para 9(b)", "head": "", "text": "appropriate technical and organisational measures are in place to ensure adherence to such standards and framework and effective observance of the obligations under item 11 of Part B."}, "dpdp-rules-2025:sched_1__part_B": {"cite": "DPDP Rules Schedule I, Part B", "head": "Obligations of Consent Manager", "text": "The Consent Manager shall enable a Data Principal using its platform to give consent to the processing of her personal data by a Data Fiduciary onboarded onto such platform either directly to such Data Fiduciary or through another Data Fiduciary onboarded onto such platform, who maintains such personal data with the consent of that Data Principal. Illustration Individuals are enabled to give, manage, review and withdraw their consent to the processing of their personal data through P, a platform maintained by a Consent Manager. X, an individual, is a registered user on P. B1 and B2 are banks o…"}, "dpdp-rules-2025:sched_1__part_B__para_1": {"cite": "DPDP Rules Schedule I, Part B, para 1", "head": "", "text": "The Consent Manager shall enable a Data Principal using its platform to give consent to the processing of her personal data by a Data Fiduciary onboarded onto such platform either directly to such Data Fiduciary or through another Data Fiduciary onboarded onto such platform, who maintains such personal data with the consent of that Data Principal. Illustration Individuals are enabled to give, manage, review and withdraw their consent to the processing of their personal data through P, a platform maintained by a Consent Manager. X, an individual, is a registered user on P. B1 and B2 are banks o…"}, "dpdp-rules-2025:sched_1__part_B__para_1__hcontainer_1": {"cite": "DPDP Rules Schedule I, Part B, para 1", "head": "Illustration", "text": "Individuals are enabled to give, manage, review and withdraw their consent to the processing of their personal data through P, a platform maintained by a Consent Manager. X, an individual, is a registered user on P. B1 and B2 are banks onboarded onto P. Case 1:B1 sends a request on P to X for consent to process personal data contained in her bank account statement. X maintains the bank account statement as a digital record in her digital locker. X uses P to directly give her consent to B1, and proceeds to give B1 access to her bank account statement. Case 2:B1 sends a request on P to X for con…"}, "dpdp-rules-2025:sched_1__part_B__para_2": {"cite": "DPDP Rules Schedule I, Part B, para 2", "head": "", "text": "The Consent Manager shall ensure that the manner of making available the personal data or its sharing is such that the contents thereof are not readable by it."}, "dpdp-rules-2025:sched_1__part_B__para_3": {"cite": "DPDP Rules Schedule I, Part B, para 3", "head": "", "text": "The Consent Manager shall maintain on its platform a record of the following, namely:— Consents given, denied or withdrawn by her; Notices preceding or accompanying requests for consent; and Sharing of her personal data with a transferee Data Fiduciary."}, "dpdp-rules-2025:sched_1__part_B__para_3__cl_a": {"cite": "DPDP Rules Schedule I, Part B, para 3(a)", "head": "", "text": "Consents given, denied or withdrawn by her;"}, "dpdp-rules-2025:sched_1__part_B__para_3__cl_b": {"cite": "DPDP Rules Schedule I, Part B, para 3(b)", "head": "", "text": "Notices preceding or accompanying requests for consent; and"}, "dpdp-rules-2025:sched_1__part_B__para_3__cl_c": {"cite": "DPDP Rules Schedule I, Part B, para 3(c)", "head": "", "text": "Sharing of her personal data with a transferee Data Fiduciary."}, "dpdp-rules-2025:sched_1__part_B__para_4": {"cite": "DPDP Rules Schedule I, Part B, para 4", "head": "", "text": "The Consent Manager: — shall give the Data Principal using such platform access to such record; shall, on the request of the Data Principal and in accordance with its terms of service, make available to her the information contained in such record, in machine-readable form; and shall maintain such record for at least seven years, or for such longer period as the Data Principal and Consent Manager may agree upon or as may be required by law."}, "dpdp-rules-2025:sched_1__part_B__para_4__cl_a": {"cite": "DPDP Rules Schedule I, Part B, para 4(a)", "head": "", "text": "shall give the Data Principal using such platform access to such record;"}, "dpdp-rules-2025:sched_1__part_B__para_4__cl_b": {"cite": "DPDP Rules Schedule I, Part B, para 4(b)", "head": "", "text": "shall, on the request of the Data Principal and in accordance with its terms of service, make available to her the information contained in such record, in machine-readable form; and"}, "dpdp-rules-2025:sched_1__part_B__para_4__cl_c": {"cite": "DPDP Rules Schedule I, Part B, para 4(c)", "head": "", "text": "shall maintain such record for at least seven years, or for such longer period as the Data Principal and Consent Manager may agree upon or as may be required by law."}, "dpdp-rules-2025:sched_1__part_B__para_5": {"cite": "DPDP Rules Schedule I, Part B, para 5", "head": "", "text": "The Consent Manager shall develop and maintain a website or app, or both, as the primary means through which a Data Principal may access the services provided by the Consent Manager."}, "dpdp-rules-2025:sched_1__part_B__para_6": {"cite": "DPDP Rules Schedule I, Part B, para 6", "head": "", "text": "The Consent Manager shall not sub-contract or assign the performance of any of its obligations under the Act and these rules."}, "dpdp-rules-2025:sched_1__part_B__para_7": {"cite": "DPDP Rules Schedule I, Part B, para 7", "head": "", "text": "The Consent Manager shall take reasonable security safeguards to prevent personal data breach."}, "dpdp-rules-2025:sched_1__part_B__para_8": {"cite": "DPDP Rules Schedule I, Part B, para 8", "head": "", "text": "The Consent Manager shall act in a fiduciary capacity in relation to the Data Principal."}, "dpdp-rules-2025:sched_1__part_B__para_9": {"cite": "DPDP Rules Schedule I, Part B, para 9", "head": "", "text": "The Consent Manager shall avoid conflict of interest with Data Fiduciaries, including in respect of their promoters and key managerial personnel."}, "dpdp-rules-2025:sched_1__part_B__para_10": {"cite": "DPDP Rules Schedule I, Part B, para 10", "head": "", "text": "The Consent Manager shall have in place measures to ensure that no conflict of interest arises on account of its directors, key managerial personnel and senior management holding a directorship, financial interest, employment or beneficial ownership in Data Fiduciaries, or having a material pecuniary relationship with them."}, "dpdp-rules-2025:sched_1__part_B__para_11": {"cite": "DPDP Rules Schedule I, Part B, para 11", "head": "", "text": "The Consent Manager shall publish in an easily accessible manner, on its website or app, or both, as the case may be, information regarding: — the promoters, directors, key managerial personnel and senior management of the company registered as Consent Manager; every person who holds shares in excess of two per cent. of the shareholding of the company registered as Consent Manager; every body corporate in whose shareholding any promoter, director, key managerial personnel or senior management of the Consent Manager holds shares in excess of two per cent. as on the first day of the preceding ca…"}, "dpdp-rules-2025:sched_1__part_B__para_11__cl_a": {"cite": "DPDP Rules Schedule I, Part B, para 11(a)", "head": "", "text": "the promoters, directors, key managerial personnel and senior management of the company registered as Consent Manager;"}, "dpdp-rules-2025:sched_1__part_B__para_11__cl_b": {"cite": "DPDP Rules Schedule I, Part B, para 11(b)", "head": "", "text": "every person who holds shares in excess of two per cent. of the shareholding of the company registered as Consent Manager;"}, "dpdp-rules-2025:sched_1__part_B__para_11__cl_c": {"cite": "DPDP Rules Schedule I, Part B, para 11(c)", "head": "", "text": "every body corporate in whose shareholding any promoter, director, key managerial personnel or senior management of the Consent Manager holds shares in excess of two per cent. as on the first day of the preceding calendar month; and"}, "dpdp-rules-2025:sched_1__part_B__para_11__cl_d": {"cite": "DPDP Rules Schedule I, Part B, para 11(d)", "head": "", "text": "such other information as the Board may direct the Consent Manager to disclose in the interests of transparency."}, "dpdp-rules-2025:sched_1__part_B__para_12": {"cite": "DPDP Rules Schedule I, Part B, para 12", "head": "", "text": "The Consent Manager shall have in place effective audit mechanisms to review, monitor, evaluate and report the outcome of such audit to the Board, periodically and on such other occasions as the Board may direct, in respect of— technical and organisational controls, systems, procedures and safeguards; continued fulfilment of the conditions of registration; and adherence to its obligations under the Act and these rules."}, "dpdp-rules-2025:sched_1__part_B__para_12__cl_a": {"cite": "DPDP Rules Schedule I, Part B, para 12(a)", "head": "", "text": "technical and organisational controls, systems, procedures and safeguards;"}, "dpdp-rules-2025:sched_1__part_B__para_12__cl_b": {"cite": "DPDP Rules Schedule I, Part B, para 12(b)", "head": "", "text": "continued fulfilment of the conditions of registration; and"}, "dpdp-rules-2025:sched_1__part_B__para_12__cl_c": {"cite": "DPDP Rules Schedule I, Part B, para 12(c)", "head": "", "text": "adherence to its obligations under the Act and these rules."}, "dpdp-rules-2025:sched_1__part_B__para_13": {"cite": "DPDP Rules Schedule I, Part B, para 13", "head": "", "text": "The control of the company registered as the Consent Manager shall not be transferred by way of sale, merger or otherwise, except with the previous approval of the Board and subject to fulfilment of such conditions as the Board may specify in this behalf."}, "dpdp-rules-2025:sched_1__part_B__hcontainer_1": {"cite": "DPDP Rules Schedule I, Part B", "head": "", "text": "In this Schedule, — the expression “body corporate” shall include a company, a body corporate as defined under clause (11) of section 2 of the Companies Act, 2013 (18 of 2013), a firm, a financial institution, a scheduled bank or a public sector enterprise established or constituted by or under any Central Act, Provincial Act or State Act, and any other incorporated association of persons or body of individuals; the expressions “company”, “control”, “director” and “key managerial personnel” shall have the same meanings as are respectively assigned to them in the Companies Act, 2013 (18 of 2013…"}, "dpdp-rules-2025:sched_1__part_B__hcontainer_1__cl_a": {"cite": "DPDP Rules Schedule I, Part B(a)", "head": "", "text": "the expression “body corporate” shall include a company, a body corporate as defined under clause (11) of section 2 of the Companies Act, 2013 (18 of 2013), a firm, a financial institution, a scheduled bank or a public sector enterprise established or constituted by or under any Central Act, Provincial Act or State Act, and any other incorporated association of persons or body of individuals;"}, "dpdp-rules-2025:sched_1__part_B__hcontainer_1__cl_b": {"cite": "DPDP Rules Schedule I, Part B(b)", "head": "", "text": "the expressions “company”, “control”, “director” and “key managerial personnel” shall have the same meanings as are respectively assigned to them in the Companies Act, 2013 (18 of 2013);"}, "dpdp-rules-2025:sched_1__part_B__hcontainer_1__cl_c": {"cite": "DPDP Rules Schedule I, Part B(c)", "head": "", "text": "the expression “net worth” shall mean the aggregate value of total assets as reduced by the value of liabilities of the Consent Manager as appearing in its books of accounts; and"}, "dpdp-rules-2025:sched_1__part_B__hcontainer_1__cl_d": {"cite": "DPDP Rules Schedule I, Part B(d)", "head": "", "text": "the expressions “promoter” and “senior management” shall have the same meanings as are respectively assigned to them in the Companies Act, 2013 (18 of 2013)."}, "dpdp-rules-2025:sched_2": {"cite": "DPDP Rules Schedule II", "head": "", "text": "SECOND SCHEDULE [See rules 5(1) and 16] Standards for processing of personal data by State and its instrumentalities under clause (b) of section 7 and for processing of personal data necessary for the purposes specified in clause (b) of sub- section (2) of section 17 Implementation of appropriate technical and organisational measures to ensure effective observance of the following, in accordance with applicable law, for the processing of personal data, namely: — Processing is carried out in a lawful manner; Processing is done for the uses specified in clause (b) of section 7 of the Act or for …"}, "dpdp-rules-2025:sched_2__intro": {"cite": "DPDP Rules Schedule II", "head": "", "text": "Implementation of appropriate technical and organisational measures to ensure effective observance of the following, in accordance with applicable law, for the processing of personal data, namely: —"}, "dpdp-rules-2025:sched_2__cl_a": {"cite": "DPDP Rules Schedule II(a)", "head": "", "text": "Processing is carried out in a lawful manner;"}, "dpdp-rules-2025:sched_2__cl_b": {"cite": "DPDP Rules Schedule II(b)", "head": "", "text": "Processing is done for the uses specified in clause (b) of section 7 of the Act or for the purposes specified in clause (b) of sub-section (2) of section 17 of the Act, as the case may be;"}, "dpdp-rules-2025:sched_2__cl_c": {"cite": "DPDP Rules Schedule II(c)", "head": "", "text": "Processing is limited to such personal data as is necessary for such uses or achieving such purposes, as the case may be;"}, "dpdp-rules-2025:sched_2__cl_d": {"cite": "DPDP Rules Schedule II(d)", "head": "", "text": "Processing is done while making reasonable efforts to ensure the completeness, accuracy and consistency of personal data;"}, "dpdp-rules-2025:sched_2__cl_e": {"cite": "DPDP Rules Schedule II(e)", "head": "", "text": "Personal data is retained till required for such uses or achieving such purposes, as the case may be, or for compliance with any law for the time being in force;"}, "dpdp-rules-2025:sched_2__cl_f": {"cite": "DPDP Rules Schedule II(f)", "head": "", "text": "Reasonable security safeguards to prevent personal data breach to protect personal data in the possession or under control of the Data Fiduciary, including in respect of any processing undertaken by it or on its behalf by a Data Processor;"}, "dpdp-rules-2025:sched_2__cl_g": {"cite": "DPDP Rules Schedule II(g)", "head": "", "text": "Where processing is to be done under clause (b) of section 7 of the Act, the same is undertaken while giving the Data Principal an intimation in respect of the same and— giving the business contact information of a person who is able to answer on behalf of the Data Fiduciary the questions of the Data Principal about the processing of her personal data; specifying the particular communication link for accessing the website or app, or both, of such Data Fiduciary, and a description of other means, if any, using which such Data Principal may exercise her rights under the Act; and is carried on in…"}, "dpdp-rules-2025:sched_2__cl_g__subcl_i": {"cite": "DPDP Rules Schedule II(g)(i)", "head": "", "text": "giving the business contact information of a person who is able to answer on behalf of the Data Fiduciary the questions of the Data Principal about the processing of her personal data;"}, "dpdp-rules-2025:sched_2__cl_g__subcl_ii": {"cite": "DPDP Rules Schedule II(g)(ii)", "head": "", "text": "specifying the particular communication link for accessing the website or app, or both, of such Data Fiduciary, and a description of other means, if any, using which such Data Principal may exercise her rights under the Act; and"}, "dpdp-rules-2025:sched_2__cl_g__subcl_iii": {"cite": "DPDP Rules Schedule II(g)(iii)", "head": "", "text": "is carried on in a manner consistent with such other standards as may be applicable to the processing of such personal data under policy issued by the Central Government or any law for the time being in force; and"}, "dpdp-rules-2025:sched_2__cl_h": {"cite": "DPDP Rules Schedule II(h)", "head": "", "text": "Accountability of the person who alone or in conjunction with other persons determines the purpose and means of processing of personal data, for effective observance of these standards."}, "dpdp-rules-2025:sched_3": {"cite": "DPDP Rules Schedule III", "head": "", "text": "THIRD SCHEDULE [See rule 8(1)] S. no. Class of Data Fiduciaries Purposes Time period (1) (2) (3) (4) 1. Data Fiduciary who is an e-commerce entity having not less than two crore registered users in India. For all purposes, except for the following: (a) Enabling the Data Principal to access her user account; and (b) Enabling the Data Principal to access any virtual token that is issued by or on behalf of the Data Fiduciary, is stored on the digital facility or platform of such Data Fiduciary, and may be used to get money, goods or services. Three years from the date on which the Data Principal …"}, "dpdp-rules-2025:sched_3__table_1": {"cite": "DPDP Rules Schedule III", "head": "", "text": "S. no. Class of Data Fiduciaries Purposes Time period (1) (2) (3) (4) 1. Data Fiduciary who is an e-commerce entity having not less than two crore registered users in India. For all purposes, except for the following: (a) Enabling the Data Principal to access her user account; and (b) Enabling the Data Principal to access any virtual token that is issued by or on behalf of the Data Fiduciary, is stored on the digital facility or platform of such Data Fiduciary, and may be used to get money, goods or services. Three years from the date on which the Data Principal last approached the Data Fiduci…"}, "dpdp-rules-2025:sched_3__hcontainer_1": {"cite": "DPDP Rules Schedule III", "head": "", "text": "In this Schedule, — “e-commerce entity” means any person who owns, operates or manages a digital facility or platform for e-commerce as defined in the Consumer Protection Act, 2019 (35 of 2019), but does not include a seller offering her goods or services for sale on a marketplace e-commerce entity as defined in the said Act; “online gaming intermediary” means any intermediary who enables the users of its computer resource to access one or more online games; “social media intermediary” means an intermediary as defined in clause (w) of sub-rule (1) of rule 2 of the Information Technology (Inter…"}, "dpdp-rules-2025:sched_3__hcontainer_1__cl_a": {"cite": "DPDP Rules Schedule III(a)", "head": "", "text": "“e-commerce entity” means any person who owns, operates or manages a digital facility or platform for e-commerce as defined in the Consumer Protection Act, 2019 (35 of 2019), but does not include a seller offering her goods or services for sale on a marketplace e-commerce entity as defined in the said Act;"}, "dpdp-rules-2025:sched_3__hcontainer_1__cl_b": {"cite": "DPDP Rules Schedule III(b)", "head": "", "text": "“online gaming intermediary” means any intermediary who enables the users of its computer resource to access one or more online games;"}, "dpdp-rules-2025:sched_3__hcontainer_1__cl_c": {"cite": "DPDP Rules Schedule III(c)", "head": "", "text": "“social media intermediary” means an intermediary as defined in clause (w) of sub-rule (1) of rule 2 of the Information Technology (Intermediary Guidelines and Digital Media Ethics Code) Rules, 2021; and"}, "dpdp-rules-2025:sched_3__hcontainer_1__cl_d": {"cite": "DPDP Rules Schedule III(d)", "head": "", "text": "“user”, in relation to— an e-commerce entity, means any person who accesses or avails any computer resource of an e-commerce entity; and an online gaming intermediary or a social media intermediary, means any person who accesses or avails of any computer resource of an intermediary for the purpose of hosting, publishing, sharing, transacting, viewing, displaying, downloading or uploading information."}, "dpdp-rules-2025:sched_3__hcontainer_1__cl_d__subcl_i": {"cite": "DPDP Rules Schedule III(d)(i)", "head": "", "text": "an e-commerce entity, means any person who accesses or avails any computer resource of an e-commerce entity; and"}, "dpdp-rules-2025:sched_3__hcontainer_1__cl_d__subcl_ii": {"cite": "DPDP Rules Schedule III(d)(ii)", "head": "", "text": "an online gaming intermediary or a social media intermediary, means any person who accesses or avails of any computer resource of an intermediary for the purpose of hosting, publishing, sharing, transacting, viewing, displaying, downloading or uploading information."}, "dpdp-rules-2025:sched_4": {"cite": "DPDP Rules Schedule IV", "head": "", "text": "FOURTH SCHEDULE [See rule 12] Classes of Data Fiduciaries in respect of whom provisions of sub-sections (1) and (3) of section 9 shall not apply S. No. Class of Data Fiduciaries Conditions (1) (2) (3) 1. A Data Fiduciary who is a clinical establishment, mental health establishment or healthcare professional. Processing is restricted to provision of health services to the child by such establishment or professional, to the extent necessary for the protection of her health. 2. A Data Fiduciary who is an allied healthcare professional. Processing is restricted to supporting implementation of any …"}, "dpdp-rules-2025:sched_4__part_A": {"cite": "DPDP Rules Schedule IV, Part A", "head": "Classes of Data Fiduciaries in respect of whom provisions of sub-sections (1) and (3) of section 9 shall not apply", "text": "S. No. Class of Data Fiduciaries Conditions (1) (2) (3) 1. A Data Fiduciary who is a clinical establishment, mental health establishment or healthcare professional. Processing is restricted to provision of health services to the child by such establishment or professional, to the extent necessary for the protection of her health. 2. A Data Fiduciary who is an allied healthcare professional. Processing is restricted to supporting implementation of any healthcare treatment and referral plan recommended by such professional for the child, to the extent necessary for the protection of her health. …"}, "dpdp-rules-2025:sched_4__part_A__table_1": {"cite": "DPDP Rules Schedule IV, Part A", "head": "", "text": "S. No. Class of Data Fiduciaries Conditions (1) (2) (3) 1. A Data Fiduciary who is a clinical establishment, mental health establishment or healthcare professional. Processing is restricted to provision of health services to the child by such establishment or professional, to the extent necessary for the protection of her health. 2. A Data Fiduciary who is an allied healthcare professional. Processing is restricted to supporting implementation of any healthcare treatment and referral plan recommended by such professional for the child, to the extent necessary for the protection of her health. …"}, "dpdp-rules-2025:sched_4__part_B": {"cite": "DPDP Rules Schedule IV, Part B", "head": "Purposes for which provisions of sub-sections (1) and (3) of section 9 shall not apply", "text": "S. No. Purposes Conditions (1) (2) (3) 1. For the exercise of any power, performance of any function or discharge of any duties in the interests of a child, under any law for the time being in force in India. Processing is restricted to the extent necessary for such exercise, performance or discharge. 2. For providing or issuing of any subsidy, benefit, service, certificate, licence or permit, by whatever name called, under law or policy or using public funds, in the interests of a child, under clause (b) of section 7 of the Act. Processing is restricted to the extent necessary for such provis…"}, "dpdp-rules-2025:sched_4__part_B__table_1": {"cite": "DPDP Rules Schedule IV, Part B", "head": "", "text": "S. No. Purposes Conditions (1) (2) (3) 1. For the exercise of any power, performance of any function or discharge of any duties in the interests of a child, under any law for the time being in force in India. Processing is restricted to the extent necessary for such exercise, performance or discharge. 2. For providing or issuing of any subsidy, benefit, service, certificate, licence or permit, by whatever name called, under law or policy or using public funds, in the interests of a child, under clause (b) of section 7 of the Act. Processing is restricted to the extent necessary for such provis…"}, "dpdp-rules-2025:sched_4__part_B__hcontainer_1": {"cite": "DPDP Rules Schedule IV, Part B", "head": "", "text": "In this Schedule, — “advertisement” shall have the same meaning as is assigned to it in the Consumer Protection Act, 2019 (35 of 2019); “allied healthcare professional” shall have the same meaning as is assigned to it in the clause (d) of section 2 of the National Commission for Allied and Healthcare Professions Act, 2021 (14 of 2021); “clinical establishment” shall have the same meaning as assigned to it in the clause (c) of section 2 of the Clinical Establishments (Registration and Regulation) Act, 2010 (23 of 2010); “educational institution” shall mean and include an institution of learning…"}, "dpdp-rules-2025:sched_4__part_B__hcontainer_1__cl_a": {"cite": "DPDP Rules Schedule IV, Part B(a)", "head": "", "text": "“advertisement” shall have the same meaning as is assigned to it in the Consumer Protection Act, 2019 (35 of 2019);"}, "dpdp-rules-2025:sched_4__part_B__hcontainer_1__cl_b": {"cite": "DPDP Rules Schedule IV, Part B(b)", "head": "", "text": "“allied healthcare professional” shall have the same meaning as is assigned to it in the clause (d) of section 2 of the National Commission for Allied and Healthcare Professions Act, 2021 (14 of 2021);"}, "dpdp-rules-2025:sched_4__part_B__hcontainer_1__cl_c": {"cite": "DPDP Rules Schedule IV, Part B(c)", "head": "", "text": "“clinical establishment” shall have the same meaning as assigned to it in the clause (c) of section 2 of the Clinical Establishments (Registration and Regulation) Act, 2010 (23 of 2010);"}, "dpdp-rules-2025:sched_4__part_B__hcontainer_1__cl_d": {"cite": "DPDP Rules Schedule IV, Part B(d)", "head": "", "text": "“educational institution” shall mean and include an institution of learning that imparts education, including vocational education;"}, "dpdp-rules-2025:sched_4__part_B__hcontainer_1__cl_e": {"cite": "DPDP Rules Schedule IV, Part B(e)", "head": "", "text": "“healthcare professional” shall have the same meaning as is assigned to it in clause (j) of section 2 of the National Commission for Allied and Healthcare Professions Act, 2021 (14 of 2021);"}, "dpdp-rules-2025:sched_4__part_B__hcontainer_1__cl_f": {"cite": "DPDP Rules Schedule IV, Part B(f)", "head": "", "text": "“health services” shall mean the services required to be provided by a healthcare professional as referred to in clause (j) of section 2 of the National Commission for Allied and Healthcare Professions Act, 2021 (14 of 2021); and"}, "dpdp-rules-2025:sched_4__part_B__hcontainer_1__cl_g": {"cite": "DPDP Rules Schedule IV, Part B(g)", "head": "", "text": "“mental health establishment” shall have the same meaning as is assigned to it in clause (p) of sub-section (1) of section 2 of the Mental Healthcare Act, 2017 (10 of 2017)."}, "dpdp-rules-2025:sched_5": {"cite": "DPDP Rules Schedule V", "head": "", "text": "FIFTH SCHEDULE [See rule 18] Terms and conditions of service of Chairperson and other Members Salary The Chairperson shall be entitled to receive a consolidated salary of rupees four lakh fifty thousand per month, without the facility of house and car. Every Member other than the Chairperson shall be entitled to receive a consolidated salary of rupees four lakh per month, without the facility of house and car. Provident Fund The Chairperson and every other Member shall be eligible to contribute to the Provident Fund of the Board, and the manner and terms and conditions applicable in this regar…"}, "dpdp-rules-2025:sched_5__para_1": {"cite": "DPDP Rules Schedule V, para 1", "head": "Salary", "text": "The Chairperson shall be entitled to receive a consolidated salary of rupees four lakh fifty thousand per month, without the facility of house and car. Every Member other than the Chairperson shall be entitled to receive a consolidated salary of rupees four lakh per month, without the facility of house and car."}, "dpdp-rules-2025:sched_5__para_1__subpara_1": {"cite": "DPDP Rules Schedule V, para 1(1)", "head": "", "text": "The Chairperson shall be entitled to receive a consolidated salary of rupees four lakh fifty thousand per month, without the facility of house and car."}, "dpdp-rules-2025:sched_5__para_1__subpara_2": {"cite": "DPDP Rules Schedule V, para 1(2)", "head": "", "text": "Every Member other than the Chairperson shall be entitled to receive a consolidated salary of rupees four lakh per month, without the facility of house and car."}, "dpdp-rules-2025:sched_5__para_2": {"cite": "DPDP Rules Schedule V, para 2", "head": "Provident Fund", "text": "The Chairperson and every other Member shall be eligible to contribute to the Provident Fund of the Board, and the manner and terms and conditions applicable in this regard shall, mutatis mutandis, be the same as those applicable to other officers and employees of the Board for their Provident Fund."}, "dpdp-rules-2025:sched_5__para_3": {"cite": "DPDP Rules Schedule V, para 3", "head": "Pension and gratuity", "text": "The Chairperson and every other Member shall not be entitled to payment of pension or gratuity for service rendered in the Board."}, "dpdp-rules-2025:sched_5__para_4": {"cite": "DPDP Rules Schedule V, para 4", "head": "Travelling allowance", "text": "The Chairperson and every other Member, while on transfer to join the Board, or on the expiry of her term with the Board for proceeding to her home town with family (including in respect of journey undertaken by her and her family), or on tour within India, shall be entitled to journey allowance, daily allowance and reimbursement of expense on transportation of personal effects at such scales and rates as are applicable to an officer of the Central Government in the following level of the pay matrix, namely:— level 17, in the case of the Chairperson; and level 15, in the case of every other Me…"}, "dpdp-rules-2025:sched_5__para_4__subpara_1": {"cite": "DPDP Rules Schedule V, para 4(1)", "head": "", "text": "The Chairperson and every other Member, while on transfer to join the Board, or on the expiry of her term with the Board for proceeding to her home town with family (including in respect of journey undertaken by her and her family), or on tour within India, shall be entitled to journey allowance, daily allowance and reimbursement of expense on transportation of personal effects at such scales and rates as are applicable to an officer of the Central Government in the following level of the pay matrix, namely:— level 17, in the case of the Chairperson; and level 15, in the case of every other Me…"}, "dpdp-rules-2025:sched_5__para_4__subpara_1__cl_a": {"cite": "DPDP Rules Schedule V, para 4(1)(a)", "head": "", "text": "level 17, in the case of the Chairperson; and"}, "dpdp-rules-2025:sched_5__para_4__subpara_1__cl_b": {"cite": "DPDP Rules Schedule V, para 4(1)(b)", "head": "", "text": "level 15, in the case of every other Member."}, "dpdp-rules-2025:sched_5__para_4__subpara_2": {"cite": "DPDP Rules Schedule V, para 4(2)", "head": "", "text": "The Chairperson and every other Member may undertake tour outside India only in accordance with guidelines or instructions issued by the Central Government, and in respect of such tour, she shall be entitled to draw the same allowances as an officer of the Central Government, in the following level of the pay matrix, is entitled to draw, namely: — level 17, in the case of the Chairperson; and level 15, in the case of every other Member."}, "dpdp-rules-2025:sched_5__para_4__subpara_2__cl_a": {"cite": "DPDP Rules Schedule V, para 4(2)(a)", "head": "", "text": "level 17, in the case of the Chairperson; and"}, "dpdp-rules-2025:sched_5__para_4__subpara_2__cl_b": {"cite": "DPDP Rules Schedule V, para 4(2)(b)", "head": "", "text": "level 15, in the case of every other Member."}, "dpdp-rules-2025:sched_5__para_5": {"cite": "DPDP Rules Schedule V, para 5", "head": "Medical assistance", "text": "The Chairperson and every other Member shall be entitled to such medical assistance as may be admissible to them under any group health insurance scheme of the Board for officers and employees of the Board and their eligible dependants. If the Chairperson or other Member has retired from Government service, or from the service of a public sector entity or a body corporate established by a Central Act, Provincial Act or State Act, and there are a separate set of rules for the grant of medical assistance for such service, she may, in lieu of medical assistance under sub-paragraph (1), opt to be …"}, "dpdp-rules-2025:sched_5__para_5__subpara_1": {"cite": "DPDP Rules Schedule V, para 5(1)", "head": "", "text": "The Chairperson and every other Member shall be entitled to such medical assistance as may be admissible to them under any group health insurance scheme of the Board for officers and employees of the Board and their eligible dependants."}, "dpdp-rules-2025:sched_5__para_5__subpara_2": {"cite": "DPDP Rules Schedule V, para 5(2)", "head": "", "text": "If the Chairperson or other Member has retired from Government service, or from the service of a public sector entity or a body corporate established by a Central Act, Provincial Act or State Act, and there are a separate set of rules for the grant of medical assistance for such service, she may, in lieu of medical assistance under sub-paragraph (1), opt to be governed by such rules."}, "dpdp-rules-2025:sched_5__para_6": {"cite": "DPDP Rules Schedule V, para 6", "head": "Leave", "text": "The authority competent to sanction leave shall be the Central Government in respect of the Chairperson, and the Chairperson in respect of any other Member. The Chairperson and every other Member may avail of such kinds of leave as are admissible to a Government servant under sub-clause (i) of clause (a) and clause (b) of sub-rule (1) of rule 26, rules 27, 29, 30 and 40 to 43-C of the Central Civil Services (Leave) Rules, 1972 (hereinafter referred to as “Leave Rules”). Leave shall be subject to the conditions applicable to a Government servant under rules 7 to 11 and 22 to 25 of the Leave Rul…"}, "dpdp-rules-2025:sched_5__para_6__subpara_1": {"cite": "DPDP Rules Schedule V, para 6(1)", "head": "", "text": "The authority competent to sanction leave shall be the Central Government in respect of the Chairperson, and the Chairperson in respect of any other Member."}, "dpdp-rules-2025:sched_5__para_6__subpara_2": {"cite": "DPDP Rules Schedule V, para 6(2)", "head": "", "text": "The Chairperson and every other Member may avail of such kinds of leave as are admissible to a Government servant under sub-clause (i) of clause (a) and clause (b) of sub-rule (1) of rule 26, rules 27, 29, 30 and 40 to 43-C of the Central Civil Services (Leave) Rules, 1972 (hereinafter referred to as “Leave Rules”)."}, "dpdp-rules-2025:sched_5__para_6__subpara_3": {"cite": "DPDP Rules Schedule V, para 6(3)", "head": "", "text": "Leave shall be subject to the conditions applicable to a Government servant under rules 7 to 11 and 22 to 25 of the Leave Rules, and the Central Government may, if satisfied that the operation of any of the said rules causes undue hardship in a particular case, by order relax the requirements of that rule to such extent and subject to such exceptions and conditions as it may consider necessary for dealing with the case in a just and equitable manner."}, "dpdp-rules-2025:sched_5__para_6__subpara_4": {"cite": "DPDP Rules Schedule V, para 6(4)", "head": "", "text": "The Chairperson and every other Member shall be entitled to casual leave to such extent as is admissible to a Government servant under instructions issued by the Central Government."}, "dpdp-rules-2025:sched_5__para_6__subpara_5": {"cite": "DPDP Rules Schedule V, para 6(5)", "head": "", "text": "The Chairperson and every other Member shall be entitled to encashment of earned leave standing to her credit, subject to such conditions and in like manner as are applicable to a Government servant under rule 38-A, sub-rules (1) and (2) and sub-clauses (i) and (ii) of clause (a) of sub-rule (6) of rule 39, rule 39-A and rule 39-C of the Leave Rules, subject to the maximum extent of encashment under any of the said rules, other than rule 38-A, being fifty per cent. of the earned leave standing to her credit."}, "dpdp-rules-2025:sched_5__para_7": {"cite": "DPDP Rules Schedule V, para 7", "head": "Leave travel concession", "text": "Leave travel concession shall be admissible to the Chairperson and every other Member in accordance with the provisions applicable to persons appointed to civil services and posts in connection with the affairs of the Union of India under rule 3, clauses (a) and (d) of rule 4, rules 5 to 15 and rule 17 of the Central Civil Services (Leave Travel Concession) Rules, 1988, and the entitlement for such concession shall be the same as is applicable to officers of the Central Government in level 17 of the pay matrix in the case of the Chairperson, and to officers of the Central Government in level 1…"}, "dpdp-rules-2025:sched_5__para_7__subpara_1": {"cite": "DPDP Rules Schedule V, para 7(1)", "head": "", "text": "Leave travel concession shall be admissible to the Chairperson and every other Member in accordance with the provisions applicable to persons appointed to civil services and posts in connection with the affairs of the Union of India under rule 3, clauses (a) and (d) of rule 4, rules 5 to 15 and rule 17 of the Central Civil Services (Leave Travel Concession) Rules, 1988, and the entitlement for such concession shall be the same as is applicable to officers of the Central Government in level 17 of the pay matrix in the case of the Chairperson, and to officers of the Central Government in level 1…"}, "dpdp-rules-2025:sched_5__para_7__subpara_2": {"cite": "DPDP Rules Schedule V, para 7(2)", "head": "", "text": "The Chairperson and every other Member shall be eligible to avail of either leave travel concession to home town or leave travel concession to any place in India in any period of two years from the date of assumption of their office as a Member."}, "dpdp-rules-2025:sched_5__para_8": {"cite": "DPDP Rules Schedule V, para 8", "head": "Other terms and conditions of service", "text": "The Chairperson and every other Member shall ensure absence of conflict of interest in the performance of the functions of her office and shall not have any such financial or other interests as are likely to prejudicially affect the performance of the functions of such office. The provisions contained in Part IV to Part IX of the Central Civil Services (Classification, Control and Appeal) Rules, 1965, as applicable to an officer of the Central Government who is a member of a Central Civil Services, Group ‘A’, shall apply, mutatis mutandis, to the Chairperson and every other Member. The Chairpe…"}, "dpdp-rules-2025:sched_5__para_8__subpara_1": {"cite": "DPDP Rules Schedule V, para 8(1)", "head": "", "text": "The Chairperson and every other Member shall ensure absence of conflict of interest in the performance of the functions of her office and shall not have any such financial or other interests as are likely to prejudicially affect the performance of the functions of such office."}, "dpdp-rules-2025:sched_5__para_8__subpara_2": {"cite": "DPDP Rules Schedule V, para 8(2)", "head": "", "text": "The provisions contained in Part IV to Part IX of the Central Civil Services (Classification, Control and Appeal) Rules, 1965, as applicable to an officer of the Central Government who is a member of a Central Civil Services, Group ‘A’, shall apply, mutatis mutandis, to the Chairperson and every other Member."}, "dpdp-rules-2025:sched_5__para_8__subpara_3": {"cite": "DPDP Rules Schedule V, para 8(3)", "head": "", "text": "The Chairperson and every other Member shall not be entitled to any sitting fee for attending meetings of the Board."}, "dpdp-rules-2025:sched_5__para_8__subpara_4": {"cite": "DPDP Rules Schedule V, para 8(4)", "head": "", "text": "The Chairperson and every other Member shall not be entitled to any sumptuary allowance."}, "dpdp-rules-2025:sched_5__para_8__subpara_5": {"cite": "DPDP Rules Schedule V, para 8(5)", "head": "", "text": "Any matter relating to the conditions of service of the Chairperson or any other Member, in respect of which no express provision has been made in these rules, shall be referred to the Central Government for its decision, and the decision of the Central Government on the same shall be final."}, "dpdp-rules-2025:sched_5__para_9": {"cite": "DPDP Rules Schedule V, para 9", "head": "", "text": "In this Schedule, “pay matrix” shall mean the pay matrix specified in Annexure I to the Central Government’s Resolution published in the Official Gazette vide Notification no. 1-2/2016-IC, dated the 25th July, 2016."}, "dpdp-rules-2025:sched_6": {"cite": "DPDP Rules Schedule VI", "head": "", "text": "SIXTH SCHEDULE [See rule 21(2)] Terms and conditions of appointment and service of officers and employees of Board Classes of officials The Board may, in accordance with the Fundamental Rules and applicable guidelines issued by the Ministry of Personnel, Public Grievances and Pensions, Department of Personnel and Training, appoint officers and employees on deputation from the Central Government, a State Government, an autonomous body under the overall control of the Central Government or a State Government, a statutory body, or a public sector enterprise, for a period not exceeding five years.…"}, "dpdp-rules-2025:sched_6__para_1": {"cite": "DPDP Rules Schedule VI, para 1", "head": "Classes of officials", "text": "The Board may, in accordance with the Fundamental Rules and applicable guidelines issued by the Ministry of Personnel, Public Grievances and Pensions, Department of Personnel and Training, appoint officers and employees on deputation from the Central Government, a State Government, an autonomous body under the overall control of the Central Government or a State Government, a statutory body, or a public sector enterprise, for a period not exceeding five years. The Board may also receive or take on deputation any officer or other employee from the National Institute for Smart Government, for a …"}, "dpdp-rules-2025:sched_6__para_1__subpara_1": {"cite": "DPDP Rules Schedule VI, para 1(1)", "head": "", "text": "The Board may, in accordance with the Fundamental Rules and applicable guidelines issued by the Ministry of Personnel, Public Grievances and Pensions, Department of Personnel and Training, appoint officers and employees on deputation from the Central Government, a State Government, an autonomous body under the overall control of the Central Government or a State Government, a statutory body, or a public sector enterprise, for a period not exceeding five years."}, "dpdp-rules-2025:sched_6__para_1__subpara_2": {"cite": "DPDP Rules Schedule VI, para 1(2)", "head": "", "text": "The Board may also receive or take on deputation any officer or other employee from the National Institute for Smart Government, for a period not exceeding five years, with salary and allowances guided by market standards and on such other terms and conditions as the Board may decide."}, "dpdp-rules-2025:sched_6__para_2": {"cite": "DPDP Rules Schedule VI, para 2", "head": "Gratuity", "text": "The officers and employees shall be entitled to payment of such gratuity as may be admissible under the Payment of Gratuity Act, 1972 (39 of 1972)."}, "dpdp-rules-2025:sched_6__para_3": {"cite": "DPDP Rules Schedule VI, para 3", "head": "Travelling allowance", "text": "The travelling allowance payable to the officers and employees shall, mutatis mutandis, be the same as those applicable to the officers and employees of the Central Government."}, "dpdp-rules-2025:sched_6__para_4": {"cite": "DPDP Rules Schedule VI, para 4", "head": "Medical assistance", "text": "The officers and employees shall be entitled to such medical assistance as may be admissible to them and their eligible dependants under any group health insurance scheme of the Board, made with the previous approval of the Central Government."}, "dpdp-rules-2025:sched_6__para_5": {"cite": "DPDP Rules Schedule VI, para 5", "head": "Leave", "text": "The officers and employees may avail of such kinds of leaves as are admissible to a Government servant under the Central Civil Services (Leave) Rules, 1972, subject to the conditions applicable under the said rules, and shall be eligible for encashment of earned leave as provided therein. The officers and employees shall be entitled to casual leave to such extent as is admissible to a Government servant under instructions issued by the Central Government."}, "dpdp-rules-2025:sched_6__para_5__subpara_1": {"cite": "DPDP Rules Schedule VI, para 5(1)", "head": "", "text": "The officers and employees may avail of such kinds of leaves as are admissible to a Government servant under the Central Civil Services (Leave) Rules, 1972, subject to the conditions applicable under the said rules, and shall be eligible for encashment of earned leave as provided therein."}, "dpdp-rules-2025:sched_6__para_5__subpara_2": {"cite": "DPDP Rules Schedule VI, para 5(2)", "head": "", "text": "The officers and employees shall be entitled to casual leave to such extent as is admissible to a Government servant under instructions issued by the Central Government."}, "dpdp-rules-2025:sched_6__para_6": {"cite": "DPDP Rules Schedule VI, para 6", "head": "Leave travel concession", "text": "Leave travel concession shall be admissible to the officers and employees appointed under clause (1) of paragraph 1, in accordance with the provisions applicable to persons appointed to civil services and posts in connection with the affairs of the Union of India under the Central Civil Services (Leave Travel Concession) Rules, 1988."}, "dpdp-rules-2025:sched_6__para_7": {"cite": "DPDP Rules Schedule VI, para 7", "head": "Other terms and conditions of service", "text": "The provisions of the Civil Service (Conduct) Rules, 1964 shall apply to the officers and employees in like manner as applicable to a person appointed to a civil service or post in connection with the affairs of the Union of India under the said rules. The provisions contained in Part IV to Part IX of the Central Civil Services (Classification, Control and Appeal) Rules, 1965 shall apply, mutatis mutandis, to the officers and employees appointed under clause (1) of paragraph 1, in like manner as applicable to a Government servant under the said rules. Any matter relating to the terms and condi…"}, "dpdp-rules-2025:sched_6__para_7__subpara_1": {"cite": "DPDP Rules Schedule VI, para 7(1)", "head": "", "text": "The provisions of the Civil Service (Conduct) Rules, 1964 shall apply to the officers and employees in like manner as applicable to a person appointed to a civil service or post in connection with the affairs of the Union of India under the said rules."}, "dpdp-rules-2025:sched_6__para_7__subpara_2": {"cite": "DPDP Rules Schedule VI, para 7(2)", "head": "", "text": "The provisions contained in Part IV to Part IX of the Central Civil Services (Classification, Control and Appeal) Rules, 1965 shall apply, mutatis mutandis, to the officers and employees appointed under clause (1) of paragraph 1, in like manner as applicable to a Government servant under the said rules."}, "dpdp-rules-2025:sched_6__para_7__subpara_3": {"cite": "DPDP Rules Schedule VI, para 7(3)", "head": "", "text": "Any matter relating to the terms and conditions of service of the officers and employees appointed under clause (1) of paragraph 1, in respect of which no express provision has been made in these rules, shall be referred to the Central Government for its decision, and the decision of the Central Government on the same shall be final."}, "dpdp-rules-2025:sched_7": {"cite": "DPDP Rules Schedule VII", "head": "", "text": "SEVENTH SCHEDULE [See rule 23(1) and 8(3)] S. no. Purpose Authorised person (1) (2) (3) 1. Use, by the State or any of its instrumentalities, of personal data of a Data Principal in the interest of sovereignty and integrity of India or security of the State. Such officer of the State or of any of its instrumentalities notified under clause (a) of sub-section (2) of section 17 of the Act, as the Central Government or the head of such instrumentality, as the case may be, may designate in this behalf. 2. Use, by the State or any of its instrumentalities, of personal data of a Data Principal for t…"}, "dpdp-rules-2025:sched_7__table_1": {"cite": "DPDP Rules Schedule VII", "head": "", "text": "S. no. Purpose Authorised person (1) (2) (3) 1. Use, by the State or any of its instrumentalities, of personal data of a Data Principal in the interest of sovereignty and integrity of India or security of the State. Such officer of the State or of any of its instrumentalities notified under clause (a) of sub-section (2) of section 17 of the Act, as the Central Government or the head of such instrumentality, as the case may be, may designate in this behalf. 2. Use, by the State or any of its instrumentalities, of personal data of a Data Principal for the following purposes, namely: — (i) perfor…"}, "it-act-2000:chp_I": {"cite": "IT Act Chapter I", "head": "PRELIMINARY", "text": "Short title, extent, commencement and application This Act may be called the Information Technology Act, 2000. It shall extend to the whole of India and, save as otherwise provided in this Act, it applies also to any offence or contravention thereunder committed outside India by any person. It shall come into force on such date as the Central Government may, by notification, appoint and different dates may be appointed for different provisions of this Act and any reference in any such provision to the commencement of this Act shall be construed as a reference to the commencement of that provis…"}, "it-act-2000:sec_1": {"cite": "IT Act s.1", "head": "Short title, extent, commencement and application", "text": "This Act may be called the Information Technology Act, 2000. It shall extend to the whole of India and, save as otherwise provided in this Act, it applies also to any offence or contravention thereunder committed outside India by any person. It shall come into force on such date as the Central Government may, by notification, appoint and different dates may be appointed for different provisions of this Act and any reference in any such provision to the commencement of this Act shall be construed as a reference to the commencement of that provision. Nothing in this Act shall apply to documents …"}, "it-act-2000:sec_1__subsec_1": {"cite": "IT Act s.1(1)", "head": "", "text": "This Act may be called the Information Technology Act, 2000."}, "it-act-2000:sec_1__subsec_2": {"cite": "IT Act s.1(2)", "head": "", "text": "It shall extend to the whole of India and, save as otherwise provided in this Act, it applies also to any offence or contravention thereunder committed outside India by any person."}, "it-act-2000:sec_1__subsec_3": {"cite": "IT Act s.1(3)", "head": "", "text": "It shall come into force on such date as the Central Government may, by notification, appoint and different dates may be appointed for different provisions of this Act and any reference in any such provision to the commencement of this Act shall be construed as a reference to the commencement of that provision."}, "it-act-2000:sec_1__subsec_4": {"cite": "IT Act s.1(4)", "head": "", "text": "Nothing in this Act shall apply to documents or transactions specified in the First Schedule: Provided that the Central Government may, by notification in the Official Gazette, amend the First Schedule by way of addition or deletion of entries thereto."}, "it-act-2000:sec_1__subsec_4__proviso_1": {"cite": "IT Act s.1(4)", "head": "", "text": "Provided that the Central Government may, by notification in the Official Gazette, amend the First Schedule by way of addition or deletion of entries thereto."}, "it-act-2000:sec_1__subsec_5": {"cite": "IT Act s.1(5)", "head": "", "text": "Every notification issued under sub-section (4) shall be laid before each House of Parliament."}, "it-act-2000:sec_2": {"cite": "IT Act s.2", "head": "Definitions", "text": "In this Act, unless the context otherwise requires,— \"access\" with its grammatical variations and cognate expressions means gaining entry into, instructing or communicating with the logical, arithmetical, or memory function resources of a computer, computer system or computer network; \"addressee\" means a person who is intended by the originator to receive the electronic record but does not include any intermediary; \"adjudicating officer\" means an adjudicating officer appointed under sub-section (1) of section 46; \"affixing electronic signature\" with its grammatical variations and cognate expre…"}, "it-act-2000:sec_2__subsec_1": {"cite": "IT Act s.2(1)", "head": "", "text": "In this Act, unless the context otherwise requires,— \"access\" with its grammatical variations and cognate expressions means gaining entry into, instructing or communicating with the logical, arithmetical, or memory function resources of a computer, computer system or computer network; \"addressee\" means a person who is intended by the originator to receive the electronic record but does not include any intermediary; \"adjudicating officer\" means an adjudicating officer appointed under sub-section (1) of section 46; \"affixing electronic signature\" with its grammatical variations and cognate expre…"}, "it-act-2000:sec_2__subsec_1__cl_a": {"cite": "IT Act s.2(1)(a)", "head": "", "text": "\"access\" with its grammatical variations and cognate expressions means gaining entry into, instructing or communicating with the logical, arithmetical, or memory function resources of a computer, computer system or computer network;"}, "it-act-2000:sec_2__subsec_1__cl_b": {"cite": "IT Act s.2(1)(b)", "head": "", "text": "\"addressee\" means a person who is intended by the originator to receive the electronic record but does not include any intermediary;"}, "it-act-2000:sec_2__subsec_1__cl_c": {"cite": "IT Act s.2(1)(c)", "head": "", "text": "\"adjudicating officer\" means an adjudicating officer appointed under sub-section (1) of section 46;"}, "it-act-2000:sec_2__subsec_1__cl_d": {"cite": "IT Act s.2(1)(d)", "head": "", "text": "\"affixing electronic signature\" with its grammatical variations and cognate expressions means adoption of any methodology or procedure by a person for the purpose of authenticating an electronic record by means of electronic signature;"}, "it-act-2000:sec_2__subsec_1__cl_da": {"cite": "IT Act s.2(1)(da)", "head": "", "text": "\"Appellate Tribunal\" means the Appellate Tribunal referred to in sub-section (1) of section 48;"}, "it-act-2000:sec_2__subsec_1__cl_e": {"cite": "IT Act s.2(1)(e)", "head": "", "text": "\"appropriate Government\" means as respects any matter,— enumerated in List II of the Seventh Schedule to the Constitution; relating to any State law enacted under List III of the Seventh Schedule to the Constitution, the State Government and in any other case, the Central Government;"}, "it-act-2000:sec_2__subsec_1__cl_e__subcl_i": {"cite": "IT Act s.2(1)(e)(i)", "head": "", "text": "enumerated in List II of the Seventh Schedule to the Constitution;"}, "it-act-2000:sec_2__subsec_1__cl_e__subcl_ii": {"cite": "IT Act s.2(1)(e)(ii)", "head": "", "text": "relating to any State law enacted under List III of the Seventh Schedule to the Constitution,"}, "it-act-2000:sec_2__subsec_1__cl_f": {"cite": "IT Act s.2(1)(f)", "head": "", "text": "\"asymmetric crypto system\" means a system of a secure key pair consisting of a private key for creating a digital signature and a public key to verify the digital signature;"}, "it-act-2000:sec_2__subsec_1__cl_g": {"cite": "IT Act s.2(1)(g)", "head": "", "text": "\"Certifying Authority\" means a person who has been granted a licence to issue a Electronic signature Certificate under section 24;"}, "it-act-2000:sec_2__subsec_1__cl_h": {"cite": "IT Act s.2(1)(h)", "head": "", "text": "\"certification practice statement\" means a statement issued by a Certifying Authority to specify the practices that the Certifying Authority employs in issuing Electronic signature Certificates;"}, "it-act-2000:sec_2__subsec_1__cl_ha": {"cite": "IT Act s.2(1)(ha)", "head": "", "text": "“communication device” means cell phones, personal digital assistance or combination of both or any other device used to communicate, send or transmit any text, video, audio or image;"}, "it-act-2000:sec_2__subsec_1__cl_i": {"cite": "IT Act s.2(1)(i)", "head": "", "text": "\"computer\" means any electronic magnetic, optical or other high-speed data processing device or system which performs logical, arithmetic, and memory functions by manipulations of electronic, magnetic or optical impulses, and includes all input, output, processing, storage, computer software, or communication facilities which are connected or related to the computer in a computer system or computer network;"}, "it-act-2000:sec_2__subsec_1__cl_j": {"cite": "IT Act s.2(1)(j)", "head": "", "text": "“computer network” means the inter-connection of one or more computers or computer systems or communication device through— the use of satellite, microwave, terrestrial line, wire, wireless or other communication media; and terminals or a complex consisting of two or more inter-connected computers or communication device whether or not the inter-connection is continuously maintained;"}, "it-act-2000:sec_2__subsec_1__cl_j__subcl_i": {"cite": "IT Act s.2(1)(j)(i)", "head": "", "text": "the use of satellite, microwave, terrestrial line, wire, wireless or other communication media; and"}, "it-act-2000:sec_2__subsec_1__cl_j__subcl_ii": {"cite": "IT Act s.2(1)(j)(ii)", "head": "", "text": "terminals or a complex consisting of two or more inter-connected computers or communication device whether or not the inter-connection is continuously maintained;"}, "it-act-2000:sec_2__subsec_1__cl_k": {"cite": "IT Act s.2(1)(k)", "head": "", "text": "\"computer resource\" means computer, computer system, computer network, data, computer data base or software;"}, "it-act-2000:sec_2__subsec_1__cl_l": {"cite": "IT Act s.2(1)(l)", "head": "", "text": "\"computer system\" means a device or collection of devices, including input and output support devices and excluding calculators which are not programmable and capable of being used in conjunction with external files, which contain computer programmes, electronic instructions, input data and output data, that performs logic, arithmetic, data storage and retrieval, communication control and other functions;"}, "it-act-2000:sec_2__subsec_1__cl_m": {"cite": "IT Act s.2(1)(m)", "head": "", "text": "\"Controller\" means the Controller of Certifying Authorities appointed under sub-section (1) of section 17;"}, "it-act-2000:sec_2__subsec_1__cl_n": {"cite": "IT Act s.2(1)(n)", "head": "", "text": ""}, "it-act-2000:sec_2__subsec_1__cl_na": {"cite": "IT Act s.2(1)(na)", "head": "", "text": "“cyber cafe” means any facility from where access to the internet is offered by any person in the ordinary course of business to the members of the public;"}, "it-act-2000:sec_2__subsec_1__cl_nb": {"cite": "IT Act s.2(1)(nb)", "head": "", "text": "“cyber security” means protecting information, equipment, devices, computer, computer resource, communication device and information stored therein from unauthorised access, use, disclosure, disruption, modification or destruction;"}, "it-act-2000:sec_2__subsec_1__cl_o": {"cite": "IT Act s.2(1)(o)", "head": "", "text": "\"data\" means a representation of information, knowledge, facts, concepts or instructions which are being prepared or have been prepared in a formalised manner, and is intended to be processed, is being processed or has been processed in a computer system or computer network, and may be in any form (including computer printouts magnetic or optical storage media, punched cards, punched tapes) or stored internally in the memory of the computer;"}, "it-act-2000:sec_2__subsec_1__cl_p": {"cite": "IT Act s.2(1)(p)", "head": "", "text": "\"digital signature\" means authentication of any electronic record by a subscriber by means of an electronic method or procedure in accordance with the provisions of section 3;"}, "it-act-2000:sec_2__subsec_1__cl_q": {"cite": "IT Act s.2(1)(q)", "head": "", "text": "\"Digital Signature Certificate\" means a Digital Signature Certificate issued under sub-section (4) of section 35;"}, "it-act-2000:sec_2__subsec_1__cl_r": {"cite": "IT Act s.2(1)(r)", "head": "", "text": "\"electronic form\" with reference to information means any information generated, sent, received or stored in media, magnetic, optical, computer memory, micro film, computer generated micro fiche or similar device;"}, "it-act-2000:sec_2__subsec_1__cl_s": {"cite": "IT Act s.2(1)(s)", "head": "", "text": "\"Electronic Gazette\" means the Official Gazette published in the electronic form;"}, "it-act-2000:sec_2__subsec_1__cl_t": {"cite": "IT Act s.2(1)(t)", "head": "", "text": "\"electronic record\" means data, record or data generated, image or sound stored, received or sent in an electronic form or micro film or computer generated micro fiche;"}, "it-act-2000:sec_2__subsec_1__cl_ta": {"cite": "IT Act s.2(1)(ta)", "head": "", "text": "“electronic signature” means authentication of any electronic record by a subscriber by means of the electronic technique specified in the Second Schedule and includes digital signature;"}, "it-act-2000:sec_2__subsec_1__cl_tb": {"cite": "IT Act s.2(1)(tb)", "head": "", "text": "“Electronic Signature Certificate” means an Electronic Signature Certificate issued under section 35 and includes Digital Signature Certificate;"}, "it-act-2000:sec_2__subsec_1__cl_u": {"cite": "IT Act s.2(1)(u)", "head": "", "text": "\"function\", in relation to a computer, includes logic, control, arithmetical process, deletion, storage and retrieval and communication or telecommunication from or within a computer;"}, "it-act-2000:sec_2__subsec_1__cl_ua": {"cite": "IT Act s.2(1)(ua)", "head": "", "text": "“Indian Computer Emergency Response Team” means an agency established under sub-section (1) of section 70B;"}, "it-act-2000:sec_2__subsec_1__cl_v": {"cite": "IT Act s.2(1)(v)", "head": "", "text": "\"information\" includes data, message, text, images, sound, voice, codes, computer programmes, software and data bases or micro film or computer generated micro fiche;"}, "it-act-2000:sec_2__subsec_1__cl_w": {"cite": "IT Act s.2(1)(w)", "head": "", "text": "“intermediary”, with respect to any particular electronic records, means any person who on behalf of another person receives, stores or transmits that record or provides any service with respect to that record and includes telecom service providers, network service providers, internet service providers, web-hosting service providers, search engines, online payment sites, online-auction sites, online-market places and cyber cafes;"}, "it-act-2000:sec_2__subsec_1__cl_x": {"cite": "IT Act s.2(1)(x)", "head": "", "text": "\"key pair\", in an asymmetric crypto system, means a private key and its mathematically related public key, which are so related that the public key can verify a digital signature created by the private key;"}, "it-act-2000:sec_2__subsec_1__cl_y": {"cite": "IT Act s.2(1)(y)", "head": "", "text": "\"law\" includes any Act of Parliament or of a State Legislature, Ordinances promulgated by the President or a Governor, as the case may be, Regulations made by the President under article 240, Bills enacted as President's Act under sub-clause (a) of clause (1) of article 357 of the Constitution and includes rules, regulations, bye-laws and orders issued or made thereunder;"}, "it-act-2000:sec_2__subsec_1__cl_z": {"cite": "IT Act s.2(1)(z)", "head": "", "text": "\"licence\" means a licence granted to a Certifying Authority under section 24;"}, "it-act-2000:sec_2__subsec_1__cl_za": {"cite": "IT Act s.2(1)(za)", "head": "", "text": "\"originator\" means a person who sends, generates, stores or transmits any electronic message or causes any electronic message to be sent, generated, stored or transmitted to any other person but does not include an intermediary;"}, "it-act-2000:sec_2__subsec_1__cl_zb": {"cite": "IT Act s.2(1)(zb)", "head": "", "text": "\"prescribed\" means prescribed by rules made under this Act;"}, "it-act-2000:sec_2__subsec_1__cl_zc": {"cite": "IT Act s.2(1)(zc)", "head": "", "text": "\"private key\" means the key of a key pair used to create a digital signature;"}, "it-act-2000:sec_2__subsec_1__cl_zd": {"cite": "IT Act s.2(1)(zd)", "head": "", "text": "\"public key\" means the key of a key pair used to verify a digital signature and listed in the Digital Signature Certificate;"}, "it-act-2000:sec_2__subsec_1__cl_ze": {"cite": "IT Act s.2(1)(ze)", "head": "", "text": "\"secure system\" means computer hardware, software, and procedure that— are reasonably secure from unauthorised access and misuse; provide a reasonable level of reliability and correct operation; are reasonably suited to performing the intended functions; and adhere to generally accepted security procedures;"}, "it-act-2000:sec_2__subsec_1__cl_ze__cl_a": {"cite": "IT Act s.2(1)(ze)(a)", "head": "", "text": "are reasonably secure from unauthorised access and misuse;"}, "it-act-2000:sec_2__subsec_1__cl_ze__cl_b": {"cite": "IT Act s.2(1)(ze)(b)", "head": "", "text": "provide a reasonable level of reliability and correct operation;"}, "it-act-2000:sec_2__subsec_1__cl_ze__cl_c": {"cite": "IT Act s.2(1)(ze)(c)", "head": "", "text": "are reasonably suited to performing the intended functions; and"}, "it-act-2000:sec_2__subsec_1__cl_ze__cl_d": {"cite": "IT Act s.2(1)(ze)(d)", "head": "", "text": "adhere to generally accepted security procedures;"}, "it-act-2000:sec_2__subsec_1__cl_zf": {"cite": "IT Act s.2(1)(zf)", "head": "", "text": "\"security procedure\" means the security procedure prescribed under section 16 by the Central Government;"}, "it-act-2000:sec_2__subsec_1__cl_zg": {"cite": "IT Act s.2(1)(zg)", "head": "", "text": "\"subscriber\" means a person in whose name the Electronic signature Certificate is issued;"}, "it-act-2000:sec_2__subsec_1__cl_zh": {"cite": "IT Act s.2(1)(zh)", "head": "", "text": "\"verify\" in relation to a digital signature, electronic record or public key, with its grammatical variations and cognate expressions means to determine whether— the initial electronic record was affixed with the digital signature by the use of private key corresponding to the public key of the subscriber; the initial electronic record is retained intact or has been altered since such electronic record was so affixed with the digital signature."}, "it-act-2000:sec_2__subsec_1__cl_zh__cl_a": {"cite": "IT Act s.2(1)(zh)(a)", "head": "", "text": "the initial electronic record was affixed with the digital signature by the use of private key corresponding to the public key of the subscriber;"}, "it-act-2000:sec_2__subsec_1__cl_zh__cl_b": {"cite": "IT Act s.2(1)(zh)(b)", "head": "", "text": "the initial electronic record is retained intact or has been altered since such electronic record was so affixed with the digital signature."}, "it-act-2000:sec_2__subsec_2": {"cite": "IT Act s.2(2)", "head": "", "text": "Any reference in this Act to any enactment or any provision thereof shall, in relation to an area in which such enactment or such provision is not in force, be construed as a reference to the corresponding law or the relevant provision of the corresponding law, if any, in force in that area."}, "it-act-2000:chp_II": {"cite": "IT Act Chapter II", "head": "DIGITAL SIGNATURE AND ELECTRONIC SIGNATURE", "text": "Authentication of electronic records Subject to the provisions of this section any subscriber may authenticate an electronic record by affixing his digital signature. The authentication of the electronic record shall be effected by the use of asymmetric crypto system and hash function which envelop and transform the initial electronic record into another electronic record. For the purposes of this sub-section, \"hash function\" means an algorithm mapping or translation of one sequence of bits into another, generally smaller, set known'as \"hash result\" such that an electronic record yields the sa…"}, "it-act-2000:sec_3": {"cite": "IT Act s.3", "head": "Authentication of electronic records", "text": "Subject to the provisions of this section any subscriber may authenticate an electronic record by affixing his digital signature. The authentication of the electronic record shall be effected by the use of asymmetric crypto system and hash function which envelop and transform the initial electronic record into another electronic record. For the purposes of this sub-section, \"hash function\" means an algorithm mapping or translation of one sequence of bits into another, generally smaller, set known'as \"hash result\" such that an electronic record yields the same hash result every time the algorit…"}, "it-act-2000:sec_3__subsec_1": {"cite": "IT Act s.3(1)", "head": "", "text": "Subject to the provisions of this section any subscriber may authenticate an electronic record by affixing his digital signature."}, "it-act-2000:sec_3__subsec_2": {"cite": "IT Act s.3(2)", "head": "", "text": "The authentication of the electronic record shall be effected by the use of asymmetric crypto system and hash function which envelop and transform the initial electronic record into another electronic record. For the purposes of this sub-section, \"hash function\" means an algorithm mapping or translation of one sequence of bits into another, generally smaller, set known'as \"hash result\" such that an electronic record yields the same hash result every time the algorithm is executed with the same electronic record as its input making it computationally infeasible— to derive or reconstruct the ori…"}, "it-act-2000:sec_3__subsec_2__hcontainer_1": {"cite": "IT Act s.3(2)", "head": "", "text": "For the purposes of this sub-section, \"hash function\" means an algorithm mapping or translation of one sequence of bits into another, generally smaller, set known'as \"hash result\" such that an electronic record yields the same hash result every time the algorithm is executed with the same electronic record as its input making it computationally infeasible— to derive or reconstruct the original electronic record from the hash result produced by the algorithm; that two electronic records can produce the same hash result using the algorithm."}, "it-act-2000:sec_3__subsec_2__hcontainer_1__cl_a": {"cite": "IT Act s.3(2)(a)", "head": "", "text": "to derive or reconstruct the original electronic record from the hash result produced by the algorithm;"}, "it-act-2000:sec_3__subsec_2__hcontainer_1__cl_b": {"cite": "IT Act s.3(2)(b)", "head": "", "text": "that two electronic records can produce the same hash result using the algorithm."}, "it-act-2000:sec_3__subsec_3": {"cite": "IT Act s.3(3)", "head": "", "text": "Any person by the use of a public key of the subscriber can verify the electronic record."}, "it-act-2000:sec_3__subsec_4": {"cite": "IT Act s.3(4)", "head": "", "text": "The private key and the public key are unique to the subscriber and constitute a functioning key pair."}, "it-act-2000:sec_3A": {"cite": "IT Act s.3A", "head": "Electronic signature", "text": "Notwithstanding anything contained in section 3, but subject to the provisions of sub-section (2), a subscriber may authenticate any electronic record by such electronic signature or electronic authentication technique which-(a) is considered reliable; and (b) may be specified in the Second Schedule. For the purposes of this section any electronic signature or electronic - authentication technique shall be considered reliable if— the signature creation data or the authentication data are, within the context in which they are used, linked to the signatory or, as the case may be, the authenticat…"}, "it-act-2000:sec_3A__subsec_1": {"cite": "IT Act s.3A(1)", "head": "", "text": "Notwithstanding anything contained in section 3, but subject to the provisions of sub-section (2), a subscriber may authenticate any electronic record by such electronic signature or electronic authentication technique which-(a) is considered reliable; and (b) may be specified in the Second Schedule."}, "it-act-2000:sec_3A__subsec_2": {"cite": "IT Act s.3A(2)", "head": "", "text": "For the purposes of this section any electronic signature or electronic - authentication technique shall be considered reliable if— the signature creation data or the authentication data are, within the context in which they are used, linked to the signatory or, as the case may be, the authenticator and to no other person; the signature creation data or the authentication data were, at the time of signing, under the control of the signatory or, as the case may be, the authenticator and of no other person; any alteration to the electronic signature made after affixing such signature is detectab…"}, "it-act-2000:sec_3A__subsec_2__cl_a": {"cite": "IT Act s.3A(2)(a)", "head": "", "text": "the signature creation data or the authentication data are, within the context in which they are used, linked to the signatory or, as the case may be, the authenticator and to no other person;"}, "it-act-2000:sec_3A__subsec_2__cl_b": {"cite": "IT Act s.3A(2)(b)", "head": "", "text": "the signature creation data or the authentication data were, at the time of signing, under the control of the signatory or, as the case may be, the authenticator and of no other person;"}, "it-act-2000:sec_3A__subsec_2__cl_c": {"cite": "IT Act s.3A(2)(c)", "head": "", "text": "any alteration to the electronic signature made after affixing such signature is detectable;"}, "it-act-2000:sec_3A__subsec_2__cl_d": {"cite": "IT Act s.3A(2)(d)", "head": "", "text": "any alteration to the information made after its authentication by electronic signature is detectable; and"}, "it-act-2000:sec_3A__subsec_2__cl_e": {"cite": "IT Act s.3A(2)(e)", "head": "", "text": "it fulfils such other conditions which may be prescribed."}, "it-act-2000:sec_3A__subsec_3": {"cite": "IT Act s.3A(3)", "head": "", "text": "The Centra! Government may prescribe the procedure for the purpose of ascertaining whether electronic signature is that of the person by whom it is purported to have been affixed or authenticated."}, "it-act-2000:sec_3A__subsec_4": {"cite": "IT Act s.3A(4)", "head": "", "text": "The Central Government may, by notification in the Official Gazette, add to or omit any electronic signature or electronic authentication technique and the procedure for affixing such signature from the Second Schedule: Provided that no electronic signature or authentication technique shall be specified in the Second Schedule unless such signature or technique is reliable."}, "it-act-2000:sec_3A__subsec_4__proviso_1": {"cite": "IT Act s.3A(4)", "head": "", "text": "Provided that no electronic signature or authentication technique shall be specified in the Second Schedule unless such signature or technique is reliable."}, "it-act-2000:sec_3A__subsec_5": {"cite": "IT Act s.3A(5)", "head": "", "text": "Every notification issued under sub-section (4) shall be laid before each House of Parliament."}, "it-act-2000:chp_III": {"cite": "IT Act Chapter III", "head": "ELECTRONIC GOVERNANCE", "text": "Legal recognition of electronic records Where any law provides that information or any other matter shall be in writing or in the typewritten or printed form, then, notwithstanding anything contained in such law, such requirement shall be deemed to have been satisfied if such information or matter is— rendered or made available in an electronic form; and accessible so as to be usable for a subsequent reference. Legal recognition of electronic signatures Where any law provides that information or any other matter shall be authenticated by affixing the signature or any document shall be signed o…"}, "it-act-2000:sec_4": {"cite": "IT Act s.4", "head": "Legal recognition of electronic records", "text": "Where any law provides that information or any other matter shall be in writing or in the typewritten or printed form, then, notwithstanding anything contained in such law, such requirement shall be deemed to have been satisfied if such information or matter is— rendered or made available in an electronic form; and accessible so as to be usable for a subsequent reference."}, "it-act-2000:sec_4__cl_a": {"cite": "IT Act s.4(a)", "head": "", "text": "rendered or made available in an electronic form; and"}, "it-act-2000:sec_4__cl_b": {"cite": "IT Act s.4(b)", "head": "", "text": "accessible so as to be usable for a subsequent reference."}, "it-act-2000:sec_5": {"cite": "IT Act s.5", "head": "Legal recognition of electronic signatures", "text": "Where any law provides that information or any other matter shall be authenticated by affixing the signature or any document shall be signed or bear the signature of any person then, notwithstanding anything contained in such law, such requirement shall be deemed to have been satisfied, if such information or matter is authenticated by means of electronic signature affixed in such manner as may be prescribed by the Central Government. For the purposes of this section, \"signed\", with its grammatical variations and cognate expressions, shall, with reference to a person, mean affixing of his hand…"}, "it-act-2000:sec_5__hcontainer_1": {"cite": "IT Act s.5", "head": "", "text": "For the purposes of this section, \"signed\", with its grammatical variations and cognate expressions, shall, with reference to a person, mean affixing of his hand written signature or any mark on any document and the expression \"signature\" shall be construed accordingly."}, "it-act-2000:sec_6": {"cite": "IT Act s.6", "head": "Use of electronic records and electronic signatures in Government and its agencies", "text": "Where any law provides for— the filing of any form, application or any other document with any office, authority, body or agency owned or controlled by the appropriate Government in a particular manner; the issue or grant of any licence, permit, sanction or approval by whatever name called in a particular manner; the receipt or payment of money in a particular manner, then, notwithstanding anything contained in any other law for the time being in force, such requirement shall be deemed to have been satisfied if such filing, issue, grant, receipt or payment, as the case may be, is effected by m…"}, "it-act-2000:sec_6__subsec_1": {"cite": "IT Act s.6(1)", "head": "", "text": "Where any law provides for— the filing of any form, application or any other document with any office, authority, body or agency owned or controlled by the appropriate Government in a particular manner; the issue or grant of any licence, permit, sanction or approval by whatever name called in a particular manner; the receipt or payment of money in a particular manner, then, notwithstanding anything contained in any other law for the time being in force, such requirement shall be deemed to have been satisfied if such filing, issue, grant, receipt or payment, as the case may be, is effected by m…"}, "it-act-2000:sec_6__subsec_1__cl_a": {"cite": "IT Act s.6(1)(a)", "head": "", "text": "the filing of any form, application or any other document with any office, authority, body or agency owned or controlled by the appropriate Government in a particular manner;"}, "it-act-2000:sec_6__subsec_1__cl_b": {"cite": "IT Act s.6(1)(b)", "head": "", "text": "the issue or grant of any licence, permit, sanction or approval by whatever name called in a particular manner;"}, "it-act-2000:sec_6__subsec_1__cl_c": {"cite": "IT Act s.6(1)(c)", "head": "", "text": "the receipt or payment of money in a particular manner,"}, "it-act-2000:sec_6__subsec_2": {"cite": "IT Act s.6(2)", "head": "", "text": "The appropriate Government may, for the purposes of sub-section (1), by rules, prescribe— the manner and format in which such electronic records shall be filed, created or issued; the manner or method of payment of any fee or charges for filing, creation or issue any electronic record under clause (a)."}, "it-act-2000:sec_6__subsec_2__cl_a": {"cite": "IT Act s.6(2)(a)", "head": "", "text": "the manner and format in which such electronic records shall be filed, created or issued;"}, "it-act-2000:sec_6__subsec_2__cl_b": {"cite": "IT Act s.6(2)(b)", "head": "", "text": "the manner or method of payment of any fee or charges for filing, creation or issue any electronic record under clause (a)."}, "it-act-2000:sec_6A": {"cite": "IT Act s.6A", "head": "Delivery of services by service provider", "text": "The appropriate Government may, for the purposes of this Chapter and for efficient delivery of services to the public through electronic means authorise, by order, any service provider to set up, maintain and upgrade the computerised facilities and perform such other services as it may specify by notification in the Official Gazette. For the purposes of this section, service provider so authorised includes any individual, private agency, private company, partnership firm, sole proprietor firm or any such other body or agency which has been granted permission by the appropriate Government to of…"}, "it-act-2000:sec_6A__subsec_1": {"cite": "IT Act s.6A(1)", "head": "", "text": "The appropriate Government may, for the purposes of this Chapter and for efficient delivery of services to the public through electronic means authorise, by order, any service provider to set up, maintain and upgrade the computerised facilities and perform such other services as it may specify by notification in the Official Gazette."}, "it-act-2000:sec_6A__hcontainer_1": {"cite": "IT Act s.6A", "head": "", "text": "For the purposes of this section, service provider so authorised includes any individual, private agency, private company, partnership firm, sole proprietor firm or any such other body or agency which has been granted permission by the appropriate Government to offer services through electronic means in accordance with the policy governing such service sector."}, "it-act-2000:sec_6A__subsec_2": {"cite": "IT Act s.6A(2)", "head": "", "text": "The appropriate Government may also authorise any service provider authorised under sub-section (1) to collect, retain and appropriate such service charges, as may be prescribed by the appropriate Government for the purpose of providing such services, from the person availing such service."}, "it-act-2000:sec_6A__subsec_3": {"cite": "IT Act s.6A(3)", "head": "", "text": "Subject to the provisions of sub-section (2), the appropriate Government may authorise the service providers to collect, retain and appropriate service charges under this section notwithstanding the fact that there is no express provision under the Act, rule, regulation or notification under which the service is provided to collect, retain and appropriate e-service charges by the service providers."}, "it-act-2000:sec_6A__subsec_4": {"cite": "IT Act s.6A(4)", "head": "", "text": "The appropriate Government shall, by notification in the Official Gazette, specify the scale of service charges which may be charged and collected by the service providers under this section:"}, "it-act-2000:sec_6A__proviso_1": {"cite": "IT Act s.6A", "head": "", "text": "Provided that the appropriate Government may specify different scale of service charges for different types of services."}, "it-act-2000:sec_7": {"cite": "IT Act s.7", "head": "Retention of electronic records", "text": "Where any law provides that documents, records or information shall be retained for any specific period, then, that requirement shall be deemed to have been satisfied if such documents, records or information are retained in the electronic form, if— the information contained therein remains accessible so as to be usable for a subsequent reference; the electronic record is retained in the format in which it was originally generated, sent or received or in a format which can be demonstrated to represent accurately the information originally generated, sent or received; the details which will fac…"}, "it-act-2000:sec_7__subsec_1": {"cite": "IT Act s.7(1)", "head": "", "text": "Where any law provides that documents, records or information shall be retained for any specific period, then, that requirement shall be deemed to have been satisfied if such documents, records or information are retained in the electronic form, if— the information contained therein remains accessible so as to be usable for a subsequent reference; the electronic record is retained in the format in which it was originally generated, sent or received or in a format which can be demonstrated to represent accurately the information originally generated, sent or received; the details which will fac…"}, "it-act-2000:sec_7__subsec_1__cl_a": {"cite": "IT Act s.7(1)(a)", "head": "", "text": "the information contained therein remains accessible so as to be usable for a subsequent reference;"}, "it-act-2000:sec_7__subsec_1__cl_b": {"cite": "IT Act s.7(1)(b)", "head": "", "text": "the electronic record is retained in the format in which it was originally generated, sent or received or in a format which can be demonstrated to represent accurately the information originally generated, sent or received;"}, "it-act-2000:sec_7__subsec_1__cl_c": {"cite": "IT Act s.7(1)(c)", "head": "", "text": "the details which will facilitate the identification of the origin, destination, date and time of despatch or receipt of such electronic record are available in the electronic record: Provided that this clause does not apply to any information which is automatically generated solely for the purpose of enabling an electronic record to be despatched or received."}, "it-act-2000:sec_7__subsec_1__cl_c__proviso_1": {"cite": "IT Act s.7(1)(c)", "head": "", "text": "Provided that this clause does not apply to any information which is automatically generated solely for the purpose of enabling an electronic record to be despatched or received."}, "it-act-2000:sec_7__subsec_2": {"cite": "IT Act s.7(2)", "head": "", "text": "Nothing in this section shall apply to any law that expressly provides for the retention of documents, records or information in the form of electronic records."}, "it-act-2000:sec_7A": {"cite": "IT Act s.7A", "head": "Audit of documents, etc., maintained in electronic form", "text": "Where in any law for the time being in force, there is a provision for audit of documents, records or information, that provision shall also be applicable for audit of documents, records or information processed and maintanined in the electronic form."}, "it-act-2000:sec_8": {"cite": "IT Act s.8", "head": "Publication of rule, regulation, etc., in Electronic Gazette", "text": "Where any law provides that any rule, regulation, order, bye-law, notification or any other matter shall be published in the Official Gazette, then, such requirement shall be deemed to have been satisfied if such rule, regulation, order, bye-law, notification or any other matter is published in the Official Gazette or Electronic Gazette: Provided that where any rule, regulation, order, bye-law, notification or any other matter is published in the Official Gazette or Electronic Gazette, the date of publication shall be deemed to be the date of the Gazette which was first published in any form."}, "it-act-2000:sec_8__proviso_1": {"cite": "IT Act s.8", "head": "", "text": "Provided that where any rule, regulation, order, bye-law, notification or any other matter is published in the Official Gazette or Electronic Gazette, the date of publication shall be deemed to be the date of the Gazette which was first published in any form."}, "it-act-2000:sec_9": {"cite": "IT Act s.9", "head": "Sections 6, 7 and 8 not to confer right to insist document should be accepted in electronic form", "text": "Nothing contained in sections 6, 7 and 8 shall confer a right upon any person to insist that any Ministry or Department of the Central Government or the State Government or any authority or body established by or under any law or controlled or funded by the Central or State Government should accept, issue, create, retain and preserve any document in the form of electronic records or effect any monetary transaction in the electronic form."}, "it-act-2000:sec_10": {"cite": "IT Act s.10", "head": "Power to make rules by Central Government in respect of electronic signature", "text": "The Central Government may, for the purposes of this Act, by rules, prescribe— the type of electronic signature; the manner and format in which the electronic signature shall be affixed; the manner or procedure which facilitates identification of the person affixing the electronic signature; control processes and procedures to ensure adequate integrity, security and confidentiality of electronic records or payments; and any other matter which is necessary to give legal effect to electronic signatures."}, "it-act-2000:sec_10__cl_a": {"cite": "IT Act s.10(a)", "head": "", "text": "the type of electronic signature;"}, "it-act-2000:sec_10__cl_b": {"cite": "IT Act s.10(b)", "head": "", "text": "the manner and format in which the electronic signature shall be affixed;"}, "it-act-2000:sec_10__cl_c": {"cite": "IT Act s.10(c)", "head": "", "text": "the manner or procedure which facilitates identification of the person affixing the electronic signature;"}, "it-act-2000:sec_10__cl_d": {"cite": "IT Act s.10(d)", "head": "", "text": "control processes and procedures to ensure adequate integrity, security and confidentiality of electronic records or payments; and"}, "it-act-2000:sec_10__cl_e": {"cite": "IT Act s.10(e)", "head": "", "text": "any other matter which is necessary to give legal effect to electronic signatures."}, "it-act-2000:sec_10A": {"cite": "IT Act s.10A", "head": "Validity of contracts formed through electronic means", "text": "Where in a contract formation, the communication of proposals, the acceptance of proposals, the revocation of proposals and acceptances, as the case may be, are expressed in electronic form or by means of an electronic record, such contract shall not be deemed to be unenforceable solely on the ground that such electronic form or means was used for that purpose."}, "it-act-2000:chp_IV": {"cite": "IT Act Chapter IV", "head": "ATTRIBUTION, ACKNOWLEDGMENT AND DESPATCH OF ELECTRONIC RECORDS", "text": "Attribution of electronic records An electronic record shall be attributed to the originator— if it was sent by the originator himself; by a person who had the authority to act on behalf of the originator in respect of that electronic record; or by an information system programmed by or on behalf of the originator to operate automatically. Acknowledgment of receipt Where the originator has not stipulated that the acknowledgment of receipt of electronic record be given in a particular form or by a particular method, an acknowledgment may be given by— any communication by the addressee, automate…"}, "it-act-2000:sec_11": {"cite": "IT Act s.11", "head": "Attribution of electronic records", "text": "An electronic record shall be attributed to the originator— if it was sent by the originator himself; by a person who had the authority to act on behalf of the originator in respect of that electronic record; or by an information system programmed by or on behalf of the originator to operate automatically."}, "it-act-2000:sec_11__cl_a": {"cite": "IT Act s.11(a)", "head": "", "text": "if it was sent by the originator himself;"}, "it-act-2000:sec_11__cl_b": {"cite": "IT Act s.11(b)", "head": "", "text": "by a person who had the authority to act on behalf of the originator in respect of that electronic record; or"}, "it-act-2000:sec_11__cl_c": {"cite": "IT Act s.11(c)", "head": "", "text": "by an information system programmed by or on behalf of the originator to operate automatically."}, "it-act-2000:sec_12": {"cite": "IT Act s.12", "head": "Acknowledgment of receipt", "text": "Where the originator has not stipulated that the acknowledgment of receipt of electronic record be given in a particular form or by a particular method, an acknowledgment may be given by— any communication by the addressee, automated or otherwise; or any conduct of the addressee, sufficient to indicate to the originator that the electronic record has been received. Where the originator has stipulated that the electronic record shall be binding only on receipt of an acknowledgment of such electronic record by him, then unless acknowledgment has been so received, the electronic record shall be d…"}, "it-act-2000:sec_12__subsec_1": {"cite": "IT Act s.12(1)", "head": "", "text": "Where the originator has not stipulated that the acknowledgment of receipt of electronic record be given in a particular form or by a particular method, an acknowledgment may be given by— any communication by the addressee, automated or otherwise; or any conduct of the addressee, sufficient to indicate to the originator that the electronic record has been received."}, "it-act-2000:sec_12__subsec_1__cl_a": {"cite": "IT Act s.12(1)(a)", "head": "", "text": "any communication by the addressee, automated or otherwise; or"}, "it-act-2000:sec_12__subsec_1__cl_b": {"cite": "IT Act s.12(1)(b)", "head": "", "text": "any conduct of the addressee, sufficient to indicate to the originator that the electronic record has been received."}, "it-act-2000:sec_12__subsec_2": {"cite": "IT Act s.12(2)", "head": "", "text": "Where the originator has stipulated that the electronic record shall be binding only on receipt of an acknowledgment of such electronic record by him, then unless acknowledgment has been so received, the electronic record shall be deemed to have been never sent by the originator."}, "it-act-2000:sec_12__subsec_3": {"cite": "IT Act s.12(3)", "head": "", "text": "Where the originator has not stipulated that the electronic record shall be binding only on receipt of such acknowledgment, and the acknowledgment has not been received by the originator within the time specified or agreed or, if no time has been specified or agreed to within a reasonable time, then the originator may give notice to the addressee stating that no acknowledgment has been received by him and specifying a reasonable time by which the acknowledgment must be received by him and if no acknowledgment is received within the aforesaid time limit he may after giving notice to the address…"}, "it-act-2000:sec_13": {"cite": "IT Act s.13", "head": "Time and place of despatch and receipt of electronic record", "text": "Save as otherwise agreed to between the originator and the addressee, the despatch of an electronic record occurs when it enters a computer resource outside the control of the originator. Save as otherwise agreed between the originator and the addressee, the time of receipt of an electronic record shall be determined as follows, namely:— if the addressee has designated a computer resource for the purpose of receiving electronic records,— receipt occurs at the time when the electronic record enters the designated computer resource; or if the electronic record is sent to a computer resource of t…"}, "it-act-2000:sec_13__subsec_1": {"cite": "IT Act s.13(1)", "head": "", "text": "Save as otherwise agreed to between the originator and the addressee, the despatch of an electronic record occurs when it enters a computer resource outside the control of the originator."}, "it-act-2000:sec_13__subsec_2": {"cite": "IT Act s.13(2)", "head": "", "text": "Save as otherwise agreed between the originator and the addressee, the time of receipt of an electronic record shall be determined as follows, namely:— if the addressee has designated a computer resource for the purpose of receiving electronic records,— receipt occurs at the time when the electronic record enters the designated computer resource; or if the electronic record is sent to a computer resource of the addressee that is not the designated computer resource, receipt occurs at the time when the electronic record is retrieved by the addressee; if the addressee has not designated a comput…"}, "it-act-2000:sec_13__subsec_2__cl_a": {"cite": "IT Act s.13(2)(a)", "head": "", "text": "if the addressee has designated a computer resource for the purpose of receiving electronic records,— receipt occurs at the time when the electronic record enters the designated computer resource; or if the electronic record is sent to a computer resource of the addressee that is not the designated computer resource, receipt occurs at the time when the electronic record is retrieved by the addressee;"}, "it-act-2000:sec_13__subsec_2__cl_a__subcl_i": {"cite": "IT Act s.13(2)(a)(i)", "head": "", "text": "receipt occurs at the time when the electronic record enters the designated computer resource; or"}, "it-act-2000:sec_13__subsec_2__cl_a__subcl_ii": {"cite": "IT Act s.13(2)(a)(ii)", "head": "", "text": "if the electronic record is sent to a computer resource of the addressee that is not the designated computer resource, receipt occurs at the time when the electronic record is retrieved by the addressee;"}, "it-act-2000:sec_13__subsec_2__cl_b": {"cite": "IT Act s.13(2)(b)", "head": "", "text": "if the addressee has not designated a computer resource along with specified timings, if any, receipt occurs when the electronic record enters the computer resource of the addressee."}, "it-act-2000:sec_13__subsec_3": {"cite": "IT Act s.13(3)", "head": "", "text": "Save as otherwise agreed to between the originator and the addressee, an electronic record is deemed to be despatched at the place where the originator has his place of business, and is deemed to be received at the place where the addressee has his place of business."}, "it-act-2000:sec_13__subsec_4": {"cite": "IT Act s.13(4)", "head": "", "text": "The provisions of sub-section (2) shall apply notwithstanding that the place where the computer resource is located may be different from the place where the electronic record is deemed to have been received under sub-section (3)."}, "it-act-2000:sec_13__subsec_5": {"cite": "IT Act s.13(5)", "head": "", "text": "For the purposes of this section,— if the originator or the addressee has more than one place of business, the principal place of business, shall be the place of business; if the originator or the addressee does not have a place of business, his usual place of residence shall be deemed to be the place of business; \"usual place of residence\", in relation to a body corporate, means the place where it is registered."}, "it-act-2000:sec_13__subsec_5__cl_a": {"cite": "IT Act s.13(5)(a)", "head": "", "text": "if the originator or the addressee has more than one place of business, the principal place of business, shall be the place of business;"}, "it-act-2000:sec_13__subsec_5__cl_b": {"cite": "IT Act s.13(5)(b)", "head": "", "text": "if the originator or the addressee does not have a place of business, his usual place of residence shall be deemed to be the place of business;"}, "it-act-2000:sec_13__subsec_5__cl_c": {"cite": "IT Act s.13(5)(c)", "head": "", "text": "\"usual place of residence\", in relation to a body corporate, means the place where it is registered."}, "it-act-2000:chp_V": {"cite": "IT Act Chapter V", "head": "SECURE ELECTRONIC RECORDS AND SECURE ELECTRONIC SIGNATURES", "text": "Secure electronic record Where any security procedure has been applied to an electronic record at a specific point of time, then such record shall be deemed to be a secure electronic record from such point of time to the time of verification. Secure electronic signature An electronic signature shall be deemed to be a secure electronic signature if (f) the signature creation data, at the time of affixing signature, was under the exclusive control of signatory and no other person; and (ii) the signature creation data was stored and affixed in such exclusive manner as may be prescribed. In case o…"}, "it-act-2000:sec_14": {"cite": "IT Act s.14", "head": "Secure electronic record", "text": "Where any security procedure has been applied to an electronic record at a specific point of time, then such record shall be deemed to be a secure electronic record from such point of time to the time of verification."}, "it-act-2000:sec_15": {"cite": "IT Act s.15", "head": "Secure electronic signature", "text": "An electronic signature shall be deemed to be a secure electronic signature if (f) the signature creation data, at the time of affixing signature, was under the exclusive control of signatory and no other person; and (ii) the signature creation data was stored and affixed in such exclusive manner as may be prescribed. In case of digital signature, the “signature creation data” means the private key of the subscriber."}, "it-act-2000:sec_15__hcontainer_1": {"cite": "IT Act s.15", "head": "", "text": "In case of digital signature, the “signature creation data” means the private key of the subscriber."}, "it-act-2000:sec_16": {"cite": "IT Act s.16", "head": "Security procedures and practices", "text": "The Central Government may, for the purposes of sections 14 and 15, prescribe the security procedures and practices: Provided that in prescribing such security procedures and practices, the Central Government shall have regard to the commercial circumstances, nature of transactions and such other related factors as it may consider appropriate."}, "it-act-2000:sec_16__proviso_1": {"cite": "IT Act s.16", "head": "", "text": "Provided that in prescribing such security procedures and practices, the Central Government shall have regard to the commercial circumstances, nature of transactions and such other related factors as it may consider appropriate."}, "it-act-2000:chp_VI": {"cite": "IT Act Chapter VI", "head": "REGULATION OF CERTIFYING AUTHORITIES", "text": "Appointment of Controller and other officers The Central Government may, by notification in the Official Gazette, appoint a Controller of Certifying Authorities for the purposes of this Act and may also by the same or subsequent notification appoint such number of Deputy Controllers, Assistant Controllers, other officers and employees as it deems fit. The Controller shall discharge his functions under this Act subject to the general control and directions of the Central Government. The Deputy Controllers and Assistant Controllers shall perform the functions assigned to them by the Controller u…"}, "it-act-2000:sec_17": {"cite": "IT Act s.17", "head": "Appointment of Controller and other officers", "text": "The Central Government may, by notification in the Official Gazette, appoint a Controller of Certifying Authorities for the purposes of this Act and may also by the same or subsequent notification appoint such number of Deputy Controllers, Assistant Controllers, other officers and employees as it deems fit. The Controller shall discharge his functions under this Act subject to the general control and directions of the Central Government. The Deputy Controllers and Assistant Controllers shall perform the functions assigned to them by the Controller under the general superintendence and control …"}, "it-act-2000:sec_17__subsec_1": {"cite": "IT Act s.17(1)", "head": "", "text": "The Central Government may, by notification in the Official Gazette, appoint a Controller of Certifying Authorities for the purposes of this Act and may also by the same or subsequent notification appoint such number of Deputy Controllers, Assistant Controllers, other officers and employees as it deems fit."}, "it-act-2000:sec_17__subsec_2": {"cite": "IT Act s.17(2)", "head": "", "text": "The Controller shall discharge his functions under this Act subject to the general control and directions of the Central Government."}, "it-act-2000:sec_17__subsec_3": {"cite": "IT Act s.17(3)", "head": "", "text": "The Deputy Controllers and Assistant Controllers shall perform the functions assigned to them by the Controller under the general superintendence and control of the Controller."}, "it-act-2000:sec_17__subsec_4": {"cite": "IT Act s.17(4)", "head": "", "text": "The qualifications, experience and terms and conditions of service of Controller, Deputy Controllers, Assistant Controllers, other officers and employees shall be such as may be prescribed by the Central Government."}, "it-act-2000:sec_17__subsec_5": {"cite": "IT Act s.17(5)", "head": "", "text": "The Head Office and Branch Office of the office of the Controller shall be at such places as the Central Government may specify, and these may be established at such places as the Central Government may think fit."}, "it-act-2000:sec_17__subsec_6": {"cite": "IT Act s.17(6)", "head": "", "text": "There shall be a seal of the Office of the Controller."}, "it-act-2000:sec_18": {"cite": "IT Act s.18", "head": "Functions of Controller", "text": "The Controller may perform all or any of the following functions, namely:— exercising supervision over the activities of the Certifying Authorities; certifying public keys of the Certifying Authorities; laying down the standards to be maintained by the Certifying Authorities; specifying the qualifications and experience which employees of the Certifying Authorities should possess; specifying the conditions subject to which the Certifying Authorities shall conduct their business; specifying the contents of written, printed or visual materials and advertisements that may be distributed or used i…"}, "it-act-2000:sec_18__cl_a": {"cite": "IT Act s.18(a)", "head": "", "text": "exercising supervision over the activities of the Certifying Authorities;"}, "it-act-2000:sec_18__cl_b": {"cite": "IT Act s.18(b)", "head": "", "text": "certifying public keys of the Certifying Authorities;"}, "it-act-2000:sec_18__cl_c": {"cite": "IT Act s.18(c)", "head": "", "text": "laying down the standards to be maintained by the Certifying Authorities;"}, "it-act-2000:sec_18__cl_d": {"cite": "IT Act s.18(d)", "head": "", "text": "specifying the qualifications and experience which employees of the Certifying Authorities should possess;"}, "it-act-2000:sec_18__cl_e": {"cite": "IT Act s.18(e)", "head": "", "text": "specifying the conditions subject to which the Certifying Authorities shall conduct their business;"}, "it-act-2000:sec_18__cl_f": {"cite": "IT Act s.18(f)", "head": "", "text": "specifying the contents of written, printed or visual materials and advertisements that may be distributed or used in respect of a Electronic signature Certificate and the public key;"}, "it-act-2000:sec_18__cl_g": {"cite": "IT Act s.18(g)", "head": "", "text": "specifying the form and content of a Electronic signature Certificate and the key;"}, "it-act-2000:sec_18__cl_h": {"cite": "IT Act s.18(h)", "head": "", "text": "specifying the form and manner in which accounts shall be maintained by the Certifying Authorities;"}, "it-act-2000:sec_18__cl_i": {"cite": "IT Act s.18(i)", "head": "", "text": "specifying the terms and conditions subject to which auditors may be appointed and the remuneration to be paid to them;"}, "it-act-2000:sec_18__cl_j": {"cite": "IT Act s.18(j)", "head": "", "text": "facilitating the establishment of any electronic system by a Certifying Authority either solely or jointly with other Certifying Authorities and regulation of such systems;"}, "it-act-2000:sec_18__cl_k": {"cite": "IT Act s.18(k)", "head": "", "text": "specifying the manner in which the Certifying Authorities shall conduct their dealings with the subscribers;"}, "it-act-2000:sec_18__cl_l": {"cite": "IT Act s.18(l)", "head": "", "text": "resolving any conflict of interests between the Certifying Authorities and the subscribers;"}, "it-act-2000:sec_18__cl_m": {"cite": "IT Act s.18(m)", "head": "", "text": "laying down the duties of the Certifying Authorities;"}, "it-act-2000:sec_18__cl_n": {"cite": "IT Act s.18(n)", "head": "", "text": "maintaining a data base containing the disclosure record of every Certifying Authority containing such particulars as may be specified by regulations, which shall be accessible to public."}, "it-act-2000:sec_19": {"cite": "IT Act s.19", "head": "Recognition of foreign Certifying Authorities", "text": "Subject to such conditions and restrictions as may be specified by regulations, the Controller may with the previous approval of the Central Government, and by notification in the Official Gazette, recognise any foreign Certifying Authority as a Certifying Authority for the purposes of this Act. Where any Certifying Authority is recognised under sub-section (1), the Electronic signature Certificate issued by such Certifying Authority shall be valid for the purposes of this Act. The Controller may, if he is satisfied that any Certifying Authority has contravened any of the conditions, and restr…"}, "it-act-2000:sec_19__subsec_1": {"cite": "IT Act s.19(1)", "head": "", "text": "Subject to such conditions and restrictions as may be specified by regulations, the Controller may with the previous approval of the Central Government, and by notification in the Official Gazette, recognise any foreign Certifying Authority as a Certifying Authority for the purposes of this Act."}, "it-act-2000:sec_19__subsec_2": {"cite": "IT Act s.19(2)", "head": "", "text": "Where any Certifying Authority is recognised under sub-section (1), the Electronic signature Certificate issued by such Certifying Authority shall be valid for the purposes of this Act."}, "it-act-2000:sec_19__subsec_3": {"cite": "IT Act s.19(3)", "head": "", "text": "The Controller may, if he is satisfied that any Certifying Authority has contravened any of the conditions, and restrictions subject to which it was granted recognition under sub-section (1) he may, for reasons to be recorded in writing, by notification in the Official Gazette, revoke such recognition."}, "it-act-2000:sec_20": {"cite": "IT Act s.20", "head": "Controller", "text": ""}, "it-act-2000:sec_21": {"cite": "IT Act s.21", "head": "Licence to issue Electronic signature Certificates", "text": "Subject to the provisions of sub-section (2), any person may make an application, to the Controller, for a licence to issue Electronic signature Certificates. No licence shall be issued under sub-section (1), unless the applicant fulfills such requirements with respect to qualification, expertise, manpower, financial resources and other infrastructure facilities, which are necessary to issue Electronic signature Certificates as may be prescribed by the Central Government. A licence granted under this section shall— be valid for such period as may be prescribed by the Central Government; not be…"}, "it-act-2000:sec_21__subsec_1": {"cite": "IT Act s.21(1)", "head": "", "text": "Subject to the provisions of sub-section (2), any person may make an application, to the Controller, for a licence to issue Electronic signature Certificates."}, "it-act-2000:sec_21__subsec_2": {"cite": "IT Act s.21(2)", "head": "", "text": "No licence shall be issued under sub-section (1), unless the applicant fulfills such requirements with respect to qualification, expertise, manpower, financial resources and other infrastructure facilities, which are necessary to issue Electronic signature Certificates as may be prescribed by the Central Government."}, "it-act-2000:sec_21__subsec_3": {"cite": "IT Act s.21(3)", "head": "", "text": "A licence granted under this section shall— be valid for such period as may be prescribed by the Central Government; not be transferable or heritable; be subject to such terms and conditions as may be specified by the regulations."}, "it-act-2000:sec_21__subsec_3__cl_a": {"cite": "IT Act s.21(3)(a)", "head": "", "text": "be valid for such period as may be prescribed by the Central Government;"}, "it-act-2000:sec_21__subsec_3__cl_b": {"cite": "IT Act s.21(3)(b)", "head": "", "text": "not be transferable or heritable;"}, "it-act-2000:sec_21__subsec_3__cl_c": {"cite": "IT Act s.21(3)(c)", "head": "", "text": "be subject to such terms and conditions as may be specified by the regulations."}, "it-act-2000:sec_22": {"cite": "IT Act s.22", "head": "Application for licence", "text": "Every application for issue of a licence shall be in such form as may be prescribed by the Central Government. Every application for issue of a licence shall be accompanied by— a certification practice statement; a statement including the procedures with respect to identification of the applicant; payment of such fees, not exceeding twenty-five thousand rupees as may be prescribed by the Central Government; such other documents, as may be prescribed by the Central Government."}, "it-act-2000:sec_22__subsec_1": {"cite": "IT Act s.22(1)", "head": "", "text": "Every application for issue of a licence shall be in such form as may be prescribed by the Central Government."}, "it-act-2000:sec_22__subsec_2": {"cite": "IT Act s.22(2)", "head": "", "text": "Every application for issue of a licence shall be accompanied by— a certification practice statement; a statement including the procedures with respect to identification of the applicant; payment of such fees, not exceeding twenty-five thousand rupees as may be prescribed by the Central Government; such other documents, as may be prescribed by the Central Government."}, "it-act-2000:sec_22__subsec_2__cl_a": {"cite": "IT Act s.22(2)(a)", "head": "", "text": "a certification practice statement;"}, "it-act-2000:sec_22__subsec_2__cl_b": {"cite": "IT Act s.22(2)(b)", "head": "", "text": "a statement including the procedures with respect to identification of the applicant;"}, "it-act-2000:sec_22__subsec_2__cl_c": {"cite": "IT Act s.22(2)(c)", "head": "", "text": "payment of such fees, not exceeding twenty-five thousand rupees as may be prescribed by the Central Government;"}, "it-act-2000:sec_22__subsec_2__cl_d": {"cite": "IT Act s.22(2)(d)", "head": "", "text": "such other documents, as may be prescribed by the Central Government."}, "it-act-2000:sec_23": {"cite": "IT Act s.23", "head": "Renewal of licence", "text": "An application for renewal of a licence shall be— in such form; accompanied by such fees, not exceeding five thousand rupees, as may be prescribed by the Central Government and shall be made not less than forty-five days before the date of expiry of the period of validity of the licence."}, "it-act-2000:sec_23__cl_a": {"cite": "IT Act s.23(a)", "head": "", "text": "in such form;"}, "it-act-2000:sec_23__cl_b": {"cite": "IT Act s.23(b)", "head": "", "text": "accompanied by such fees, not exceeding five thousand rupees,"}, "it-act-2000:sec_24": {"cite": "IT Act s.24", "head": "Procedure for grant or rejection of licence", "text": "The Controller may, on receipt of an application under sub-section (1) of section 21, after considering the documents accompanying the application and such other factors, as he deems fit, grant the licence or reject the application: Provided that no application shall be rejected under this section unless the applicant has been given a reasonable opportunity of presenting his case."}, "it-act-2000:sec_24__proviso_1": {"cite": "IT Act s.24", "head": "", "text": "Provided that no application shall be rejected under this section unless the applicant has been given a reasonable opportunity of presenting his case."}, "it-act-2000:sec_25": {"cite": "IT Act s.25", "head": "Suspension of licence", "text": "The Controller may, if he is satisfied after making such inquiry, as he may think fit, that a Certifying Authority has,— made a statement in, or in relation to, the application for the issue or renewal of the licence, which is incorrect or false in material particulars; failed to comply with the terms and conditions subject to which the licence was granted; failed to maintain the procedures and standards specified in section 30: contravened any provisions of this Act, rule, regulation or order made thereunder, revoke the licence: Provided that no licence shall be revoked unless the Certifying …"}, "it-act-2000:sec_25__subsec_1": {"cite": "IT Act s.25(1)", "head": "", "text": "The Controller may, if he is satisfied after making such inquiry, as he may think fit, that a Certifying Authority has,— made a statement in, or in relation to, the application for the issue or renewal of the licence, which is incorrect or false in material particulars; failed to comply with the terms and conditions subject to which the licence was granted; failed to maintain the procedures and standards specified in section 30: contravened any provisions of this Act, rule, regulation or order made thereunder, revoke the licence: Provided that no licence shall be revoked unless the Certifying …"}, "it-act-2000:sec_25__subsec_1__cl_a": {"cite": "IT Act s.25(1)(a)", "head": "", "text": "made a statement in, or in relation to, the application for the issue or renewal of the licence, which is incorrect or false in material particulars;"}, "it-act-2000:sec_25__subsec_1__cl_b": {"cite": "IT Act s.25(1)(b)", "head": "", "text": "failed to comply with the terms and conditions subject to which the licence was granted;"}, "it-act-2000:sec_25__subsec_1__cl_c": {"cite": "IT Act s.25(1)(c)", "head": "", "text": "failed to maintain the procedures and standards specified in section 30:"}, "it-act-2000:sec_25__subsec_1__cl_d": {"cite": "IT Act s.25(1)(d)", "head": "", "text": "contravened any provisions of this Act, rule, regulation or order made thereunder,"}, "it-act-2000:sec_25__subsec_1__wrap_1": {"cite": "IT Act s.25(1)", "head": "", "text": "revoke the licence:"}, "it-act-2000:sec_25__subsec_1__proviso_1": {"cite": "IT Act s.25(1)", "head": "", "text": "Provided that no licence shall be revoked unless the Certifying Authority has been given a reasonable opportunity of showing cause against the proposed revocation."}, "it-act-2000:sec_25__subsec_2": {"cite": "IT Act s.25(2)", "head": "", "text": "The Controller may, if he has reasonable cause to believe that there is any ground for revoking a licence under sub-section (1), by order suspend such licence pending the completion of any inquiry ordered by him: Provided that no licence shall be suspended for a period exceeding ten days unless the Certifying Authority has been given a reasonable opportunity of showing cause against the proposed suspension."}, "it-act-2000:sec_25__subsec_2__proviso_1": {"cite": "IT Act s.25(2)", "head": "", "text": "Provided that no licence shall be suspended for a period exceeding ten days unless the Certifying Authority has been given a reasonable opportunity of showing cause against the proposed suspension."}, "it-act-2000:sec_25__subsec_3": {"cite": "IT Act s.25(3)", "head": "", "text": "No Certifying Authority whose licence has been suspended shall issue any Electronic signature Certificate during such suspension."}, "it-act-2000:sec_26": {"cite": "IT Act s.26", "head": "Notice of suspension or revocation of licence", "text": "Where the licence of the Certifying Authority is suspended or revoked, the Controller shall publish notice of such suspension or revocation, as the case may be, in the data base maintained by him. Where one or more repositories are specified, the Controller shall publish notices of such suspension or revocation, as the case may be, in all such repositories: Provided that the data base containing the notice of such suspension or revocation, as the case may be, shall be made available through a web site which shall be accessible round the clock: Provided further that the Controller may, if he co…"}, "it-act-2000:sec_26__subsec_1": {"cite": "IT Act s.26(1)", "head": "", "text": "Where the licence of the Certifying Authority is suspended or revoked, the Controller shall publish notice of such suspension or revocation, as the case may be, in the data base maintained by him."}, "it-act-2000:sec_26__subsec_2": {"cite": "IT Act s.26(2)", "head": "", "text": "Where one or more repositories are specified, the Controller shall publish notices of such suspension or revocation, as the case may be, in all such repositories: Provided that the data base containing the notice of such suspension or revocation, as the case may be, shall be made available through a web site which shall be accessible round the clock: Provided further that the Controller may, if he considers necessary, publicise the contents of data base in such electronic or other media, as he may consider appropriate."}, "it-act-2000:sec_26__subsec_2__proviso_1": {"cite": "IT Act s.26(2)", "head": "", "text": "Provided that the data base containing the notice of such suspension or revocation, as the case may be, shall be made available through a web site which shall be accessible round the clock:"}, "it-act-2000:sec_26__subsec_2__proviso_2": {"cite": "IT Act s.26(2)", "head": "", "text": "Provided further that the Controller may, if he considers necessary, publicise the contents of data base in such electronic or other media, as he may consider appropriate."}, "it-act-2000:sec_27": {"cite": "IT Act s.27", "head": "Power to delegate", "text": "The Controller may, in writing, authorise the Deputy Controller, Assistant Controller or any officer to exercise any of the powers of the Controller under this Chapter."}, "it-act-2000:sec_28": {"cite": "IT Act s.28", "head": "Power to investigate contraventions", "text": "The Controller or any officer authorised by him in this behalf shall take up for investigation any contravention of the provisions of this Act, rules or regulations made thereunder. The Controller or any officer authorised by him in this behalf shall exercise the like powers which are conferred on Income-tax authorities under Chapter XIII of the Income-tax Act, 1961 and shall exercise such powers, subject to such limitations laid down under that Act."}, "it-act-2000:sec_28__subsec_1": {"cite": "IT Act s.28(1)", "head": "", "text": "The Controller or any officer authorised by him in this behalf shall take up for investigation any contravention of the provisions of this Act, rules or regulations made"}, "it-act-2000:sec_28__wrap_1": {"cite": "IT Act s.28", "head": "", "text": "thereunder."}, "it-act-2000:sec_28__subsec_2": {"cite": "IT Act s.28(2)", "head": "", "text": "The Controller or any officer authorised by him in this behalf shall exercise the like powers which are conferred on Income-tax authorities under Chapter XIII of the Income-tax Act, 1961 and shall exercise such powers, subject to such limitations laid down under that Act."}, "it-act-2000:sec_29": {"cite": "IT Act s.29", "head": "Access to computers and data", "text": "Without prejudice to the provisions of sub-section (1)of section 69, the Controller or any person authorised by him shall, if he has reasonable cause to suspect that any contravention of the provisions of this Chapter has been committed, have access to any computer system, any apparatus, data or any other material connected with such system, for the purpose of searching or causing a search to be made for obtaining any information or data contained in or available to such computer system. For the purposes of sub-section (1), the Controller or any person authorised by him may, by order, direct a…"}, "it-act-2000:sec_29__subsec_1": {"cite": "IT Act s.29(1)", "head": "", "text": "Without prejudice to the provisions of sub-section (1)of section 69, the Controller or any person authorised by him shall, if he has reasonable cause to suspect that any contravention of the provisions of this Chapter has been committed, have access to any computer system, any apparatus, data or any other material connected with such system, for the purpose of searching or causing a search to be made for obtaining any information or data contained in or available to such computer system."}, "it-act-2000:sec_29__subsec_2": {"cite": "IT Act s.29(2)", "head": "", "text": "For the purposes of sub-section (1), the Controller or any person authorised by him may, by order, direct any person incharge of, or otherwise concerned with the operation of, the computer system, data apparatus or material, to provide him with such reasonable technical and other assistance as he may consider necessary."}, "it-act-2000:sec_30": {"cite": "IT Act s.30", "head": "Certifying Authority to follow certain procedures", "text": "Every Certifying Authority shall,— make use of hardware, software and procedures that are secure from intrusion and misuse; provide a reasonable level of reliability in its services which are reasonably suited to the performance of intended functions; adhere to security procedures to ensure that the secrecy and privacy of the electronic signatures are assured; be the repository of all Electronic Signature Certificates issued under this Act; publish information regarding its practices, Electronic Signature Certificates and current status of such certificates; and observe such other standards as…"}, "it-act-2000:sec_30__cl_a": {"cite": "IT Act s.30(a)", "head": "", "text": "make use of hardware, software and procedures that are secure from intrusion and misuse;"}, "it-act-2000:sec_30__cl_b": {"cite": "IT Act s.30(b)", "head": "", "text": "provide a reasonable level of reliability in its services which are reasonably suited to the performance of intended functions;"}, "it-act-2000:sec_30__cl_c": {"cite": "IT Act s.30(c)", "head": "", "text": "adhere to security procedures to ensure that the secrecy and privacy of the electronic signatures are assured;"}, "it-act-2000:sec_30__cl_ca": {"cite": "IT Act s.30(ca)", "head": "", "text": "be the repository of all Electronic Signature Certificates issued under this Act;"}, "it-act-2000:sec_30__cl_cb": {"cite": "IT Act s.30(cb)", "head": "", "text": "publish information regarding its practices, Electronic Signature Certificates and current status of such certificates; and"}, "it-act-2000:sec_30__cl_d": {"cite": "IT Act s.30(d)", "head": "", "text": "observe such other standards as may be specified by regulations."}, "it-act-2000:sec_31": {"cite": "IT Act s.31", "head": "Certifying Authority to ensure compliance of the Act, etc", "text": "Every Certifying Authority shall ensure that every person employed or otherwise engaged by it complies, in the course of his employment or engagement, with the provisions of this Act, rules, regulations and orders made thereunder."}, "it-act-2000:sec_32": {"cite": "IT Act s.32", "head": "Display of licence", "text": "Every Certifying Authority shall display its licence at a conspicuous place of the premises in which it carries on its business."}, "it-act-2000:sec_33": {"cite": "IT Act s.33", "head": "Surrender of licence", "text": "Every Certifying Authority whose licence is suspended or revoked shall immediately after such suspension or revocation, surrender the licence to the Controller. Where any Certifying Authority fails to surrender a licence under sub-section (1), the person in whose favour a licence is issued, shall be guilty of an offence and shall be liable to penalty which may extend to five lakh rupees."}, "it-act-2000:sec_33__subsec_1": {"cite": "IT Act s.33(1)", "head": "", "text": "Every Certifying Authority whose licence is suspended or revoked shall immediately after such suspension or revocation, surrender the licence to the Controller."}, "it-act-2000:sec_33__subsec_2": {"cite": "IT Act s.33(2)", "head": "", "text": "Where any Certifying Authority fails to surrender a licence under sub-section (1), the person in whose favour a licence is issued, shall be guilty of an offence and shall be liable to penalty which may extend to five lakh rupees."}, "it-act-2000:sec_34": {"cite": "IT Act s.34", "head": "Disclosure", "text": "Every Certifying Authority shall disclose in the manner specified by regulations— its Electronic signature Certificate ; any certification practice statement relevant thereto; notice of the revocation or suspension of its Certifying Authority certificate, if any; and any other fact that materially and adversely affects either the reliability of a Electronic signature Certificate, which that Authority has issued, or the Authority's ability to perform its services. Where in the opinion of the Certifying Authority any event has occurred or any situation has arisen which may materially and adverse…"}, "it-act-2000:sec_34__subsec_1": {"cite": "IT Act s.34(1)", "head": "", "text": "Every Certifying Authority shall disclose in the manner specified by regulations— its Electronic signature Certificate ; any certification practice statement relevant thereto; notice of the revocation or suspension of its Certifying Authority certificate, if any; and any other fact that materially and adversely affects either the reliability of a Electronic signature Certificate, which that Authority has issued, or the Authority's ability to perform its services."}, "it-act-2000:sec_34__subsec_1__cl_a": {"cite": "IT Act s.34(1)(a)", "head": "", "text": "its Electronic signature Certificate ;"}, "it-act-2000:sec_34__subsec_1__cl_b": {"cite": "IT Act s.34(1)(b)", "head": "", "text": "any certification practice statement relevant thereto;"}, "it-act-2000:sec_34__subsec_1__cl_c": {"cite": "IT Act s.34(1)(c)", "head": "", "text": "notice of the revocation or suspension of its Certifying Authority certificate, if any; and"}, "it-act-2000:sec_34__subsec_1__cl_d": {"cite": "IT Act s.34(1)(d)", "head": "", "text": "any other fact that materially and adversely affects either the reliability of a Electronic signature Certificate, which that Authority has issued, or the Authority's ability to perform its services."}, "it-act-2000:sec_34__subsec_2": {"cite": "IT Act s.34(2)", "head": "", "text": "Where in the opinion of the Certifying Authority any event has occurred or any situation has arisen which may materially and adversely affect the integrity of its computer system or the conditions subject to which a Electronic signature Certificate was granted, then, the Certifying Authority shall— use reasonable efforts to notify any person who is likely to be affected by that occurrence; or act in accordance with the procedure specified in its certification practice statement to deal with such event or situation."}, "it-act-2000:sec_34__subsec_2__cl_a": {"cite": "IT Act s.34(2)(a)", "head": "", "text": "use reasonable efforts to notify any person who is likely to be affected by that occurrence; or"}, "it-act-2000:sec_34__subsec_2__cl_b": {"cite": "IT Act s.34(2)(b)", "head": "", "text": "act in accordance with the procedure specified in its certification practice statement to deal with such event or situation."}, "it-act-2000:chp_VII": {"cite": "IT Act Chapter VII", "head": "ELECTRONIC SIGNATURE CERTIFICATES", "text": "Certifying Authority to issue Electronic signature Certificate Any person may make an application to the Certifying Authority for the issue of a Electronic signature Certificate in such form as may be prescribed by the Central Government. Every such application shall be accompanied by such fee not exceeding twenty-five thousand rupees as may be prescribed by the Central Government, to be paid to the Certifying Authority: Provided that while prescribing fees under sub-section (2) different fees may be prescribed for different classes of applicants. Every such application shall be accompanied by…"}, "it-act-2000:sec_35": {"cite": "IT Act s.35", "head": "Certifying Authority to issue Electronic signature Certificate", "text": "Any person may make an application to the Certifying Authority for the issue of a Electronic signature Certificate in such form as may be prescribed by the Central Government. Every such application shall be accompanied by such fee not exceeding twenty-five thousand rupees as may be prescribed by the Central Government, to be paid to the Certifying Authority: Provided that while prescribing fees under sub-section (2) different fees may be prescribed for different classes of applicants. Every such application shall be accompanied by a certification practice statement or where there is no such s…"}, "it-act-2000:sec_35__subsec_1": {"cite": "IT Act s.35(1)", "head": "", "text": "Any person may make an application to the Certifying Authority for the issue of a Electronic signature Certificate in such form as may be prescribed by the Central Government."}, "it-act-2000:sec_35__subsec_2": {"cite": "IT Act s.35(2)", "head": "", "text": "Every such application shall be accompanied by such fee not exceeding twenty-five thousand rupees as may be prescribed by the Central Government, to be paid to the Certifying Authority: Provided that while prescribing fees under sub-section (2) different fees may be prescribed for different classes of applicants."}, "it-act-2000:sec_35__subsec_2__proviso_1": {"cite": "IT Act s.35(2)", "head": "", "text": "Provided that while prescribing fees under sub-section (2) different fees may be prescribed for different classes of applicants."}, "it-act-2000:sec_35__subsec_3": {"cite": "IT Act s.35(3)", "head": "", "text": "Every such application shall be accompanied by a certification practice statement or where there is no such statement, a statement containing such particulars, as may be specified by regulations."}, "it-act-2000:sec_35__subsec_4": {"cite": "IT Act s.35(4)", "head": "", "text": "On receipt of an application under sub-section (1), the Certifying Authority may, after consideration of the certification practice statement or the other statement under sub-section (3) and after making such enquiries as it may deem fit, grant the Electronic signature Certificate or for reasons to be recorded in writing, reject the application: Provided that no application shall be rejected unless the applicant has been given a reasonable opportunity of showing cause against the proposed rejection."}, "it-act-2000:sec_35__subsec_4__proviso_1": {"cite": "IT Act s.35(4)", "head": "", "text": ""}, "it-act-2000:sec_35__subsec_4__proviso_2": {"cite": "IT Act s.35(4)", "head": "", "text": "Provided that no application shall be rejected unless the applicant has been given a reasonable opportunity of showing cause against the proposed rejection."}, "it-act-2000:sec_36": {"cite": "IT Act s.36", "head": "Representations upon issuance of Digital Signature Certificate", "text": "A Certifying Authority while issuing a Digital Signature Certificate shall certify that— it has complied with the provisions of this Act and the rules and regulations made thereunder; it has published the Digital Signature Certificate or otherwise made it available to such person relying on it and the subscriber has accepted it; the subscriber holds the private key corresponding to the public key, listed in the Digital Signature Certificate; the subscriber holds a private key which is capable of creating a digital signature; the public key to be listed in the certificate can be used to verify …"}, "it-act-2000:sec_36__cl_a": {"cite": "IT Act s.36(a)", "head": "", "text": "it has complied with the provisions of this Act and the rules and regulations made thereunder;"}, "it-act-2000:sec_36__cl_b": {"cite": "IT Act s.36(b)", "head": "", "text": "it has published the Digital Signature Certificate or otherwise made it available to such person relying on it and the subscriber has accepted it;"}, "it-act-2000:sec_36__cl_c": {"cite": "IT Act s.36(c)", "head": "", "text": "the subscriber holds the private key corresponding to the public key, listed in the Digital Signature Certificate;"}, "it-act-2000:sec_36__cl_ca": {"cite": "IT Act s.36(ca)", "head": "", "text": "the subscriber holds a private key which is capable of creating a digital signature;"}, "it-act-2000:sec_36__cl_cb": {"cite": "IT Act s.36(cb)", "head": "", "text": "the public key to be listed in the certificate can be used to verify a digital signature affixed by the private key held by the subscriber;"}, "it-act-2000:sec_36__cl_d": {"cite": "IT Act s.36(d)", "head": "", "text": "the subscriber's public key and private key constitute a functioning key pair;"}, "it-act-2000:sec_36__cl_e": {"cite": "IT Act s.36(e)", "head": "", "text": "the information contained in the Digital Signature Certificate is accurate; and"}, "it-act-2000:sec_36__cl_f": {"cite": "IT Act s.36(f)", "head": "", "text": "it has no knowledge of any material fact, which if it had been included in the Digital Signature Certificate would adversely affect the reliability of the representations made in clauses (a) to (d)."}, "it-act-2000:sec_37": {"cite": "IT Act s.37", "head": "Suspension of Digital Signature Certificate", "text": "Subject to the provisions of sub-section (2), the Certifying Authority which has issued a Digital Signature Certificate may suspend such Digital Signature Certificate,— on receipt of a request to that effect from— the subscriber listed in the Digital Signature Certificate; or any person duly authorised to act on behalf of that subscriber, if it is of opinion that the Digital Signature Certificate should be suspended in public interest. A Digital Signature Certificate shall not be suspended for a period exceeding fifteen days unless the subscriber has been given an opportunity of being heard in…"}, "it-act-2000:sec_37__subsec_1": {"cite": "IT Act s.37(1)", "head": "", "text": "Subject to the provisions of sub-section (2), the Certifying Authority which has issued a Digital Signature Certificate may suspend such Digital Signature Certificate,— on receipt of a request to that effect from— the subscriber listed in the Digital Signature Certificate; or any person duly authorised to act on behalf of that subscriber, if it is of opinion that the Digital Signature Certificate should be suspended in public interest."}, "it-act-2000:sec_37__subsec_1__cl_a": {"cite": "IT Act s.37(1)(a)", "head": "", "text": "on receipt of a request to that effect from— the subscriber listed in the Digital Signature Certificate; or any person duly authorised to act on behalf of that subscriber,"}, "it-act-2000:sec_37__subsec_1__cl_a__subcl_i": {"cite": "IT Act s.37(1)(a)(i)", "head": "", "text": "the subscriber listed in the Digital Signature Certificate; or"}, "it-act-2000:sec_37__subsec_1__cl_a__subcl_ii": {"cite": "IT Act s.37(1)(a)(ii)", "head": "", "text": "any person duly authorised to act on behalf of that subscriber,"}, "it-act-2000:sec_37__subsec_1__cl_b": {"cite": "IT Act s.37(1)(b)", "head": "", "text": "if it is of opinion that the Digital Signature Certificate should be suspended in public interest."}, "it-act-2000:sec_37__subsec_2": {"cite": "IT Act s.37(2)", "head": "", "text": "A Digital Signature Certificate shall not be suspended for a period exceeding fifteen days unless the subscriber has been given an opportunity of being heard in the matter."}, "it-act-2000:sec_37__subsec_3": {"cite": "IT Act s.37(3)", "head": "", "text": "On suspension of a Digital Signature Certificate under this section, the Certifying Authority shall communicate the same to the subscriber."}, "it-act-2000:sec_38": {"cite": "IT Act s.38", "head": "Revocation of Digital Signature Certificate", "text": "A Certifying Authority may revoke a Digital Signature Certificate issued by it— where the subscriber or any other person authorised by him makes a request to that effect; or upon the death of the subscriber; or upon the dissolution of the firm or winding up of the company where the subscriber is a firm or a company. Subject to the provisions of sub-section (3) and without prejudice to the provisions of sub-section (1), a Certifying Authority may revoke a Digital Signature Certificate which has been issued by it at any time, if it is of opinion that— a material fact represented in the Digital S…"}, "it-act-2000:sec_38__subsec_1": {"cite": "IT Act s.38(1)", "head": "", "text": "A Certifying Authority may revoke a Digital Signature Certificate issued by it— where the subscriber or any other person authorised by him makes a request to that effect; or upon the death of the subscriber; or upon the dissolution of the firm or winding up of the company where the subscriber is a firm or a company."}, "it-act-2000:sec_38__subsec_1__cl_a": {"cite": "IT Act s.38(1)(a)", "head": "", "text": "where the subscriber or any other person authorised by him makes a request to that effect; or"}, "it-act-2000:sec_38__subsec_1__cl_b": {"cite": "IT Act s.38(1)(b)", "head": "", "text": "upon the death of the subscriber; or"}, "it-act-2000:sec_38__subsec_1__cl_c": {"cite": "IT Act s.38(1)(c)", "head": "", "text": "upon the dissolution of the firm or winding up of the company where the subscriber is a firm or a company."}, "it-act-2000:sec_38__subsec_2": {"cite": "IT Act s.38(2)", "head": "", "text": "Subject to the provisions of sub-section (3) and without prejudice to the provisions of sub-section (1), a Certifying Authority may revoke a Digital Signature Certificate which has been issued by it at any time, if it is of opinion that— a material fact represented in the Digital Signature Certificate is false or has been concealed; a requirement for issuance of the Digital Signature Certificate was not satisfied; the Certifying Authority's private key or security system was compromised in a manner materially affecting the Digital Signature Certificate's reliability; the subscriber has been de…"}, "it-act-2000:sec_38__subsec_2__cl_a": {"cite": "IT Act s.38(2)(a)", "head": "", "text": "a material fact represented in the Digital Signature Certificate is false or has been concealed;"}, "it-act-2000:sec_38__subsec_2__cl_b": {"cite": "IT Act s.38(2)(b)", "head": "", "text": "a requirement for issuance of the Digital Signature Certificate was not satisfied;"}, "it-act-2000:sec_38__subsec_2__cl_c": {"cite": "IT Act s.38(2)(c)", "head": "", "text": "the Certifying Authority's private key or security system was compromised in a manner materially affecting the Digital Signature Certificate's reliability;"}, "it-act-2000:sec_38__subsec_2__cl_d": {"cite": "IT Act s.38(2)(d)", "head": "", "text": "the subscriber has been declared insolvent or dead or where a subscriber is a firm or a company, which has been dissolved, wound-up or otherwise ceased to exist."}, "it-act-2000:sec_38__subsec_3": {"cite": "IT Act s.38(3)", "head": "", "text": "A Digital Signature Certificate shall not be revoked unless the subscriber has been given an opportunity of being heard in the matter."}, "it-act-2000:sec_38__subsec_4": {"cite": "IT Act s.38(4)", "head": "", "text": "On revocation of a Digital Signature Certificate under this section, the Certifying Authority shall communicate the same to the subscriber."}, "it-act-2000:sec_39": {"cite": "IT Act s.39", "head": "Notice of suspension or revocation", "text": "Where a Digital Signature Certificate is suspended or revoked under section 37 or section 38, the Certifying Authority shall publish a notice of such suspension or revocation, as the case may be, in the repository specified in the Digital Signature Certificate for publication of such notice. Where one or more repositories are specified, the Certifying Authority shall publish notices of such suspension or revocation, as the case may be, in all such repositories."}, "it-act-2000:sec_39__subsec_1": {"cite": "IT Act s.39(1)", "head": "", "text": "Where a Digital Signature Certificate is suspended or revoked under section 37 or section 38, the Certifying Authority shall publish a notice of such suspension or revocation, as the case may be, in the repository specified in the Digital Signature Certificate for publication of such notice."}, "it-act-2000:sec_39__subsec_2": {"cite": "IT Act s.39(2)", "head": "", "text": "Where one or more repositories are specified, the Certifying Authority shall publish notices of such suspension or revocation, as the case may be, in all such repositories."}, "it-act-2000:chp_VIII": {"cite": "IT Act Chapter VIII", "head": "DUTIES OFSUBSCRIBERS", "text": "Generating key pair Where any Digital Signature Certificate, the public key of which corresponds to the private key of that subscriber which is to be listed in the Digital Signature Certificate has been accepted by a subscriber,, the subscriber shall generate that key pair by applying the security procedure. Duties of subscriber of Electronic Signature Certificate In respect of Electronic Signature Certificate the subscriber shall perform such duties as may be prescribed. Acceptance of Digital Signature Certificate A subscriber shall be deemed to have accepted a Digital Signature Certificate i…"}, "it-act-2000:sec_40": {"cite": "IT Act s.40", "head": "Generating key pair", "text": "Where any Digital Signature Certificate, the public key of which corresponds to the private key of that subscriber which is to be listed in the Digital Signature Certificate has been accepted by a subscriber,, the subscriber shall generate that key pair by applying the security procedure."}, "it-act-2000:sec_40A": {"cite": "IT Act s.40A", "head": "Duties of subscriber of Electronic Signature Certificate", "text": "In respect of Electronic Signature Certificate the subscriber shall perform such duties as may be prescribed."}, "it-act-2000:sec_41": {"cite": "IT Act s.41", "head": "Acceptance of Digital Signature Certificate", "text": "A subscriber shall be deemed to have accepted a Digital Signature Certificate if he publishes or authorises the publication of a Digital Signature Certificate— to one or more persons; in a repository, or otherwise demonstrates his approval of the Digital Signature Certificate in any manner. By accepting a Digital Signature Certificate the subscriber certifies to all who reasonably rely on the information contained in the Digital Signature Certificate that— the subscriber holds the private key corresponding to the public key listed in the Digital Signature Certificate and is entitled to hold th…"}, "it-act-2000:sec_41__subsec_1": {"cite": "IT Act s.41(1)", "head": "", "text": "A subscriber shall be deemed to have accepted a Digital Signature Certificate if he publishes or authorises the publication of a Digital Signature Certificate— to one or more persons; in a repository, or otherwise demonstrates his approval of the Digital Signature Certificate in any manner."}, "it-act-2000:sec_41__subsec_1__cl_a": {"cite": "IT Act s.41(1)(a)", "head": "", "text": "to one or more persons;"}, "it-act-2000:sec_41__subsec_1__cl_b": {"cite": "IT Act s.41(1)(b)", "head": "", "text": "in a repository, or"}, "it-act-2000:sec_41__subsec_2": {"cite": "IT Act s.41(2)", "head": "", "text": "By accepting a Digital Signature Certificate the subscriber certifies to all who reasonably rely on the information contained in the Digital Signature Certificate that— the subscriber holds the private key corresponding to the public key listed in the Digital Signature Certificate and is entitled to hold the same; all representations made by the subscriber to the Certifying Authority and all material relevant to the information contained in the Digital Signature Certificate are true; all information in the Digital Signature Certificate that is within the knowledge of the subscriber is true."}, "it-act-2000:sec_41__subsec_2__cl_a": {"cite": "IT Act s.41(2)(a)", "head": "", "text": "the subscriber holds the private key corresponding to the public key listed in the Digital Signature Certificate and is entitled to hold the same;"}, "it-act-2000:sec_41__subsec_2__cl_b": {"cite": "IT Act s.41(2)(b)", "head": "", "text": "all representations made by the subscriber to the Certifying Authority and all material relevant to the information contained in the Digital Signature Certificate are true;"}, "it-act-2000:sec_41__subsec_2__cl_c": {"cite": "IT Act s.41(2)(c)", "head": "", "text": "all information in the Digital Signature Certificate that is within the knowledge of the subscriber is true."}, "it-act-2000:sec_42": {"cite": "IT Act s.42", "head": "Control of private key", "text": "Every subscriber shall exercise reasonable care to retain control of the private key corresponding to the public key listed in his Digital Signature Certificate and take all steps to prevent its disclosure . If the private key corresponding to the public key listed in the Digital Signature Certificate has been compromised, then, the subscriber shall communicate the same without any delay to the Certifying Authority in such manner as may be specified by the regulations. For the removal of doubts, it is hereby declared that the subscriber shall be liable till he has informed the Certifying Autho…"}, "it-act-2000:sec_42__subsec_1": {"cite": "IT Act s.42(1)", "head": "", "text": "Every subscriber shall exercise reasonable care to retain control of the private key corresponding to the public key listed in his Digital Signature Certificate and take all steps to prevent its disclosure ."}, "it-act-2000:sec_42__subsec_2": {"cite": "IT Act s.42(2)", "head": "", "text": "If the private key corresponding to the public key listed in the Digital Signature Certificate has been compromised, then, the subscriber shall communicate the same without any delay to the Certifying Authority in such manner as may be specified by the regulations. For the removal of doubts, it is hereby declared that the subscriber shall be liable till he has informed the Certifying Authority that the private key has been compromised."}, "it-act-2000:sec_42__subsec_2__hcontainer_1": {"cite": "IT Act s.42(2)", "head": "", "text": "For the removal of doubts, it is hereby declared that the subscriber shall be liable till he has informed the Certifying Authority that the private key has been compromised."}, "it-act-2000:chp_IX": {"cite": "IT Act Chapter IX", "head": "PENALITIES, COMPENSATION AND ADJUDICATION", "text": "Penalty and Compensation for damage to computer, computer system, etc If any person without permission of the owner or any other person who is incharge of a computer, computer system or computer network,— accesses or secures access to such computer, computer system or computer network or computer resource; downloads, copies or extracts any data, computer data base or information from such computer, computer system or computer network including information or data held or stored in any removable storage medium; introduces or causes to be introduced any computer contaminant or computer virus int…"}, "it-act-2000:sec_43": {"cite": "IT Act s.43", "head": "Penalty and Compensation for damage to computer, computer system, etc", "text": "If any person without permission of the owner or any other person who is incharge of a computer, computer system or computer network,— accesses or secures access to such computer, computer system or computer network or computer resource; downloads, copies or extracts any data, computer data base or information from such computer, computer system or computer network including information or data held or stored in any removable storage medium; introduces or causes to be introduced any computer contaminant or computer virus into any computer, computer system or computer network; damages or causes…"}, "it-act-2000:sec_43__cl_a": {"cite": "IT Act s.43(a)", "head": "", "text": "accesses or secures access to such computer, computer system or computer network or computer resource;"}, "it-act-2000:sec_43__cl_b": {"cite": "IT Act s.43(b)", "head": "", "text": "downloads, copies or extracts any data, computer data base or information from such computer, computer system or computer network including information or data held or stored in any removable storage medium;"}, "it-act-2000:sec_43__cl_c": {"cite": "IT Act s.43(c)", "head": "", "text": "introduces or causes to be introduced any computer contaminant or computer virus into any computer, computer system or computer network;"}, "it-act-2000:sec_43__cl_d": {"cite": "IT Act s.43(d)", "head": "", "text": "damages or causes to be damaged any computer, computer system or computer network, data, computer data base or any other programmes residing in such computer, computer system or computer network;"}, "it-act-2000:sec_43__cl_e": {"cite": "IT Act s.43(e)", "head": "", "text": "disrupts or causes disruption of any computer, computer system or computer network;"}, "it-act-2000:sec_43__cl_f": {"cite": "IT Act s.43(f)", "head": "", "text": "denies or causes the denial of access to any person authorised to access any computer, computer system or computer network by any means;"}, "it-act-2000:sec_43__cl_g": {"cite": "IT Act s.43(g)", "head": "", "text": "provides any assistance to any person to facilitate access to a computer, computer system or computer network in contravention of the provisions of this Act, rules or regulations made thereunder,"}, "it-act-2000:sec_43__cl_h": {"cite": "IT Act s.43(h)", "head": "", "text": "charges the services availed of by a person to the account of another person by tampering with or manipulating any computer, computer system, or computer network,"}, "it-act-2000:sec_43__cl_i": {"cite": "IT Act s.43(i)", "head": "", "text": "destroys, deletes or alters any information residing in a computer resource or diminishes its value or utility or affects it injuriously by any means;"}, "it-act-2000:sec_43__cl_j": {"cite": "IT Act s.43(j)", "head": "", "text": "steal, conceals, destroys or alters or causes any person to steal, conceal, destroy or alter any computer source code used for a computer resource with an intention to cause damage;"}, "it-act-2000:sec_43__wrap_1": {"cite": "IT Act s.43", "head": "", "text": "he shall be liable to pay damages by way of compensation to the person so affected."}, "it-act-2000:sec_43__hcontainer_1": {"cite": "IT Act s.43", "head": "", "text": "For the purposes of this section,— \"computer contaminant\" means any set of computer instructions that are designed— to modify, destroy, record, transmit data or programme residing within a computer, computer system or computer network; or by any means to usurp the normal operation of the computer, computer system, or computer network; \"computer data base\" means a representation of information, knowledge, facts, concepts or instructions in text, image, audio, video that are being prepared or have been prepared in a formalised manner or have been produced by a computer, computer system or comput…"}, "it-act-2000:sec_43__hcontainer_1__subcl_i": {"cite": "IT Act s.43(i)", "head": "", "text": "\"computer contaminant\" means any set of computer instructions that are designed— to modify, destroy, record, transmit data or programme residing within a computer, computer system or computer network; or by any means to usurp the normal operation of the computer, computer system, or computer network;"}, "it-act-2000:sec_43__hcontainer_1__subcl_i__cl_a": {"cite": "IT Act s.43(i)(a)", "head": "", "text": "to modify, destroy, record, transmit data or programme residing within a computer, computer system or computer network; or"}, "it-act-2000:sec_43__hcontainer_1__subcl_i__cl_b": {"cite": "IT Act s.43(i)(b)", "head": "", "text": "by any means to usurp the normal operation of the computer, computer system, or computer network;"}, "it-act-2000:sec_43__hcontainer_1__subcl_ii": {"cite": "IT Act s.43(ii)", "head": "", "text": "\"computer data base\" means a representation of information, knowledge, facts, concepts or instructions in text, image, audio, video that are being prepared or have been prepared in a formalised manner or have been produced by a computer, computer system or computer network and are intended for use in a computer, computer system or computer network;"}, "it-act-2000:sec_43__hcontainer_1__subcl_iii": {"cite": "IT Act s.43(iii)", "head": "", "text": "\"computer virus\" means any computer instruction, information, data or programme that destroys, damages, degrades or adversely affects the performance ofacomputer resource or attaches itself to another computer resource and operates when a programme, data or instruction is executed or some other event takes place in that computer resource;"}, "it-act-2000:sec_43__hcontainer_1__subcl_iv": {"cite": "IT Act s.43(iv)", "head": "", "text": "\"damage\" means to destroy, alter, delete, add, modify or rearrange any computer resource by any means."}, "it-act-2000:sec_43__hcontainer_1__subcl_v": {"cite": "IT Act s.43(v)", "head": "", "text": "“computer source code” means the listing of programmes, computer commands, design and layout and programme analysis of computer resource in any form."}, "it-act-2000:sec_43A": {"cite": "IT Act s.43A", "head": "Compensation for failure to protect data", "text": "Where a body corporate, possessing, dealing or handling any sensitive personal data or information in a computer resource which it owns, controls or operates, is negligent in implementing and maintaining reasonable security practices and procedures and thereby causes wrongful loss or wrongful gain to any person, such body corporate shall be liable to pay damages by way of compensation to the person so affected. For the purposes of this section,— “body corporate” means any company and includes a firm, sole proprietorship or other association of individuals engaged in commercial or professional …"}, "it-act-2000:sec_43A__hcontainer_1": {"cite": "IT Act s.43A", "head": "", "text": "For the purposes of this section,— “body corporate” means any company and includes a firm, sole proprietorship or other association of individuals engaged in commercial or professional activities; “reasonable security practices and procedures” means security practices and procedures designed to protect such information from unauthorised access, damage, use, modification, disclosure or impairment, as may be specified in an agreement between the parties or as may be specified in any law for the time being in force and in the absence of such agreement or any law, such reasonable security practice…"}, "it-act-2000:sec_43A__hcontainer_1__subcl_i": {"cite": "IT Act s.43A(i)", "head": "", "text": "“body corporate” means any company and includes a firm, sole proprietorship or other association of individuals engaged in commercial or professional activities;"}, "it-act-2000:sec_43A__hcontainer_1__subcl_ii": {"cite": "IT Act s.43A(ii)", "head": "", "text": "“reasonable security practices and procedures” means security practices and procedures designed to protect such information from unauthorised access, damage, use, modification, disclosure or impairment, as may be specified in an agreement between the parties or as may be specified in any law for the time being in force and in the absence of such agreement or any law, such reasonable security practices and procedures, as may be prescribed by the Central Government in consultation with such professional bodies or associations as it may deem fit;"}, "it-act-2000:sec_43A__hcontainer_1__subcl_iii": {"cite": "IT Act s.43A(iii)", "head": "", "text": "“sensitive personal data or information” means such personal information as may be prescribed by the Central Government in consultation with such professional bodies or associations as it may deem fit."}, "it-act-2000:sec_44": {"cite": "IT Act s.44", "head": "Penalty for failure to furnish information, return, etc", "text": "If any person who is required under this Act or any rules or regulations made thereunder to— furnish any document, return or report to the Controller or the Certifying Authority fails to furnish the same, he shall be liable to a penalty not exceeding fifteen lakh rupees for each such failure; file any return or furnish any information, books or other documents within the time specified therefor in the regulations fails to file return or furnish the same within the time specified therefor in the regulations, he shall be liable to a penalty not exceeding fifty thousand rupees for every day durin…"}, "it-act-2000:sec_44__cl_a": {"cite": "IT Act s.44(a)", "head": "", "text": "furnish any document, return or report to the Controller or the Certifying Authority fails to furnish the same, he shall be liable to a penalty not exceeding fifteen lakh rupees for each such failure;"}, "it-act-2000:sec_44__cl_b": {"cite": "IT Act s.44(b)", "head": "", "text": "file any return or furnish any information, books or other documents within the time specified therefor in the regulations fails to file return or furnish the same within the time specified therefor in the regulations, he shall be liable to a penalty not exceeding fifty thousand rupees for every day during which such failure continues;"}, "it-act-2000:sec_44__cl_c": {"cite": "IT Act s.44(c)", "head": "", "text": "maintain books of account or records, fails to maintain the same, he shall be liable to a penalty not exceeding one lakh rupees for every day during which the failure continues."}, "it-act-2000:sec_45": {"cite": "IT Act s.45", "head": "Residuary penalty", "text": "Whoever contravenes any rules, regulations, directions or orders made under this Act, for the contravention of which no penalty has been separately provided, shall be liable to pay a penalty not exceeding one lakh rupees, in addition to compensation to the person affected by such contravention not exceeding— (a) ten lakh rupees, by an intermediary, company or body corporate; or (b) one lakh rupees, by any other person.."}, "it-act-2000:sec_46": {"cite": "IT Act s.46", "head": "Power to adjudicate", "text": "For the purpose of adjudging under this Act whether any person has committed a contravention of any of the provisions of this Act or of any rule, regulation, direction or order made thereunder which renders him liable to pay penalty or compensation, the Central Government shall, subject to the provisions of sub-section (3), appoint any officer not below the rank of a Director to the Government of India or an equivalent officer of a State Government to be an adjudicating officer for holding an inquiry in the mannner prescribed by the Central Government. The adjudicating officer appointed under …"}, "it-act-2000:sec_46__subsec_1": {"cite": "IT Act s.46(1)", "head": "", "text": "For the purpose of adjudging under this Act whether any person has committed a contravention of any of the provisions of this Act or of any rule, regulation, direction or order made thereunder which renders him liable to pay penalty or compensation, the Central Government shall, subject to the provisions of sub-section (3), appoint any officer not below the rank of a Director to the Government of India or an equivalent officer of a State Government to be an adjudicating officer for holding an inquiry in the mannner prescribed by the Central Government."}, "it-act-2000:sec_46__subsec_1A": {"cite": "IT Act s.46(1A)", "head": "", "text": "The adjudicating officer appointed under sub-section (1) shall exercise jurisdiction to adjudicate matters in which the claim for damage does not exceed rupees five crore: Provided that the jurisdiction in respect of the claim for damage exceeding rupees five crore shall vest with the competent court."}, "it-act-2000:sec_46__subsec_1A__proviso_1": {"cite": "IT Act s.46(1A)", "head": "", "text": "Provided that the jurisdiction in respect of the claim for damage exceeding rupees five crore shall vest with the competent court."}, "it-act-2000:sec_46__subsec_2": {"cite": "IT Act s.46(2)", "head": "", "text": "The adjudicating officer shall, after giving the person referred to in sub-section (1) a reasonable opportunity for making representation in the matter and if, on such inquiry, he is satisfied that the person has committed the contravention, he may impose such penalty or award such compensation as he thinks fit in accordance with the provisions of that section."}, "it-act-2000:sec_46__subsec_3": {"cite": "IT Act s.46(3)", "head": "", "text": "No person shall be appointed as an adjudicating officer unless he possesses such experience in the field of Information Technology and legal or judicial experience as may be prescribed by the Central Government."}, "it-act-2000:sec_46__subsec_4": {"cite": "IT Act s.46(4)", "head": "", "text": "Where more than one adjudicating officers are appointed, the Central Government shall specify by order the matters and places with respect to which such officers shall exercise their jurisdiction."}, "it-act-2000:sec_46__subsec_5": {"cite": "IT Act s.46(5)", "head": "", "text": "Every adjudicating officer shall have the powers of a civil court which are conferred on the Appellate Tribunal under sub-section (2) of section 58, and— all proceedings before it shall be deemed to be judicial proceedings within the meaning of sections 193 and 228 of the Indian Penal Code; shall be deemed to be a civil court for the purposes of sections 345 and 346 of the Code of Criminal Procedure, 1973. shall be deemed to be a civil court for purposes of Order XXI of the 5 of 1908. Civil Procedure Code, 1908."}, "it-act-2000:sec_46__subsec_5__cl_a": {"cite": "IT Act s.46(5)(a)", "head": "", "text": "all proceedings before it shall be deemed to be judicial proceedings within the meaning of sections 193 and 228 of the Indian Penal Code;"}, "it-act-2000:sec_46__subsec_5__cl_b": {"cite": "IT Act s.46(5)(b)", "head": "", "text": "shall be deemed to be a civil court for the purposes of sections 345 and 346 of the Code of Criminal Procedure, 1973."}, "it-act-2000:sec_46__subsec_5__cl_c": {"cite": "IT Act s.46(5)(c)", "head": "", "text": "shall be deemed to be a civil court for purposes of Order XXI of the 5 of 1908. Civil Procedure Code, 1908."}, "it-act-2000:sec_47": {"cite": "IT Act s.47", "head": "Factors to be taken into account by the adjudicating officer", "text": "While adjudging the quantum of compensation under this Chapter, the adjudicating officer shall have due regard to the following factors, namely:— the amount of gain of unfair advantage, wherever quantifiable, made as a result of the default; the amount of loss caused to any person as a result of the default; the repetitive nature of the default."}, "it-act-2000:sec_47__cl_a": {"cite": "IT Act s.47(a)", "head": "", "text": "the amount of gain of unfair advantage, wherever quantifiable, made as a result of the default;"}, "it-act-2000:sec_47__cl_b": {"cite": "IT Act s.47(b)", "head": "", "text": "the amount of loss caused to any person as a result of the default;"}, "it-act-2000:sec_47__cl_c": {"cite": "IT Act s.47(c)", "head": "", "text": "the repetitive nature of the default."}, "it-act-2000:chp_X": {"cite": "IT Act Chapter X", "head": "THE APPELLATE TRIBUNAL", "text": "Appellate Tribunal The Telecom Disputes Settlement and Appellate Tribunal established under section 14 of the Telecom Regulatory Authority of India Act, 1997 shall, on and from the commencement of Part XIV of Chapter VI of the Finance Act, 2017, be the Appellate Tribunal for the purposes of this Act and the said Appellate Tribunal shall exercise the jurisdiction, powers and authority conferred on it by or under this Act. The Central Government shall specify, by notification), the matters and places in relation to which the Appellate Tribunal may exercise jurisdiction. Composition of Appellate …"}, "it-act-2000:sec_48": {"cite": "IT Act s.48", "head": "Appellate Tribunal", "text": "The Telecom Disputes Settlement and Appellate Tribunal established under section 14 of the Telecom Regulatory Authority of India Act, 1997 shall, on and from the commencement of Part XIV of Chapter VI of the Finance Act, 2017, be the Appellate Tribunal for the purposes of this Act and the said Appellate Tribunal shall exercise the jurisdiction, powers and authority conferred on it by or under this Act. The Central Government shall specify, by notification), the matters and places in relation to which the Appellate Tribunal may exercise jurisdiction."}, "it-act-2000:sec_48__subsec_1": {"cite": "IT Act s.48(1)", "head": "", "text": "The Telecom Disputes Settlement and Appellate Tribunal established under section 14 of the Telecom Regulatory Authority of India Act, 1997 shall, on and from the commencement of Part XIV of Chapter VI of the Finance Act, 2017, be the Appellate Tribunal for the purposes of this Act and the said Appellate Tribunal shall exercise the jurisdiction, powers and authority conferred on it by or under this Act."}, "it-act-2000:sec_48__subsec_2": {"cite": "IT Act s.48(2)", "head": "", "text": "The Central Government shall specify, by notification), the matters and places in relation to which the Appellate Tribunal may exercise jurisdiction."}, "it-act-2000:sec_49": {"cite": "IT Act s.49", "head": "Composition of Appellate Tribunal", "text": ""}, "it-act-2000:sec_50": {"cite": "IT Act s.50", "head": "Qualifications for appoint-ment as Chairperson and Members of Appellate Tribunal", "text": ""}, "it-act-2000:sec_51": {"cite": "IT Act s.51", "head": "Term of office, conditions of service, etc., of Chairperson and Members", "text": ""}, "it-act-2000:sec_52": {"cite": "IT Act s.52", "head": "Salary, allowances and other terms and conditions of service of Chairperson and Members", "text": ""}, "it-act-2000:sec_52A": {"cite": "IT Act s.52A", "head": "Powers of superintendencc. direction, etc", "text": ""}, "it-act-2000:sec_52B": {"cite": "IT Act s.52B", "head": "Distribution of business among Benches", "text": ""}, "it-act-2000:sec_52C": {"cite": "IT Act s.52C", "head": "Power of Chairperson to transfer cases", "text": ""}, "it-act-2000:sec_52D": {"cite": "IT Act s.52D", "head": "Decision by majority", "text": "If the Members of a Bench consisting of two Members differ in opinion on any point, they shall state the point or points on which they differ, and make a reference to the Chairperson of the Appellate Tribunal who shall hear the point or points himself and such point or points shall be decided according to the opinion of the majority of the Members who have heard the case, including those who first heard it."}, "it-act-2000:sec_53": {"cite": "IT Act s.53", "head": "Filling up of vacancies", "text": ""}, "it-act-2000:sec_54": {"cite": "IT Act s.54", "head": "Resignation and removal", "text": ""}, "it-act-2000:sec_55": {"cite": "IT Act s.55", "head": "Orders constituting Appellate Tribunal to be final and not to invalidate its proceedings", "text": "No order of the Central Government appointing any person as the Chairperson or the Member of a Appellate Tribunal shall be called in question in any manner and no act or proceeding before a Appellate Tribunal shall be called in question in any manner on the ground merely of any defect in the constitution of a Appellate Tribunal."}, "it-act-2000:sec_56": {"cite": "IT Act s.56", "head": "Staff of the Appellate Tribunal", "text": ""}, "it-act-2000:sec_57": {"cite": "IT Act s.57", "head": "Appeal to Appellate Tribunal", "text": "Save as provided in sub-section (2), any person aggrieved by an order made by Controller or an adjudicating officer under this Act may prefer an appeal to a Appellate Tribunal having jurisdiction in the matter. No appeal shall lie to the Appellate Tribunal from an order made by an adjudicating officer with the consent of the parties. Every appeal under sub-section (1) shall be filed within a period of forty-five days from the date on which a copy of the order made by the Controller or the adjudicating officer is received by the person aggrieved and it shall be in such form and be accompanied b…"}, "it-act-2000:sec_57__subsec_1": {"cite": "IT Act s.57(1)", "head": "", "text": "Save as provided in sub-section (2), any person aggrieved by an order made by Controller or an adjudicating officer under this Act may prefer an appeal to a Appellate Tribunal having jurisdiction in the matter."}, "it-act-2000:sec_57__subsec_2": {"cite": "IT Act s.57(2)", "head": "", "text": "No appeal shall lie to the Appellate Tribunal from an order made by an adjudicating officer with the consent of the parties."}, "it-act-2000:sec_57__subsec_3": {"cite": "IT Act s.57(3)", "head": "", "text": "Every appeal under sub-section (1) shall be filed within a period of forty-five days from the date on which a copy of the order made by the Controller or the adjudicating officer is received by the person aggrieved and it shall be in such form and be accompanied by such fee as may be prescribed: Provided that the Appellate Tribunal may entertain an appeal after the expiry of the said period of forty-five days if it is satisfied that there was sufficient cause for not filing it within that period."}, "it-act-2000:sec_57__subsec_3__proviso_1": {"cite": "IT Act s.57(3)", "head": "", "text": "Provided that the Appellate Tribunal may entertain an appeal after the expiry of the said period of forty-five days if it is satisfied that there was sufficient cause for not filing it within that period."}, "it-act-2000:sec_57__subsec_4": {"cite": "IT Act s.57(4)", "head": "", "text": "On receipt of an appeal under sub-section (1), the Appellate Tribunal may, after giving the parties to the appeal, an opportunity of being heard, pass such orders therein as it thinks fit, confirming, modifying or setting aside the order appealed against."}, "it-act-2000:sec_57__subsec_5": {"cite": "IT Act s.57(5)", "head": "", "text": "The Appellate Tribunal shall send a copy of every order made by it to the parties to the appeal and to the concerned Controller or adjudicating officer."}, "it-act-2000:sec_57__subsec_6": {"cite": "IT Act s.57(6)", "head": "", "text": "The appeal filed before the Appellate Tribunal under sub-section (1) shall be dealt with by it as expeditiously as possible and endeavour shall be made by it to dispose of the appeal finally within six months from the date of receipt of the appeal."}, "it-act-2000:sec_58": {"cite": "IT Act s.58", "head": "Procedure and powers of the Appellate Tribunal", "text": "The Appellate Tribunal shall not be bound by the procedure laid down by the Code of Civil Procedure, 1908 but shall be guided by the principles of natural justice and, subject to the other provisions of this Act and of any rules, the Appellate Tribunal shall have powers to regulate its own procedure including the place at which it shall have its sittings. The Appellate Tribunal shall have, for the purposes of discharging its functions under this Act, the same powers as are vested in a civil court under the Code of Civil Procedure, 1908, while trying a suit, in respect of the following matters,…"}, "it-act-2000:sec_58__subsec_1": {"cite": "IT Act s.58(1)", "head": "", "text": "The Appellate Tribunal shall not be bound by the procedure laid down by the Code of Civil Procedure, 1908 but shall be guided by the principles of natural justice and, subject to the other provisions of this Act and of any rules, the Appellate Tribunal shall have powers to regulate its own procedure including the place at which it shall have its sittings."}, "it-act-2000:sec_58__subsec_2": {"cite": "IT Act s.58(2)", "head": "", "text": "The Appellate Tribunal shall have, for the purposes of discharging its functions under this Act, the same powers as are vested in a civil court under the Code of Civil Procedure, 1908, while trying a suit, in respect of the following matters, namely:— summoning and enforcing the attendance of any person and examining him on oath; requiring the discovery and production of documents or other electronic records; receiving evidence on affidavits; issuing commissions for the examination of witnesses or documents; reviewing its decisions; dismissing an application for default or deciding it ex parte…"}, "it-act-2000:sec_58__subsec_2__cl_a": {"cite": "IT Act s.58(2)(a)", "head": "", "text": "summoning and enforcing the attendance of any person and examining him on oath;"}, "it-act-2000:sec_58__subsec_2__cl_b": {"cite": "IT Act s.58(2)(b)", "head": "", "text": "requiring the discovery and production of documents or other electronic records;"}, "it-act-2000:sec_58__subsec_2__cl_c": {"cite": "IT Act s.58(2)(c)", "head": "", "text": "receiving evidence on affidavits;"}, "it-act-2000:sec_58__subsec_2__cl_d": {"cite": "IT Act s.58(2)(d)", "head": "", "text": "issuing commissions for the examination of witnesses or documents;"}, "it-act-2000:sec_58__subsec_2__cl_e": {"cite": "IT Act s.58(2)(e)", "head": "", "text": "reviewing its decisions;"}, "it-act-2000:sec_58__subsec_2__cl_f": {"cite": "IT Act s.58(2)(f)", "head": "", "text": "dismissing an application for default or deciding it ex parte;"}, "it-act-2000:sec_58__subsec_2__cl_g": {"cite": "IT Act s.58(2)(g)", "head": "", "text": "any other matter which may be prescribed."}, "it-act-2000:sec_58__subsec_3": {"cite": "IT Act s.58(3)", "head": "", "text": "Every proceeding before the Appellate Tribunal shall be deemed to be a judicial proceeding within the meaning of sections 193 and 228, and for the purposes of section 196 of the Indian Penal Code and the Appellate Tribunal shall be deemed to be a civil court for the purposes of section 195 and Chapter XXVI of the Code of Criminal Procedure, 1973."}, "it-act-2000:sec_59": {"cite": "IT Act s.59", "head": "Right to legal representation", "text": "The appellant may either appear in person or authorise one or more legal practitioners or any of its officers to present his or its case before the Appellate Tribunal."}, "it-act-2000:sec_60": {"cite": "IT Act s.60", "head": "36 of 1963. Limitation", "text": "The provisions of the Limitation Act, 1963, shall, as far as may be, apply to an appeal made to the Appellate Tribunal."}, "it-act-2000:sec_61": {"cite": "IT Act s.61", "head": "Civil court not to have jurisdiction", "text": "No court shall have jurisdiction to entertain any suit or proceeding in respect of any matter which an adjudicating officer appointed under this Act or the Appellate Tribunal constituted under this Act is empowered by or under this Act to determine and no injunction shall be granted by any court or other authority in respect of any action taken or to be taken in pursuance of any power conferred by or under this Act."}, "it-act-2000:sec_62": {"cite": "IT Act s.62", "head": "Appeal to High Court", "text": "Any person aggrieved by any decision or order of the Appellate Tribunal may file an appeal to the High Court within sixty days from the date of communication of the decision or order of the Appellate Tribunal to him on any question of fact or law arising out of such order: Provided that the High Court may, if it is satisfied that the appellant was prevented by sufficient cause from filing the appeal within the said period, allow it to be filed within a further period not exceeding sixty days."}, "it-act-2000:sec_62__proviso_1": {"cite": "IT Act s.62", "head": "", "text": "Provided that the High Court may, if it is satisfied that the appellant was prevented by sufficient cause from filing the appeal within the said period, allow it to be filed within a further period not exceeding sixty days."}, "it-act-2000:sec_63": {"cite": "IT Act s.63", "head": "Compounding of contraventions", "text": "Any contravention under this Act may, either before or after the institution of adjudication proceedings, be compounded by the Controller or such other officer as may be specially authorised by him in this behalf or by the adjudicating officer, as the case may be, subject to such conditions as the Controller or such other officer or the adjudicating officer may specify: Provided that such sum shall not, in any case, exceed the maximum amount of the penalty which may be imposed under this Act for the contravention so compounded. Nothing in sub-section (1) shall apply to a person who commits the…"}, "it-act-2000:sec_63__subsec_1": {"cite": "IT Act s.63(1)", "head": "", "text": "Any contravention under this Act may, either before or after the institution of adjudication proceedings, be compounded by the Controller or such other officer as may be specially authorised by him in this behalf or by the adjudicating officer, as the case may be, subject to such conditions as the Controller or such other officer or the adjudicating officer may specify: Provided that such sum shall not, in any case, exceed the maximum amount of the penalty which may be imposed under this Act for the contravention so compounded."}, "it-act-2000:sec_63__subsec_1__proviso_1": {"cite": "IT Act s.63(1)", "head": "", "text": "Provided that such sum shall not, in any case, exceed the maximum amount of the penalty which may be imposed under this Act for the contravention so compounded."}, "it-act-2000:sec_63__subsec_2": {"cite": "IT Act s.63(2)", "head": "", "text": "Nothing in sub-section (1) shall apply to a person who commits the same or similar contravention within a period of three years from the date on which the first contravention, committed by him, was compounded. For the purposes of this sub-section, any second or subsequent contravention committed after the expiry of a period of three years from the date on which the contravention was previously compounded shall be deemed to be a first contravention."}, "it-act-2000:sec_63__subsec_2__hcontainer_1": {"cite": "IT Act s.63(2)", "head": "", "text": "For the purposes of this sub-section, any second or subsequent contravention committed after the expiry of a period of three years from the date on which the contravention was previously compounded shall be deemed to be a first contravention."}, "it-act-2000:sec_63__subsec_3": {"cite": "IT Act s.63(3)", "head": "", "text": "Where any contravention has been compounded under sub-section (1), no proceeding or further proceeding, as the case may be, shall be taken against the person guilty of such contravention in respect of the contravention so compounded."}, "it-act-2000:sec_64": {"cite": "IT Act s.64", "head": "Recovery of penalty or compensation", "text": "A penalty imposed or compensation awarded under this Act, if it is not paid, shall be recovered as an arrear of land revenue and the licence or the Electronic signature Certificate, as the case may be, shall be suspended till the penalty is paid."}, "it-act-2000:chp_XI": {"cite": "IT Act Chapter XI", "head": "OFFENCES", "text": "Tampering with computer source documents Whoever knowingly or intentionally conceals, destroys or alters or intentionally or knowingly causes another to conceal, destroy or alter any computer source code used for a computer, computer programme, computer system or computer network, when the computer source code is required to be kept or maintained by law for the time being in force, shall be punishable with imprisonment up to three years, or with fine which may extend up to two lakh rupees, or with both. For the purposes of this section, \"computer source code\" means the listing of programmes, c…"}, "it-act-2000:sec_65": {"cite": "IT Act s.65", "head": "Tampering with computer source documents", "text": "Whoever knowingly or intentionally conceals, destroys or alters or intentionally or knowingly causes another to conceal, destroy or alter any computer source code used for a computer, computer programme, computer system or computer network, when the computer source code is required to be kept or maintained by law for the time being in force, shall be punishable with imprisonment up to three years, or with fine which may extend up to two lakh rupees, or with both. For the purposes of this section, \"computer source code\" means the listing of programmes, computer commands, design and layout and p…"}, "it-act-2000:sec_65__hcontainer_1": {"cite": "IT Act s.65", "head": "", "text": "For the purposes of this section, \"computer source code\" means the listing of programmes, computer commands, design and layout and programme analysis of computer resource in any form."}, "it-act-2000:sec_66": {"cite": "IT Act s.66", "head": "Computer related offences", "text": "If any person, dishonestly or fraudulently, coes any act referred to in section 43, he shall be punishable with imprisonment for a term which may extend to three years or with fine which may extend to five lakh rupees or with both. For the purposes of this section, the word “dishonestly” shall have the meaning assigned to it in section 24 45 of 1860. of the Indian Penal Code; the word “fraudulently” shall have the meaning assigned to it in section 25 45 of 1860. of the Indian Penal Code."}, "it-act-2000:sec_66__hcontainer_1": {"cite": "IT Act s.66", "head": "", "text": "For the purposes of this section, the word “dishonestly” shall have the meaning assigned to it in section 24 45 of 1860. of the Indian Penal Code; the word “fraudulently” shall have the meaning assigned to it in section 25 45 of 1860. of the Indian Penal Code."}, "it-act-2000:sec_66__hcontainer_1__cl_a": {"cite": "IT Act s.66(a)", "head": "", "text": "the word “dishonestly” shall have the meaning assigned to it in section 24 45 of 1860. of the Indian Penal Code;"}, "it-act-2000:sec_66__hcontainer_1__cl_b": {"cite": "IT Act s.66(b)", "head": "", "text": "the word “fraudulently” shall have the meaning assigned to it in section 25 45 of 1860. of the Indian Penal Code."}, "it-act-2000:sec_66A": {"cite": "IT Act s.66A", "head": "Punishment for sending offensive messages through communication service, etc", "text": ""}, "it-act-2000:sec_66B": {"cite": "IT Act s.66B", "head": "Punishment for dishonestly receiving stolen computer resource or communication device", "text": "Whoever dishonestly receives or retains any stolen computer resource or communication device knowing or having reason to believe the same to be stolen computer resource or communication device, shall be punished with imprisonment of either description for a term which may extend to three years or with fine which may extend to rupees one lakh or with both."}, "it-act-2000:sec_66C": {"cite": "IT Act s.66C", "head": "Punishment for identity theft", "text": "Whoever, fraudulently or dishonestly make use of the electronic signature, password or any other unique identification feature of any other person, shall be punished with imprisonment of either description for a term which may extend to three years and shall also be liable to fine which may extend to rupees one lakh."}, "it-act-2000:sec_66D": {"cite": "IT Act s.66D", "head": "Punishment for cheating by personation by using computer resource", "text": "Whoever, by means of any communication device or computer resource cheats by personation, shall be punished with imprisonment of either description for a term which may extend to three years and shall also be liable to fine which may extend to one lakh rupees."}, "it-act-2000:sec_66E": {"cite": "IT Act s.66E", "head": "Punishment for violation of privacy", "text": "Whoever, intentionally or knowingly captures, publishes or transmits the image of a private area of any person without his or her consent, under circumstances violating the privacy of that person, shall be punished with imprisonment which may extend to three years or with fine not exceeding two lakh rupees, or with both. For the purposes of this section - “transmit” means to electronically send a visual image with the intent that it be viewed by a person or persons; “capture”, with respect to an image, means to videotape, photograph, film or record by any means; “private area” means the naked …"}, "it-act-2000:sec_66E__hcontainer_1": {"cite": "IT Act s.66E", "head": "", "text": "For the purposes of this section - “transmit” means to electronically send a visual image with the intent that it be viewed by a person or persons; “capture”, with respect to an image, means to videotape, photograph, film or record by any means; “private area” means the naked or undergarment clad genitals, public area, buttocks or female breast; “publishes” means reproduction in the printed or electronic form and making it available for public; “under circumstances violating privacy” means circumstances in which a person can have a reasonable expectation that— he or she could disrobe in privac…"}, "it-act-2000:sec_66E__hcontainer_1__cl_a": {"cite": "IT Act s.66E(a)", "head": "", "text": "“transmit” means to electronically send a visual image with the intent that it be viewed by a person or persons;"}, "it-act-2000:sec_66E__hcontainer_1__cl_b": {"cite": "IT Act s.66E(b)", "head": "", "text": "“capture”, with respect to an image, means to videotape, photograph, film or record by any means;"}, "it-act-2000:sec_66E__hcontainer_1__cl_c": {"cite": "IT Act s.66E(c)", "head": "", "text": "“private area” means the naked or undergarment clad genitals, public area, buttocks or female breast;"}, "it-act-2000:sec_66E__hcontainer_1__cl_d": {"cite": "IT Act s.66E(d)", "head": "", "text": "“publishes” means reproduction in the printed or electronic form and making it available for public;"}, "it-act-2000:sec_66E__hcontainer_1__cl_e": {"cite": "IT Act s.66E(e)", "head": "", "text": "“under circumstances violating privacy” means circumstances in which a person can have a reasonable expectation that— he or she could disrobe in privacy, without being concerned that an image of his private area was being captured; or (ii) any part of his or her private area would not be visible to the public, regardless of whether that person is in a public or private place."}, "it-act-2000:sec_66E__hcontainer_1__cl_e__subsec_1": {"cite": "IT Act s.66E(e)(1)", "head": "", "text": "he or she could disrobe in privacy, without being concerned that an image of his private area was being captured; or (ii) any part of his or her private area would not be visible to the public, regardless of whether that person is in a public or private place."}, "it-act-2000:sec_66F": {"cite": "IT Act s.66F", "head": "Punishment for cyber terrorism", "text": "Whoever,— (A4) with intent to threaten the unity, integrity, security or sovereignty of India or to strike terror in the people or any section of the people by-- denying or cause the denial of access to any person authorised to access computer resource; or (ii) attempting to penetrate or access a computer resource without authorisation or exceeding authorised access; or (ii) introducing or causing to introduce any computer contaminant, and by means of such conduct causes or is likely to cause death or injuries to persons or damage to or destruction of property or disrupts or knowing that it is…"}, "it-act-2000:sec_66F__subsec_1": {"cite": "IT Act s.66F(1)", "head": "", "text": "Whoever,— (A4) with intent to threaten the unity, integrity, security or sovereignty of India or to strike terror in the people or any section of the people by-- denying or cause the denial of access to any person authorised to access computer resource; or (ii) attempting to penetrate or access a computer resource without authorisation or exceeding authorised access; or (ii) introducing or causing to introduce any computer contaminant, and by means of such conduct causes or is likely to cause death or injuries to persons or damage to or destruction of property or disrupts or knowing that it is…"}, "it-act-2000:sec_66F__subsec_1__subsec_1": {"cite": "IT Act s.66F(1)(1)", "head": "", "text": "denying or cause the denial of access to any person authorised to access computer resource; or (ii) attempting to penetrate or access a computer resource without authorisation or exceeding authorised access; or (ii) introducing or causing to introduce any computer contaminant, and by means of such conduct causes or is likely to cause death or injuries to persons or damage to or destruction of property or disrupts or knowing that it is likely to cause damage or disruption of supplies or services essential to the life of the community or adversely affect the critical information infrastructure s…"}, "it-act-2000:sec_66F__subsec_1__subsec_2": {"cite": "IT Act s.66F(1)(2)", "head": "", "text": "Whoever commits or conspires to commit cyber terrorism shall be punishable with imprisonment which may extend to imprisonment for life."}, "it-act-2000:sec_67": {"cite": "IT Act s.67", "head": "Punishment for publishing or transmitting obscene material in electronic form", "text": "Whoever publishes or transmits or causes to be published or transmitted in the electronic form, any material which is lascivious or appeals to the prurient interest or if its effect is such as to tend to deprave and corrupt persons who are likely, having regard to all relevant circumstances, to read, see or hear the matter contained or embodied in it, shall be punished on first conviction with imprisonment of either description for a term which may extend to three years and with fine which may extend to five lakh rupees and in the event of second or subsequent conviction with imprisonment of e…"}, "it-act-2000:sec_67A": {"cite": "IT Act s.67A", "head": "Punishment for publishing or transmitting of material containing sexually explicit act, etc., in electronic form", "text": "Whoever publishes or transmits or causes to be published or transmitted in the electronic form any material which contains sexually explicit act or conduct shall be punished on first conviction with imprisonment of either description for a term which may extend to five years and with fine which may extend to ten lakh rupees and in the event of second or subsequent conviction with imprisonment of either description for a term which may extend to seven years and also with fine which may extend to ten lakh rupees."}, "it-act-2000:sec_67B": {"cite": "IT Act s.67B", "head": "Punishment for publishing or transmitting of material depicting children in sexually explicit act, etc., in electronic form", "text": "Whoever, publishes or transmits or causes to be published or transmitted material in any electronic form which depicts children engaged in sexually explicit act or conduct; or creates text or digital images, collects, seeks, browses, downloads, advertises, promotes, exchanges or distributes material in any electronic form depicting children in obscene or indecent or sexually explicit manner; or cultivates, entices or induces children to online relationship with one or more children for and on sexually explicit act or in a manner that may offend a reasonable adult on the computer resource; or f…"}, "it-act-2000:sec_67B__cl_a": {"cite": "IT Act s.67B(a)", "head": "", "text": "publishes or transmits or causes to be published or transmitted material in any electronic form which depicts children engaged in sexually explicit act or conduct;"}, "it-act-2000:sec_67B__wrap_1": {"cite": "IT Act s.67B", "head": "", "text": "or"}, "it-act-2000:sec_67B__cl_b": {"cite": "IT Act s.67B(b)", "head": "", "text": "creates text or digital images, collects, seeks, browses, downloads, advertises, promotes, exchanges or distributes material in any electronic form depicting children in obscene or indecent or sexually explicit manner; or"}, "it-act-2000:sec_67B__cl_c": {"cite": "IT Act s.67B(c)", "head": "", "text": "cultivates, entices or induces children to online relationship with one or more children for and on sexually explicit act or in a manner that may offend a reasonable adult on the computer resource; or"}, "it-act-2000:sec_67B__cl_d": {"cite": "IT Act s.67B(d)", "head": "", "text": "facilitates abusing children online; or"}, "it-act-2000:sec_67B__cl_e": {"cite": "IT Act s.67B(e)", "head": "", "text": "records in any electronic form own abuse or that of others pertaining to sexually explicit act with children, shall be punished on first conviction with imprisonment of either description for a term which may extend to five years and with fine which may extend to ten lakh rupees and in the event of second or subsequent conviction with imprisonment of either discription for a term which may extend to seven years and also with fine which may extend to ten lakh rupees: Provided that provisions of section 67, section 67A and this section does not extend to any book, pamphlet, paper, writing, drawi…"}, "it-act-2000:sec_67B__cl_e__proviso_1": {"cite": "IT Act s.67B(e)", "head": "", "text": "Provided that provisions of section 67, section 67A and this section does not extend to any book, pamphlet, paper, writing, drawing, painting representation or figure in electronic form— the publication of which is proved to be justified as being for the public good on the ground that such book, pamphlet, paper, writing, drawing, painting representation or figure is in the interest of science, literature, art or learning or other objects of general concern; or (ii) which is kept or used for bona fide heritage or religious purposes."}, "it-act-2000:sec_67B__cl_e__proviso_1__subsec_1": {"cite": "IT Act s.67B(e)(1)", "head": "", "text": "the publication of which is proved to be justified as being for the public good on the ground that such book, pamphlet, paper, writing, drawing, painting representation or figure is in the interest of science, literature, art or learning or other objects of general concern; or (ii) which is kept or used for bona fide heritage or religious purposes."}, "it-act-2000:sec_67B__hcontainer_1": {"cite": "IT Act s.67B", "head": "", "text": "For the purposes of this section, “children” means a person who has not completed the age of 18 years."}, "it-act-2000:sec_67C": {"cite": "IT Act s.67C", "head": "Preservation and retention of information by intermediaries", "text": "Intermediary shall preserve and retain such information as may be specified for such duration and in such manner and format as the Central Government may prescribe. Any intermediary who intentionally or knowingly contravenes the provisions of sub-section (1) shall be liable to penalty which may extend to twenty-five lakh rupees."}, "it-act-2000:sec_67C__subsec_1": {"cite": "IT Act s.67C(1)", "head": "", "text": "Intermediary shall preserve and retain such information as may be specified for such duration and in such manner and format as the Central Government may prescribe."}, "it-act-2000:sec_67C__subsec_2": {"cite": "IT Act s.67C(2)", "head": "", "text": "Any intermediary who intentionally or knowingly contravenes the provisions of sub-section (1) shall be liable to penalty which may extend to twenty-five lakh rupees."}, "it-act-2000:sec_68": {"cite": "IT Act s.68", "head": "Power of Controller to give directions", "text": "The Controller may, by order, direct a Certifying Authority or any employee of such Authority to take such measures or cease carrying on such activities as specified in the order if those are necessary to ensure compliance with the provisions of this Act, rules or any regulations made thereunder. Any person who intentionally or knowingly fails to comply with any order under sub-section (1) shall be guilty of an offence and shall be liable to penalty which may extend to twenty-five lakh rupees."}, "it-act-2000:sec_68__subsec_1": {"cite": "IT Act s.68(1)", "head": "", "text": "The Controller may, by order, direct a Certifying Authority or any employee of such Authority to take such measures or cease carrying on such activities as specified in the order if those are necessary to ensure compliance with the provisions of this Act, rules or any regulations made thereunder."}, "it-act-2000:sec_68__subsec_2": {"cite": "IT Act s.68(2)", "head": "", "text": "Any person who intentionally or knowingly fails to comply with any order under sub-section (1) shall be guilty of an offence and shall be liable to penalty which may extend to twenty-five lakh rupees."}, "it-act-2000:sec_69": {"cite": "IT Act s.69", "head": "Power to issue directions for interception or monitoring or decryption of any information through any computer resource", "text": "Where the Central Government or a State Government or any of its officers specially authorised by the Central Government or the State Government, as the case may be, in this behalf may, if satisfied that it is necessary or expedient so to do, in the interest of the sovereignty or integrity of India, defence of India, security of the State, friendly relations with foreign States or public order or for preventing incitement to the commission of any cognizable offence relating to above or for investigation of any offence, it may subject to the provisions of sub-section (2), for reasons to be reco…"}, "it-act-2000:sec_69__subsec_1": {"cite": "IT Act s.69(1)", "head": "", "text": "Where the Central Government or a State Government or any of its officers specially authorised by the Central Government or the State Government, as the case may be, in this behalf may, if satisfied that it is necessary or expedient so to do, in the interest of the sovereignty or integrity of India, defence of India, security of the State, friendly relations with foreign States or public order or for preventing incitement to the commission of any cognizable offence relating to above or for investigation of any offence, it may subject to the provisions of sub-section (2), for reasons to be reco…"}, "it-act-2000:sec_69__subsec_2": {"cite": "IT Act s.69(2)", "head": "", "text": "The procedure and safeguards subject to which such interception or monitoring or decryption may be carried out, shall be such as may be prescribed."}, "it-act-2000:sec_69__subsec_3": {"cite": "IT Act s.69(3)", "head": "", "text": "The subscriber or intermediary or any person in-charge of the computer resource shall, when called upon by any agency referred to in sub-section (1), extend all facilities and technical assistance to— provide access to or secure access to the computer resource generating, transmitting, receiving or storing such information; or intercept, monitor, or decrypt the information, as the case may be; or provide information stored in computer resource."}, "it-act-2000:sec_69__subsec_3__cl_a": {"cite": "IT Act s.69(3)(a)", "head": "", "text": "provide access to or secure access to the computer resource generating, transmitting, receiving or storing such information; or"}, "it-act-2000:sec_69__subsec_3__cl_b": {"cite": "IT Act s.69(3)(b)", "head": "", "text": "intercept, monitor, or decrypt the information, as the case may be; or"}, "it-act-2000:sec_69__subsec_3__cl_c": {"cite": "IT Act s.69(3)(c)", "head": "", "text": "provide information stored in computer resource."}, "it-act-2000:sec_69__subsec_4": {"cite": "IT Act s.69(4)", "head": "", "text": "The subscriber or intermediary or any person who fails to assist the agency referred to in sub-section (3) shall be punished with imprisonment for a term which may extend to seven years and shall also be liable to fine."}, "it-act-2000:sec_69A": {"cite": "IT Act s.69A", "head": "Power to issue directions for blocking for public access of any information through any computer resource", "text": "Where the Central Government or any of its officers specially authorised by it in this behalf is satisfied that it is necessary or expedient so to do, in the interest of sovereignty and integrity of India, defence of India, security of the State, friendly relations with foreign States or public order or for preventing incitement to the commission of any cognizable offence relating to above, it may subject to the provisions of sub-section (2), for reasons to be recorded in writing, by order, direct any agency of the Government or intermediary to block for access by the public or cause to be blo…"}, "it-act-2000:sec_69A__subsec_1": {"cite": "IT Act s.69A(1)", "head": "", "text": "Where the Central Government or any of its officers specially authorised by it in this behalf is satisfied that it is necessary or expedient so to do, in the interest of sovereignty and integrity of India, defence of India, security of the State, friendly relations with foreign States or public order or for preventing incitement to the commission of any cognizable offence relating to above, it may subject to the provisions of sub-section (2), for reasons to be recorded in writing, by order, direct any agency of the Government or intermediary to block for access by the public or cause to be blo…"}, "it-act-2000:sec_69A__subsec_2": {"cite": "IT Act s.69A(2)", "head": "", "text": "The procedure and safeguards subject to which such blocking for access by the public may be carried out, shall be such as may be prescribed."}, "it-act-2000:sec_69A__subsec_3": {"cite": "IT Act s.69A(3)", "head": "", "text": "The intermediary who fails to comply with the direction issued under sub-section (1) shall be punished with an imprisonment for a term which may extend to seven years and shall also be liable to fine."}, "it-act-2000:sec_69B": {"cite": "IT Act s.69B", "head": "Power to authorise to monitor and collect traffic data or information through any computer resource for cyber security", "text": "The Central Government may, to enhance cyber security and for identification, analysis and prevention of intrusion or spread of computer contaminant in the country, by notification in the Official Gazette, authorise any agency of the Government to monitor and collect traffic data or information generated, transmitted, received or stored in any computer resource. The intermediary or any person in-charge or the computer resource shall, when called upon by the agency which has been authorised under sub-section (1), provide technical assistance and extend all facilities to such agency to enable on…"}, "it-act-2000:sec_69B__subsec_1": {"cite": "IT Act s.69B(1)", "head": "", "text": "The Central Government may, to enhance cyber security and for identification, analysis and prevention of intrusion or spread of computer contaminant in the country, by notification in the Official Gazette, authorise any agency of the Government to monitor and collect traffic data or information generated, transmitted, received or stored in any computer resource."}, "it-act-2000:sec_69B__subsec_2": {"cite": "IT Act s.69B(2)", "head": "", "text": "The intermediary or any person in-charge or the computer resource shall, when called upon by the agency which has been authorised under sub-section (1), provide technical assistance and extend all facilities to such agency to enable online access or to secure and provide online access to the computer resource generating, transmitting, receiving or storing such traffic data or information."}, "it-act-2000:sec_69B__subsec_3": {"cite": "IT Act s.69B(3)", "head": "", "text": "The procedure and safeguards for monitoring and collecting traffic data or information, shall be such as may be prescribed."}, "it-act-2000:sec_69B__subsec_4": {"cite": "IT Act s.69B(4)", "head": "", "text": "Any intermediary who intentionally or knowingly contravenes the provisions of sub-section (2) shall be punished with an imprisonment for a term which any extend to one year or shall be liable to fine which may extend to one crore rupees, or with both."}, "it-act-2000:sec_69B__hcontainer_1": {"cite": "IT Act s.69B", "head": "", "text": "For the purposes of this section, (f) “computer contaminant” shall have the meaning assigned to it in section 43; “traffic data” means any data identifying or purporting to identify any person, computer system or computer network or location to or from which the communication is or may be transmitted and includes communications origin, destination, route, time, date, size, duration or type of underlying service and any other information."}, "it-act-2000:sec_69B__hcontainer_1__subcl_i": {"cite": "IT Act s.69B(i)", "head": "", "text": "“traffic data” means any data identifying or purporting to identify any person, computer system or computer network or location to or from which the communication is or may be transmitted and includes communications origin, destination, route, time, date, size, duration or type of underlying service and any other information."}, "it-act-2000:sec_70": {"cite": "IT Act s.70", "head": "Protected system", "text": "The appropriate Government may, by notification in the Official Gazette, declare any computer resource which directly or indirectly affects the facility of Critical Information Infrastructure, to be a protected system. For the purposes of this section, “Critical Information Infrastructure” means the computer resource, the incapacitation or destruction of which, shall have debilitating impact on national security, economy, public health or safety. The appropriate Government may, by order in writing, authorise the persons who are authorised to access protected systems notified under sub-section …"}, "it-act-2000:sec_70__subsec_1": {"cite": "IT Act s.70(1)", "head": "", "text": "The appropriate Government may, by notification in the Official Gazette, declare any computer resource which directly or indirectly affects the facility of Critical Information Infrastructure, to be a protected system."}, "it-act-2000:sec_70__hcontainer_1": {"cite": "IT Act s.70", "head": "", "text": "For the purposes of this section, “Critical Information Infrastructure” means the computer resource, the incapacitation or destruction of which, shall have debilitating impact on national security, economy, public health or safety."}, "it-act-2000:sec_70__subsec_2": {"cite": "IT Act s.70(2)", "head": "", "text": "The appropriate Government may, by order in writing, authorise the persons who are authorised to access protected systems notified under sub-section (1)."}, "it-act-2000:sec_70__subsec_3": {"cite": "IT Act s.70(3)", "head": "", "text": "Any person who secures access or attempts to secure access to a protected system in contravention of the provisions of this section shall be punished with imprisonment of either description for a term which may extend to ten years and shall also be liable to fine."}, "it-act-2000:sec_70__subsec_4": {"cite": "IT Act s.70(4)", "head": "", "text": "The Central Government shall prescribe the information security practices and procedures for such protected system."}, "it-act-2000:sec_70A": {"cite": "IT Act s.70A", "head": "National nodal agency", "text": "The Central Government may, by notification published in the Official Gazette, designate any organisation of the Government as the national nodal agency in respect of Critical Information Infrastructure Protection. The national nodal agency designated under sub-section (1) shall be responsible for all measures including Research and Development relating to protection of Critical Information Infrastructure. The manner of performing functions and duties of the agency referred to in sub-section (1) shall be such as may be prescribed."}, "it-act-2000:sec_70A__subsec_1": {"cite": "IT Act s.70A(1)", "head": "", "text": "The Central Government may, by notification published in the Official Gazette, designate any organisation of the Government as the national nodal agency in respect of Critical Information Infrastructure Protection."}, "it-act-2000:sec_70A__subsec_2": {"cite": "IT Act s.70A(2)", "head": "", "text": "The national nodal agency designated under sub-section (1) shall be responsible for all measures including Research and Development relating to protection of Critical Information Infrastructure."}, "it-act-2000:sec_70A__subsec_3": {"cite": "IT Act s.70A(3)", "head": "", "text": "The manner of performing functions and duties of the agency referred to in sub-section (1) shall be such as may be prescribed."}, "it-act-2000:sec_70B": {"cite": "IT Act s.70B", "head": "Indian Computer Emergency Response Team to serve as national agency for incident response", "text": "The Central Government shall, by notification in the Official Gazette, appoint an agency of the Government to be called the Indian Computer Emergency Response Team. The Centra! Government shall provide the agency referred to in sub-section (1) with a Director-General and such other officers and employees as may be prescribed. The salary and allowances and terms and conditions of the Director-General and other officers and employees shall be such as may be prescribed. The Indian Computer Emergency Response Team shall serve as the national agency for performing the following functions in the are…"}, "it-act-2000:sec_70B__subsec_1": {"cite": "IT Act s.70B(1)", "head": "", "text": "The Central Government shall, by notification in the Official Gazette, appoint an agency of the Government to be called the Indian Computer Emergency Response Team."}, "it-act-2000:sec_70B__subsec_2": {"cite": "IT Act s.70B(2)", "head": "", "text": "The Centra! Government shall provide the agency referred to in sub-section (1) with a Director-General and such other officers and employees as may be prescribed."}, "it-act-2000:sec_70B__subsec_3": {"cite": "IT Act s.70B(3)", "head": "", "text": "The salary and allowances and terms and conditions of the Director-General and other officers and employees shall be such as may be prescribed."}, "it-act-2000:sec_70B__subsec_4": {"cite": "IT Act s.70B(4)", "head": "", "text": "The Indian Computer Emergency Response Team shall serve as the national agency for performing the following functions in the area of cyber security, collection, analysis and dissemination of information on cyber incidents; forecast and alerts of cyber security incidents; emergency measures for handling cyber security incidents; coordination of cyber incidents response activities; issue guidelines, advisories, vulnerability notes and whitepapers relating to information security practices, procedures, preventation, response and reporting of cyber incidents; such other functions relating to cyber…"}, "it-act-2000:sec_70B__subsec_4__cl_a": {"cite": "IT Act s.70B(4)(a)", "head": "", "text": "collection, analysis and dissemination of information on cyber incidents;"}, "it-act-2000:sec_70B__subsec_4__cl_b": {"cite": "IT Act s.70B(4)(b)", "head": "", "text": "forecast and alerts of cyber security incidents;"}, "it-act-2000:sec_70B__subsec_4__cl_c": {"cite": "IT Act s.70B(4)(c)", "head": "", "text": "emergency measures for handling cyber security incidents;"}, "it-act-2000:sec_70B__subsec_4__cl_d": {"cite": "IT Act s.70B(4)(d)", "head": "", "text": "coordination of cyber incidents response activities;"}, "it-act-2000:sec_70B__subsec_4__cl_e": {"cite": "IT Act s.70B(4)(e)", "head": "", "text": "issue guidelines, advisories, vulnerability notes and whitepapers relating to information security practices, procedures, preventation, response and reporting of cyber incidents;"}, "it-act-2000:sec_70B__subsec_4__cl_f": {"cite": "IT Act s.70B(4)(f)", "head": "", "text": "such other functions relating to cyber security as may be prescribed."}, "it-act-2000:sec_70B__subsec_5": {"cite": "IT Act s.70B(5)", "head": "", "text": "The manner of performing functions and duties of the agency referred to in sub-section (1) shall be such as may be prescribed."}, "it-act-2000:sec_70B__subsec_6": {"cite": "IT Act s.70B(6)", "head": "", "text": "For carrying out the provisions of sub-section (4), the agency referred to in sub-section (1) may call for information and give direction to the service providers, intermediaries, data centres, body corporate and any other person."}, "it-act-2000:sec_70B__subsec_7": {"cite": "IT Act s.70B(7)", "head": "", "text": "Any service provider, intermediaries, data centres, body corporate or person who fails to provide the information called for or comply with the direction under sub-section (6), shall be punishable with imprisonment for a term which may extend to one year or with fine which may extend to one crore rupees or with both."}, "it-act-2000:sec_70B__subsec_8": {"cite": "IT Act s.70B(8)", "head": "", "text": "No court shall take cognizance of any offence under this section, except on a complaint made by an officer authorised in this behalf by the agency referred to in sub-section (1)."}, "it-act-2000:sec_71": {"cite": "IT Act s.71", "head": "Penalty for misrepresentation", "text": "Whoever makes any misrepresentation to, or suppresses any material fact from, the Controller or the Certifying Authority for obtaining any licence or Electronic signature Certificate, as the case may be, shall be punished with imprisonment for a term which may extend to two years, or with fine which may extend to one lakh rupees, or with both."}, "it-act-2000:sec_72": {"cite": "IT Act s.72", "head": "Penalty for breach of confidentiality and privacy", "text": "Save as otherwise provided in this Act or any other law for the time being in force, any person who, in pursuance of any of the powers conferred under this Act, rules or regulations made thereunder, has secured access to any electronic record, book, register, correspondence, information, document or other material without the consent of the person concerned discloses such electronic record, book, register, correspondence, information, document or other material to any other person shall be liable to penalty which may extend to five lakh rupees."}, "it-act-2000:sec_72A": {"cite": "IT Act s.72A", "head": "Penalty for disclosure of information in breach of lawful contract", "text": "Save as otherwise provided in this Act or any other law for the time being in force, any person including an intermediary who, while providing services under the terms of lawful contract, has secured access to any material containing personal information about another person, with the intent to cause or knowing that he is likely to cause wrongful loss or wrongful gain discloses, without the consent of the person concerned, or in breach of a lawful contract, such material to any other person, shall be liable to penalty which may extend to twenty-five lakh rupees."}, "it-act-2000:sec_73": {"cite": "IT Act s.73", "head": "Penalty for publishing Electronic signature Certificate false in certain particulars", "text": "No person shall publish a Electronic signature Certificate or otherwise make it available to any other person with the knowledge that— the Certifying Authority listed in the certificate has not issued it; or the subscriber listed in the certificate has not accepted it; or the certificate has been revoked or suspended, unless such publication is for the purpose of verifying a electronic signature created prior to such suspension or revocation. Any person who contravenes the provisions of sub-section (1) shall be punished with imprisonment for a term which may extend to two years, or with fine w…"}, "it-act-2000:sec_73__subsec_1": {"cite": "IT Act s.73(1)", "head": "", "text": "No person shall publish a Electronic signature Certificate or otherwise make it available to any other person with the knowledge that— the Certifying Authority listed in the certificate has not issued it; or the subscriber listed in the certificate has not accepted it; or the certificate has been revoked or suspended, unless such publication is for the purpose of verifying a electronic signature created prior to such suspension or revocation."}, "it-act-2000:sec_73__subsec_1__cl_a": {"cite": "IT Act s.73(1)(a)", "head": "", "text": "the Certifying Authority listed in the certificate has not issued it; or"}, "it-act-2000:sec_73__subsec_1__cl_b": {"cite": "IT Act s.73(1)(b)", "head": "", "text": "the subscriber listed in the certificate has not accepted it; or"}, "it-act-2000:sec_73__subsec_1__cl_c": {"cite": "IT Act s.73(1)(c)", "head": "", "text": "the certificate has been revoked or suspended,"}, "it-act-2000:sec_73__subsec_2": {"cite": "IT Act s.73(2)", "head": "", "text": "Any person who contravenes the provisions of sub-section (1) shall be punished with imprisonment for a term which may extend to two years, or with fine which may extend to one lakh rupees, or with both."}, "it-act-2000:sec_74": {"cite": "IT Act s.74", "head": "Publication for fraudulent purpose", "text": "Whoever knowingly creates, publishes or otherwise makes available a Electronic signature Certificate for any fraudulent or unlawful purpose shall be punished with imprisonment for a term which may extend to two years, or with fine which may extend to one lakh rupees, or with both."}, "it-act-2000:sec_75": {"cite": "IT Act s.75", "head": "Act to apply for offence or contravention committed outside India", "text": "Subject to the provisions of sub-section (2), the provisions of this Act shall apply also to any offence or contravention committed outside India by any person irrespective of his nationality. For the purposes of sub-section (1), this Act shall apply to an offence or contravention committed outside India by any person if the act or conduct constituting the offence or contravention involves a computer, computer system or computer network located in India."}, "it-act-2000:sec_75__subsec_1": {"cite": "IT Act s.75(1)", "head": "", "text": "Subject to the provisions of sub-section (2), the provisions of this Act shall apply also to any offence or contravention committed outside India by any person irrespective of his nationality."}, "it-act-2000:sec_75__subsec_2": {"cite": "IT Act s.75(2)", "head": "", "text": "For the purposes of sub-section (1), this Act shall apply to an offence or contravention committed outside India by any person if the act or conduct constituting the offence or contravention involves a computer, computer system or computer network located in India."}, "it-act-2000:sec_76": {"cite": "IT Act s.76", "head": "Confiscation", "text": "Any computer, computer system, floppies, compact disks, tape drives or any other accessories related thereto, in respect of which, any provision of this Act, rules, orders or regulations made thereunder has been or is being contravened, shall be liable to confiscation: Provided that where it is established to the satisfaction of the court adjudicating the confiscation that the person in whose possession, power or control of any such computer, computer system, floppies, compact disks, tape drives or any other accessories relating thereto is found is not responsible for the contravention of the …"}, "it-act-2000:sec_76__proviso_1": {"cite": "IT Act s.76", "head": "", "text": "Provided that where it is established to the satisfaction of the court adjudicating the confiscation that the person in whose possession, power or control of any such computer, computer system, floppies, compact disks, tape drives or any other accessories relating thereto is found is not responsible for the contravention of the provisions of this Act, rules, orders or regulations made thereunder, the court may, instead of making an order for confiscation of such computer, computer system, floppies, compact disks, tape drives or any other accessories related thereto, make such other order autho…"}, "it-act-2000:sec_77": {"cite": "IT Act s.77", "head": "Compensation, penalties or confiscation not to interfere with other punishment", "text": "No compensation awarded, penalty imposed or confiscation made under this Act shall prevent the award of compensation or imposition of any other penalty or punishment under any other law for the time being in force."}, "it-act-2000:sec_77A": {"cite": "IT Act s.77A", "head": "Compounding of offences", "text": "A court of competent jurisdiction may compound offences, other than offences for which the punishment for life or imprisonment for a term exceeding three years has been provided, under this Act: Provided that the court shall not compound such offence where the accused is, by reason of his previous conviction, liable to either enhanced punishment or to a punishment of a different kind: Provided further that the court shall not compound any offence where such offence affects the socio economic conditions of the country or has been committed against a child below the age of 18 years or a woman. T…"}, "it-act-2000:sec_77A__proviso_1": {"cite": "IT Act s.77A", "head": "", "text": "Provided that the court shall not compound such offence where the accused is, by reason of his previous conviction, liable to either enhanced punishment or to a punishment of a different kind:"}, "it-act-2000:sec_77A__proviso_2": {"cite": "IT Act s.77A", "head": "", "text": "Provided further that the court shall not compound any offence where such offence affects the socio economic conditions of the country or has been committed against a child below the age of 18 years or a woman."}, "it-act-2000:sec_77A__subsec_2": {"cite": "IT Act s.77A(2)", "head": "", "text": "The person accused of an offence under this Act may file an application for compounding in the court in which offence is pending for trial and the provisions of 2 of 1974. sections 265B and 265C of the Code of Criminal Procedure, 1973 shall apply."}, "it-act-2000:sec_77B": {"cite": "IT Act s.77B", "head": "Offences with three years imprisonment to be bailable", "text": "Notwithstanding anything contained in the Code of Criminal Procedure, 2 of 1974. 1973, the offence punishable with imprisonment of three years and above shall be cognizable and the offence punishable with imprisonment of three years shall be bailable."}, "it-act-2000:sec_78": {"cite": "IT Act s.78", "head": "Power to investigate offences", "text": "Notwithstanding anything contained in the Code of Criminal Procedure, 1973, a police officer not below the rank of Inspector shall investigate any offence under this Act."}, "it-act-2000:chp_XII": {"cite": "IT Act Chapter XII", "head": "İNTERMEDIARIES NOT TO BE LLABLE IN CERTAIN CASES", "text": "Exemption from liability of intermediary in certain cases Notwithstanding anything contained in any law for the time being in force but subject to the provisions of sub-sections (2) and (3), an intermediary shall not be liable for any third party information, data, or communication link made available or hosted by him. The provisions of sub-section (1) shall apply if - the function of the intermediary is limited to providing access to a communication system over which information made available by third parties is transmitted or temporarily stored or hosted; or the intermediary docs not— initi…"}, "it-act-2000:sec_79": {"cite": "IT Act s.79", "head": "Exemption from liability of intermediary in certain cases", "text": "Notwithstanding anything contained in any law for the time being in force but subject to the provisions of sub-sections (2) and (3), an intermediary shall not be liable for any third party information, data, or communication link made available or hosted by him. The provisions of sub-section (1) shall apply if - the function of the intermediary is limited to providing access to a communication system over which information made available by third parties is transmitted or temporarily stored or hosted; or the intermediary docs not— initiate the transmission, select the receiver of the transmiss…"}, "it-act-2000:sec_79__subsec_1": {"cite": "IT Act s.79(1)", "head": "", "text": "Notwithstanding anything contained in any law for the time being in force but subject to the provisions of sub-sections (2) and (3), an intermediary shall not be liable for any third party information, data, or communication link made available or hosted by him."}, "it-act-2000:sec_79__subsec_2": {"cite": "IT Act s.79(2)", "head": "", "text": "The provisions of sub-section (1) shall apply if - the function of the intermediary is limited to providing access to a communication system over which information made available by third parties is transmitted or temporarily stored or hosted; or the intermediary docs not— initiate the transmission, select the receiver of the transmission, and select or modify the information contained in the transmission; the intermediary observes due diligence while discharging his duties under this Act and also observes such other guidelines as the Central Government may prescribe in this behalf."}, "it-act-2000:sec_79__subsec_2__cl_a": {"cite": "IT Act s.79(2)(a)", "head": "", "text": "the function of the intermediary is limited to providing access to a communication system over which information made available by third parties is transmitted or temporarily stored or hosted; or"}, "it-act-2000:sec_79__subsec_2__cl_b": {"cite": "IT Act s.79(2)(b)", "head": "", "text": "the intermediary docs not— initiate the transmission, select the receiver of the transmission, and select or modify the information contained in the transmission;"}, "it-act-2000:sec_79__subsec_2__cl_b__subcl_i": {"cite": "IT Act s.79(2)(b)(i)", "head": "", "text": "initiate the transmission,"}, "it-act-2000:sec_79__subsec_2__cl_b__subcl_ii": {"cite": "IT Act s.79(2)(b)(ii)", "head": "", "text": "select the receiver of the transmission, and"}, "it-act-2000:sec_79__subsec_2__cl_b__subcl_iii": {"cite": "IT Act s.79(2)(b)(iii)", "head": "", "text": "select or modify the information contained in the transmission;"}, "it-act-2000:sec_79__subsec_2__cl_c": {"cite": "IT Act s.79(2)(c)", "head": "", "text": "the intermediary observes due diligence while discharging his duties under this Act and also observes such other guidelines as the Central Government may prescribe in this behalf."}, "it-act-2000:sec_79__subsec_3": {"cite": "IT Act s.79(3)", "head": "", "text": "The provisions of sub-section (1) shall not apply if- the intermediary has conspired or abetted or aided or induced, whether by threats or promise or otherwise in the commission of the unlawful act; upon receiving actual knowledge, or on being notified by the appropriate Government or its agency that any information, data or communication link residing in or connected to a computer resource controlled by the intermediary is being used to commit the unlawful act, the intermediary fails to expeditiously remove or disable access to that material on that resource without vitiating the evidence in …"}, "it-act-2000:sec_79__subsec_3__cl_a": {"cite": "IT Act s.79(3)(a)", "head": "", "text": "the intermediary has conspired or abetted or aided or induced, whether by threats or promise or otherwise in the commission of the unlawful act;"}, "it-act-2000:sec_79__subsec_3__cl_b": {"cite": "IT Act s.79(3)(b)", "head": "", "text": "upon receiving actual knowledge, or on being notified by the appropriate Government or its agency that any information, data or communication link residing in or connected to a computer resource controlled by the intermediary is being used to commit the unlawful act, the intermediary fails to expeditiously remove or disable access to that material on that resource without vitiating the evidence in any manner."}, "it-act-2000:sec_79__hcontainer_1": {"cite": "IT Act s.79", "head": "", "text": "For the purposes of this section, the expression “third party information” means any information dealt with by an intermediary in his capacity as an intermediary."}, "it-act-2000:chp_XIIA": {"cite": "IT Act Chapter XIIA", "head": "EXAMINER OF ELECTRONIC EVIDENCE", "text": "Central Government to notify Examiner of Electronic Evidence The Central Government may, for the purposes of providing expert opinion on electronic form evidence before any court or other authority specify, by notification in the Official Gazette, any Department, body or agency of the Central Government or a State Government as an Examiner of Electronic Evidence. For the purposes of this section, “electronic form evidence” means any information of probative value that is either stored or transmitted in electronic form and includes computer evidence, digital audio, digital video, cell phones, d…"}, "it-act-2000:sec_79A": {"cite": "IT Act s.79A", "head": "Central Government to notify Examiner of Electronic Evidence", "text": "The Central Government may, for the purposes of providing expert opinion on electronic form evidence before any court or other authority specify, by notification in the Official Gazette, any Department, body or agency of the Central Government or a State Government as an Examiner of Electronic Evidence. For the purposes of this section, “electronic form evidence” means any information of probative value that is either stored or transmitted in electronic form and includes computer evidence, digital audio, digital video, cell phones, digital fax machines."}, "it-act-2000:sec_79A__hcontainer_1": {"cite": "IT Act s.79A", "head": "", "text": "For the purposes of this section, “electronic form evidence” means any information of probative value that is either stored or transmitted in electronic form and includes computer evidence, digital audio, digital video, cell phones, digital fax machines."}, "it-act-2000:chp_XIII": {"cite": "IT Act Chapter XIII", "head": "MISCELLANEOUS", "text": "Power of police officer and other officers to enter, search, etc. Notwithstanding anything contained in the Code of Criminal Procedure, 1973, any police officer, not below the rank of a Inspector, or any other officer of the Central Government or a State Government authorised by the Central Government in this behalf may enter any public place and search and arrest without warrant any person found therein who is reasonably suspected or having committed or of committing or of being about to commit any offence under this Act. For the purposes of this sub-section, the expression \"public place\" inc…"}, "it-act-2000:sec_80": {"cite": "IT Act s.80", "head": "Power of police officer and other officers to enter, search, etc.", "text": "Notwithstanding anything contained in the Code of Criminal Procedure, 1973, any police officer, not below the rank of a Inspector, or any other officer of the Central Government or a State Government authorised by the Central Government in this behalf may enter any public place and search and arrest without warrant any person found therein who is reasonably suspected or having committed or of committing or of being about to commit any offence under this Act. For the purposes of this sub-section, the expression \"public place\" includes any public conveyance, any hotel, any shop or any other plac…"}, "it-act-2000:sec_80__subsec_1": {"cite": "IT Act s.80(1)", "head": "", "text": "Notwithstanding anything contained in the Code of Criminal Procedure, 1973, any police officer, not below the rank of a Inspector, or any other officer of the Central Government or a State Government authorised by the Central Government in this behalf may enter any public place and search and arrest without warrant any person found therein who is reasonably suspected or having committed or of committing or of being about to commit any offence under this Act. For the purposes of this sub-section, the expression \"public place\" includes any public conveyance, any hotel, any shop or any other plac…"}, "it-act-2000:sec_80__subsec_1__hcontainer_1": {"cite": "IT Act s.80(1)", "head": "", "text": "For the purposes of this sub-section, the expression \"public place\" includes any public conveyance, any hotel, any shop or any other place intended for use by, or accessible to the public."}, "it-act-2000:sec_80__subsec_2": {"cite": "IT Act s.80(2)", "head": "", "text": "Where any person is arrested under sub-section (1) by an officer other than a police officer, such officer shall, without unnecessary delay, take or send the person arrested before a magistrate having jurisdiction in the case or before the officer-in-charge of a police station."}, "it-act-2000:sec_80__subsec_3": {"cite": "IT Act s.80(3)", "head": "", "text": "The provisions of the Code of Criminal Procedure, 1973 shall, subject to the provisions of this section, apply, so far as may be, in relation to any entry, search or arrest, made under this section."}, "it-act-2000:sec_81": {"cite": "IT Act s.81", "head": "Act to have overriding effect", "text": "The provisions of this Act shall have effect notwithstanding anything inconsistent therewith contained in any other law for the time being in force. Provided that nothing contained in this Act shall restrict any person from exercising any right conferred under the CopyrightAct, 1957 or the Patents Act, 1970.”. 14 of 1957. 39 of 1970."}, "it-act-2000:sec_81__proviso_1": {"cite": "IT Act s.81", "head": "", "text": "Provided that nothing contained in this Act shall restrict any person from exercising any right conferred under the CopyrightAct, 1957 or the Patents Act, 1970.”. 14 of 1957. 39 of 1970."}, "it-act-2000:sec_81A": {"cite": "IT Act s.81A", "head": "Application of the Act to electronic cheque and truncated cheque", "text": "The provisions of this Act, for the time being in force, shall apply to, or in relation to, electronic cheques and the truncated cheques subject to such modifications and amendments as may be necessary for carrying out the purposes of the Negotiable Instruments Act, 1881 by the Central Government, in consultation with the Reserve Bank of India, by notification in the Official Gazette. Every notification made by the Central Government under sub-section (1) shall be laid, as soon as may be after it is made, before each House of Parliament, while it is in session, for a total period of thirty day…"}, "it-act-2000:sec_81A__subsec_1": {"cite": "IT Act s.81A(1)", "head": "", "text": "The provisions of this Act, for the time being in force, shall apply to, or in relation to, electronic cheques and the truncated cheques subject to such modifications and amendments as may be necessary for carrying out the purposes of the Negotiable Instruments Act, 1881 by the Central Government, in consultation with the Reserve Bank of India, by notification in the Official Gazette."}, "it-act-2000:sec_81A__subsec_2": {"cite": "IT Act s.81A(2)", "head": "", "text": "Every notification made by the Central Government under sub-section (1) shall be laid, as soon as may be after it is made, before each House of Parliament, while it is in session, for a total period of thirty days which may be comprised in one session or in two or more successive sessions, and if, before the expiry of the session immediately following the session or the successive sessions aforesaid, both Houses agree in making any modification in the notification or both Houses agree that the notification should not be made, the notification shall thereafter have effect only in such modified …"}, "it-act-2000:sec_81A__subsec_2__hcontainer_1": {"cite": "IT Act s.81A(2)", "head": "", "text": "For the purposes of this Act, the expressions “electronic cheque” and “truncated cheque” shall have the same meaning as assigned to them in section 6 of the Negotiable Instruments Act, 1881 ."}, "it-act-2000:sec_82": {"cite": "IT Act s.82", "head": "Controller, Deputy Controller and Assistant Controller to be public servants", "text": "The Controller, the Deputy Controller and the Assistant Controllers shall be deemed to be public servants within the meaning of section 21 of the Indian Penal Code."}, "it-act-2000:sec_83": {"cite": "IT Act s.83", "head": "Power to give directions", "text": "The Central Government may give directions to any State Government as to the carrying into execution in the State of any of the provisions of this Act or of any rule, regulation or order made thereunder."}, "it-act-2000:sec_84": {"cite": "IT Act s.84", "head": "Protection of action taken in good faith", "text": "No suit, prosecution or other legal proceeding shall lie against the Central Government, the State Government, the Controller or any person acting on behalf of him, and adjudicating officers for anything which is in good faith done or intended to be done in pursuance of this Act or any rule, regulation or order made thereunder."}, "it-act-2000:sec_84A": {"cite": "IT Act s.84A", "head": "Modes or methods for encryption", "text": "The Central Government may, for secure use of the electronic medium and for promotion of e-governance and e-commerce, prescribe the modes or methods for encryption."}, "it-act-2000:sec_84B": {"cite": "IT Act s.84B", "head": "Punishment for abetment of offences", "text": "Whoever abets any offence shall, if the act abetted is committed in consequence of the abetment, and no express provision is made by this Act for the punishment of such abetment, be punished with the punishment provided for the offence under this Act. An act or offence is said to be committed in consequence of abetment, when it is committed in consequence of the instigation, or in pursuance of the conspiracy, or with the aid which constitutes the abetment."}, "it-act-2000:sec_84B__hcontainer_1": {"cite": "IT Act s.84B", "head": "", "text": "An act or offence is said to be committed in consequence of abetment, when it is committed in consequence of the instigation, or in pursuance of the conspiracy, or with the aid which constitutes the abetment."}, "it-act-2000:sec_84C": {"cite": "IT Act s.84C", "head": "Punishment for attempt to commit offences", "text": "Whoever attempts to commit an offence punishable by this Act or causes such an offence to be committed, and in such an attempt does any act towards the commission of the offence, shall, where no express provision is made for the punishment of such attempt, be punished with imprisonment of any description provided for the offence, for a term which may extend to one-half of the longest term of imprisonment provided for that offence, or with such fine as is provided for the offence, or with both."}, "it-act-2000:sec_85": {"cite": "IT Act s.85", "head": "Offences by companies", "text": "Where a person committing a contravention of any of the provisions of this Act or of any rule, direction or order made thereunder is a company, every person who, at the time the contravention was committed, was in charge of, and was responsible to, the company for the conduct of business of the company as well as the company, shall be guilty of the contravention and shall be liable to be proceeded against and punished accordingly: Provided that nothing contained in this sub-section shall render any such person liable to punishment if he proves that the contravention took place without his know…"}, "it-act-2000:sec_85__subsec_1": {"cite": "IT Act s.85(1)", "head": "", "text": "Where a person committing a contravention of any of the provisions of this Act or of any rule, direction or order made thereunder is a company, every person who, at the time the contravention was committed, was in charge of, and was responsible to, the company for the conduct of business of the company as well as the company, shall be guilty of the contravention and shall be liable to be proceeded against and punished accordingly: Provided that nothing contained in this sub-section shall render any such person liable to punishment if he proves that the contravention took place without his know…"}, "it-act-2000:sec_85__subsec_1__proviso_1": {"cite": "IT Act s.85(1)", "head": "", "text": "Provided that nothing contained in this sub-section shall render any such person liable to punishment if he proves that the contravention took place without his knowledge or that he exercised all due diligence to prevent such contravention."}, "it-act-2000:sec_85__subsec_2": {"cite": "IT Act s.85(2)", "head": "", "text": "Notwithstanding anything contained in sub-section (1), where a contravention of any of the provisions of this Act or of any rule, direction or order made thereunder has been committed by a company and it is proved that the contravention has taken place with the consent or connivance of, or is attributable to any neglect on the part of, any director, manager, secretary or other officer of the company, such director, manager, secretary or other officer shall also be deemed to be guilty of the contravention and shall be liable to be proceeded against and punished accordingly."}, "it-act-2000:sec_85__hcontainer_1": {"cite": "IT Act s.85", "head": "", "text": "For the purposes of this section,— \"company\" means any body corporate and includes a firm or other association of individuals; and \"director\", in relation to a firm, means a partner in the firm."}, "it-act-2000:sec_85__hcontainer_1__subcl_i": {"cite": "IT Act s.85(i)", "head": "", "text": "\"company\" means any body corporate and includes a firm or other association of individuals; and"}, "it-act-2000:sec_85__hcontainer_1__subcl_ii": {"cite": "IT Act s.85(ii)", "head": "", "text": "\"director\", in relation to a firm, means a partner in the firm."}, "it-act-2000:sec_86": {"cite": "IT Act s.86", "head": "Removal of difficulties", "text": "If any difficulty arises in giving effect to the provisions of this Act, the Central Government may, by order published in the Official Gazette, make such provisions not inconsistent with the provisions of this Act as appear to it to be necessary or expedient for removing the difficulty: Provided that no order shall be made under this section after the expiry of a period of two years from the commencement of this Act. Every order made under this section shall be laid, as soon as may be after it is made, before each House of Parliament."}, "it-act-2000:sec_86__subsec_1": {"cite": "IT Act s.86(1)", "head": "", "text": "If any difficulty arises in giving effect to the provisions of this Act, the Central Government may, by order published in the Official Gazette, make such provisions not inconsistent with the provisions of this Act as appear to it to be necessary or expedient for removing the difficulty: Provided that no order shall be made under this section after the expiry of a period of two years from the commencement of this Act."}, "it-act-2000:sec_86__subsec_1__proviso_1": {"cite": "IT Act s.86(1)", "head": "", "text": "Provided that no order shall be made under this section after the expiry of a period of two years from the commencement of this Act."}, "it-act-2000:sec_86__subsec_2": {"cite": "IT Act s.86(2)", "head": "", "text": "Every order made under this section shall be laid, as soon as may be after it is made, before each House of Parliament."}, "it-act-2000:sec_87": {"cite": "IT Act s.87", "head": "Power of Central Government to make rules", "text": "The Central Government may, by notification in the Official Gazette and in the Electronic Gazette make rules to carry out the provisions of this Act. In particular, and without prejudice to the generality of the foregoing power, such rules may provide for all or any of the following matters, namely:— the conditions for considering reliability of electronic signature or electronic authentication technique under sub-section (2) of section 3A; the procedure for ascertaining electronic signature or authentication under sub-section (3) of section 3A; the manner in which any information or matter ma…"}, "it-act-2000:sec_87__subsec_1": {"cite": "IT Act s.87(1)", "head": "", "text": "The Central Government may, by notification in the Official Gazette and in the Electronic Gazette make rules to carry out the provisions of this Act."}, "it-act-2000:sec_87__subsec_2": {"cite": "IT Act s.87(2)", "head": "", "text": "In particular, and without prejudice to the generality of the foregoing power, such rules may provide for all or any of the following matters, namely:— the conditions for considering reliability of electronic signature or electronic authentication technique under sub-section (2) of section 3A; the procedure for ascertaining electronic signature or authentication under sub-section (3) of section 3A; the manner in which any information or matter may be authenticated by means of electronic signature under section 5; the electronic form in which filing, issue, grant or payment shall be effected un…"}, "it-act-2000:sec_87__subsec_2__cl_a": {"cite": "IT Act s.87(2)(a)", "head": "", "text": "the conditions for considering reliability of electronic signature or electronic authentication technique under sub-section (2) of section 3A;"}, "it-act-2000:sec_87__subsec_2__cl_aa": {"cite": "IT Act s.87(2)(aa)", "head": "", "text": "the procedure for ascertaining electronic signature or authentication under sub-section (3) of section 3A;"}, "it-act-2000:sec_87__subsec_2__cl_ab": {"cite": "IT Act s.87(2)(ab)", "head": "", "text": "the manner in which any information or matter may be authenticated by means of electronic signature under section 5;"}, "it-act-2000:sec_87__subsec_2__cl_b": {"cite": "IT Act s.87(2)(b)", "head": "", "text": "the electronic form in which filing, issue, grant or payment shall be effected under sub-section (1) of section 6;"}, "it-act-2000:sec_87__subsec_2__cl_c": {"cite": "IT Act s.87(2)(c)", "head": "", "text": "the manner and format in which electronic records shall be filed, or issued and the method of payment under sub-section (2) of section 6;"}, "it-act-2000:sec_87__subsec_2__cl_ca": {"cite": "IT Act s.87(2)(ca)", "head": "", "text": "the manner in which the authorised service provider may collect, retain and appropriate service charges under sub-section (2) of section 6A;"}, "it-act-2000:sec_87__subsec_2__cl_d": {"cite": "IT Act s.87(2)(d)", "head": "", "text": "the matters relating to the type of electronic signature, manner and format in which it may be affixed under section 10;"}, "it-act-2000:sec_87__subsec_2__cl_e": {"cite": "IT Act s.87(2)(e)", "head": "", "text": "the manner of storing and affixing electronic signature creation data under section 15;"}, "it-act-2000:sec_87__subsec_2__cl_ea": {"cite": "IT Act s.87(2)(ea)", "head": "", "text": "the security procedures and practices under section 16;"}, "it-act-2000:sec_87__subsec_2__cl_f": {"cite": "IT Act s.87(2)(f)", "head": "", "text": "the qualifications, experience and terms and conditions of service of Controller, Deputy Controllers, Assistant Controllers, other officers and employees under section 17;"}, "it-act-2000:sec_87__subsec_2__cl_g": {"cite": "IT Act s.87(2)(g)", "head": "", "text": ""}, "it-act-2000:sec_87__subsec_2__cl_h": {"cite": "IT Act s.87(2)(h)", "head": "", "text": "the requirements which an applicant must fulfil under sub-section (2) of section 21;"}, "it-act-2000:sec_87__subsec_2__cl_i": {"cite": "IT Act s.87(2)(i)", "head": "", "text": "the period of validity of licence granted under clause (a) of sub-section (3) of section 21;"}, "it-act-2000:sec_87__subsec_2__cl_j": {"cite": "IT Act s.87(2)(j)", "head": "", "text": "the form in which an application for licence may be made under sub-section (1) of section 22;"}, "it-act-2000:sec_87__subsec_2__cl_k": {"cite": "IT Act s.87(2)(k)", "head": "", "text": "the amount of fees payable under clause (c) of sub-section (2) of section 22;"}, "it-act-2000:sec_87__subsec_2__cl_l": {"cite": "IT Act s.87(2)(l)", "head": "", "text": "such other documents which shall accompany an application for licence under clause (d) of sub-section (2) of section 22;"}, "it-act-2000:sec_87__subsec_2__cl_m": {"cite": "IT Act s.87(2)(m)", "head": "", "text": "the form and the fee for renewal of a licence and the fee payable thereof under section 23;"}, "it-act-2000:sec_87__subsec_2__cl_ma": {"cite": "IT Act s.87(2)(ma)", "head": "", "text": "the form of application and fee for issue of Electronic Signature"}, "it-act-2000:sec_87__subsec_2__wrap_1": {"cite": "IT Act s.87(2)", "head": "", "text": "Certificate under section 35;"}, "it-act-2000:sec_87__subsec_2__cl_n": {"cite": "IT Act s.87(2)(n)", "head": "", "text": "the form in which application for issue of a Electronic signature Certificate may be made under sub-section (1) of section 35;"}, "it-act-2000:sec_87__subsec_2__cl_o": {"cite": "IT Act s.87(2)(o)", "head": "", "text": "the fee to be paid to the Certifying Authority for issue of a Electronic signature Certificate under sub-section (2) of section 35;"}, "it-act-2000:sec_87__subsec_2__cl_oa": {"cite": "IT Act s.87(2)(oa)", "head": "", "text": "the duties of subscribers under section 40A;"}, "it-act-2000:sec_87__subsec_2__cl_ob": {"cite": "IT Act s.87(2)(ob)", "head": "", "text": "the reasonable security practices and procedures and sensitive personal data or information under section 43A;"}, "it-act-2000:sec_87__subsec_2__cl_p": {"cite": "IT Act s.87(2)(p)", "head": "", "text": "the manner in which the adjudicating officer shall hold inquiry under sub-section (1) of section 46;"}, "it-act-2000:sec_87__subsec_2__cl_q": {"cite": "IT Act s.87(2)(q)", "head": "", "text": "the qualification and experience which the adjudicating officer shall possess under sub-section (3) of section 46;"}, "it-act-2000:sec_87__subsec_2__cl_r": {"cite": "IT Act s.87(2)(r)", "head": "", "text": ""}, "it-act-2000:sec_87__subsec_2__cl_s": {"cite": "IT Act s.87(2)(s)", "head": "", "text": ""}, "it-act-2000:sec_87__subsec_2__cl_t": {"cite": "IT Act s.87(2)(t)", "head": "", "text": ""}, "it-act-2000:sec_87__subsec_2__cl_u": {"cite": "IT Act s.87(2)(u)", "head": "", "text": "the form in which appeal may be filed and the fee thereof under sub section (3) of section 57;"}, "it-act-2000:sec_87__subsec_2__cl_v": {"cite": "IT Act s.87(2)(v)", "head": "", "text": "any other power of a civil court required to be prescribed under clause (g) of sub-section (2) of section 58; and"}, "it-act-2000:sec_87__subsec_2__cl_w": {"cite": "IT Act s.87(2)(w)", "head": "", "text": "the powers and functions of the Chairperson of the Appellate Tribunal under section 52A;"}, "it-act-2000:sec_87__subsec_2__cl_x": {"cite": "IT Act s.87(2)(x)", "head": "", "text": "the information, duration, manner and form of such information to be retained and preserved under section 67C;"}, "it-act-2000:sec_87__subsec_2__cl_y": {"cite": "IT Act s.87(2)(y)", "head": "", "text": "the procedures and safeguards for interception, monitoring, or decryption under sub-section (2) of section 69;"}, "it-act-2000:sec_87__subsec_2__cl_z": {"cite": "IT Act s.87(2)(z)", "head": "", "text": "the procedure and safeguards for blocking for access by the public under sub-section (2) of section 69A;"}, "it-act-2000:sec_87__subsec_2__cl_za": {"cite": "IT Act s.87(2)(za)", "head": "", "text": "the procedure and safeguards for monitoring and collecting traffic data or information under sub-section (3) of section 69B;"}, "it-act-2000:sec_87__subsec_2__cl_zb": {"cite": "IT Act s.87(2)(zb)", "head": "", "text": "the information security practices and procedures for protected system under section 70;"}, "it-act-2000:sec_87__subsec_2__cl_zc": {"cite": "IT Act s.87(2)(zc)", "head": "", "text": "manner of performing functions and duties of the agency under sub-section (3) of section 70A;"}, "it-act-2000:sec_87__subsec_2__cl_zd": {"cite": "IT Act s.87(2)(zd)", "head": "", "text": "the officers and employees under sub-section (2) of section 70B;"}, "it-act-2000:sec_87__subsec_2__cl_ze": {"cite": "IT Act s.87(2)(ze)", "head": "", "text": "salaries and allowances and terms and conditions of service of the Director General and other officers and employees under sub-section (3) of section 70B;"}, "it-act-2000:sec_87__subsec_2__cl_zf": {"cite": "IT Act s.87(2)(zf)", "head": "", "text": "the manner in whcih the functions and duties of agency shall be performed under sub-section (5) of section 70B;"}, "it-act-2000:sec_87__subsec_2__cl_zg": {"cite": "IT Act s.87(2)(zg)", "head": "", "text": "the guidelines to be observed by the intermediaries under sub-section (2) of section 79;"}, "it-act-2000:sec_87__subsec_2__cl_zh": {"cite": "IT Act s.87(2)(zh)", "head": "", "text": "the modes or methods for encryption under section 84A;"}, "it-act-2000:sec_87__subsec_3": {"cite": "IT Act s.87(3)", "head": "", "text": "Every notification made by the Central Government under sub-section (1) of section 70A and every rule made by it shall be laid, as soon as may be after it is made, before each House of Parliament, while it is in session, for a total period of thirty days which may be comprised in one session or in two or more successive sessions, and if, before the expiry of the session immediately following the session or the successive sessions aforesaid, both Houses agree in making any modification in the rule or both Houses agree that the rule should not be made, the rule shall thereafter have effect only …"}, "it-act-2000:sec_88": {"cite": "IT Act s.88", "head": "Constitution of Advisory Committee", "text": "The Central Government shall, as soon as may be after the commencement of this Act, constitute a Committee called the Cyber Regulations Advisory Committee. The Cyber Regulations Advisory Committee shall consist of a Chairperson and such number of other official and non-official members representing the interests principally affected or having special knowledge of the subject-matter as the Central Government may deem fit. The Cyber Regulations Advisory Committee shall advise— the Central Government either generally as regards any rules or for any other purpose connected with this Act; the Contr…"}, "it-act-2000:sec_88__subsec_1": {"cite": "IT Act s.88(1)", "head": "", "text": "The Central Government shall, as soon as may be after the commencement of this Act, constitute a Committee called the Cyber Regulations Advisory Committee."}, "it-act-2000:sec_88__subsec_2": {"cite": "IT Act s.88(2)", "head": "", "text": "The Cyber Regulations Advisory Committee shall consist of a Chairperson and such number of other official and non-official members representing the interests principally affected or having special knowledge of the subject-matter as the Central Government may deem fit."}, "it-act-2000:sec_88__subsec_3": {"cite": "IT Act s.88(3)", "head": "", "text": "The Cyber Regulations Advisory Committee shall advise— the Central Government either generally as regards any rules or for any other purpose connected with this Act; the Controller in framing the regulations under this Act."}, "it-act-2000:sec_88__subsec_3__cl_a": {"cite": "IT Act s.88(3)(a)", "head": "", "text": "the Central Government either generally as regards any rules or for any other purpose connected with this Act;"}, "it-act-2000:sec_88__subsec_3__cl_b": {"cite": "IT Act s.88(3)(b)", "head": "", "text": "the Controller in framing the regulations under this Act."}, "it-act-2000:sec_88__subsec_4": {"cite": "IT Act s.88(4)", "head": "", "text": "There shall be paid to the non-official members of such Committee such travelling and other allowances as the Central Government may fix."}, "it-act-2000:sec_89": {"cite": "IT Act s.89", "head": "Power of Controller to make regulations", "text": "The Controller may, after consultation with the Cyber Regulations Advisory Committee and with the previous approval of the Central Government, by notification in the Official Gazette, make regulations consistent with this Act and the rules made thereunder to carry out the purposes of this Act. In particular, and without prejudice to the generality of the foregoing power, such regulations may provide for all or any of the following matters, namely:— the particulars relating to maintenance of data-base containing the disclosure record of every Certifying Authority under clause (n) of section 18;…"}, "it-act-2000:sec_89__subsec_1": {"cite": "IT Act s.89(1)", "head": "", "text": "The Controller may, after consultation with the Cyber Regulations Advisory Committee and with the previous approval of the Central Government, by notification in the Official Gazette, make regulations consistent with this Act and the rules made thereunder to carry out the purposes of this Act."}, "it-act-2000:sec_89__subsec_2": {"cite": "IT Act s.89(2)", "head": "", "text": "In particular, and without prejudice to the generality of the foregoing power, such regulations may provide for all or any of the following matters, namely:— the particulars relating to maintenance of data-base containing the disclosure record of every Certifying Authority under clause (n) of section 18; the conditions and restrictions subject to which the Controller may recognise any foreign Certifying Authority under sub-section (1) of section 19; the terms and conditions subject to which a licence may be granted under clause (c) of sub-section (3) of section 21; other standards to be observ…"}, "it-act-2000:sec_89__subsec_2__cl_a": {"cite": "IT Act s.89(2)(a)", "head": "", "text": "the particulars relating to maintenance of data-base containing the disclosure record of every Certifying Authority under clause (n) of section 18;"}, "it-act-2000:sec_89__subsec_2__cl_b": {"cite": "IT Act s.89(2)(b)", "head": "", "text": "the conditions and restrictions subject to which the Controller may recognise any foreign Certifying Authority under sub-section (1) of section 19;"}, "it-act-2000:sec_89__subsec_2__cl_c": {"cite": "IT Act s.89(2)(c)", "head": "", "text": "the terms and conditions subject to which a licence may be granted under clause (c) of sub-section (3) of section 21;"}, "it-act-2000:sec_89__subsec_2__cl_d": {"cite": "IT Act s.89(2)(d)", "head": "", "text": "other standards to be observed by a Certifying Authority under clause (d) of section 30;"}, "it-act-2000:sec_89__subsec_2__cl_e": {"cite": "IT Act s.89(2)(e)", "head": "", "text": "the manner in which the Certifying Authority shall disclose the matters specified in sub-section (1) of section 34;"}, "it-act-2000:sec_89__subsec_2__cl_f": {"cite": "IT Act s.89(2)(f)", "head": "", "text": "the particulars of statement which shall accompany an application under sub-section (3) of section 35;"}, "it-act-2000:sec_89__subsec_2__cl_g": {"cite": "IT Act s.89(2)(g)", "head": "", "text": "the manner in which the subscriber shall communicate the compromise of private key to the certifying Authority under sub-section (2) of section 42."}, "it-act-2000:sec_89__subsec_3": {"cite": "IT Act s.89(3)", "head": "", "text": "Every regulation made under this Act shall be laid, as soon as may be after it is made, before each House of Parliament, while it is in session, for a total period of thirty days which may be comprised in one session or in two or more successive sessions, and if, before the expiry of the session immediately following the session or the successive sessions aforesaid, both Houses agree in making any modification in the regulation or both Houses agree that the regulation should not be made, the regulation shall thereafter have effect only in such modified form or be of no effect, as the case may …"}, "it-act-2000:sec_90": {"cite": "IT Act s.90", "head": "Power of State Government to make rules", "text": "The State Government may, by notification in the Official Gazette, make rules to carry out the provisions of this Act. In particular, and without prejudice to the generality of the foregoing power, such rules may provide for all or any of the following matters, namely:— the electronic form in which filing, issue, grant receipt or payment shall be effected under sub-section (1) of section 6; for matters specified in sub-section (2) of section 6; Every rule made by the State Government under this section shall be laid, as soon as may be after it is made, before each House of the State Legislatur…"}, "it-act-2000:sec_90__subsec_1": {"cite": "IT Act s.90(1)", "head": "", "text": "The State Government may, by notification in the Official Gazette, make rules to carry out the provisions of this Act."}, "it-act-2000:sec_90__subsec_2": {"cite": "IT Act s.90(2)", "head": "", "text": "In particular, and without prejudice to the generality of the foregoing power, such rules may provide for all or any of the following matters, namely:— the electronic form in which filing, issue, grant receipt or payment shall be effected under sub-section (1) of section 6; for matters specified in sub-section (2) of section 6;"}, "it-act-2000:sec_90__subsec_2__cl_a": {"cite": "IT Act s.90(2)(a)", "head": "", "text": "the electronic form in which filing, issue, grant receipt or payment shall be effected under sub-section (1) of section 6;"}, "it-act-2000:sec_90__subsec_2__cl_b": {"cite": "IT Act s.90(2)(b)", "head": "", "text": "for matters specified in sub-section (2) of section 6;"}, "it-act-2000:sec_90__subsec_2__cl_c": {"cite": "IT Act s.90(2)(c)", "head": "", "text": ""}, "it-act-2000:sec_90__subsec_3": {"cite": "IT Act s.90(3)", "head": "", "text": "Every rule made by the State Government under this section shall be laid, as soon as may be after it is made, before each House of the State Legislature where it consists of two Houses, or where such Legislature consists of one House, before that House."}, "it-act-2000:sec_91": {"cite": "IT Act s.91", "head": "Amendment of Act 45 of 1860", "text": ""}, "it-act-2000:sec_92": {"cite": "IT Act s.92", "head": "Amendment of Act 1 of 1872", "text": ""}, "it-act-2000:sec_93": {"cite": "IT Act s.93", "head": "Amendment of Act 18 of 1891. Amendment of Act 2 of 1934", "text": ""}, "it-act-2000:sec_94": {"cite": "IT Act s.94", "head": "", "text": ""}, "it-act-2000:sched_1": {"cite": "IT Act Schedule I", "head": "", "text": "THE FIRST SCHEDULE [See sub-section (4) of section 1] A negotiable instrument (other than a cheque, a Demand Promissory Note or a Bill of Exchange issued in favour of or endorsed by an entity regulated by the Reserve Bank of India, National Housing Bank, Securities and Exchange Board of India, Insurance Regulatory and Development Authority of India and Pension Fund Regulatory and Development Authority) as defined in section 13 of the Negotiable Instrument Act, 1881 (26 of 1881). A power-of-attorney as defined in section 1A of the Powers-of-Attorney Act, 1882 (7 of 1882) but excluding those pow…"}, "it-act-2000:sched_1__para_1": {"cite": "IT Act Schedule I, para 1", "head": "", "text": "A negotiable instrument (other than a cheque, a Demand Promissory Note or a Bill of Exchange issued in favour of or endorsed by an entity regulated by the Reserve Bank of India, National Housing Bank, Securities and Exchange Board of India, Insurance Regulatory and Development Authority of India and Pension Fund Regulatory and Development Authority) as defined in section 13 of the Negotiable Instrument Act, 1881 (26 of 1881)."}, "it-act-2000:sched_1__para_2": {"cite": "IT Act Schedule I, para 2", "head": "", "text": "A power-of-attorney as defined in section 1A of the Powers-of-Attorney Act, 1882 (7 of 1882) but excluding those power-of-attorney that empower an entity regulated by the Reserve Bank of India, National Housing Bank, Securities and Exchange Board of India, Insurance Regulatory and Development Authority of India and Pension Fund Regulatory and Development Authority to act for, on behalf of, and in the name of the person executing them.."}, "it-act-2000:sched_1__para_3": {"cite": "IT Act Schedule I, para 3", "head": "", "text": "A trust as defined in section 3 of the Indian Trusts Act, 1882."}, "it-act-2000:sched_1__para_4": {"cite": "IT Act Schedule I, para 4", "head": "", "text": "A will as defined in clause (h) of section 2 of the Indian Succession Act, 1925, including any other testamentary disposition by whatever name called."}, "it-act-2000:sched_1__para_5": {"cite": "IT Act Schedule I, para 5", "head": "", "text": ""}, "it-act-2000:sched_2": {"cite": "IT Act Schedule II", "head": "", "text": "THE SECOND SCHEDULE [See sub-section (1) of section 3A] ELECTRONIC SIGNATURE OR ELECTRONIC AUTHENTICATION TECHNIQUE AND PROCEDURE [No entries yet: the table's entries are added by notification.]"}, "it-act-2000:sched_2__hcontainer_1": {"cite": "IT Act Schedule II", "head": "", "text": "[No entries yet: the table's entries are added by notification.]"}, "it-act-2000:sched_3": {"cite": "IT Act Schedule III", "head": "", "text": "THE THIRD SCHEDULE (See section 93) [Omitted.]"}, "it-act-2000:sched_3__hcontainer_1": {"cite": "IT Act Schedule III", "head": "", "text": "[Omitted.]"}, "it-act-2000:sched_4": {"cite": "IT Act Schedule IV", "head": "", "text": "THE FOURTH SCHEDULE (See section 94) [Omitted.]"}, "it-act-2000:sched_4__hcontainer_1": {"cite": "IT Act Schedule IV", "head": "", "text": "[Omitted.]"}, "it-rules-2021:part_I": {"cite": "IT Rules 2021 Part I", "head": "PRELIMINARY", "text": "Short Title and Commencement These rules may be called the Information Technology (Intermediary Guidelines and Digital Media Ethics Code) Rules, 2021. They shall come into force on the date of their publication in the Official Gazette. Definitions In these rules, unless the context otherwise requires- ‘access control mechanism‘ means any measure, including a technical measure, through which access to online curated content may be restricted based on verification of the identity or age of a user; ‘access services‘ means any measure, including technical measure such as closed captioning, subtitl…"}, "it-rules-2021:rule_1": {"cite": "IT Rules 2021 r.1", "head": "Short Title and Commencement", "text": "These rules may be called the Information Technology (Intermediary Guidelines and Digital Media Ethics Code) Rules, 2021. They shall come into force on the date of their publication in the Official Gazette."}, "it-rules-2021:rule_1__subrule_1": {"cite": "IT Rules 2021 r.1(1)", "head": "", "text": "These rules may be called the Information Technology (Intermediary Guidelines and Digital Media Ethics Code) Rules, 2021."}, "it-rules-2021:rule_1__subrule_2": {"cite": "IT Rules 2021 r.1(2)", "head": "", "text": "They shall come into force on the date of their publication in the Official Gazette."}, "it-rules-2021:rule_2": {"cite": "IT Rules 2021 r.2", "head": "Definitions", "text": "In these rules, unless the context otherwise requires- ‘access control mechanism‘ means any measure, including a technical measure, through which access to online curated content may be restricted based on verification of the identity or age of a user; ‘access services‘ means any measure, including technical measure such as closed captioning, subtitles and audio descriptions, through which the accessibility of online curated content may be improved for persons with disabilities; ‘Act‘ means the Information Technology Act, 2000 (21 of 2000); ‘audio, visual or audio-visual information’ means any…"}, "it-rules-2021:rule_2__subrule_1": {"cite": "IT Rules 2021 r.2(1)", "head": "", "text": "In these rules, unless the context otherwise requires- ‘access control mechanism‘ means any measure, including a technical measure, through which access to online curated content may be restricted based on verification of the identity or age of a user; ‘access services‘ means any measure, including technical measure such as closed captioning, subtitles and audio descriptions, through which the accessibility of online curated content may be improved for persons with disabilities; ‘Act‘ means the Information Technology Act, 2000 (21 of 2000); ‘audio, visual or audio-visual information’ means any…"}, "it-rules-2021:rule_2__subrule_1__cl_a": {"cite": "IT Rules 2021 r.2(1)(a)", "head": "", "text": "‘access control mechanism‘ means any measure, including a technical measure, through which access to online curated content may be restricted based on verification of the identity or age of a user;"}, "it-rules-2021:rule_2__subrule_1__cl_b": {"cite": "IT Rules 2021 r.2(1)(b)", "head": "", "text": "‘access services‘ means any measure, including technical measure such as closed captioning, subtitles and audio descriptions, through which the accessibility of online curated content may be improved for persons with disabilities;"}, "it-rules-2021:rule_2__subrule_1__cl_c": {"cite": "IT Rules 2021 r.2(1)(c)", "head": "", "text": "‘Act‘ means the Information Technology Act, 2000 (21 of 2000);"}, "it-rules-2021:rule_2__subrule_1__cl_ca": {"cite": "IT Rules 2021 r.2(1)(ca)", "head": "", "text": "‘audio, visual or audio-visual information’ means any audio, image, photograph, graphic, video, moving visual recording, sound recording or any other audio, visual or audio-visual content, with or without accompanying audio, whether created, generated, modified or altered through any computer resource;"}, "it-rules-2021:rule_2__subrule_1__cl_d": {"cite": "IT Rules 2021 r.2(1)(d)", "head": "", "text": "‘child‘ means any person below the age of eighteen years;"}, "it-rules-2021:rule_2__subrule_1__cl_e": {"cite": "IT Rules 2021 r.2(1)(e)", "head": "", "text": "‘committee‘ means the Inter-Departmental Committee constituted under rule 14;"}, "it-rules-2021:rule_2__subrule_1__cl_f": {"cite": "IT Rules 2021 r.2(1)(f)", "head": "", "text": "‘communication link‘ means a connection between a hypertext or graphical element, and one or more items in the same or different electronic document wherein upon clicking on a hyperlinked item, the user is automatically transferred to the other end of the hyperlink which can be another electronic record or another website or application or graphical element;"}, "it-rules-2021:rule_2__subrule_1__cl_g": {"cite": "IT Rules 2021 r.2(1)(g)", "head": "", "text": "‘content‘ means the electronic record defined in clause (t) of section 2 of the Act;"}, "it-rules-2021:rule_2__subrule_1__cl_h": {"cite": "IT Rules 2021 r.2(1)(h)", "head": "", "text": "‘content descriptor‘ means the issues and concerns which are relevant to the classification of any online curated content, including discrimination, depiction of illegal or harmful substances, imitable behaviour, nudity, language, sex, violence, fear, threat, horror and other such concerns as specified in the Schedule annexed to the rules;"}, "it-rules-2021:rule_2__subrule_1__cl_i": {"cite": "IT Rules 2021 r.2(1)(i)", "head": "", "text": "‘digital media‘ means digitized content that can be transmitted over the internet or computer networks and includes content received, stored, transmitted, edited or processed by- an intermediary; or a publisher of news and current affairs content or a publisher of online curated content;"}, "it-rules-2021:rule_2__subrule_1__cl_i__subcl_i": {"cite": "IT Rules 2021 r.2(1)(i)(i)", "head": "", "text": "an intermediary; or"}, "it-rules-2021:rule_2__subrule_1__cl_i__subcl_ii": {"cite": "IT Rules 2021 r.2(1)(i)(ii)", "head": "", "text": "a publisher of news and current affairs content or a publisher of online curated content;"}, "it-rules-2021:rule_2__subrule_1__cl_j": {"cite": "IT Rules 2021 r.2(1)(j)", "head": "", "text": "‘grievance‘ includes any complaint, whether regarding any content, any duties of an intermediary or publisher under the Act, or other matters pertaining to the computer resource of an intermediary or publisher, as the case may be;"}, "it-rules-2021:rule_2__subrule_1__cl_k": {"cite": "IT Rules 2021 r.2(1)(k)", "head": "", "text": "‘Grievance Officer‘ means an officer appointed by the intermediary or the online gaming self-regulatory body or the publisher, as the case may be, for the purposes of these rules;"}, "it-rules-2021:rule_2__subrule_1__cl_ka": {"cite": "IT Rules 2021 r.2(1)(ka)", "head": "", "text": "‘Grievance Appellate Committee’ means a grievance appellate committee constituted under rule 3A;"}, "it-rules-2021:rule_2__subrule_1__cl_l": {"cite": "IT Rules 2021 r.2(1)(l)", "head": "", "text": "‘Ministry‘ means, for the purpose of Part II of these rules unless specified otherwise, the Ministry of Electronics and Information Technology, Government of India, and for the purpose of Part III of these rules, the Ministry of Information and Broadcasting, Government of India;"}, "it-rules-2021:rule_2__subrule_1__cl_m": {"cite": "IT Rules 2021 r.2(1)(m)", "head": "", "text": "‘news and current affairs content‘ includes newly received or noteworthy content, including analysis, especially about recent events primarily of socio-political, economic or cultural nature, made available over the internet or computer networks, and any digital media shall be news and current affairs content where the context, substance, purpose, import and meaning of such information is in the nature of news and current affairs content."}, "it-rules-2021:rule_2__subrule_1__cl_n": {"cite": "IT Rules 2021 r.2(1)(n)", "head": "", "text": "‘newspaper‘ means a periodical of loosely folded sheets usually printed on newsprint and brought out daily or at least once in a week, containing information on current events, public news or comments on public news;"}, "it-rules-2021:rule_2__subrule_1__cl_o": {"cite": "IT Rules 2021 r.2(1)(o)", "head": "", "text": "‘news aggregator‘ means an entity who, performing a significant role in determining the news and current affairs content being made available, makes available to users a computer resource that enable such users to access the news and current affairs content which is aggregated, curated and presented by such entity."}, "it-rules-2021:rule_2__subrule_1__cl_p": {"cite": "IT Rules 2021 r.2(1)(p)", "head": "", "text": "‘on demand‘ means a system where a user, subscriber or viewer is enabled to access, at a time chosen by such user, any content in electronic form, which is transmitted over a computer resource and is selected by the user;"}, "it-rules-2021:rule_2__subrule_1__cl_q": {"cite": "IT Rules 2021 r.2(1)(q)", "head": "", "text": "‘online curated content‘ means any curated catalogue of audio-visual content, other than news and current affairs content, which is owned by, licensed to or contracted to be transmitted by a publisher of online curated content, and made available on demand, including but not limited through subscription, over the internet or computer networks, and includes films, audio visual programmes, documentaries, television programmes, serials, podcasts and other such content;"}, "it-rules-2021:rule_2__subrule_1__cl_qa": {"cite": "IT Rules 2021 r.2(1)(qa)", "head": "", "text": "‘online game’ means a game that is offered on the Internet and is accessible by a user through a computer resource or an intermediary. In this clause, ‘Internet’ means the combination of computer facilities and electromagnetic transmission media, and related equipment and software, comprising the interconnected worldwide network of computer networks that transmits information based on a protocol for controlling such transmission;"}, "it-rules-2021:rule_2__subrule_1__cl_qa__hcontainer_1": {"cite": "IT Rules 2021 r.2(1)(qa)", "head": "", "text": "In this clause, ‘Internet’ means the combination of computer facilities and electromagnetic transmission media, and related equipment and software, comprising the interconnected worldwide network of computer networks that transmits information based on a protocol for controlling such transmission;"}, "it-rules-2021:rule_2__subrule_1__cl_qb": {"cite": "IT Rules 2021 r.2(1)(qb)", "head": "", "text": "‘online gaming intermediary’ means any intermediary that enables the users of its computer resource to access one or more online games;"}, "it-rules-2021:rule_2__subrule_1__cl_qc": {"cite": "IT Rules 2021 r.2(1)(qc)", "head": "", "text": "‘online gaming self-regulatory body’ means an entity designated as such under rule 4A;"}, "it-rules-2021:rule_2__subrule_1__cl_qd": {"cite": "IT Rules 2021 r.2(1)(qd)", "head": "", "text": "‘online real money game’ means an online game where a user makes a deposit in cash or kind with the expectation of earning winnings on that deposit. In this clause, ‘winnings’ means any prize, in cash or kind, which is distributed or intended to be distributed to a user of an online game based on the performance of the user and in accordance with the rules of such online game;"}, "it-rules-2021:rule_2__subrule_1__cl_qd__hcontainer_1": {"cite": "IT Rules 2021 r.2(1)(qd)", "head": "", "text": "In this clause, ‘winnings’ means any prize, in cash or kind, which is distributed or intended to be distributed to a user of an online game based on the performance of the user and in accordance with the rules of such online game;"}, "it-rules-2021:rule_2__subrule_1__cl_qe": {"cite": "IT Rules 2021 r.2(1)(qe)", "head": "", "text": "‘permissible online game’ means a permissible online real money game or any other online game that is not an online real money game;"}, "it-rules-2021:rule_2__subrule_1__cl_qf": {"cite": "IT Rules 2021 r.2(1)(qf)", "head": "", "text": "‘permissible online real money game’ means an online real money game verified by an online gaming self-regulatory body under rule 4A;"}, "it-rules-2021:rule_2__subrule_1__cl_r": {"cite": "IT Rules 2021 r.2(1)(r)", "head": "", "text": "‘person‘ means a person as defined in sub-section (31) of section 2 of the Income tax Act, 1961 (43 of 1961);"}, "it-rules-2021:rule_2__subrule_1__cl_s": {"cite": "IT Rules 2021 r.2(1)(s)", "head": "", "text": "‘publisher‘ means a publisher of news and current affairs content or a publisher of online curated content;"}, "it-rules-2021:rule_2__subrule_1__cl_t": {"cite": "IT Rules 2021 r.2(1)(t)", "head": "", "text": "‘publisher of news and current affairs content‘ means an online paper, news portal, news aggregator, news agency and such other entity called by whatever name, which is functionally similar to publishers of news and current affairs content but shall not include newspapers, replica e-papers of the newspaper and any individual or user who is not transmitting content in the course of systematic business, professional or commercial activity;"}, "it-rules-2021:rule_2__subrule_1__cl_u": {"cite": "IT Rules 2021 r.2(1)(u)", "head": "", "text": "‘publisher of online curated content‘ means a publisher who, performing a significant role in determining the online curated content being made available, makes available to users a computer resource that enables such users to access online curated content over the internet or computer networks, and such other entity called by whatever name, which is functionally similar to publishers of online curated content but does not include any individual or user who is not transmitting online curated content in the course of systematic business, professional or commercial activity;"}, "it-rules-2021:rule_2__subrule_1__cl_v": {"cite": "IT Rules 2021 r.2(1)(v)", "head": "", "text": "‘significant social media intermediary‘ means a social media intermediary having number of registered users in India above such threshold as notified by the Central Government;"}, "it-rules-2021:rule_2__subrule_1__cl_w": {"cite": "IT Rules 2021 r.2(1)(w)", "head": "", "text": "‘social media intermediary‘ means an intermediary which primarily or solely enables online interaction between two or more users and allows them to create, upload, share, disseminate, modify or access information using its services;"}, "it-rules-2021:rule_2__subrule_1__cl_wa": {"cite": "IT Rules 2021 r.2(1)(wa)", "head": "", "text": "‘synthetically generated information’ means audio, visual or audio-visual information which is artificially or algorithmically created, generated, modified or altered using a computer resource, in a manner that such information appears to be real, authentic or true and depicts or portrays any individual or event in a manner that is, or is likely to be perceived as indistinguishable from a natural person or real-world event; Provided that the purposes of this clause, an audio, visual or audio-visual information shall not be deemed to be ‘synthetically generated information’, where such audio, v…"}, "it-rules-2021:rule_2__subrule_1__cl_wa__proviso_1": {"cite": "IT Rules 2021 r.2(1)(wa)", "head": "", "text": "Provided that the purposes of this clause, an audio, visual or audio-visual information shall not be deemed to be ‘synthetically generated information’, where such audio, visual or audio-visual information arises from— routine or good-faith editing, formatting, enhancement, technical correction, colour adjustment, noise reduction, transcription, or compression that does not materially alter, distort, or misrepresent the substance, context, or meaning of the underlying audio, visual or audio-visual information; or the routine or good-faith creation, preparation, formatting, presentation or desi…"}, "it-rules-2021:rule_2__subrule_1__cl_wa__proviso_1__cl_a": {"cite": "IT Rules 2021 r.2(1)(wa)(a)", "head": "", "text": "routine or good-faith editing, formatting, enhancement, technical correction, colour adjustment, noise reduction, transcription, or compression that does not materially alter, distort, or misrepresent the substance, context, or meaning of the underlying audio, visual or audio-visual information; or"}, "it-rules-2021:rule_2__subrule_1__cl_wa__proviso_1__cl_b": {"cite": "IT Rules 2021 r.2(1)(wa)(b)", "head": "", "text": "the routine or good-faith creation, preparation, formatting, presentation or design of documents, presentations, portable document format (PDF) files, educational or training materials, research outputs, including the use of illustrative, hypothetical, draft, template-based or conceptual content, where such creation or presentation does not result in the creation or generation of any false document or false electronic record; or"}, "it-rules-2021:rule_2__subrule_1__cl_wa__proviso_1__cl_c": {"cite": "IT Rules 2021 r.2(1)(wa)(c)", "head": "", "text": "the use of computer resources solely for improving accessibility, clarity, quality, translation, description, searchability, or discoverability, without generating, altering, or manipulating any material part of the underlying audio, visual or audio-visual information;"}, "it-rules-2021:rule_2__subrule_1__cl_x": {"cite": "IT Rules 2021 r.2(1)(x)", "head": "", "text": "‘user‘ means any person who accesses or avails any computer resource of an intermediary or a publisher for the purpose of hosting, publishing, sharing, transacting, viewing, displaying, downloading or uploading information and includes other persons jointly participating in using such computer resource and addressee and originator;"}, "it-rules-2021:rule_2__subrule_1__cl_y": {"cite": "IT Rules 2021 r.2(1)(y)", "head": "", "text": "‘user account‘ means the account registration of a user with an intermediary or publisher and includes profiles, accounts, pages, handles and other similar presences by means of which a user is able to access the services offered by the intermediary or publisher."}, "it-rules-2021:rule_2__subrule_1A": {"cite": "IT Rules 2021 r.2(1A)", "head": "", "text": "For the purposes of these rules, any reference to ‘information’ in the context of information being used to commit an unlawful act, including under clauses (b) and (d) of sub-rule (1) of rule 3 and sub-rules (2) and (4) of rule 4, shall be construed to include synthetically generated information, unless the context otherwise requires."}, "it-rules-2021:rule_2__subrule_1B": {"cite": "IT Rules 2021 r.2(1B)", "head": "", "text": "For the purposes of these rules and for the removal of doubts, it is hereby clarified that the removal of, or disabling of access to, any information, including synthetically generated information, data or communication link, by an intermediary in compliance with these rules, including in accordance with sub-rule (1), sub-rule (2) or sub-rule (3) of rule 3, or upon becoming aware of any violation thereunder by deploying reasonable and appropriate technical measures, including automated tools or other suitable mechanisms, shall not amount to a violation of the conditions specified under clauses…"}, "it-rules-2021:rule_2__subrule_2": {"cite": "IT Rules 2021 r.2(2)", "head": "", "text": "Words and expressions used and not defined in these rules but defined in the Act and rules made thereunder shall have the same meaning as assigned to them in the Act and the said rules, as the case may be."}, "it-rules-2021:part_II": {"cite": "IT Rules 2021 Part II", "head": "DUE DILIGENCE BY INTERMEDIARIES AND GRIEVANCE REDRESSAL MECHANISM", "text": "Due diligence by an intermediary: An intermediary, including a social media intermediary, a significant social media intermediary and an online gaming intermediary, shall observe the following due diligence while discharging its duties, namely:— the intermediary shall prominently publish on its website, mobile based application or both, as the case may be, the rules and regulations, privacy policy and user agreement in English or any language specified in the Eighth Schedule to the Constitution for access or usage of its computer resource by any person in the language of his choice and ensure …"}, "it-rules-2021:rule_3": {"cite": "IT Rules 2021 r.3", "head": "", "text": "Due diligence by an intermediary: An intermediary, including a social media intermediary, a significant social media intermediary and an online gaming intermediary, shall observe the following due diligence while discharging its duties, namely:— the intermediary shall prominently publish on its website, mobile based application or both, as the case may be, the rules and regulations, privacy policy and user agreement in English or any language specified in the Eighth Schedule to the Constitution for access or usage of its computer resource by any person in the language of his choice and ensure …"}, "it-rules-2021:rule_3__subrule_1": {"cite": "IT Rules 2021 r.3(1)", "head": "", "text": "Due diligence by an intermediary: An intermediary, including a social media intermediary, a significant social media intermediary and an online gaming intermediary, shall observe the following due diligence while discharging its duties, namely:— the intermediary shall prominently publish on its website, mobile based application or both, as the case may be, the rules and regulations, privacy policy and user agreement in English or any language specified in the Eighth Schedule to the Constitution for access or usage of its computer resource by any person in the language of his choice and ensure …"}, "it-rules-2021:rule_3__subrule_1__cl_a": {"cite": "IT Rules 2021 r.3(1)(a)", "head": "", "text": "the intermediary shall prominently publish on its website, mobile based application or both, as the case may be, the rules and regulations, privacy policy and user agreement in English or any language specified in the Eighth Schedule to the Constitution for access or usage of its computer resource by any person in the language of his choice and ensure compliance of the same;"}, "it-rules-2021:rule_3__subrule_1__cl_b": {"cite": "IT Rules 2021 r.3(1)(b)", "head": "", "text": "the intermediary shall inform its rules and regulations, privacy policy and user agreement to the user in English or any language specified in the Eighth Schedule to the Constitution in the language of his choice and shall make reasonable efforts by itself, and to cause the users of its computer resource to not host display, upload, modify, publish, transmit, store, update or share any information that, belongs to another person and to which the user does not have any right; is obscene, pornographic, paedophilic, invasive of another’s privacy including bodily privacy, insulting or harassing on…"}, "it-rules-2021:rule_3__subrule_1__cl_b__subcl_i": {"cite": "IT Rules 2021 r.3(1)(b)(i)", "head": "", "text": "belongs to another person and to which the user does not have any right;"}, "it-rules-2021:rule_3__subrule_1__cl_b__subcl_ii": {"cite": "IT Rules 2021 r.3(1)(b)(ii)", "head": "", "text": "is obscene, pornographic, paedophilic, invasive of another’s privacy including bodily privacy, insulting or harassing on the basis of gender, racially or ethnically objectionable, relating or encouraging money laundering or gambling, or an online game that causes user harm, or promoting enmity between different groups on the grounds of religion or caste with the intent to incite violence;"}, "it-rules-2021:rule_3__subrule_1__cl_b__subcl_iii": {"cite": "IT Rules 2021 r.3(1)(b)(iii)", "head": "", "text": "is harmful to child;"}, "it-rules-2021:rule_3__subrule_1__cl_b__subcl_iv": {"cite": "IT Rules 2021 r.3(1)(b)(iv)", "head": "", "text": "infringes any patent, trademark, copyright or other proprietary rights;"}, "it-rules-2021:rule_3__subrule_1__cl_b__subcl_v": {"cite": "IT Rules 2021 r.3(1)(b)(v)", "head": "", "text": "deceives or misleads the addressee about the origin of the message or knowingly and intentionally communicates any misinformation or information which is patently false and untrue or misleading in nature or, in respect of any business of the Central Government, is identified as fake or false or misleading by such fact check unit of the Central Government as the Ministry may, by notification published in the Official Gazette, specify;"}, "it-rules-2021:rule_3__subrule_1__cl_b__subcl_vi": {"cite": "IT Rules 2021 r.3(1)(b)(vi)", "head": "", "text": "impersonates another person;"}, "it-rules-2021:rule_3__subrule_1__cl_b__subcl_vii": {"cite": "IT Rules 2021 r.3(1)(b)(vii)", "head": "", "text": "threatens the unity, integrity, defence, security or sovereignty of India, friendly relations with foreign States, or public order, or causes incitement to the commission of any cognisable offence, or prevents investigation of any offence, or is insulting other nation;"}, "it-rules-2021:rule_3__subrule_1__cl_b__subcl_viii": {"cite": "IT Rules 2021 r.3(1)(b)(viii)", "head": "", "text": "contains software virus or any other computer code, file or program designed to interrupt, destroy or limit the functionality of any computer resource;"}, "it-rules-2021:rule_3__subrule_1__cl_b__subcl_ix": {"cite": "IT Rules 2021 r.3(1)(b)(ix)", "head": "", "text": "is in the nature of an online game that is not verified as a permissible online game;"}, "it-rules-2021:rule_3__subrule_1__cl_b__subcl_x": {"cite": "IT Rules 2021 r.3(1)(b)(x)", "head": "", "text": "is in the nature of advertisement or surrogate advertisement or promotion of an online game that is not a permissible online game, or of any online gaming intermediary offering such an online game;"}, "it-rules-2021:rule_3__subrule_1__cl_b__subcl_xi": {"cite": "IT Rules 2021 r.3(1)(b)(xi)", "head": "", "text": "violates any law for the time being in force."}, "it-rules-2021:rule_3__subrule_1__cl_b__hcontainer_1": {"cite": "IT Rules 2021 r.3(1)(b)", "head": "", "text": "In this clause, “user harm” and “harm” mean any effect which is detrimental to a user or child, as the case may be;"}, "it-rules-2021:rule_3__subrule_1__cl_c": {"cite": "IT Rules 2021 r.3(1)(c)", "head": "", "text": "an intermediary shall periodically inform its users, at least once every three months, in a simple and effective manner through its rules and regulations, privacy policy, user agreement, or any other appropriate means, in English or any language specified in the Eighth Schedule to the Constitution, that— in case of non-compliance with such rules and regulations, privacy policy or user agreement, by whatever name called, it has the right to terminate or suspend the access or usage rights of the users to the computer resource immediately, or to remove or disable access to non-compliant informati…"}, "it-rules-2021:rule_3__subrule_1__cl_c__subcl_i": {"cite": "IT Rules 2021 r.3(1)(c)(i)", "head": "", "text": "in case of non-compliance with such rules and regulations, privacy policy or user agreement, by whatever name called, it has the right to terminate or suspend the access or usage rights of the users to the computer resource immediately, or to remove or disable access to non-compliant information, or both, as the case may be;"}, "it-rules-2021:rule_3__subrule_1__cl_c__subcl_ii": {"cite": "IT Rules 2021 r.3(1)(c)(ii)", "head": "", "text": "where such non-compliance relates to the creation, generation, modification, alteration, hosting, displaying, uploading, publishing, transmitting, storing, updating, sharing or otherwise disseminating of information in contravention of any law for the time being in force, the user who is responsible for such non-compliance may be liable to penalty or punishment under the provisions of the Act or any other applicable law; and"}, "it-rules-2021:rule_3__subrule_1__cl_c__subcl_iii": {"cite": "IT Rules 2021 r.3(1)(c)(iii)", "head": "", "text": "where such violation relates to the commission of an offence under any law for the time being in force, such as the Bharatiya Nyaya Sanhita, 2023 (45 of 2023) read with the Bharatiya Nagarik Suraksha Sanhita, 2023 (46 of 2023) or the Protection of Children from Sexual Offences Act, 2012 (32 of 2012) which requires such offence to be mandatorily reported, reporting of such offence to the appropriate authority in accordance with the provisions of the applicable law;"}, "it-rules-2021:rule_3__subrule_1__cl_ca": {"cite": "IT Rules 2021 r.3(1)(ca)", "head": "", "text": "without prejudice to sub-clauses (i) and (ii) of clause (c), where an intermediary referred to under sub-rule (3) offers a computer resource which enables, permits or facilitates the creation, generation, modification, alteration, publication, transmission, sharing, or dissemination of information as synthetically generated information, such intermediary shall additionally inform its users that— directing, instructing or otherwise causing the computer resource of the intermediary for creation, generation, modification, alteration publication, transmission, sharing, or dissemination of informat…"}, "it-rules-2021:rule_3__subrule_1__cl_ca__subcl_i": {"cite": "IT Rules 2021 r.3(1)(ca)(i)", "head": "", "text": "directing, instructing or otherwise causing the computer resource of the intermediary for creation, generation, modification, alteration publication, transmission, sharing, or dissemination of information as synthetically generated information in contravention of sub-clause (i) of clause (a) of sub-rule (3) may attract penalty or punishment as may be applicable under any law for the time being in force, including the provisions of the Act, the Bharatiya Nyaya Sanhita, 2023 (45 of 2023), the Protection of Children from Sexual Offences Act, 2012 (32 of 2012), the Representation of the People Act…"}, "it-rules-2021:rule_3__subrule_1__cl_ca__subcl_ii": {"cite": "IT Rules 2021 r.3(1)(ca)(ii)", "head": "", "text": "any such contravention of sub-clause (i) of clause (a) of sub-rule (3) may lead to— the immediate disabling of access to or removal of such information; suspension or termination of the user account of the user who violates this sub-rule without vitiating the evidence; in accordance with applicable law, identification of such user and disclosure of the identity of the violating user to the complainant, where such complainant is a victim of, or an individual acting on behalf of a victim of, such contravention; and where such violation relates to the commission of an offence under any law for th…"}, "it-rules-2021:rule_3__subrule_1__cl_ca__subcl_ii__point_I": {"cite": "IT Rules 2021 r.3(1)(ca)(ii)(I)", "head": "", "text": "the immediate disabling of access to or removal of such information;"}, "it-rules-2021:rule_3__subrule_1__cl_ca__subcl_ii__point_II": {"cite": "IT Rules 2021 r.3(1)(ca)(ii)(II)", "head": "", "text": "suspension or termination of the user account of the user who violates this sub-rule without vitiating the evidence;"}, "it-rules-2021:rule_3__subrule_1__cl_ca__subcl_ii__point_III": {"cite": "IT Rules 2021 r.3(1)(ca)(ii)(III)", "head": "", "text": "in accordance with applicable law, identification of such user and disclosure of the identity of the violating user to the complainant, where such complainant is a victim of, or an individual acting on behalf of a victim of, such contravention; and"}, "it-rules-2021:rule_3__subrule_1__cl_ca__subcl_ii__point_IV": {"cite": "IT Rules 2021 r.3(1)(ca)(ii)(IV)", "head": "", "text": "where such violation relates to the commission of an offence under any law for the time being in force, including the Bharatiya Nyaya Sanhita, 2023 (45 of 2023) read with the Bharatiya Nagarik Suraksha Sanhita, 2023 (46 of 2023) or the Protection of Children from Sexual Offences Act, 2012 (32 of 2012) which requires such offence to be mandatorily reported, reporting of such offence to the appropriate authority in accordance with the provisions of the applicable law;"}, "it-rules-2021:rule_3__subrule_1__cl_cb": {"cite": "IT Rules 2021 r.3(1)(cb)", "head": "", "text": "where an intermediary becomes aware, either on its own accord or upon receipt of actual knowledge or on the basis of any grievance, complaint or information received under these rules, of any violation of sub-rule (3), in relation to the creation, generation, modification, alteration, hosting, displaying, uploading, publishing, transmitting, storing, updating, sharing or otherwise dissemination of information as synthetically generated information covered under sub-clause (ii) of clause (a), it shall take expeditious and appropriate action, including those specified in sub-clause (ii) of claus…"}, "it-rules-2021:rule_3__subrule_1__cl_d": {"cite": "IT Rules 2021 r.3(1)(d)", "head": "", "text": "an intermediary, on whose computer resource the information which is used to commit an unlawful act which is prohibited under any law for the time being in force in relation to the interest of the sovereignty and integrity of India; security of the State; friendly relations with foreign States; public order; decency or morality; in relation to contempt of court; defamation; incitement to an offence relating to the above, or any information which is prohibited under any law for the time being in force is hosted, displayed, published, transmitted or stored shall, upon receiving the actual knowle…"}, "it-rules-2021:rule_3__subrule_1__cl_d__subcl_i": {"cite": "IT Rules 2021 r.3(1)(d)(i)", "head": "", "text": "by an order of a court of competent jurisdiction; or"}, "it-rules-2021:rule_3__subrule_1__cl_d__subcl_ii": {"cite": "IT Rules 2021 r.3(1)(d)(ii)", "head": "", "text": "a reasoned intimation, in writing,— issued by an officer authorised, by order in writing, for the purpose of issuing such intimation by the Appropriate Government or its agency, being not below the rank of Joint Secretary or an officer equivalent in rank or where an officer at such rank is not appointed, a Director or an officer equivalent in rank, to the Government of India or to the State Government, as the case may be, and, where so authorised, acting through a single corresponding officer in its authorised agency, where such agency is so appointed: Provided that where such intimation is to…"}, "it-rules-2021:rule_3__subrule_1__cl_d__subcl_ii__point_I": {"cite": "IT Rules 2021 r.3(1)(d)(ii)(I)", "head": "", "text": "issued by an officer authorised, by order in writing, for the purpose of issuing such intimation by the Appropriate Government or its agency, being not below the rank of Joint Secretary or an officer equivalent in rank or where an officer at such rank is not appointed, a Director or an officer equivalent in rank, to the Government of India or to the State Government, as the case may be, and, where so authorised, acting through a single corresponding officer in its authorised agency, where such agency is so appointed: Provided that where such intimation is to be issued by the police administrat…"}, "it-rules-2021:rule_3__subrule_1__cl_d__subcl_ii__point_I__proviso_1": {"cite": "IT Rules 2021 r.3(1)(d)(ii)(I)", "head": "", "text": "Provided that where such intimation is to be issued by the police administration, there may be one or more authorised officers, each not below the rank of Deputy Inspector General of Police, especially authorised by the Appropriate Government in this behalf:"}, "it-rules-2021:rule_3__subrule_1__cl_d__subcl_ii__point_I__proviso_2": {"cite": "IT Rules 2021 r.3(1)(d)(ii)(I)", "head": "", "text": "Provided further that all such intimations shall be subject to periodic review by an officer not below the rank of the Secretary of the concerned Appropriate Government once in every month to ensure that such intimations are necessary, proportionate, and consistent with clause (b) of sub-section (3) of section 79 of the Act and this clause;"}, "it-rules-2021:rule_3__subrule_1__cl_d__subcl_ii__point_II": {"cite": "IT Rules 2021 r.3(1)(d)(ii)(II)", "head": "", "text": "clearly specifying the legal basis and statutory provision invoked, the nature of the unlawful act, and the specific uniform resource locator, identifier or other electronic location of the information, data or communication link required to be removed or disabled;"}, "it-rules-2021:rule_3__subrule_1__cl_e": {"cite": "IT Rules 2021 r.3(1)(e)", "head": "", "text": "the temporary or transient or intermediate storage of information automatically by an intermediary in a computer resource within its control as an intrinsic feature of that computer resource, involving no exercise of any human, automated or algorithmic editorial control for onward transmission or communication to another computer resource shall not amount to hosting, storing or publishing any information referred to under clause (d);"}, "it-rules-2021:rule_3__subrule_1__cl_f": {"cite": "IT Rules 2021 r.3(1)(f)", "head": "", "text": "the intermediary shall periodically, and at least once in a year, inform its users in English or any language specified in the Eighth Schedule to the Constitution in the language of his choice of its rules and regulations, privacy policy or user agreement or any change in the rules and regulations, privacy policy or user agreement, as the case may be; Provided that an online gaming intermediary who enables the users to access any permissible online real money game shall inform its users of such change as soon as possible, but not later than twenty-four hours after the change is effected;"}, "it-rules-2021:rule_3__subrule_1__cl_f__proviso_1": {"cite": "IT Rules 2021 r.3(1)(f)", "head": "", "text": "Provided that an online gaming intermediary who enables the users to access any permissible online real money game shall inform its users of such change as soon as possible, but not later than twenty-four hours after the change is effected;"}, "it-rules-2021:rule_3__subrule_1__cl_g": {"cite": "IT Rules 2021 r.3(1)(g)", "head": "", "text": "where upon receiving actual knowledge under clause (d), on a voluntary basis on violation of clause (b), or on the basis of grievances received under sub-rule (2), any information has been removed or access to which has been disabled, the intermediary shall, without vitiating the evidence in any manner, preserve such information and associated records for one hundred and eighty days for investigation purposes, or for such longer period as may be required by the court or by Government agencies who are lawfully authorised;"}, "it-rules-2021:rule_3__subrule_1__cl_h": {"cite": "IT Rules 2021 r.3(1)(h)", "head": "", "text": "where an intermediary collects information from a user for registration on the computer resource, it shall retain his information for a period of one hundred and eighty days after any cancellation or withdrawal of his registration, as the case may be;"}, "it-rules-2021:rule_3__subrule_1__cl_i": {"cite": "IT Rules 2021 r.3(1)(i)", "head": "", "text": "the intermediary shall take all reasonable measures to secure its computer resource and information contained therein following the reasonable security practices and procedures as prescribed in the Information Technology (Reasonable Security Practices and Procedures and Sensitive Personal Information) Rules, 2011;"}, "it-rules-2021:rule_3__subrule_1__cl_j": {"cite": "IT Rules 2021 r.3(1)(j)", "head": "", "text": "the intermediary shall, as soon as possible, but not later than seventy two hours and in case of an online gaming intermediary who enables the users to access any permissible online real money game not later than twenty-four hours of the receipt of an order, provide information under its control or possession, or assistance to the Government agency which is lawfully authorised for investigative or protective or cyber security activities, for the purposes of verification of identity, or for the prevention, detection, investigation, or prosecution, of offences under any law for the time being in…"}, "it-rules-2021:rule_3__subrule_1__cl_j__proviso_1": {"cite": "IT Rules 2021 r.3(1)(j)", "head": "", "text": "Provided that any such order shall be in writing stating clearly the purpose of seeking information or assistance, as the case may be;"}, "it-rules-2021:rule_3__subrule_1__cl_k": {"cite": "IT Rules 2021 r.3(1)(k)", "head": "", "text": "the intermediary shall not knowingly deploy or install or modify technical configuration of computer resource or become party to any act that may change or has the potential to change the normal course of operation of the computer resource than what it is supposed to perform thereby circumventing any law for the time being in force: Provided that the intermediary may develop, produce, distribute or employ technological means for the purpose of performing the acts of securing the computer resource and information contained therein;"}, "it-rules-2021:rule_3__subrule_1__cl_k__proviso_1": {"cite": "IT Rules 2021 r.3(1)(k)", "head": "", "text": "Provided that the intermediary may develop, produce, distribute or employ technological means for the purpose of performing the acts of securing the computer resource and information contained therein;"}, "it-rules-2021:rule_3__subrule_1__cl_l": {"cite": "IT Rules 2021 r.3(1)(l)", "head": "", "text": "the intermediary shall report cyber security incidents and share related information with the Indian Computer Emergency Response Team in accordance with the policies and procedures as mentioned in the Information Technology (The Indian Computer Emergency Response Team and Manner of Performing Functions and Duties) Rules, 2013."}, "it-rules-2021:rule_3__subrule_1__cl_m": {"cite": "IT Rules 2021 r.3(1)(m)", "head": "", "text": "the intermediary shall take all reasonable measures to ensure accessibility of its services to users along with reasonable expectation of due diligence, privacy and transparency;"}, "it-rules-2021:rule_3__subrule_1__cl_n": {"cite": "IT Rules 2021 r.3(1)(n)", "head": "", "text": "the intermediary shall respect all the rights accorded to the citizens under the Constitution, including in the articles 14, 19 and 21."}, "it-rules-2021:rule_3__subrule_2": {"cite": "IT Rules 2021 r.3(2)", "head": "", "text": "Grievance redressal mechanism of intermediary: The intermediary shall prominently publish on its website, mobile based application or both, as the case may be, the name of the Grievance Officer and his contact details as well as mechanism by which a user or a victim may make complaint against violation of the provisions of this rule or sub-rules (11) to (13) of rule 4, or in respect of any other matters pertaining to the computer resources made available by it, and the Grievance Officer shall - acknowledge the complaint within twenty-four hours and resolve such complaint within a period of sev…"}, "it-rules-2021:rule_3__subrule_2__cl_a": {"cite": "IT Rules 2021 r.3(2)(a)", "head": "", "text": "The intermediary shall prominently publish on its website, mobile based application or both, as the case may be, the name of the Grievance Officer and his contact details as well as mechanism by which a user or a victim may make complaint against violation of the provisions of this rule or sub-rules (11) to (13) of rule 4, or in respect of any other matters pertaining to the computer resources made available by it, and the Grievance Officer shall - acknowledge the complaint within twenty-four hours and resolve such complaint within a period of seven days from the date of its receipt: Provided …"}, "it-rules-2021:rule_3__subrule_2__cl_a__subcl_i": {"cite": "IT Rules 2021 r.3(2)(a)(i)", "head": "", "text": "acknowledge the complaint within twenty-four hours and resolve such complaint within a period of seven days from the date of its receipt: Provided that the complaint in the nature of request for removal of information or communication link relating to clause (b) of sub-rule (1) of rule 3, except sub-clauses (i), (iv) and (xi), shall be acted upon as expeditiously as possible and shall be resolved within thirty-six hours of such reporting; Provided further that appropriate safeguards may be developed by the intermediary to avoid any misuse by users;"}, "it-rules-2021:rule_3__subrule_2__cl_a__subcl_i__proviso_1": {"cite": "IT Rules 2021 r.3(2)(a)(i)", "head": "", "text": "Provided that the complaint in the nature of request for removal of information or communication link relating to clause (b) of sub-rule (1) of rule 3, except sub-clauses (i), (iv) and (xi), shall be acted upon as expeditiously as possible and shall be resolved within thirty-six hours of such reporting;"}, "it-rules-2021:rule_3__subrule_2__cl_a__subcl_i__proviso_2": {"cite": "IT Rules 2021 r.3(2)(a)(i)", "head": "", "text": "Provided further that appropriate safeguards may be developed by the intermediary to avoid any misuse by users;"}, "it-rules-2021:rule_3__subrule_2__cl_a__subcl_ii": {"cite": "IT Rules 2021 r.3(2)(a)(ii)", "head": "", "text": "receive and acknowledge any order, notice or direction issued by the Appropriate Government, any competent authority or a court of competent jurisdiction."}, "it-rules-2021:rule_3__subrule_2__cl_a__hcontainer_1": {"cite": "IT Rules 2021 r.3(2)(a)", "head": "", "text": "In this rule, “prominently publish” shall mean publishing in a clearly visible manner on the home page of the website or the home screen of the mobile based application, or both, as the case may be, or on a web page or an app screen directly accessible from the home page or home screen."}, "it-rules-2021:rule_3__subrule_2__cl_b": {"cite": "IT Rules 2021 r.3(2)(b)", "head": "", "text": "The intermediary shall, within two hours from the receipt of a complaint made by an individual or any person on his behalf under this sub-rule, in relation to any content which is prima facie in the nature of any material which exposes the private area of such individual, shows such individual in full or partial nudity or shows or depicts such individual in any sexual act or conduct, or is in the nature of impersonation in an electronic form, including artificially morphed images of such individual, take all reasonable and practicable measures to remove or disable access to such content which …"}, "it-rules-2021:rule_3__subrule_2__cl_c": {"cite": "IT Rules 2021 r.3(2)(c)", "head": "", "text": "The intermediary shall implement a mechanism for the receipt of complaints under clause (b) of this sub-rule which may enable the individual or person to provide details, as may be necessary, in relation to such content or communication link."}, "it-rules-2021:rule_3__subrule_3": {"cite": "IT Rules 2021 r.3(3)", "head": "", "text": "Due diligence in relation to synthetically generated information: Where an intermediary offers a computer resource which may enable, permit, or facilitate the creation, generation, modification, alteration, publication, transmission, sharing, or dissemination of information as synthetically generated information, it shall ensure that,— it deploys reasonable and appropriate technical measures, including automated tools or other suitable mechanisms, to not allow any user to create, generate, modify, alter, publish, transmit, share, or disseminate, as the case may be, any such synthetically gener…"}, "it-rules-2021:rule_3__subrule_3__cl_a": {"cite": "IT Rules 2021 r.3(3)(a)", "head": "", "text": "Where an intermediary offers a computer resource which may enable, permit, or facilitate the creation, generation, modification, alteration, publication, transmission, sharing, or dissemination of information as synthetically generated information, it shall ensure that,— it deploys reasonable and appropriate technical measures, including automated tools or other suitable mechanisms, to not allow any user to create, generate, modify, alter, publish, transmit, share, or disseminate, as the case may be, any such synthetically generated information that violates any law for the time being in force…"}, "it-rules-2021:rule_3__subrule_3__cl_a__subcl_i": {"cite": "IT Rules 2021 r.3(3)(a)(i)", "head": "", "text": "it deploys reasonable and appropriate technical measures, including automated tools or other suitable mechanisms, to not allow any user to create, generate, modify, alter, publish, transmit, share, or disseminate, as the case may be, any such synthetically generated information that violates any law for the time being in force, including the Act, Bharatiya Nyaya Sanhita, 2023 (45 of 2023), Protection of Children from Sexual Offences Act, 2012 (32 of 2012), Explosive Substances Act, 1908 (6 of 1908), and includes any such synthetically generated information that,— contains child sexual exploita…"}, "it-rules-2021:rule_3__subrule_3__cl_a__subcl_i__point_I": {"cite": "IT Rules 2021 r.3(3)(a)(i)(I)", "head": "", "text": "contains child sexual exploitative and abuse material, non-consensual intimate imagery content, or is obscene, pornographic, paedophilic, invasive of another person’s privacy, including bodily privacy, vulgar, indecent or sexually explicit; or"}, "it-rules-2021:rule_3__subrule_3__cl_a__subcl_i__point_II": {"cite": "IT Rules 2021 r.3(3)(a)(i)(II)", "head": "", "text": "results in the creation, generation, modification or alteration of any false document or false electronic record; or"}, "it-rules-2021:rule_3__subrule_3__cl_a__subcl_i__point_III": {"cite": "IT Rules 2021 r.3(3)(a)(i)(III)", "head": "", "text": "relates to the preparation, development or procurement of explosive material, arms or ammunition; or"}, "it-rules-2021:rule_3__subrule_3__cl_a__subcl_i__point_IV": {"cite": "IT Rules 2021 r.3(3)(a)(i)(IV)", "head": "", "text": "falsely depicts or portrays a natural person or real-world event by misrepresenting, in a manner that is likely to deceive, such person’s identity, voice, conduct, action, statement, or such event as having occurred, with or without the involvement of natural person; and"}, "it-rules-2021:rule_3__subrule_3__cl_a__subcl_ii": {"cite": "IT Rules 2021 r.3(3)(a)(ii)", "head": "", "text": "every such information not covered under sub-clause (i) of clause (a) is prominently labelled in a manner that ensures prominent visibility in the visual display that is easily noticeable and adequately perceivable, or, in the case of audio content, through a prominently prefixed audio disclosure, that can be used to immediately identify that such information is synthetically generated information which has been created, generated, modified or altered using a computer resource and such information shall be embedded with a permanent metadata or other appropriate technical provenance mechanisms,…"}, "it-rules-2021:rule_3__subrule_3__cl_b": {"cite": "IT Rules 2021 r.3(3)(b)", "head": "", "text": "the intermediary shall not enable the modification, suppression or removal of the label, permanent metadata, including the unique identifier, displayed or embedded in accordance with sub-clause (ii) of clause (a)."}, "it-rules-2021:rule_3A": {"cite": "IT Rules 2021 r.3A", "head": "Appeal to Grievance Appellate Committee(s)", "text": "The Central Government shall, by notification, establish one or more Grievance Appellate Committees within three months from the date of commencement of the Information Technology (Intermediary Guidelines and Digital Media Ethics Code) Amendment Rules, 2022. Each Grievance Appellate Committee shall consist of a chairperson and two whole time members appointed by the Central Government, of which one shall be a member ex-officio and two shall be independent members. Any person who is aggrieved by a decision of the Grievance Officer or whose grievance is not resolved within the period specified f…"}, "it-rules-2021:rule_3A__subrule_1": {"cite": "IT Rules 2021 r.3A(1)", "head": "", "text": "The Central Government shall, by notification, establish one or more Grievance Appellate Committees within three months from the date of commencement of the Information Technology (Intermediary Guidelines and Digital Media Ethics Code) Amendment Rules, 2022."}, "it-rules-2021:rule_3A__subrule_2": {"cite": "IT Rules 2021 r.3A(2)", "head": "", "text": "Each Grievance Appellate Committee shall consist of a chairperson and two whole time members appointed by the Central Government, of which one shall be a member ex-officio and two shall be independent members."}, "it-rules-2021:rule_3A__subrule_3": {"cite": "IT Rules 2021 r.3A(3)", "head": "", "text": "Any person who is aggrieved by a decision of the Grievance Officer or whose grievance is not resolved within the period specified for resolution in sub-clause (i) of clause (a) of sub-rule (2) of rule 3 or clause (b) of sub-rule (2) of rule 3 or sub-rule (11) of rule 4A, as the case may be, may prefer an appeal to the Grievance Appellate Committee within a period of thirty days from the date of receipt of communication from the Grievance Officer."}, "it-rules-2021:rule_3A__subrule_4": {"cite": "IT Rules 2021 r.3A(4)", "head": "", "text": "The Grievance Appellate Committee shall deal with such appeal expeditiously and shall make an endeavour to resolve the appeal finally within thirty calendar days from the date of receipt of the appeal."}, "it-rules-2021:rule_3A__subrule_5": {"cite": "IT Rules 2021 r.3A(5)", "head": "", "text": "While dealing with the appeal if the Grievance Appellate Committee feels necessary, it may seek assistance from any person having requisite qualification, experience and expertise in the subject matter."}, "it-rules-2021:rule_3A__subrule_6": {"cite": "IT Rules 2021 r.3A(6)", "head": "", "text": "The Grievance Appellate Committee shall adopt an online dispute resolution mechanism wherein the entire appeal process, from filing of appeal to the decision thereof, shall be conducted through digital mode."}, "it-rules-2021:rule_3A__subrule_7": {"cite": "IT Rules 2021 r.3A(7)", "head": "", "text": "Every order passed by the Grievance Appellate Committee shall be complied with by the intermediary concerned or the online gaming self-regulatory body concerned, as the case may be, and a report to that effect shall be uploaded on its website."}, "it-rules-2021:rule_4": {"cite": "IT Rules 2021 r.4", "head": "Additional due diligence to be observed by significant social media intermediary and online gaming intermediary", "text": "In addition to the due diligence observed under rule 3, a significant social media intermediary, within three months from the date of notification of the threshold under clause (v) of sub-rule (1) of rule 2, and an online gaming intermediary that enables the users to access any permissible online real money game, shall observe the following additional due diligence while discharging its duties, namely:— appoint a Chief Compliance Officer who shall be responsible for ensuring compliance with the Act and rules made thereunder and shall be liable in any proceedings relating to any relevant third-…"}, "it-rules-2021:rule_4__subrule_1": {"cite": "IT Rules 2021 r.4(1)", "head": "", "text": "In addition to the due diligence observed under rule 3, a significant social media intermediary, within three months from the date of notification of the threshold under clause (v) of sub-rule (1) of rule 2, and an online gaming intermediary that enables the users to access any permissible online real money game, shall observe the following additional due diligence while discharging its duties, namely:— appoint a Chief Compliance Officer who shall be responsible for ensuring compliance with the Act and rules made thereunder and shall be liable in any proceedings relating to any relevant third-…"}, "it-rules-2021:rule_4__subrule_1__cl_a": {"cite": "IT Rules 2021 r.4(1)(a)", "head": "", "text": "appoint a Chief Compliance Officer who shall be responsible for ensuring compliance with the Act and rules made thereunder and shall be liable in any proceedings relating to any relevant third-party information, data or communication link made available or hosted by that intermediary where he fails to ensure that such intermediary observes due diligence while discharging its duties under the Act and rules made thereunder: Provided that no liability under the Act or rules made thereunder may be imposed on such significant social media intermediary or such online gaming intermediary without bein…"}, "it-rules-2021:rule_4__subrule_1__cl_a__proviso_1": {"cite": "IT Rules 2021 r.4(1)(a)", "head": "", "text": "Provided that no liability under the Act or rules made thereunder may be imposed on such significant social media intermediary or such online gaming intermediary without being given an opportunity of being heard."}, "it-rules-2021:rule_4__subrule_1__cl_a__hcontainer_1": {"cite": "IT Rules 2021 r.4(1)(a)", "head": "", "text": "For the purposes of this clause “Chief Compliance Officer” means a key managerial personnel or such other senior employee of a significant social media intermediary or an online gaming intermediary, as the case may be, who is resident in India;"}, "it-rules-2021:rule_4__subrule_1__cl_b": {"cite": "IT Rules 2021 r.4(1)(b)", "head": "", "text": "appoint a nodal contact person for 24x7 coordination with law enforcement agencies and officers to ensure compliance to their orders or requisitions made in accordance with the provisions of law or rules made thereunder. In this clause, “nodal contact person” means the employee of— a significant social media intermediary, other than its Chief Compliance Officer; or an online gaming intermediary, who is resident in India;"}, "it-rules-2021:rule_4__subrule_1__cl_b__hcontainer_1": {"cite": "IT Rules 2021 r.4(1)(b)", "head": "", "text": "In this clause, “nodal contact person” means the employee of— a significant social media intermediary, other than its Chief Compliance Officer; or an online gaming intermediary, who is resident in India;"}, "it-rules-2021:rule_4__subrule_1__cl_b__hcontainer_1__subcl_i": {"cite": "IT Rules 2021 r.4(1)(b)(i)", "head": "", "text": "a significant social media intermediary, other than its Chief Compliance Officer; or"}, "it-rules-2021:rule_4__subrule_1__cl_b__hcontainer_1__subcl_ii": {"cite": "IT Rules 2021 r.4(1)(b)(ii)", "head": "", "text": "an online gaming intermediary, who is resident in India;"}, "it-rules-2021:rule_4__subrule_1__cl_c": {"cite": "IT Rules 2021 r.4(1)(c)", "head": "", "text": "appoint a Resident Grievance Officer, who shall, subject to clause (b), be responsible for the functions referred to in sub-rule (2) of rule 3. For the purposes of this clause, “Resident Grievance Officer” means the employee of a significant social media intermediary or an online gaming intermediary, as the case may be, who is resident in India;"}, "it-rules-2021:rule_4__subrule_1__cl_c__hcontainer_1": {"cite": "IT Rules 2021 r.4(1)(c)", "head": "", "text": "For the purposes of this clause, “Resident Grievance Officer” means the employee of a significant social media intermediary or an online gaming intermediary, as the case may be, who is resident in India;"}, "it-rules-2021:rule_4__subrule_1__cl_d": {"cite": "IT Rules 2021 r.4(1)(d)", "head": "", "text": "publish periodic compliance report every month mentioning the details of complaints received and action taken thereon, and, in respect of a significant social media intermediary, the number of specific communication links or parts of information that the intermediary has removed or disabled access to in pursuance of any proactive monitoring conducted by using automated tools or any other relevant information as may be specified;"}, "it-rules-2021:rule_4__subrule_1A": {"cite": "IT Rules 2021 r.4(1A)", "head": "", "text": "A significant social media intermediary which enables displaying, uploading, or publishing any information on its computer resource shall, prior to such display, uploading, or publication,— require users to declare whether such information is synthetically generated information; deploy appropriate technical measures, including automated tools or other suitable mechanisms, to verify the accuracy of such declaration, having regard to the nature, format, and source of such information; and where such declaration or technical verification confirms that the information is synthetically generated, e…"}, "it-rules-2021:rule_4__subrule_1A__cl_a": {"cite": "IT Rules 2021 r.4(1A)(a)", "head": "", "text": "require users to declare whether such information is synthetically generated information;"}, "it-rules-2021:rule_4__subrule_1A__cl_b": {"cite": "IT Rules 2021 r.4(1A)(b)", "head": "", "text": "deploy appropriate technical measures, including automated tools or other suitable mechanisms, to verify the accuracy of such declaration, having regard to the nature, format, and source of such information; and"}, "it-rules-2021:rule_4__subrule_1A__cl_c": {"cite": "IT Rules 2021 r.4(1A)(c)", "head": "", "text": "where such declaration or technical verification confirms that the information is synthetically generated, ensure that the same is clearly and prominently displayed with an appropriate label or notice, indicating that the content is synthetically generated: Provided that where such intermediary becomes aware, or it is otherwise established, that the intermediary knowingly permitted, promoted, or failed to act upon such synthetically generated information in contravention of these rules, such intermediary shall be deemed to have failed to exercise due diligence under this sub-rule. For the remo…"}, "it-rules-2021:rule_4__subrule_1A__cl_c__proviso_1": {"cite": "IT Rules 2021 r.4(1A)(c)", "head": "", "text": "Provided that where such intermediary becomes aware, or it is otherwise established, that the intermediary knowingly permitted, promoted, or failed to act upon such synthetically generated information in contravention of these rules, such intermediary shall be deemed to have failed to exercise due diligence under this sub-rule."}, "it-rules-2021:rule_4__subrule_1A__cl_c__hcontainer_1": {"cite": "IT Rules 2021 r.4(1A)(c)", "head": "", "text": "For the removal of doubts, it is hereby clarified that the responsibility of the significant social media intermediary shall extend to taking reasonable and proportionate technical measures to verify the correctness of user declarations and to ensure that no synthetically generated information is published without such declaration or label."}, "it-rules-2021:rule_4__subrule_2": {"cite": "IT Rules 2021 r.4(2)", "head": "", "text": "A significant social media intermediary providing services primarily in the nature of messaging shall enable the identification of the first originator of the information on its computer resource as may be required by a judicial order passed by a court of competent jurisdiction or an order passed under section 69 by the Competent Authority as per the Information Technology (Procedure and Safeguards for interception, monitoring and decryption of information) Rules, 2009, which shall be supported with a copy of such information in electronic form: Provided that an order shall only be passed for …"}, "it-rules-2021:rule_4__subrule_2__proviso_1": {"cite": "IT Rules 2021 r.4(2)", "head": "", "text": "Provided that an order shall only be passed for the purposes of prevention, detection, investigation, prosecution or punishment of an offence related to the sovereignty and integrity of India, the security of the State, friendly relations with foreign States, or public order, or of incitement to an offence relating to the above or in relation with rape, sexually explicit material or child sexual abuse material, punishable with imprisonment for a term of not less than five years:"}, "it-rules-2021:rule_4__subrule_2__proviso_2": {"cite": "IT Rules 2021 r.4(2)", "head": "", "text": "Provided further that no order shall be passed in cases where other less intrusive means are effective in identifying the originator of the information:"}, "it-rules-2021:rule_4__subrule_2__proviso_3": {"cite": "IT Rules 2021 r.4(2)", "head": "", "text": "Provided also that in complying with an order for identification of the first originator, no significant social media intermediary shall be required to disclose the contents of any electronic message, any other information related to the first originator, or any information related to its other users:"}, "it-rules-2021:rule_4__subrule_2__proviso_4": {"cite": "IT Rules 2021 r.4(2)", "head": "", "text": "Provided also that where the first originator of any information on the computer resource of an intermediary is located outside the territory of India, the first originator of that information within the territory of India shall be deemed to be the first originator of the information for the purpose of this clause."}, "it-rules-2021:rule_4__subrule_3": {"cite": "IT Rules 2021 r.4(3)", "head": "", "text": "A significant social media intermediary that provides any service with respect to an information or transmits that information on behalf of another person on its computer resource– for direct financial benefit in a manner that increases its visibility or prominence, or targets the receiver of that information; or to which it owns a copyright, or has an exclusive license, or in relation with which it has entered into any contract that directly or indirectly restricts the publication or transmission of that information through any means other than those provided through the computer resource of …"}, "it-rules-2021:rule_4__subrule_3__cl_a": {"cite": "IT Rules 2021 r.4(3)(a)", "head": "", "text": "for direct financial benefit in a manner that increases its visibility or prominence, or targets the receiver of that information; or"}, "it-rules-2021:rule_4__subrule_3__cl_b": {"cite": "IT Rules 2021 r.4(3)(b)", "head": "", "text": "to which it owns a copyright, or has an exclusive license, or in relation with which it has entered into any contract that directly or indirectly restricts the publication or transmission of that information through any means other than those provided through the computer resource of such social media intermediary,"}, "it-rules-2021:rule_4__subrule_4": {"cite": "IT Rules 2021 r.4(4)", "head": "", "text": "A significant social media intermediary shall deploy appropriate technical measures, including automated tools or other suitable mechanisms to proactively identify information that depicts any act or simulation in any form depicting rape, child sexual abuse or conduct, whether explicit or implicit, or any information which is exactly identical in content to information that has previously been removed or access to which has been disabled on the computer resource of such intermediary under clause (d) of sub-rule (1) of rule 3, and shall display a notice to any user attempting to access such inf…"}, "it-rules-2021:rule_4__subrule_4__proviso_1": {"cite": "IT Rules 2021 r.4(4)", "head": "", "text": "Provided that the measures taken by the intermediary under this sub-rule shall be proportionate having regard to the interests of free speech and expression, privacy of users on the computer resource of such intermediary, including interests protected through the appropriate use of technical measures:"}, "it-rules-2021:rule_4__subrule_4__proviso_2": {"cite": "IT Rules 2021 r.4(4)", "head": "", "text": "Provided further that such intermediary shall implement mechanisms for appropriate human oversight of measures deployed under this sub-rule, including a periodic review of any automated tools deployed by such intermediary:"}, "it-rules-2021:rule_4__subrule_4__proviso_3": {"cite": "IT Rules 2021 r.4(4)", "head": "", "text": "Provided also that the review of automated tools under this sub-rule shall evaluate the automated tools having regard to the accuracy and fairness of such tools, the propensity of bias and discrimination in such tools and the impact on privacy and security of such tools."}, "it-rules-2021:rule_4__subrule_5": {"cite": "IT Rules 2021 r.4(5)", "head": "", "text": "A significant social media intermediary and an online gaming intermediary who enables the users to access any permissible online real money game shall have a physical contact address in India published on its website, mobile based application or both, as the case may be, for the purposes of receiving the communication addressed to it."}, "it-rules-2021:rule_4__subrule_6": {"cite": "IT Rules 2021 r.4(6)", "head": "", "text": "A significant social media intermediary and an online gaming intermediary who enables the users to access any permissible online real money game shall implement an appropriate mechanism for the receipt of complaints under sub-rule (2) of rule 3 and grievances in relation to the violation of provisions under this rule, which shall enable the complainant to track the status of such complaint or grievance by providing a unique ticket number for every complaint or grievance received by such intermediary: Provided that such intermediary shall, to the extent reasonable, provide such complainant with…"}, "it-rules-2021:rule_4__subrule_6__proviso_1": {"cite": "IT Rules 2021 r.4(6)", "head": "", "text": "Provided that such intermediary shall, to the extent reasonable, provide such complainant with reasons for any action taken or not taken by such intermediary in pursuance of the complaint or grievance received by it."}, "it-rules-2021:rule_4__subrule_7": {"cite": "IT Rules 2021 r.4(7)", "head": "", "text": "A significant social media intermediary and an online gaming intermediary who enables the users to access any permissible online real money game shall enable users who register for their services from India, or use their services in India, to voluntarily verify their accounts by using any appropriate mechanism, including the active Indian mobile number of such users, and where any user voluntarily verifies their account, such user shall be provided with a demonstrable and visible mark of verification, which shall be visible to all users of the service: Provided that the information received fo…"}, "it-rules-2021:rule_4__subrule_7__proviso_1": {"cite": "IT Rules 2021 r.4(7)", "head": "", "text": "Provided that the information received for the purpose of verification under this sub-rule shall not be used for any other purpose, unless the user expressly consents to such use."}, "it-rules-2021:rule_4__subrule_8": {"cite": "IT Rules 2021 r.4(8)", "head": "", "text": "Where a significant social media intermediary removes or disables access to any information, data or communication link, under clause (b) of sub-rule (1) of rule 3 on its own accord, such intermediary shall,— ensure that prior to the time at which such intermediary removes or disables access, it has provided the user who has created, uploaded, shared, disseminated, or modified information, data or communication link using its services with a notification explaining the action being taken and the grounds or reasons for such action; ensure that the user who has created, uploaded, shared, dissemi…"}, "it-rules-2021:rule_4__subrule_8__cl_a": {"cite": "IT Rules 2021 r.4(8)(a)", "head": "", "text": "ensure that prior to the time at which such intermediary removes or disables access, it has provided the user who has created, uploaded, shared, disseminated, or modified information, data or communication link using its services with a notification explaining the action being taken and the grounds or reasons for such action;"}, "it-rules-2021:rule_4__subrule_8__cl_b": {"cite": "IT Rules 2021 r.4(8)(b)", "head": "", "text": "ensure that the user who has created, uploaded, shared, disseminated, or modified information using its services is provided with an adequate and reasonable opportunity to dispute the action being taken by such intermediary and request for the reinstatement of access to such information, data or communication link, which may be decided within a reasonable time;"}, "it-rules-2021:rule_4__subrule_8__cl_c": {"cite": "IT Rules 2021 r.4(8)(c)", "head": "", "text": "ensure that the Resident Grievance Officer of such intermediary maintains appropriate oversight over the mechanism for resolution of any disputes raised by the user under clause (b)."}, "it-rules-2021:rule_4__subrule_9": {"cite": "IT Rules 2021 r.4(9)", "head": "", "text": "The Ministry may call for such additional information from any significant social media intermediary as it may consider necessary for the purposes of this part."}, "it-rules-2021:rule_4__subrule_10": {"cite": "IT Rules 2021 r.4(10)", "head": "", "text": "An online gaming intermediary who enables access to its users to any permissible online real money game, shall display a demonstrable and visible mark of verification of such online game by an online gaming self-regulatory body on such permissible online real money game."}, "it-rules-2021:rule_4__subrule_11": {"cite": "IT Rules 2021 r.4(11)", "head": "", "text": "While informing the users of its rules and regulations, privacy policy, terms of service and user agreements under clause (b) of sub-rule (1) of rule 3, an online gaming intermediary who enables the users to access any permissible online real money game, shall include the following information in respect of every such online games, namely:— the policy related to withdrawal or refund of the deposit made with the expectation of earning winnings, the manner of determination and distribution of such winnings, and the fees and other charges payable by the user; the know-your-customer procedure foll…"}, "it-rules-2021:rule_4__subrule_11__cl_a": {"cite": "IT Rules 2021 r.4(11)(a)", "head": "", "text": "the policy related to withdrawal or refund of the deposit made with the expectation of earning winnings, the manner of determination and distribution of such winnings, and the fees and other charges payable by the user;"}, "it-rules-2021:rule_4__subrule_11__cl_b": {"cite": "IT Rules 2021 r.4(11)(b)", "head": "", "text": "the know-your-customer procedure followed by it for verifying the identity of the users of such online game;"}, "it-rules-2021:rule_4__subrule_11__cl_c": {"cite": "IT Rules 2021 r.4(11)(c)", "head": "", "text": "the measures taken for protection of deposit made by a user for such online game; and"}, "it-rules-2021:rule_4__subrule_11__cl_d": {"cite": "IT Rules 2021 r.4(11)(d)", "head": "", "text": "the framework referred to in rule 4A, relating to such online game."}, "it-rules-2021:rule_4__subrule_12": {"cite": "IT Rules 2021 r.4(12)", "head": "", "text": "An online gaming intermediary shall, before accepting any deposit in cash or kind from any user for a permissible online real money game, identify such user and verify his identity: Provided that the procedure required to be followed by an entity regulated by the Reserve Bank of India for identification and verification of a customer at the commencement of an account-based relationship shall apply, mutatis mutandis, in identification and verification of the users of such online gaming intermediary."}, "it-rules-2021:rule_4__subrule_12__proviso_1": {"cite": "IT Rules 2021 r.4(12)", "head": "", "text": "Provided that the procedure required to be followed by an entity regulated by the Reserve Bank of India for identification and verification of a customer at the commencement of an account-based relationship shall apply, mutatis mutandis, in identification and verification of the users of such online gaming intermediary."}, "it-rules-2021:rule_4__subrule_13": {"cite": "IT Rules 2021 r.4(13)", "head": "", "text": "An online gaming intermediary who enables the users to access any permissible online real money game shall not itself finance by way of credit or enable financing to be offered by third party for the purpose of playing such online game."}, "it-rules-2021:rule_4A": {"cite": "IT Rules 2021 r.4A", "head": "Verification of online real money game", "text": "The Ministry may, by a notification in the Official Gazette, designate as many online gaming self-regulatory bodies as it may consider necessary for the purposes of verifying an online real money game as a permissible online real money game under these rules. An entity which fulfils the following criteria may apply to the Ministry for designation as an online gaming self-regulatory body, namely:— the entity is a company registered under section 8 of the Companies Act, 2013 (18 of 2013); its membership is representative of the gaming industry; its members have been offering and promoting online…"}, "it-rules-2021:rule_4A__subrule_1": {"cite": "IT Rules 2021 r.4A(1)", "head": "", "text": "The Ministry may, by a notification in the Official Gazette, designate as many online gaming self-regulatory bodies as it may consider necessary for the purposes of verifying an online real money game as a permissible online real money game under these rules."}, "it-rules-2021:rule_4A__subrule_2": {"cite": "IT Rules 2021 r.4A(2)", "head": "", "text": "An entity which fulfils the following criteria may apply to the Ministry for designation as an online gaming self-regulatory body, namely:— the entity is a company registered under section 8 of the Companies Act, 2013 (18 of 2013); its membership is representative of the gaming industry; its members have been offering and promoting online games in a responsible manner; its Board of Directors is comprised of individuals of repute and do not have any conflict of interest and possess special knowledge or practical experience suitable for the performance of the functions of such self-regulatory bo…"}, "it-rules-2021:rule_4A__subrule_2__cl_a": {"cite": "IT Rules 2021 r.4A(2)(a)", "head": "", "text": "the entity is a company registered under section 8 of the Companies Act, 2013 (18 of 2013);"}, "it-rules-2021:rule_4A__subrule_2__cl_b": {"cite": "IT Rules 2021 r.4A(2)(b)", "head": "", "text": "its membership is representative of the gaming industry;"}, "it-rules-2021:rule_4A__subrule_2__cl_c": {"cite": "IT Rules 2021 r.4A(2)(c)", "head": "", "text": "its members have been offering and promoting online games in a responsible manner;"}, "it-rules-2021:rule_4A__subrule_2__cl_d": {"cite": "IT Rules 2021 r.4A(2)(d)", "head": "", "text": "its Board of Directors is comprised of individuals of repute and do not have any conflict of interest and possess special knowledge or practical experience suitable for the performance of the functions of such self-regulatory body, and consists of— an individual having special knowledge of or practical experience in the online gaming industry; an individual having experience in promoting the interests of users of online games; an educationist; an expert in the field of psychology or mental health or such other relevant field; an individual having special knowledge of or practical experience in…"}, "it-rules-2021:rule_4A__subrule_2__cl_d__subcl_i": {"cite": "IT Rules 2021 r.4A(2)(d)(i)", "head": "", "text": "an individual having special knowledge of or practical experience in the online gaming industry;"}, "it-rules-2021:rule_4A__subrule_2__cl_d__subcl_ii": {"cite": "IT Rules 2021 r.4A(2)(d)(ii)", "head": "", "text": "an individual having experience in promoting the interests of users of online games;"}, "it-rules-2021:rule_4A__subrule_2__cl_d__subcl_iii": {"cite": "IT Rules 2021 r.4A(2)(d)(iii)", "head": "", "text": "an educationist;"}, "it-rules-2021:rule_4A__subrule_2__cl_d__subcl_iv": {"cite": "IT Rules 2021 r.4A(2)(d)(iv)", "head": "", "text": "an expert in the field of psychology or mental health or such other relevant field;"}, "it-rules-2021:rule_4A__subrule_2__cl_d__subcl_v": {"cite": "IT Rules 2021 r.4A(2)(d)(v)", "head": "", "text": "an individual having special knowledge of or practical experience in the field of information and communications technology;"}, "it-rules-2021:rule_4A__subrule_2__cl_d__subcl_vi": {"cite": "IT Rules 2021 r.4A(2)(d)(vi)", "head": "", "text": "an individual who is or has been a member or officer of an organisation dealing with the protection of child rights;"}, "it-rules-2021:rule_4A__subrule_2__cl_d__subcl_vii": {"cite": "IT Rules 2021 r.4A(2)(d)(vii)", "head": "", "text": "an individual having practical experience in the field of public policy or public administration or law enforcement or public finance or other relevant field, to be nominated by the Ministry; and"}, "it-rules-2021:rule_4A__subrule_2__cl_d__subcl_viii": {"cite": "IT Rules 2021 r.4A(2)(d)(viii)", "head": "", "text": "such other individuals as may be appointed with the previous approval of the Ministry;"}, "it-rules-2021:rule_4A__subrule_2__cl_e": {"cite": "IT Rules 2021 r.4A(2)(e)", "head": "", "text": "its memorandum of association and articles of association contain provisions relating to— the performance of its functions under these rules, including the redressal of grievances under sub-rule (11), in a manner free from conflict of interest and at arm’s length from its members; the disclosure and reporting by and accountability of its members in relation to the online games verified by such body; the clear and relevant criteria, consistent with these rules, for the acceptance and continuation of a person as its member, and for revoking or suspending such membership after giving such person …"}, "it-rules-2021:rule_4A__subrule_2__cl_e__subcl_i": {"cite": "IT Rules 2021 r.4A(2)(e)(i)", "head": "", "text": "the performance of its functions under these rules, including the redressal of grievances under sub-rule (11), in a manner free from conflict of interest and at arm’s length from its members;"}, "it-rules-2021:rule_4A__subrule_2__cl_e__subcl_ii": {"cite": "IT Rules 2021 r.4A(2)(e)(ii)", "head": "", "text": "the disclosure and reporting by and accountability of its members in relation to the online games verified by such body;"}, "it-rules-2021:rule_4A__subrule_2__cl_e__subcl_iii": {"cite": "IT Rules 2021 r.4A(2)(e)(iii)", "head": "", "text": "the clear and relevant criteria, consistent with these rules, for the acceptance and continuation of a person as its member, and for revoking or suspending such membership after giving such person an opportunity of being heard; and"}, "it-rules-2021:rule_4A__subrule_2__cl_e__subcl_iv": {"cite": "IT Rules 2021 r.4A(2)(e)(iv)", "head": "", "text": "the requirement that the amendment in the memorandum of association and articles of association in relation to any matter referred to in sub-clauses (i), (ii) or (iii) is carried out with the previous approval of the Ministry; and"}, "it-rules-2021:rule_4A__subrule_2__cl_f": {"cite": "IT Rules 2021 r.4A(2)(f)", "head": "", "text": "the entity has sufficient capacity, including financial capacity, to perform its functions as an online gaming self-regulatory body under these rules."}, "it-rules-2021:rule_4A__subrule_3": {"cite": "IT Rules 2021 r.4A(3)", "head": "", "text": "The online gaming self-regulatory body, upon an application made to it by its member in respect of an online real money game, may declare such online real money game as a permissible online real money game, if, after making such inquiry as it deems fit, it is satisfied that— the online real money game does not involve wagering on any outcome; and the online gaming intermediary and such online game is in compliance with the provisions of rules 3 and 4, the provisions of any law relating to the age at which an individual is competent to enter into a contract, and the framework made by the online…"}, "it-rules-2021:rule_4A__subrule_3__cl_a": {"cite": "IT Rules 2021 r.4A(3)(a)", "head": "", "text": "the online real money game does not involve wagering on any outcome; and"}, "it-rules-2021:rule_4A__subrule_3__cl_b": {"cite": "IT Rules 2021 r.4A(3)(b)", "head": "", "text": "the online gaming intermediary and such online game is in compliance with the provisions of rules 3 and 4, the provisions of any law relating to the age at which an individual is competent to enter into a contract, and the framework made by the online gaming self-regulatory body under sub-rule (8): Provided that an online gaming self-regulatory body may, initially rely upon the information furnished by the applicant for verification of the online real money game and declare such game as a permissible online real money game for a period not exceeding three months: Provided further that the onli…"}, "it-rules-2021:rule_4A__subrule_3__cl_b__proviso_1": {"cite": "IT Rules 2021 r.4A(3)(b)", "head": "", "text": "Provided that an online gaming self-regulatory body may, initially rely upon the information furnished by the applicant for verification of the online real money game and declare such game as a permissible online real money game for a period not exceeding three months:"}, "it-rules-2021:rule_4A__subrule_3__cl_b__proviso_2": {"cite": "IT Rules 2021 r.4A(3)(b)", "head": "", "text": "Provided further that the online gaming self-regulatory body shall endeavour to complete the inquiry within the said period of three months and, upon its completion, either declare the online real money game as a permissible online real money game or inform the applicant in writing with the reasons thereof that such online game does not meet the requirements under these rules."}, "it-rules-2021:rule_4A__subrule_4": {"cite": "IT Rules 2021 r.4A(4)", "head": "", "text": "The online gaming self-regulatory body shall publish and maintain on its website, mobile based application or both, at all times, an updated list of all permissible online real money games verified under sub-rule (3), along with the details of such online games including the details of the applicant, the dates and period of validity of the verification, the reasons of such verification and the details of the suspension or revocation, if any, of verification of any online real money game."}, "it-rules-2021:rule_4A__subrule_5": {"cite": "IT Rules 2021 r.4A(5)", "head": "", "text": "Every online gaming self-regulatory body shall publish and maintain on its website, mobile based application or both, at all times, an updated list of all its members, whether present or former, the dates of their acceptance as member, their corporate or business-related identity number and other details, and the details of suspension or revocation of membership of any member."}, "it-rules-2021:rule_4A__subrule_6": {"cite": "IT Rules 2021 r.4A(6)", "head": "", "text": "The online gaming self-regulatory body may, at any time, after giving the applicant member an opportunity of being heard and for reasons to be communicated in writing, suspend or revoke the verification, if it is satisfied that the online real money game verified by it is not in compliance with the provisions of these rules."}, "it-rules-2021:rule_4A__subrule_7": {"cite": "IT Rules 2021 r.4A(7)", "head": "", "text": "The online real money game verified under sub-rule (3), and the online gaming intermediary which enables access to such online real money game, shall display a demonstrable and visible mark of such verification stating that the online real money game is verified by the online gaming self-regulatory body as a permissible online real money game under these rules."}, "it-rules-2021:rule_4A__subrule_8": {"cite": "IT Rules 2021 r.4A(8)", "head": "", "text": "The online gaming self-regulatory body shall prominently publish on its website, mobile based application or both, as the case may be, a framework for verifying an online real money game, which, among other things, includes the following, namely:— the measures to ensure that such online real money game is not against the interests of sovereignty and integrity of India, security of the State, friendly relations with foreign States and public order; the safeguards against user harm, including self-harm and psychological harm; the measures to safeguard children, including measures for parental or…"}, "it-rules-2021:rule_4A__subrule_8__cl_a": {"cite": "IT Rules 2021 r.4A(8)(a)", "head": "", "text": "the measures to ensure that such online real money game is not against the interests of sovereignty and integrity of India, security of the State, friendly relations with foreign States and public order;"}, "it-rules-2021:rule_4A__subrule_8__cl_b": {"cite": "IT Rules 2021 r.4A(8)(b)", "head": "", "text": "the safeguards against user harm, including self-harm and psychological harm;"}, "it-rules-2021:rule_4A__subrule_8__cl_c": {"cite": "IT Rules 2021 r.4A(8)(c)", "head": "", "text": "the measures to safeguard children, including measures for parental or access control and classifying online games through age-rating mechanism, based on the nature and type of content; and"}, "it-rules-2021:rule_4A__subrule_8__cl_d": {"cite": "IT Rules 2021 r.4A(8)(d)", "head": "", "text": "the measures to safeguard users against the risk of gaming addiction, financial loss and financial fraud, including repeated warning messages at higher frequency beyond a reasonable duration for a gaming session and provision to enable a user to exclude himself upon user-defined limits being reached for time or money spent."}, "it-rules-2021:rule_4A__subrule_9": {"cite": "IT Rules 2021 r.4A(9)", "head": "", "text": "The Ministry may, if it considers it necessary, by a notice in writing, require an online gaming self-regulatory body to furnish to the Ministry or disclose on such body’s website or mobile based application or both, such information as the Ministry may specify in the notice."}, "it-rules-2021:rule_4A__subrule_10": {"cite": "IT Rules 2021 r.4A(10)", "head": "", "text": "Before issuing a direction under section 69A of the Act in respect of a permissible online real money game, the Central Government may take into consideration the details published by an online gaming self-regulatory body under sub-rule (4)."}, "it-rules-2021:rule_4A__subrule_11": {"cite": "IT Rules 2021 r.4A(11)", "head": "", "text": "Every online gaming self-regulatory body shall prominently publish on its website, mobile based application or both, the framework for redressal of grievances and the contact details of the Grievance Officer to which an applicant aggrieved by a decision of such body with respect to verification may make a complaint in respect of any matter related to such online real money game or verification which shall be acknowledged by the Grievance Officer within twenty-four hours and resolved within a period of fifteen days from the date of its receipt."}, "it-rules-2021:rule_4A__subrule_12": {"cite": "IT Rules 2021 r.4A(12)", "head": "", "text": "Where the Ministry is of the view that any verification of a permissible online real money game by an online gaming self-regulatory body is not in conformity with these rules, it may, after giving such body an opportunity of being heard, communicate, in writing, the fact of such non-conformity to that body and direct it to take measures to rectify the same."}, "it-rules-2021:rule_4A__subrule_13": {"cite": "IT Rules 2021 r.4A(13)", "head": "", "text": "The Ministry may, if it is satisfied that it is necessary so to do, after giving the online gaming self-regulatory body an opportunity of being heard, by order, for reasons to be recorded in writing, suspend or revoke the designation of such body: Provided that the Ministry may, in the interest of the users of any online game that was verified by such body at the same time or at any subsequent time, give such interim directions as it may deem necessary to any intermediary or class of intermediaries regarding enabling its users to access such online game."}, "it-rules-2021:rule_4A__subrule_13__proviso_1": {"cite": "IT Rules 2021 r.4A(13)", "head": "", "text": "Provided that the Ministry may, in the interest of the users of any online game that was verified by such body at the same time or at any subsequent time, give such interim directions as it may deem necessary to any intermediary or class of intermediaries regarding enabling its users to access such online game."}, "it-rules-2021:rule_4A__subrule_14": {"cite": "IT Rules 2021 r.4A(14)", "head": "", "text": "In this rule, ‘prominently publish’ shall mean publishing in a clearly visible manner on the home page of the website or the home screen of the mobile based application, or both, as the case may be, or on a web page or an app screen directly accessible from the home page or home screen."}, "it-rules-2021:rule_4B": {"cite": "IT Rules 2021 r.4B", "head": "Applicability of certain obligations after an initial period", "text": "The obligations under rules 3 and 4 shall not apply in relation to online games until the expiry of a period of three months from the date on which at least three online gaming self-regulatory bodies have been designated under rule 4A: Provided that the Central Government may, at any time before the expiry of the said period of three months, by a notification in the Official Gazette, direct that the obligations under rules 3 and 4 shall apply in relation to an online game from such date as may be specified in the notification."}, "it-rules-2021:rule_4B__proviso_1": {"cite": "IT Rules 2021 r.4B", "head": "", "text": "Provided that the Central Government may, at any time before the expiry of the said period of three months, by a notification in the Official Gazette, direct that the obligations under rules 3 and 4 shall apply in relation to an online game from such date as may be specified in the notification."}, "it-rules-2021:rule_4C": {"cite": "IT Rules 2021 r.4C", "head": "Obligations in relation to online game other than online real money game", "text": "If the Central Government considers it necessary so to do in the interest of the sovereignty and integrity of India or security of the State or friendly relations with foreign States or public order, or preventing user harm, it may, by a notification in the Official Gazette, for reasons to be recorded in writing,— direct that an intermediary in respect of such online game, shall observe, mutatis mutandis, the obligations under sub-clauses (ix) and (x) of clause (b) of sub-rule (1) of rule 3 and sub-rules (1), (5), (6), (7), (10) and clause (d) of sub-rule (11) of rule 4 as if it is a permissib…"}, "it-rules-2021:rule_4C__subrule_1": {"cite": "IT Rules 2021 r.4C(1)", "head": "", "text": "If the Central Government considers it necessary so to do in the interest of the sovereignty and integrity of India or security of the State or friendly relations with foreign States or public order, or preventing user harm, it may, by a notification in the Official Gazette, for reasons to be recorded in writing,— direct that an intermediary in respect of such online game, shall observe, mutatis mutandis, the obligations under sub-clauses (ix) and (x) of clause (b) of sub-rule (1) of rule 3 and sub-rules (1), (5), (6), (7), (10) and clause (d) of sub-rule (11) of rule 4 as if it is a permissib…"}, "it-rules-2021:rule_4C__subrule_1__cl_a": {"cite": "IT Rules 2021 r.4C(1)(a)", "head": "", "text": "direct that an intermediary in respect of such online game, shall observe, mutatis mutandis, the obligations under sub-clauses (ix) and (x) of clause (b) of sub-rule (1) of rule 3 and sub-rules (1), (5), (6), (7), (10) and clause (d) of sub-rule (11) of rule 4 as if it is a permissible online real money game; and"}, "it-rules-2021:rule_4C__subrule_1__cl_b": {"cite": "IT Rules 2021 r.4C(1)(b)", "head": "", "text": "specify the period within which the online gaming intermediary which enables access to such online game shall observe the obligations referred to in clause (a)."}, "it-rules-2021:rule_4C__subrule_2": {"cite": "IT Rules 2021 r.4C(2)", "head": "", "text": "Where an online game is notified under sub-rule (1), the provisions of rule 4A shall apply as they apply to a permissible online real money game. In this rule, “user harm” means any effect which is detrimental to users."}, "it-rules-2021:rule_4C__subrule_2__hcontainer_1": {"cite": "IT Rules 2021 r.4C(2)", "head": "", "text": "In this rule, “user harm” means any effect which is detrimental to users."}, "it-rules-2021:rule_5": {"cite": "IT Rules 2021 r.5", "head": "Additional due diligence to be observed by an intermediary in relation to news and current affairs content", "text": "In addition to adherence to rules 3 and 4, as may be applicable, an intermediary shall publish, on an appropriate place on its website, mobile based application or both, as the case may be, a clear and concise statement informing publishers of news and current affairs content that in addition to the common terms of service for all users, such publishers shall furnish the details of their user accounts on the services of such intermediary to the Ministry as may be required under rule 18: Provided that an intermediary may provide such publishers who have provided information under rule 18 with a…"}, "it-rules-2021:rule_5__proviso_1": {"cite": "IT Rules 2021 r.5", "head": "", "text": "Provided that an intermediary may provide such publishers who have provided information under rule 18 with a demonstrable and visible mark of verification as being publishers, which shall be visible to all users of the service."}, "it-rules-2021:rule_5__hcontainer_1": {"cite": "IT Rules 2021 r.5", "head": "", "text": "This rule relates only to news and current affairs content and shall be administered by the Ministry of Information and Broadcasting."}, "it-rules-2021:rule_6": {"cite": "IT Rules 2021 r.6", "head": "Notification of other intermediary", "text": "The Ministry may by order, for reasons to be recorded in writing, require any intermediary, which is not a significant social media intermediary, to comply with all or any of the obligations mentioned under rule 4, if the services of that intermediary permits the publication or transmission of information in a manner that may create a material risk of harm to the sovereignty and integrity of India, security of the State, friendly relations with foreign States or public order. The assessment of material risk of harm referred to in sub-rule (1) shall be made having regard to the nature of servic…"}, "it-rules-2021:rule_6__subrule_1": {"cite": "IT Rules 2021 r.6(1)", "head": "", "text": "The Ministry may by order, for reasons to be recorded in writing, require any intermediary, which is not a significant social media intermediary, to comply with all or any of the obligations mentioned under rule 4, if the services of that intermediary permits the publication or transmission of information in a manner that may create a material risk of harm to the sovereignty and integrity of India, security of the State, friendly relations with foreign States or public order."}, "it-rules-2021:rule_6__subrule_2": {"cite": "IT Rules 2021 r.6(2)", "head": "", "text": "The assessment of material risk of harm referred to in sub-rule (1) shall be made having regard to the nature of services of such intermediary, and if those services permit,— interaction between users, notwithstanding, whether it is the primary purpose of that intermediary; and the publication or transmission of information to a significant number of other users as would be likely to result in widespread dissemination of such information."}, "it-rules-2021:rule_6__subrule_2__cl_a": {"cite": "IT Rules 2021 r.6(2)(a)", "head": "", "text": "interaction between users, notwithstanding, whether it is the primary purpose of that intermediary; and"}, "it-rules-2021:rule_6__subrule_2__cl_b": {"cite": "IT Rules 2021 r.6(2)(b)", "head": "", "text": "the publication or transmission of information to a significant number of other users as would be likely to result in widespread dissemination of such information."}, "it-rules-2021:rule_6__subrule_3": {"cite": "IT Rules 2021 r.6(3)", "head": "", "text": "An order under this rule may be issued in relation to a specific part of the computer resources of any website, mobile based application or both, as the case may be, if such specific part is in the nature of an intermediary: Provided that where such order is issued, an entity may be required to comply with all or any of the obligations mentions under rule 4, in relation to the specific part of its computer resource which is in the nature of an intermediary."}, "it-rules-2021:rule_6__subrule_3__proviso_1": {"cite": "IT Rules 2021 r.6(3)", "head": "", "text": "Provided that where such order is issued, an entity may be required to comply with all or any of the obligations mentions under rule 4, in relation to the specific part of its computer resource which is in the nature of an intermediary."}, "it-rules-2021:rule_7": {"cite": "IT Rules 2021 r.7", "head": "Non-observance of Rules", "text": "Where an intermediary fails to observe these rules, the provisions of sub-section (1) of section 79 of the Act shall not be applicable to such intermediary and the intermediary shall be liable for punishment under any law for the time being in force including the provisions of the Act and the Bharatiya Nyaya Sanhita, 2023 (45 of 2023)."}, "it-rules-2021:part_III": {"cite": "IT Rules 2021 Part III", "head": "CODE OF ETHICS AND PROCEDURE AND SAFEGUARDS IN RELATION TO DIGITAL MEDIA", "text": "Application of this Part The rules made under this Part shall apply to the following persons or entities, namely:— publishers of news and current affairs content; publishers of online curated content; and shall be administered by the Ministry of Information and Broadcasting, Government of India, which shall be referred to in this Part as the “Ministry”: Provided that the rules made under this Part shall apply to intermediaries for the purposes of rules 15 and 16; the rules made under this Part shall apply to the publishers, where,— such publisher operates in the territory of India; or such pub…"}, "it-rules-2021:rule_8": {"cite": "IT Rules 2021 r.8", "head": "Application of this Part", "text": "The rules made under this Part shall apply to the following persons or entities, namely:— publishers of news and current affairs content; publishers of online curated content; and shall be administered by the Ministry of Information and Broadcasting, Government of India, which shall be referred to in this Part as the “Ministry”: Provided that the rules made under this Part shall apply to intermediaries for the purposes of rules 15 and 16; the rules made under this Part shall apply to the publishers, where,— such publisher operates in the territory of India; or such publisher conducts systemati…"}, "it-rules-2021:rule_8__subrule_1": {"cite": "IT Rules 2021 r.8(1)", "head": "", "text": "The rules made under this Part shall apply to the following persons or entities, namely:— publishers of news and current affairs content; publishers of online curated content; and shall be administered by the Ministry of Information and Broadcasting, Government of India, which shall be referred to in this Part as the “Ministry”: Provided that the rules made under this Part shall apply to intermediaries for the purposes of rules 15 and 16;"}, "it-rules-2021:rule_8__subrule_1__cl_a": {"cite": "IT Rules 2021 r.8(1)(a)", "head": "", "text": "publishers of news and current affairs content;"}, "it-rules-2021:rule_8__subrule_1__cl_b": {"cite": "IT Rules 2021 r.8(1)(b)", "head": "", "text": "publishers of online curated content; and"}, "it-rules-2021:rule_8__subrule_1__wrap_1": {"cite": "IT Rules 2021 r.8(1)", "head": "", "text": "shall be administered by the Ministry of Information and Broadcasting, Government of India, which shall be referred to in this Part as the “Ministry”:"}, "it-rules-2021:rule_8__subrule_1__proviso_1": {"cite": "IT Rules 2021 r.8(1)", "head": "", "text": "Provided that the rules made under this Part shall apply to intermediaries for the purposes of rules 15 and 16;"}, "it-rules-2021:rule_8__subrule_2": {"cite": "IT Rules 2021 r.8(2)", "head": "", "text": "the rules made under this Part shall apply to the publishers, where,— such publisher operates in the territory of India; or such publisher conducts systematic business activity of making its content available in India."}, "it-rules-2021:rule_8__subrule_2__cl_a": {"cite": "IT Rules 2021 r.8(2)(a)", "head": "", "text": "such publisher operates in the territory of India; or"}, "it-rules-2021:rule_8__subrule_2__cl_b": {"cite": "IT Rules 2021 r.8(2)(b)", "head": "", "text": "such publisher conducts systematic business activity of making its content available in India."}, "it-rules-2021:rule_8__hcontainer_1": {"cite": "IT Rules 2021 r.8", "head": "", "text": "For the purposes of this rule,— a publisher shall be deemed to operate in the territory of India where such publisher has a physical presence in the territory of India; “systematic activity” shall mean any structured or organised activity that involves an element of planning, method, continuity or persistence."}, "it-rules-2021:rule_8__hcontainer_1__cl_a": {"cite": "IT Rules 2021 r.8(a)", "head": "", "text": "a publisher shall be deemed to operate in the territory of India where such publisher has a physical presence in the territory of India;"}, "it-rules-2021:rule_8__hcontainer_1__cl_b": {"cite": "IT Rules 2021 r.8(b)", "head": "", "text": "“systematic activity” shall mean any structured or organised activity that involves an element of planning, method, continuity or persistence."}, "it-rules-2021:rule_8__subrule_3": {"cite": "IT Rules 2021 r.8(3)", "head": "", "text": "The rules made under this Part shall be in addition to and not in derogation of the provisions of any other law for the time being in force and any remedies available under such laws including the Information Technology (Procedure and Safeguards for Blocking of Access of Information by the Public) Rules, 2009."}, "it-rules-2021:rule_9": {"cite": "IT Rules 2021 r.9", "head": "Observance and adherence to the Code", "text": "A publisher referred to in rule 8 shall observe and adhere to the Code of Ethics laid down in the Appendix annexed to these rules. Notwithstanding anything contained in these rules, a publisher referred to in rule 8 who contravenes any law for the time being in force, shall also be liable for consequential action as provided in such law which has so been contravened. For ensuring observance and adherence to the Code of Ethics by publishers operating in the territory of India, and for addressing the grievances made in relation to publishers under this Part, there shall be a three-tier structure…"}, "it-rules-2021:rule_9__subrule_1": {"cite": "IT Rules 2021 r.9(1)", "head": "", "text": "A publisher referred to in rule 8 shall observe and adhere to the Code of Ethics laid down in the Appendix annexed to these rules."}, "it-rules-2021:rule_9__subrule_2": {"cite": "IT Rules 2021 r.9(2)", "head": "", "text": "Notwithstanding anything contained in these rules, a publisher referred to in rule 8 who contravenes any law for the time being in force, shall also be liable for consequential action as provided in such law which has so been contravened."}, "it-rules-2021:rule_9__subrule_3": {"cite": "IT Rules 2021 r.9(3)", "head": "", "text": "For ensuring observance and adherence to the Code of Ethics by publishers operating in the territory of India, and for addressing the grievances made in relation to publishers under this Part, there shall be a three-tier structure as under— Level I - Self-regulation by the publishers; Level II – Self-regulation by the self-regulating bodies of the publishers; Level III - Oversight mechanism by the Central Government."}, "it-rules-2021:rule_9__subrule_3__cl_a": {"cite": "IT Rules 2021 r.9(3)(a)", "head": "", "text": "Level I - Self-regulation by the publishers;"}, "it-rules-2021:rule_9__subrule_3__cl_b": {"cite": "IT Rules 2021 r.9(3)(b)", "head": "", "text": "Level II – Self-regulation by the self-regulating bodies of the publishers;"}, "it-rules-2021:rule_9__subrule_3__cl_c": {"cite": "IT Rules 2021 r.9(3)(c)", "head": "", "text": "Level III - Oversight mechanism by the Central Government."}, "it-rules-2021:chp_I": {"cite": "IT Rules 2021 Chapter I", "head": "GRIEVANCE REDRESSAL MECHANISM", "text": "Furnishing and processing of grievance Any person having a grievance regarding content published by a publisher in relation to the Code of Ethics may furnish his grievance on the grievance mechanism established by the publisher under rule 11. The publisher shall generate and issue an acknowledgement of the grievance for the benefit of the complainant within twenty-four hours of it being furnished for information and record. The manner of grievance redressal shall have the following arrangement– the publisher shall address the grievance and inform the complainant of its decision within fifteen …"}, "it-rules-2021:rule_10": {"cite": "IT Rules 2021 r.10", "head": "Furnishing and processing of grievance", "text": "Any person having a grievance regarding content published by a publisher in relation to the Code of Ethics may furnish his grievance on the grievance mechanism established by the publisher under rule 11. The publisher shall generate and issue an acknowledgement of the grievance for the benefit of the complainant within twenty-four hours of it being furnished for information and record. The manner of grievance redressal shall have the following arrangement– the publisher shall address the grievance and inform the complainant of its decision within fifteen days of the registration of the grievan…"}, "it-rules-2021:rule_10__subrule_1": {"cite": "IT Rules 2021 r.10(1)", "head": "", "text": "Any person having a grievance regarding content published by a publisher in relation to the Code of Ethics may furnish his grievance on the grievance mechanism established by the publisher under rule 11."}, "it-rules-2021:rule_10__subrule_2": {"cite": "IT Rules 2021 r.10(2)", "head": "", "text": "The publisher shall generate and issue an acknowledgement of the grievance for the benefit of the complainant within twenty-four hours of it being furnished for information and record."}, "it-rules-2021:rule_10__subrule_3": {"cite": "IT Rules 2021 r.10(3)", "head": "", "text": "The manner of grievance redressal shall have the following arrangement– the publisher shall address the grievance and inform the complainant of its decision within fifteen days of the registration of the grievance; if the decision of the publisher is not communicated to the complainant within the stipulated fifteen days, the grievance shall be escalated to the level of the self–regulating body of which such publisher is a member. where the complainant is not satisfied with the decision of the publisher, it may prefer to appeal to the self-regulating body of which such publisher is a member wit…"}, "it-rules-2021:rule_10__subrule_3__cl_a": {"cite": "IT Rules 2021 r.10(3)(a)", "head": "", "text": "the publisher shall address the grievance and inform the complainant of its decision within fifteen days of the registration of the grievance;"}, "it-rules-2021:rule_10__subrule_3__cl_b": {"cite": "IT Rules 2021 r.10(3)(b)", "head": "", "text": "if the decision of the publisher is not communicated to the complainant within the stipulated fifteen days, the grievance shall be escalated to the level of the self–regulating body of which such publisher is a member."}, "it-rules-2021:rule_10__subrule_3__cl_c": {"cite": "IT Rules 2021 r.10(3)(c)", "head": "", "text": "where the complainant is not satisfied with the decision of the publisher, it may prefer to appeal to the self-regulating body of which such publisher is a member within fifteen days of receiving such a decision."}, "it-rules-2021:rule_10__subrule_3__cl_d": {"cite": "IT Rules 2021 r.10(3)(d)", "head": "", "text": "the self-regulating body shall address the grievance referred to in clauses (b) and (c), and convey its decision in the form of a guidance or advisory to the publisher, and inform the complainant of such decision within a period of fifteen days.."}, "it-rules-2021:rule_10__subrule_3__cl_e": {"cite": "IT Rules 2021 r.10(3)(e)", "head": "", "text": "where the complainant is not satisfied with the decision of the self-regulating body, it may, within fifteen days of such decision, prefer an appeal to the Oversight Mechanism referred to in rule 13 for resolution."}, "it-rules-2021:chp_II": {"cite": "IT Rules 2021 Chapter II", "head": "SELF REGULATING MECHANISM - LEVEL I", "text": "Self-Regulating mechanism at Level I The publisher shall be the Level I of the self-regulating mechanism. A publisher shall— establish a grievance redressal mechanism and shall appoint a Grievance Officer based in India, who shall be responsible for the redressal of grievances received by him; display the contact details related to its grievance redressal mechanism and the name and contact details of its Grievance Officer at an appropriate place on its website or interface, as the case may be; ensure that the Grievance Officer takes a decision on every grievance received by it within fifteen d…"}, "it-rules-2021:rule_11": {"cite": "IT Rules 2021 r.11", "head": "Self-Regulating mechanism at Level I", "text": "The publisher shall be the Level I of the self-regulating mechanism. A publisher shall— establish a grievance redressal mechanism and shall appoint a Grievance Officer based in India, who shall be responsible for the redressal of grievances received by him; display the contact details related to its grievance redressal mechanism and the name and contact details of its Grievance Officer at an appropriate place on its website or interface, as the case may be; ensure that the Grievance Officer takes a decision on every grievance received by it within fifteen days, and communicate the same to the …"}, "it-rules-2021:rule_11__subrule_1": {"cite": "IT Rules 2021 r.11(1)", "head": "", "text": "The publisher shall be the Level I of the self-regulating mechanism."}, "it-rules-2021:rule_11__subrule_2": {"cite": "IT Rules 2021 r.11(2)", "head": "", "text": "A publisher shall— establish a grievance redressal mechanism and shall appoint a Grievance Officer based in India, who shall be responsible for the redressal of grievances received by him; display the contact details related to its grievance redressal mechanism and the name and contact details of its Grievance Officer at an appropriate place on its website or interface, as the case may be; ensure that the Grievance Officer takes a decision on every grievance received by it within fifteen days, and communicate the same to the complainant within the specified time: be a member of a self-regulati…"}, "it-rules-2021:rule_11__subrule_2__cl_a": {"cite": "IT Rules 2021 r.11(2)(a)", "head": "", "text": "establish a grievance redressal mechanism and shall appoint a Grievance Officer based in India, who shall be responsible for the redressal of grievances received by him;"}, "it-rules-2021:rule_11__subrule_2__cl_b": {"cite": "IT Rules 2021 r.11(2)(b)", "head": "", "text": "display the contact details related to its grievance redressal mechanism and the name and contact details of its Grievance Officer at an appropriate place on its website or interface, as the case may be;"}, "it-rules-2021:rule_11__subrule_2__cl_c": {"cite": "IT Rules 2021 r.11(2)(c)", "head": "", "text": "ensure that the Grievance Officer takes a decision on every grievance received by it within fifteen days, and communicate the same to the complainant within the specified time:"}, "it-rules-2021:rule_11__subrule_2__cl_d": {"cite": "IT Rules 2021 r.11(2)(d)", "head": "", "text": "be a member of a self-regulating body as referred to in rule 12 and abide by its terms and conditions."}, "it-rules-2021:rule_11__subrule_3": {"cite": "IT Rules 2021 r.11(3)", "head": "", "text": "The Grievance Officer shall,— be the contact point for receiving any grievance relating to Code of Ethics; act as the nodal point for interaction with the complainant, the self-regulating body and the Ministry."}, "it-rules-2021:rule_11__subrule_3__cl_a": {"cite": "IT Rules 2021 r.11(3)(a)", "head": "", "text": "be the contact point for receiving any grievance relating to Code of Ethics;"}, "it-rules-2021:rule_11__subrule_3__cl_b": {"cite": "IT Rules 2021 r.11(3)(b)", "head": "", "text": "act as the nodal point for interaction with the complainant, the self-regulating body and the Ministry."}, "it-rules-2021:rule_11__subrule_4": {"cite": "IT Rules 2021 r.11(4)", "head": "", "text": "Online curated content shall be classified by the publisher of such content into the categories referred to in the Schedule, having regard to the context, theme, tone, impact and target audience of such content, with the relevant rating for such categories based on an assessment of the relevant content descriptors in the manner specified in the said Schedule."}, "it-rules-2021:rule_11__subrule_5": {"cite": "IT Rules 2021 r.11(5)", "head": "", "text": "Every publisher of online curated content shall display the rating of any online curated content and an explanation of the relevant content descriptors, prominently to its users at an appropriate place, as the case may be, in a manner that ensures that such users are aware of this information before accessing such content."}, "it-rules-2021:chp_III": {"cite": "IT Rules 2021 Chapter III", "head": "SELF REGULATING MECHANISM – LEVEL II", "text": "Self-regulating body There may be one or more self-regulatory bodies of publishers, being an independent body constituted by publishers or their associations. The self-regulatory body referred to in sub-rule (1) shall be headed by a retired judge of the Supreme Court, a High Court, or an independent eminent person from the field of media, broadcasting, entertainment, child rights, human rights or such other relevant field, and have other members, not exceeding six, being experts from the field of media, broadcasting, entertainment, child rights, human rights and such other relevant fields. The…"}, "it-rules-2021:rule_12": {"cite": "IT Rules 2021 r.12", "head": "Self-regulating body", "text": "There may be one or more self-regulatory bodies of publishers, being an independent body constituted by publishers or their associations. The self-regulatory body referred to in sub-rule (1) shall be headed by a retired judge of the Supreme Court, a High Court, or an independent eminent person from the field of media, broadcasting, entertainment, child rights, human rights or such other relevant field, and have other members, not exceeding six, being experts from the field of media, broadcasting, entertainment, child rights, human rights and such other relevant fields. The self-regulating body…"}, "it-rules-2021:rule_12__subrule_1": {"cite": "IT Rules 2021 r.12(1)", "head": "", "text": "There may be one or more self-regulatory bodies of publishers, being an independent body constituted by publishers or their associations."}, "it-rules-2021:rule_12__subrule_2": {"cite": "IT Rules 2021 r.12(2)", "head": "", "text": "The self-regulatory body referred to in sub-rule (1) shall be headed by a retired judge of the Supreme Court, a High Court, or an independent eminent person from the field of media, broadcasting, entertainment, child rights, human rights or such other relevant field, and have other members, not exceeding six, being experts from the field of media, broadcasting, entertainment, child rights, human rights and such other relevant fields."}, "it-rules-2021:rule_12__subrule_3": {"cite": "IT Rules 2021 r.12(3)", "head": "", "text": "The self-regulating body shall, after its constitution in accordance with sub-rule (2), register itself with the Ministry within a period of thirty days from the date of notification of these rules, and where a self-regulating body is constituted after such period, within thirty days from the date of its constitution: Provided that before grant of registration to the self-regulating body, the Ministry shall satisfy itself that the self-regulating body has been constituted in accordance with sub-rule (2) and has agreed to perform the functions laid down in sub-rules (4) and (5)."}, "it-rules-2021:rule_12__subrule_3__proviso_1": {"cite": "IT Rules 2021 r.12(3)", "head": "", "text": "Provided that before grant of registration to the self-regulating body, the Ministry shall satisfy itself that the self-regulating body has been constituted in accordance with sub-rule (2) and has agreed to perform the functions laid down in sub-rules (4) and (5)."}, "it-rules-2021:rule_12__subrule_4": {"cite": "IT Rules 2021 r.12(4)", "head": "", "text": "The self-regulating body shall perform the following functions, namely:— oversee and ensure the alignment and adherence by the publisher to the Code of Ethics; provide guidance to publishers on various aspects of the Code of Ethics; address grievances which have not been resolved by publishers within the specified period of fifteen days; hear appeals filed by the complainant against the decision of publishers; issue such guidance or advisories to such publishers as specified in sub-rule (5) for ensuring compliance to the Code of Ethics."}, "it-rules-2021:rule_12__subrule_4__cl_a": {"cite": "IT Rules 2021 r.12(4)(a)", "head": "", "text": "oversee and ensure the alignment and adherence by the publisher to the Code of Ethics;"}, "it-rules-2021:rule_12__subrule_4__cl_b": {"cite": "IT Rules 2021 r.12(4)(b)", "head": "", "text": "provide guidance to publishers on various aspects of the Code of Ethics;"}, "it-rules-2021:rule_12__subrule_4__cl_c": {"cite": "IT Rules 2021 r.12(4)(c)", "head": "", "text": "address grievances which have not been resolved by publishers within the specified period of fifteen days;"}, "it-rules-2021:rule_12__subrule_4__cl_d": {"cite": "IT Rules 2021 r.12(4)(d)", "head": "", "text": "hear appeals filed by the complainant against the decision of publishers;"}, "it-rules-2021:rule_12__subrule_4__cl_e": {"cite": "IT Rules 2021 r.12(4)(e)", "head": "", "text": "issue such guidance or advisories to such publishers as specified in sub-rule (5) for ensuring compliance to the Code of Ethics."}, "it-rules-2021:rule_12__subrule_5": {"cite": "IT Rules 2021 r.12(5)", "head": "", "text": "The self-regulating body while disposing a grievance or an appeal referred to it in sub-rule (4) may issue following guidance or advisories to the publishers as under, namely:— warning, censuring, admonishing or reprimanding the publisher; or requiring an apology by the publisher; or requiring the publisher to include a warning card or a disclaimer; or in case of online curated content, direct the publisher to,— reclassify ratings of relevant content; make appropriate modification in the content descriptor, age classification and access control measures; edit synopsis of relevant content; or i…"}, "it-rules-2021:rule_12__subrule_5__cl_a": {"cite": "IT Rules 2021 r.12(5)(a)", "head": "", "text": "warning, censuring, admonishing or reprimanding the publisher; or"}, "it-rules-2021:rule_12__subrule_5__cl_b": {"cite": "IT Rules 2021 r.12(5)(b)", "head": "", "text": "requiring an apology by the publisher; or"}, "it-rules-2021:rule_12__subrule_5__cl_c": {"cite": "IT Rules 2021 r.12(5)(c)", "head": "", "text": "requiring the publisher to include a warning card or a disclaimer; or"}, "it-rules-2021:rule_12__subrule_5__cl_d": {"cite": "IT Rules 2021 r.12(5)(d)", "head": "", "text": "in case of online curated content, direct the publisher to,— reclassify ratings of relevant content; make appropriate modification in the content descriptor, age classification and access control measures; edit synopsis of relevant content; or"}, "it-rules-2021:rule_12__subrule_5__cl_d__subcl_i": {"cite": "IT Rules 2021 r.12(5)(d)(i)", "head": "", "text": "reclassify ratings of relevant content;"}, "it-rules-2021:rule_12__subrule_5__cl_d__subcl_ii": {"cite": "IT Rules 2021 r.12(5)(d)(ii)", "head": "", "text": "make appropriate modification in the content descriptor, age classification and access control measures;"}, "it-rules-2021:rule_12__subrule_5__cl_d__subcl_iii": {"cite": "IT Rules 2021 r.12(5)(d)(iii)", "head": "", "text": "edit synopsis of relevant content; or"}, "it-rules-2021:rule_12__subrule_5__cl_e": {"cite": "IT Rules 2021 r.12(5)(e)", "head": "", "text": "in case of any content where it is satisfied that there is a need for taking action to delete or modify the content for preventing incitement to the commission of a cognizable offence relating to public order, or in relation to the reasons enumerated in sub-section (1) of section 69A of the Act, refer such content to the Ministry for consideration by the Oversight Mechanism referred to in rule 13 for appropriate action."}, "it-rules-2021:rule_12__subrule_6": {"cite": "IT Rules 2021 r.12(6)", "head": "", "text": "Where the self-regulating body is of the opinion that there is no violation of the Code of Ethics, it shall convey such decision to the complainant and such entity."}, "it-rules-2021:rule_12__subrule_7": {"cite": "IT Rules 2021 r.12(7)", "head": "", "text": "Where a publisher fails to comply with the guidance or advisories of the self-regulating body within the time specified in such guidance or advisory, the self-regulating body shall refer the matter to the Oversight Mechanism referred to in rule 13 within fifteen days of expiry of the specified date."}, "it-rules-2021:chp_IV": {"cite": "IT Rules 2021 Chapter IV", "head": "OVERSIGHT MECHANISM - LEVEL III", "text": "Oversight mechanism The Ministry shall co-ordinate and facilitate the adherence to the Code of Ethics by publishers and self regulating bodies, develop an Oversight Mechanism, and perform the following functions, namely:— publish a charter for self regulating bodies, including Codes of Practices for such bodies; establish an Inter-Departmental Committee for hearing grievances; refer to the Inter-Departmental Committee grievances arising out of the decision of the self-regulating body under rule 12, or where no decision has been taken by the self-regulating body within the specified time period…"}, "it-rules-2021:rule_13": {"cite": "IT Rules 2021 r.13", "head": "Oversight mechanism", "text": "The Ministry shall co-ordinate and facilitate the adherence to the Code of Ethics by publishers and self regulating bodies, develop an Oversight Mechanism, and perform the following functions, namely:— publish a charter for self regulating bodies, including Codes of Practices for such bodies; establish an Inter-Departmental Committee for hearing grievances; refer to the Inter-Departmental Committee grievances arising out of the decision of the self-regulating body under rule 12, or where no decision has been taken by the self-regulating body within the specified time period, or such other comp…"}, "it-rules-2021:rule_13__subrule_1": {"cite": "IT Rules 2021 r.13(1)", "head": "", "text": "The Ministry shall co-ordinate and facilitate the adherence to the Code of Ethics by publishers and self regulating bodies, develop an Oversight Mechanism, and perform the following functions, namely:— publish a charter for self regulating bodies, including Codes of Practices for such bodies; establish an Inter-Departmental Committee for hearing grievances; refer to the Inter-Departmental Committee grievances arising out of the decision of the self-regulating body under rule 12, or where no decision has been taken by the self-regulating body within the specified time period, or such other comp…"}, "it-rules-2021:rule_13__subrule_1__cl_a": {"cite": "IT Rules 2021 r.13(1)(a)", "head": "", "text": "publish a charter for self regulating bodies, including Codes of Practices for such bodies;"}, "it-rules-2021:rule_13__subrule_1__cl_b": {"cite": "IT Rules 2021 r.13(1)(b)", "head": "", "text": "establish an Inter-Departmental Committee for hearing grievances;"}, "it-rules-2021:rule_13__subrule_1__cl_c": {"cite": "IT Rules 2021 r.13(1)(c)", "head": "", "text": "refer to the Inter-Departmental Committee grievances arising out of the decision of the self-regulating body under rule 12, or where no decision has been taken by the self-regulating body within the specified time period, or such other complaints or references relating to violation of Code of Ethics as it may consider necessary;"}, "it-rules-2021:rule_13__subrule_1__cl_d": {"cite": "IT Rules 2021 r.13(1)(d)", "head": "", "text": "issue appropriate guidance and advisories to publishers;"}, "it-rules-2021:rule_13__subrule_1__cl_e": {"cite": "IT Rules 2021 r.13(1)(e)", "head": "", "text": "issue orders and directions to the publishers for maintenance and adherence to the Code of Ethics."}, "it-rules-2021:rule_13__subrule_2": {"cite": "IT Rules 2021 r.13(2)", "head": "", "text": "The Ministry shall appoint an officer of the Ministry not below the rank of a Joint Secretary to the Government of India, as the “Authorised Officer”, for the purposes of issuing directions under rules 15 or 16, as the case may be."}, "it-rules-2021:rule_14": {"cite": "IT Rules 2021 r.14", "head": "Inter-Departmental Committee", "text": "The Ministry shall constitute an Inter-Departmental Committee, called the Committee, consisting of representatives from the Ministry of Information and Broadcasting, Ministry of Women and Child Development, Ministry of Law and Justice, Ministry of Home Affairs, Ministry of Electronics and Information Technology, Ministry of External Affairs, Ministry of Defence, and such other Ministries and Organisations, including domain experts, that it may decide to include in the Committee: Provided that the Authorised Officer designated under sub-rule (2) of rule 13 shall be the Chairperson of such Commi…"}, "it-rules-2021:rule_14__subrule_1": {"cite": "IT Rules 2021 r.14(1)", "head": "", "text": "The Ministry shall constitute an Inter-Departmental Committee, called the Committee, consisting of representatives from the Ministry of Information and Broadcasting, Ministry of Women and Child Development, Ministry of Law and Justice, Ministry of Home Affairs, Ministry of Electronics and Information Technology, Ministry of External Affairs, Ministry of Defence, and such other Ministries and Organisations, including domain experts, that it may decide to include in the Committee: Provided that the Authorised Officer designated under sub-rule (2) of rule 13 shall be the Chairperson of such Commi…"}, "it-rules-2021:rule_14__subrule_1__proviso_1": {"cite": "IT Rules 2021 r.14(1)", "head": "", "text": "Provided that the Authorised Officer designated under sub-rule (2) of rule 13 shall be the Chairperson of such Committee."}, "it-rules-2021:rule_14__subrule_2": {"cite": "IT Rules 2021 r.14(2)", "head": "", "text": "The Committee shall meet periodically and hear the following complaints regarding violation or contravention of the Code of Ethics by the entities referred to in Rule 8– arising out of the grievances in respect of the decisions taken at the Level I or II, including the cases where no such decision is taken within the time specified in the grievance redressal mechanism; or referred to it by the Ministry."}, "it-rules-2021:rule_14__subrule_2__cl_a": {"cite": "IT Rules 2021 r.14(2)(a)", "head": "", "text": "arising out of the grievances in respect of the decisions taken at the Level I or II, including the cases where no such decision is taken within the time specified in the grievance redressal mechanism; or"}, "it-rules-2021:rule_14__subrule_2__cl_b": {"cite": "IT Rules 2021 r.14(2)(b)", "head": "", "text": "referred to it by the Ministry."}, "it-rules-2021:rule_14__subrule_3": {"cite": "IT Rules 2021 r.14(3)", "head": "", "text": "Any complaint referred to the Committee, whether arising out of the grievances or referred to it by the Ministry, shall be in writing and may be sent either by mail or fax or by e-mail signed with electronic signature of the authorised representative of the entity referring the grievance, and the Committee shall ensure that such reference is assigned a number which is recorded along with the date and time of its receipt."}, "it-rules-2021:rule_14__subrule_4": {"cite": "IT Rules 2021 r.14(4)", "head": "", "text": "The Ministry shall make all reasonable efforts to identify the entity referred to in Rule 8 which has created, published or hosted the content or part thereof, and where it is able to identify such entity, it shall issue a duly signed notice to such entity to appear and submit their reply and clarifications, if any, before the Committee."}, "it-rules-2021:rule_14__subrule_5": {"cite": "IT Rules 2021 r.14(5)", "head": "", "text": "In the hearing, the Committee shall examine complaints or grievances, and may either accept or allow such complaint or grievance, and make the following recommendations to the Ministry, namely:— warning, censuring, admonishing or reprimanding such entity; or requiring an apology by such entity; or requiring such entity to include a warning card or a disclaimer; or in case of online curated content, direct a publisher to— reclassify ratings of relevant content; or edit synopsis of relevant content; or make appropriate modification in the content descriptor, age classification and parental or ac…"}, "it-rules-2021:rule_14__subrule_5__cl_a": {"cite": "IT Rules 2021 r.14(5)(a)", "head": "", "text": "warning, censuring, admonishing or reprimanding such entity; or"}, "it-rules-2021:rule_14__subrule_5__cl_b": {"cite": "IT Rules 2021 r.14(5)(b)", "head": "", "text": "requiring an apology by such entity; or"}, "it-rules-2021:rule_14__subrule_5__cl_c": {"cite": "IT Rules 2021 r.14(5)(c)", "head": "", "text": "requiring such entity to include a warning card or a disclaimer; or"}, "it-rules-2021:rule_14__subrule_5__cl_d": {"cite": "IT Rules 2021 r.14(5)(d)", "head": "", "text": "in case of online curated content, direct a publisher to— reclassify ratings of relevant content; or edit synopsis of relevant content; or make appropriate modification in the content descriptor, age classification and parental or access control;"}, "it-rules-2021:rule_14__subrule_5__cl_d__subcl_i": {"cite": "IT Rules 2021 r.14(5)(d)(i)", "head": "", "text": "reclassify ratings of relevant content; or"}, "it-rules-2021:rule_14__subrule_5__cl_d__subcl_ii": {"cite": "IT Rules 2021 r.14(5)(d)(ii)", "head": "", "text": "edit synopsis of relevant content; or"}, "it-rules-2021:rule_14__subrule_5__cl_d__subcl_iii": {"cite": "IT Rules 2021 r.14(5)(d)(iii)", "head": "", "text": "make appropriate modification in the content descriptor, age classification and parental or access control;"}, "it-rules-2021:rule_14__subrule_5__cl_e": {"cite": "IT Rules 2021 r.14(5)(e)", "head": "", "text": "delete or modify content for preventing incitement to the commission of a cognisable offence relating to public order;"}, "it-rules-2021:rule_14__subrule_5__cl_f": {"cite": "IT Rules 2021 r.14(5)(f)", "head": "", "text": "in case of content where the Committee is satisfied that there is a need for taking action in relation to the reasons enumerated in sub-section (1) of section 69A of the Act, it may recommend such action."}, "it-rules-2021:rule_14__subrule_6": {"cite": "IT Rules 2021 r.14(6)", "head": "", "text": "The Ministry may, after taking into consideration the recommendations of the Committee, issue appropriate orders and directions for compliance by the publisher: Provided that no such order shall be issued without the approval of the Secretary, Ministry of Information and Broadcasting, Government of India (hereinafter referred to as the “Secretary, Ministry of Information and Broadcasting”)."}, "it-rules-2021:rule_14__subrule_6__proviso_1": {"cite": "IT Rules 2021 r.14(6)", "head": "", "text": "Provided that no such order shall be issued without the approval of the Secretary, Ministry of Information and Broadcasting, Government of India (hereinafter referred to as the “Secretary, Ministry of Information and Broadcasting”)."}, "it-rules-2021:rule_15": {"cite": "IT Rules 2021 r.15", "head": "Procedure for issuing of direction", "text": "In respect of recommendations referred to in clauses (e) and (f) of sub-rule (5) of rule 14, the Authorised Officer shall place the matter for consideration before the Secretary, Ministry of Information and Broadcasting for taking appropriate decision. The Authorised Officer shall, on approval of the decision by the Secretary, Ministry of Information and Broadcasting, direct the publisher, any agency of the Government or any intermediary, as the case may be to delete or modify or block the relevant content and information generated, transmitted, received, stored or hosted in their computer res…"}, "it-rules-2021:rule_15__subrule_1": {"cite": "IT Rules 2021 r.15(1)", "head": "", "text": "In respect of recommendations referred to in clauses (e) and (f) of sub-rule (5) of rule 14, the Authorised Officer shall place the matter for consideration before the Secretary, Ministry of Information and Broadcasting for taking appropriate decision."}, "it-rules-2021:rule_15__subrule_2": {"cite": "IT Rules 2021 r.15(2)", "head": "", "text": "The Authorised Officer shall, on approval of the decision by the Secretary, Ministry of Information and Broadcasting, direct the publisher, any agency of the Government or any intermediary, as the case may be to delete or modify or block the relevant content and information generated, transmitted, received, stored or hosted in their computer resource for public access within the time limit specified in the direction: Provided that in case the recommendation of the Authorised Officer is not approved by the Secretary, Ministry of Information and Broadcasting, the Authorised Officer shall convey …"}, "it-rules-2021:rule_15__subrule_2__proviso_1": {"cite": "IT Rules 2021 r.15(2)", "head": "", "text": "Provided that in case the recommendation of the Authorised Officer is not approved by the Secretary, Ministry of Information and Broadcasting, the Authorised Officer shall convey the same to the Committee."}, "it-rules-2021:rule_15__subrule_3": {"cite": "IT Rules 2021 r.15(3)", "head": "", "text": "A direction under this rule may be issued only in respect of a specific piece of content or an enumerated list of content, as the case may be, and shall not require any entity to cease its operations."}, "it-rules-2021:rule_16": {"cite": "IT Rules 2021 r.16", "head": "Blocking of information in case of emergency", "text": "Notwithstanding anything contained in rules 14 and 15, the Authorised Officer, in any case of emergency nature, for which no delay is acceptable, shall examine the relevant content and consider whether it is within the grounds referred to in sub-section (1) of section 69A of the Act and it is necessary or expedient and justifiable to block such information or part thereof and submit a specific recommendation in writing to the Secretary, Ministry of Information and Broadcasting. In case of emergency nature, the Secretary, Ministry of Information and Broadcasting may, if he is satisfied that it …"}, "it-rules-2021:rule_16__subrule_1": {"cite": "IT Rules 2021 r.16(1)", "head": "", "text": "Notwithstanding anything contained in rules 14 and 15, the Authorised Officer, in any case of emergency nature, for which no delay is acceptable, shall examine the relevant content and consider whether it is within the grounds referred to in sub-section (1) of section 69A of the Act and it is necessary or expedient and justifiable to block such information or part thereof and submit a specific recommendation in writing to the Secretary, Ministry of Information and Broadcasting."}, "it-rules-2021:rule_16__subrule_2": {"cite": "IT Rules 2021 r.16(2)", "head": "", "text": "In case of emergency nature, the Secretary, Ministry of Information and Broadcasting may, if he is satisfied that it is necessary or expedient and justifiable for blocking for public access of any information or part thereof through any computer resource and after recording reasons in writing, as an interim measure issue such directions as he may consider necessary to such identified or identifiable persons, publishers or intermediary in control of such computer resource hosting such information or part thereof without giving him an opportunity of hearing."}, "it-rules-2021:rule_16__subrule_3": {"cite": "IT Rules 2021 r.16(3)", "head": "", "text": "The Authorised Officer, at the earliest but not later than forty-eight hours of issue of direction under sub-rule (2), shall bring the request before the Committee for its consideration and recommendation."}, "it-rules-2021:rule_16__subrule_4": {"cite": "IT Rules 2021 r.16(4)", "head": "", "text": "On receipt of recommendations of the Committee under sub-rule (3), the Secretary, Ministry of Information and Broadcasting, shall pass the final order as regard to approval of such request and in case the request for blocking is not approved by the Secretary, Ministry of Information and Broadcasting in his final order, the interim direction issued under sub-rule (2) shall be revoked and the person, publisher or intermediary in control of such information shall be accordingly, directed to unblock the information for public access."}, "it-rules-2021:rule_17": {"cite": "IT Rules 2021 r.17", "head": "Review of directions issued", "text": "The Authorised Officer shall maintain complete records of the proceedings of the Committee, including any complaints referred to the Committee, and shall also maintain records of recommendations made by the Committee and any directions issued by the Authorised Officer. The Review Committee shall meet at least once in every two months and record its findings whether the directions of blocking of content or information issued under these rules are in accordance with the provisions of sub-section (1) of section 69A of the Act and if it is of the opinion that the directions are not in accordance w…"}, "it-rules-2021:rule_17__subrule_1": {"cite": "IT Rules 2021 r.17(1)", "head": "", "text": "The Authorised Officer shall maintain complete records of the proceedings of the Committee, including any complaints referred to the Committee, and shall also maintain records of recommendations made by the Committee and any directions issued by the Authorised Officer."}, "it-rules-2021:rule_17__subrule_2": {"cite": "IT Rules 2021 r.17(2)", "head": "", "text": "The Review Committee shall meet at least once in every two months and record its findings whether the directions of blocking of content or information issued under these rules are in accordance with the provisions of sub-section (1) of section 69A of the Act and if it is of the opinion that the directions are not in accordance with the said provisions, it may set aside the directions and issue order for unblocking of such content or information generated, transmitted, received, stored or hosted in a computer resource."}, "it-rules-2021:rule_17__hcontainer_1": {"cite": "IT Rules 2021 r.17", "head": "", "text": "For the purpose of this rule, “Review Committee” shall mean the Review Committee constituted under rule 419A of the Indian Telegraph Rules, 1951."}, "it-rules-2021:chp_V": {"cite": "IT Rules 2021 Chapter V", "head": "FURNISHING OF INFORMATION", "text": "Furnishing of information A publisher of news and current affairs content and a publisher of online curated content operating in the territory of India, shall inform the Ministry about the details of its entity by furnishing information along with such documents as may be specified, for the purpose of enabling communication and coordination. The information referred to in sub-rule (1) shall be furnished within a period of thirty days of the publication of these rules, and where such publisher begins operation in the territory of India or comes into existence after commencement of these rules, …"}, "it-rules-2021:rule_18": {"cite": "IT Rules 2021 r.18", "head": "Furnishing of information", "text": "A publisher of news and current affairs content and a publisher of online curated content operating in the territory of India, shall inform the Ministry about the details of its entity by furnishing information along with such documents as may be specified, for the purpose of enabling communication and coordination. The information referred to in sub-rule (1) shall be furnished within a period of thirty days of the publication of these rules, and where such publisher begins operation in the territory of India or comes into existence after commencement of these rules, within thirty days from th…"}, "it-rules-2021:rule_18__subrule_1": {"cite": "IT Rules 2021 r.18(1)", "head": "", "text": "A publisher of news and current affairs content and a publisher of online curated content operating in the territory of India, shall inform the Ministry about the details of its entity by furnishing information along with such documents as may be specified, for the purpose of enabling communication and coordination."}, "it-rules-2021:rule_18__subrule_2": {"cite": "IT Rules 2021 r.18(2)", "head": "", "text": "The information referred to in sub-rule (1) shall be furnished within a period of thirty days of the publication of these rules, and where such publisher begins operation in the territory of India or comes into existence after commencement of these rules, within thirty days from the date of start of its operations in the territory of India or its coming into existence, as the case may be."}, "it-rules-2021:rule_18__subrule_3": {"cite": "IT Rules 2021 r.18(3)", "head": "", "text": "The publisher of news and current affairs content and the publisher of online curated content shall publish periodic compliance report every month mentioning the details of grievances received and action taken thereon."}, "it-rules-2021:rule_18__subrule_4": {"cite": "IT Rules 2021 r.18(4)", "head": "", "text": "The Ministry may call for such additional information from the publisher as it may consider necessary for the implementation of this Rule."}, "it-rules-2021:chp_VI": {"cite": "IT Rules 2021 Chapter VI", "head": "MISCELLANEOUS", "text": "Disclosure of Information A publisher and a self-regulating body, shall make true and full disclosure of all grievances received by it, the manner in which the grievances are disposed of, the action taken on the grievance, the reply sent to the complainant, the orders or directions received by it under these rules and action taken on such orders or directions. The information referred to in sub-rule (1) shall be displayed publicly and updated monthly. Subject to any law for the time being in force, the publisher shall preserve records of content transmitted by it for a minimum period of sixty …"}, "it-rules-2021:rule_19": {"cite": "IT Rules 2021 r.19", "head": "Disclosure of Information", "text": "A publisher and a self-regulating body, shall make true and full disclosure of all grievances received by it, the manner in which the grievances are disposed of, the action taken on the grievance, the reply sent to the complainant, the orders or directions received by it under these rules and action taken on such orders or directions. The information referred to in sub-rule (1) shall be displayed publicly and updated monthly. Subject to any law for the time being in force, the publisher shall preserve records of content transmitted by it for a minimum period of sixty days and make it available…"}, "it-rules-2021:rule_19__subrule_1": {"cite": "IT Rules 2021 r.19(1)", "head": "", "text": "A publisher and a self-regulating body, shall make true and full disclosure of all grievances received by it, the manner in which the grievances are disposed of, the action taken on the grievance, the reply sent to the complainant, the orders or directions received by it under these rules and action taken on such orders or directions."}, "it-rules-2021:rule_19__subrule_2": {"cite": "IT Rules 2021 r.19(2)", "head": "", "text": "The information referred to in sub-rule (1) shall be displayed publicly and updated monthly."}, "it-rules-2021:rule_19__subrule_3": {"cite": "IT Rules 2021 r.19(3)", "head": "", "text": "Subject to any law for the time being in force, the publisher shall preserve records of content transmitted by it for a minimum period of sixty days and make it available to the self-regulating body or the Central Government, or any other Government agency, as may be requisitioned by them for implementation of these rules."}, "it-rules-2021:sched_1": {"cite": "IT Rules 2021 Schedule", "head": "", "text": "APPENDIX CODE OF ETHICS I News and current affairs: (i) Norms of Journalistic Conduct of the Press Council of India under the Press Council Act, 1978; (ii) Programme Code under section 5 of the Cable Television Networks Regulation) Act, 1995; (iii) Content which is prohibited under any law for the time being in force shall not be published or transmitted. II Online curated content: (A) General Principles: (a) A publisher shall not transmit or publish or exhibit any content which is prohibited under any law for the time being in force or has been prohibited by any court of competent jurisdictio…"}, "it-rules-2021:sched_1__part_I": {"cite": "IT Rules 2021 Schedule, Part I", "head": "GENERAL GUIDELINES FOR CLASSIFICATION OF FILMS AND OTHER", "text": "ENTERTAINMENT PROGRAMMES, INCLUDING WEB BASED SERIALS There are general factors that may influence a classification decision at any level and in connection with any issue and the following factors are elucidated which may be read along with Part II of the Guidelines - Context: Curated content may be considered in the light of the period depicted in such content and the contemporary standards of the country and the people to which such content relates. Therefore, the context in which an issue is presented within a film or video may be given consideration. Factors such as the setting of a work (…"}, "it-rules-2021:sched_1__part_I__cl_a": {"cite": "IT Rules 2021 Schedule, Part I(a)", "head": "", "text": "Context: Curated content may be considered in the light of the period depicted in such content and the contemporary standards of the country and the people to which such content relates. Therefore, the context in which an issue is presented within a film or video may be given consideration. Factors such as the setting of a work (historical, fantasy, realistic, contemporary etc.), the manner of presentation of the content, the apparent intention of the content, the original production date of the content, and any special merits of the work may influence the classification decision."}, "it-rules-2021:sched_1__part_I__cl_b": {"cite": "IT Rules 2021 Schedule, Part I(b)", "head": "", "text": "Theme: Classification decisions may take into the theme of any content but will depend significantly on the treatment of that theme, especially the sensitivity of its presentation. The most challenging themes (for example, drug misuse, violence, pedophilia, sex, racial or communal hatred or violence etc.) are unlikely to be appropriate at the junior levels of classification."}, "it-rules-2021:sched_1__part_I__cl_c": {"cite": "IT Rules 2021 Schedule, Part I(c)", "head": "", "text": "Tone and impact: Curated content may be judged in its entirety from the point of view of its overall impact. The tone of content can be an important factor in deciding the influence it may have on various groups of people. Thus, films/serials that have a stronger depiction of violence may receive a higher classification."}, "it-rules-2021:sched_1__part_I__cl_d": {"cite": "IT Rules 2021 Schedule, Part I(d)", "head": "", "text": "Target audience: The classification of any content may also depend upon the target audience of the work and the impact of the work on such audience."}, "it-rules-2021:sched_1__part_II": {"cite": "IT Rules 2021 Schedule, Part II", "head": "ISSUE RELATED GUIDELINES", "text": "This part of the guidelines comprises the issues and concerns that apply in varying degrees to all categories of classification and elaborates the general approach that may be taken in this regard to the same. These concerns are listed in alphabetical order, and are to be read with the four General Guidelines listed in Part I Discrimination: The categorical classification of content shall take into account the impact of a film on matters such as caste, race, gender, religion, disability or sexuality that may arise in a wide range of works, and the classification decision will take account of t…"}, "it-rules-2021:sched_1__part_II__cl_a": {"cite": "IT Rules 2021 Schedule, Part II(a)", "head": "", "text": "Discrimination: The categorical classification of content shall take into account the impact of a film on matters such as caste, race, gender, religion, disability or sexuality that may arise in a wide range of works, and the classification decision will take account of the strength or impact of their inclusion."}, "it-rules-2021:sched_1__part_II__cl_b": {"cite": "IT Rules 2021 Schedule, Part II(b)", "head": "", "text": "Psychotropic substances, liquor, smoking and tobacco: Films or serials, etc. that as a whole portray misuse of psychotropic substances, liquor, smoking and tobacco would qualify for a higher category of classification."}, "it-rules-2021:sched_1__part_II__cl_c": {"cite": "IT Rules 2021 Schedule, Part II(c)", "head": "", "text": "Imitable behaviour: Classification decisions may take into account any portrayal of criminal and violent behaviour with weapons. Portrayal of potentially dangerous behaviour that are likely to incite the commission of any offence (including suicide, and infliction of self-harm) and that children and young people may potentially copy, shall receive a higher classification. Films or serials with song and dance scenes comprising lyrics and gestures that have sexual innuendos would receive a higher classification."}, "it-rules-2021:sched_1__part_II__cl_c__subpara_1": {"cite": "IT Rules 2021 Schedule, Part II(c)(1)", "head": "", "text": "Classification decisions may take into account any portrayal of criminal and violent behaviour with weapons."}, "it-rules-2021:sched_1__part_II__cl_c__subpara_2": {"cite": "IT Rules 2021 Schedule, Part II(c)(2)", "head": "", "text": "Portrayal of potentially dangerous behaviour that are likely to incite the commission of any offence (including suicide, and infliction of self-harm) and that children and young people may potentially copy, shall receive a higher classification."}, "it-rules-2021:sched_1__part_II__cl_c__subpara_3": {"cite": "IT Rules 2021 Schedule, Part II(c)(3)", "head": "", "text": "Films or serials with song and dance scenes comprising lyrics and gestures that have sexual innuendos would receive a higher classification."}, "it-rules-2021:sched_1__part_II__cl_d": {"cite": "IT Rules 2021 Schedule, Part II(d)", "head": "", "text": "Language: Language is of particular importance, given the vast linguistic diversity of our country. The use of language, dialect, idioms and euphemisms vary from region to region and are culture-specific. This factor has to be taken into account during the process of classification of a work in a particular category. Language that people may find offensive includes the use of expletives. The extent of offence may vary according to age, gender, race, background, beliefs and expectations of the target audience from the work as well as the context, region and language in which the word, expressio…"}, "it-rules-2021:sched_1__part_II__cl_d__subpara_1": {"cite": "IT Rules 2021 Schedule, Part II(d)(1)", "head": "", "text": "Language is of particular importance, given the vast linguistic diversity of our country. The use of language, dialect, idioms and euphemisms vary from region to region and are culture-specific. This factor has to be taken into account during the process of classification of a work in a particular category."}, "it-rules-2021:sched_1__part_II__cl_d__subpara_2": {"cite": "IT Rules 2021 Schedule, Part II(d)(2)", "head": "", "text": "Language that people may find offensive includes the use of expletives. The extent of offence may vary according to age, gender, race, background, beliefs and expectations of the target audience from the work as well as the context, region and language in which the word, expression or gesture is used."}, "it-rules-2021:sched_1__part_II__cl_d__subpara_3": {"cite": "IT Rules 2021 Schedule, Part II(d)(3)", "head": "", "text": "It is not possible to set out a comprehensive list of words, expressions or gestures that are acceptable at each category in every Indian language. The advice at different classification levels, therefore, provides general guidance to consider while judging the level of classification for content, based on this guideline."}, "it-rules-2021:sched_1__part_II__cl_e": {"cite": "IT Rules 2021 Schedule, Part II(e)", "head": "", "text": "Nudity: No content that is prohibited by law at the time being in force can be published or transmitted. Nudity with a sexual context will receive a higher classification of “A”."}, "it-rules-2021:sched_1__part_II__cl_e__subpara_1": {"cite": "IT Rules 2021 Schedule, Part II(e)(1)", "head": "", "text": "No content that is prohibited by law at the time being in force can be published or transmitted."}, "it-rules-2021:sched_1__part_II__cl_e__subpara_2": {"cite": "IT Rules 2021 Schedule, Part II(e)(2)", "head": "", "text": "Nudity with a sexual context will receive a higher classification of “A”."}, "it-rules-2021:sched_1__part_II__cl_f": {"cite": "IT Rules 2021 Schedule, Part II(f)", "head": "", "text": "Sex: No content that is prohibited by law at the time being in force can be published or transmitted. The classification of content in various ratings from U/A 16+ to “A” shall depend upon the portrayal of non-explicit (implicit) to explicit depiction of sexual behaviour."}, "it-rules-2021:sched_1__part_II__cl_g": {"cite": "IT Rules 2021 Schedule, Part II(g)", "head": "", "text": "Violence: Classification decisions shall take account of the degree and nature of violence in a work."}, "it-intermediaries-rules-2011:rule_1": {"cite": "Intermediaries Rules 2011 r.1", "head": "Short title and commencement", "text": "These rules may be called the Information Technology (Intermediaries guidelines) Rules, 2011. They shall come into force on the date of their publication in the Official Gazette"}, "it-intermediaries-rules-2011:rule_1__subrule_1": {"cite": "Intermediaries Rules 2011 r.1(1)", "head": "", "text": "These rules may be called the Information Technology (Intermediaries guidelines) Rules, 2011."}, "it-intermediaries-rules-2011:rule_1__subrule_2": {"cite": "Intermediaries Rules 2011 r.1(2)", "head": "", "text": "They shall come into force on the date of their publication in the Official Gazette"}, "it-intermediaries-rules-2011:rule_2": {"cite": "Intermediaries Rules 2011 r.2", "head": "Definitions", "text": "In these rules, unless the context otherwise requires,-- \"Act\" means the Information Technology Act, 2000 (21 of 2000); \"Communication link” means a connection between a hyperlink or graphical element (button, drawing, image) and one or more such items in the same or different electronic document wherein upon clicking on a hyperlinked item, the user is automatically transferred to the other end of the hyperlink which could be another document website or graphical element. \"Computer resource” means computer resources as defined in clause (k) of sub-section (1) of section 2 of the Act; \"Cyber se…"}, "it-intermediaries-rules-2011:rule_2__subrule_1": {"cite": "Intermediaries Rules 2011 r.2(1)", "head": "", "text": "In these rules, unless the context otherwise requires,-- \"Act\" means the Information Technology Act, 2000 (21 of 2000); \"Communication link” means a connection between a hyperlink or graphical element (button, drawing, image) and one or more such items in the same or different electronic document wherein upon clicking on a hyperlinked item, the user is automatically transferred to the other end of the hyperlink which could be another document website or graphical element. \"Computer resource” means computer resources as defined in clause (k) of sub-section (1) of section 2 of the Act; \"Cyber se…"}, "it-intermediaries-rules-2011:rule_2__subrule_1__cl_a": {"cite": "Intermediaries Rules 2011 r.2(1)(a)", "head": "", "text": "\"Act\" means the Information Technology Act, 2000 (21 of 2000);"}, "it-intermediaries-rules-2011:rule_2__subrule_1__cl_b": {"cite": "Intermediaries Rules 2011 r.2(1)(b)", "head": "", "text": "\"Communication link” means a connection between a hyperlink or graphical element (button, drawing, image) and one or more such items in the same or different electronic document wherein upon clicking on a hyperlinked item, the user is automatically transferred to the other end of the hyperlink which could be another document website or graphical element."}, "it-intermediaries-rules-2011:rule_2__subrule_1__cl_c": {"cite": "Intermediaries Rules 2011 r.2(1)(c)", "head": "", "text": "\"Computer resource” means computer resources as defined in clause (k) of sub-section (1) of section 2 of the Act;"}, "it-intermediaries-rules-2011:rule_2__subrule_1__cl_d": {"cite": "Intermediaries Rules 2011 r.2(1)(d)", "head": "", "text": "\"Cyber security incidnt” means any real or suspected adverse event in relation to cyber security that violates an explicity or implicity applicable security policy resulting in unauthotrised access, denial of service or disruption, unauthorised use of a computer resource for processing or storage of information or changes to data, information without authorisation;"}, "it-intermediaries-rules-2011:rule_2__subrule_1__cl_e": {"cite": "Intermediaries Rules 2011 r.2(1)(e)", "head": "", "text": "\"Data\" means data as defined in clause (o) of sub-section (1) of section 2 of the Act;"}, "it-intermediaries-rules-2011:rule_2__subrule_1__cl_f": {"cite": "Intermediaries Rules 2011 r.2(1)(f)", "head": "", "text": "\"Electronic Signature\" means electronic signature as defined in clause (ta) of sub-section (1) of section 2 of the Act;"}, "it-intermediaries-rules-2011:rule_2__subrule_1__cl_g": {"cite": "Intermediaries Rules 2011 r.2(1)(g)", "head": "", "text": "\"Indian Computer Emergency Response Team” means the Indian Computer Emergency Response Team appointed under sub section (1) section 70 (B) of the Act;"}, "it-intermediaries-rules-2011:rule_2__subrule_1__cl_h": {"cite": "Intermediaries Rules 2011 r.2(1)(h)", "head": "", "text": "“Information” means information as defined in clause (v) of sub-section (1) of section 2 of the Act;"}, "it-intermediaries-rules-2011:rule_2__subrule_1__cl_i": {"cite": "Intermediaries Rules 2011 r.2(1)(i)", "head": "", "text": "“Intermediary” means an intermediary as defined in clause (w) of sub-section (1) of section 2 of the Act;"}, "it-intermediaries-rules-2011:rule_2__subrule_1__cl_j": {"cite": "Intermediaries Rules 2011 r.2(1)(j)", "head": "", "text": "\"User\" means any person who access or avail any computer resource of intermediary for the purpose of hosting, publishing, sharing, transacting, displaying or uploading information or views and includes other persons jointly participating in using the computer resource of an intermediary."}, "it-intermediaries-rules-2011:rule_2__subrule_2": {"cite": "Intermediaries Rules 2011 r.2(2)", "head": "", "text": "Ail other words and expressions used and not defined in these rules but defined in the Act shall have the meanings respectively assigned to them in the Act."}, "it-intermediaries-rules-2011:rule_3": {"cite": "Intermediaries Rules 2011 r.3", "head": "Due diligence to he observed by intermediary", "text": "The intermediary shall observe following due diligence while discharging his duties, namely : — The intermediary shall publish the rules and regulations, privacy policy and user agreement for access-or usage of the intermediary's computer resource by any person. Such rules and regulations, terms and conditions or user agreement shall inform the users of computer resource not to host, display, upload, modify, publish, transmit, update or share any information that — belongs to another person and to which the user does not have any right to; is grossly harmful, harassing, blasphemous defamatory,…"}, "it-intermediaries-rules-2011:rule_3__subrule_1": {"cite": "Intermediaries Rules 2011 r.3(1)", "head": "", "text": "The intermediary shall publish the rules and regulations, privacy policy and user agreement for access-or usage of the intermediary's computer resource by any person."}, "it-intermediaries-rules-2011:rule_3__subrule_2": {"cite": "Intermediaries Rules 2011 r.3(2)", "head": "", "text": "Such rules and regulations, terms and conditions or user agreement shall inform the users of computer resource not to host, display, upload, modify, publish, transmit, update or share any information that — belongs to another person and to which the user does not have any right to; is grossly harmful, harassing, blasphemous defamatory, obscene, pornographic, paedophilic, libellous, invasive of another's privacy, hateful, or racially, ethnically objectionable, disparaging, relating or encouraging money laundering or gambling, or otherwise unlawful in any manner whatever; harm minors in any way;…"}, "it-intermediaries-rules-2011:rule_3__subrule_2__cl_a": {"cite": "Intermediaries Rules 2011 r.3(2)(a)", "head": "", "text": "belongs to another person and to which the user does not have any right to;"}, "it-intermediaries-rules-2011:rule_3__subrule_2__cl_b": {"cite": "Intermediaries Rules 2011 r.3(2)(b)", "head": "", "text": "is grossly harmful, harassing, blasphemous defamatory, obscene, pornographic, paedophilic, libellous, invasive of another's privacy, hateful, or racially, ethnically objectionable, disparaging, relating or encouraging money laundering or gambling, or otherwise unlawful in any manner whatever;"}, "it-intermediaries-rules-2011:rule_3__subrule_2__cl_c": {"cite": "Intermediaries Rules 2011 r.3(2)(c)", "head": "", "text": "harm minors in any way;"}, "it-intermediaries-rules-2011:rule_3__subrule_2__cl_d": {"cite": "Intermediaries Rules 2011 r.3(2)(d)", "head": "", "text": "infringes any patent, trademark, copyright or other proprietary rights;"}, "it-intermediaries-rules-2011:rule_3__subrule_2__cl_e": {"cite": "Intermediaries Rules 2011 r.3(2)(e)", "head": "", "text": "violates any law for the time being in force;"}, "it-intermediaries-rules-2011:rule_3__subrule_2__cl_f": {"cite": "Intermediaries Rules 2011 r.3(2)(f)", "head": "", "text": "deceives or misleads the addressee about the origin of such messages or communicates any information which is grossly offensive or menacing in nature;"}, "it-intermediaries-rules-2011:rule_3__subrule_2__cl_g": {"cite": "Intermediaries Rules 2011 r.3(2)(g)", "head": "", "text": "impersonate another person;"}, "it-intermediaries-rules-2011:rule_3__subrule_2__cl_h": {"cite": "Intermediaries Rules 2011 r.3(2)(h)", "head": "", "text": "contains software viruses or any other computer code, files or programs designed to interrupt, destroy or limit the functionality of any computer resource;"}, "it-intermediaries-rules-2011:rule_3__subrule_2__cl_i": {"cite": "Intermediaries Rules 2011 r.3(2)(i)", "head": "", "text": "threatens the unity, integrity, defence, security or sovereignty of India, friendly relations with foreign states, or public order or causes incitement to the commission of any cognisable offence or prevents investigation of any offence or is insulting any other nation"}, "it-intermediaries-rules-2011:rule_3__subrule_3": {"cite": "Intermediaries Rules 2011 r.3(3)", "head": "", "text": "The intermediary shall not knowingly host or publish any information or shall not initiate the transmission, select the receiver of transmission, and select or modify the information contained in the transmission as specified in sub-rule (2): provided that the following actions by an intermediary shall not amount to hosing, publishing, editing or storing of any such information as specified in sub-rule: (2) — temporary or transient or intermediate storage of information automatically within the computer resource as an intrinsic feature of such computer resource, involving no exercise of any hu…"}, "it-intermediaries-rules-2011:rule_3__subrule_3__cl_a": {"cite": "Intermediaries Rules 2011 r.3(3)(a)", "head": "", "text": "temporary or transient or intermediate storage of information automatically within the computer resource as an intrinsic feature of such computer resource, involving no exercise of any human editorial control, for onward transmission or communication to another computer resource;"}, "it-intermediaries-rules-2011:rule_3__subrule_3__cl_b": {"cite": "Intermediaries Rules 2011 r.3(3)(b)", "head": "", "text": "removal of access to any information, data or communication link by an intermediary after such information, data or communication link comes to the actual knowledge of a person authorised by the intermediary pursuant to any order or direction as per the provisions of the Act;"}, "it-intermediaries-rules-2011:rule_3__subrule_4": {"cite": "Intermediaries Rules 2011 r.3(4)", "head": "", "text": "The intermediary, on whose computer system the information is stored or hosted or published, upon obtaining knowledge by itself or been brought to actual knowledge by an affected person in writing or through email signed with electronic signature about any such information as mentioned in sub-rule (2) above, shall act within thirty six hours and where applicable, work with user or owner of such information to disable such information that is in contravention of sub-rule (2). Further the intermediary shall preserve such information and associated records for at least ninety days for investigati…"}, "it-intermediaries-rules-2011:rule_3__subrule_5": {"cite": "Intermediaries Rules 2011 r.3(5)", "head": "", "text": "The Intermediary shall inform its users that in case of non-compliance with rules and regulations, user agreement and privacy policy for access or usage of intermediary computer resource, the Intermediary has the right to immediately terminate the access or usage lights of the users to the computer resource of Intermediary and remove non-compliant information.."}, "it-intermediaries-rules-2011:rule_3__subrule_6": {"cite": "Intermediaries Rules 2011 r.3(6)", "head": "", "text": "The intermediary shall strictly follow the provisions of the Act or any other laws for the time being in force."}, "it-intermediaries-rules-2011:rule_3__subrule_7": {"cite": "Intermediaries Rules 2011 r.3(7)", "head": "", "text": "When required by lawful order, the intermediary shall provide information or any such assistance to Government Agencies who are lawfully authorised for investigative, protective, cyber security activity. The information or any such assistance shall be provided for the purpose of verification of identity, or for prevention, detection, investigation, prosecution, cyber security incidents and punishment of offences under any law for the time being in force, on a request in writing staling clearly the purpose of seeking such information or any such assistance."}, "it-intermediaries-rules-2011:rule_3__subrule_8": {"cite": "Intermediaries Rules 2011 r.3(8)", "head": "", "text": "The intermediary shall take all reasonable measures to secure its computer resource and information contained therein following the reasonable security practices and procedures as prescribed in the Information Technology (Reasonable security practices and procedures and sensitive personal Information) Rules, 2011."}, "it-intermediaries-rules-2011:rule_3__subrule_9": {"cite": "Intermediaries Rules 2011 r.3(9)", "head": "", "text": "The intermediary shall report cyber security incidents and also share cyber security incidents related information with the Indian Computer Emergency Response Team."}, "it-intermediaries-rules-2011:rule_3__subrule_10": {"cite": "Intermediaries Rules 2011 r.3(10)", "head": "", "text": "The intermediary shall not knowingly deploy or install or modify the technical configuration of computer resource or become party to any such act which may change or has the potential to change the normal course of operation of the computer resource than what it is supposed to \"perform thereby circumventing any law for the time being in force: provided that the intermediary may develop, produce, distribute or employ technological means for the sole purpose of performing the acts of securing the computer resource and information contained therein."}, "it-intermediaries-rules-2011:rule_3__subrule_11": {"cite": "Intermediaries Rules 2011 r.3(11)", "head": "", "text": "The intermediary shall publish on its website the name of the Grievance Officer and his contact details as well as mechanism by which users or any victim who suffers as a result of access or usage of computer resource by any person in violation of rule 3 can notify their complaints against such access or usage of computer resource of the intermediary or other matters pertaining to the computer resources made available by it. The Grievance Officer shall redress the complaints within one month from the date of receipt of complaint."}, "it-spdi-rules-2011:rule_1": {"cite": "SPDI Rules 2011 r.1", "head": "Short title and commencement", "text": "These rules may be called the Information Technology (Reasonable security practices and procedures and sensitive personal data or information) Rules, 2011. They shall come into force on the date of their publication in the Official Gazette."}, "it-spdi-rules-2011:rule_1__subrule_1": {"cite": "SPDI Rules 2011 r.1(1)", "head": "", "text": "These rules may be called the Information Technology (Reasonable security practices and procedures and sensitive personal data or information) Rules, 2011."}, "it-spdi-rules-2011:rule_1__subrule_2": {"cite": "SPDI Rules 2011 r.1(2)", "head": "", "text": "They shall come into force on the date of their publication in the Official Gazette."}, "it-spdi-rules-2011:rule_2": {"cite": "SPDI Rules 2011 r.2", "head": "Definitions", "text": "In these rules, unless the context otherwise requires,-- \"Act\" means the Information Technology Act, 2000 (21 of 2000); \"Biometrics\" means the technologies that measure and analyse human body characteristics, such as 'fingerprints', 'eye retinas and irises', 'voice patterns', \"facial patterns', 'hand measurements' and 'DNA' for authentication purposes; \"Body corporate\" means the body corporate as defined in clause (i) of explanation to section 43A of the Act; \"Cyber incidents\" means any real or suspected adverse event in relation to cyber security that violates an explicitly or implicitly appl…"}, "it-spdi-rules-2011:rule_2__subrule_1": {"cite": "SPDI Rules 2011 r.2(1)", "head": "", "text": "In these rules, unless the context otherwise requires,-- \"Act\" means the Information Technology Act, 2000 (21 of 2000); \"Biometrics\" means the technologies that measure and analyse human body characteristics, such as 'fingerprints', 'eye retinas and irises', 'voice patterns', \"facial patterns', 'hand measurements' and 'DNA' for authentication purposes; \"Body corporate\" means the body corporate as defined in clause (i) of explanation to section 43A of the Act; \"Cyber incidents\" means any real or suspected adverse event in relation to cyber security that violates an explicitly or implicitly appl…"}, "it-spdi-rules-2011:rule_2__subrule_1__cl_a": {"cite": "SPDI Rules 2011 r.2(1)(a)", "head": "", "text": "\"Act\" means the Information Technology Act, 2000 (21 of 2000);"}, "it-spdi-rules-2011:rule_2__subrule_1__cl_b": {"cite": "SPDI Rules 2011 r.2(1)(b)", "head": "", "text": "\"Biometrics\" means the technologies that measure and analyse human body characteristics, such as 'fingerprints', 'eye retinas and irises', 'voice patterns', \"facial patterns', 'hand measurements' and 'DNA' for authentication purposes;"}, "it-spdi-rules-2011:rule_2__subrule_1__cl_c": {"cite": "SPDI Rules 2011 r.2(1)(c)", "head": "", "text": "\"Body corporate\" means the body corporate as defined in clause (i) of explanation to section 43A of the Act;"}, "it-spdi-rules-2011:rule_2__subrule_1__cl_d": {"cite": "SPDI Rules 2011 r.2(1)(d)", "head": "", "text": "\"Cyber incidents\" means any real or suspected adverse event in relation to cyber security that violates an explicitly or implicitly applicable security policy resulting in unauthorised access, denial of service or disruption, unauthorised use of a computer resource for processing or storage of information or changes to data, information without authorisation;"}, "it-spdi-rules-2011:rule_2__subrule_1__cl_e": {"cite": "SPDI Rules 2011 r.2(1)(e)", "head": "", "text": "\"Data\" means data as defined in clause (o) of sub-section (1) of section 2 of the Act;"}, "it-spdi-rules-2011:rule_2__subrule_1__cl_f": {"cite": "SPDI Rules 2011 r.2(1)(f)", "head": "", "text": "\"Information\" means information as defined in clause (v) of sub-section (1) of section 2 of the Act;"}, "it-spdi-rules-2011:rule_2__subrule_1__cl_g": {"cite": "SPDI Rules 2011 r.2(1)(g)", "head": "", "text": "\"Intermediary\" means an intermediary as defined in clause (w) of sub-section (1) of section 2 of the Act; THE GAZETTE OF INDIA : EXTRAORDINARY [ PART II-SEC. 3(i)]"}, "it-spdi-rules-2011:rule_2__subrule_1__cl_h": {"cite": "SPDI Rules 2011 r.2(1)(h)", "head": "", "text": "\"Password\" means a secret word or phrase or code or passphrase or secret key, or encryption or decryption keys that one uses to gain admittance or access to information;"}, "it-spdi-rules-2011:rule_2__subrule_1__cl_i": {"cite": "SPDI Rules 2011 r.2(1)(i)", "head": "", "text": "\"Personal information\" means any information that relates to a natural person, which, either directly or indirectly, in combination with other information available or likely to be available with a body corporate, is capable of identifying such person."}, "it-spdi-rules-2011:rule_2__subrule_2": {"cite": "SPDI Rules 2011 r.2(2)", "head": "", "text": "All other words and expressions used and not defined in these rules but defined in the Act shall have the meanings respectively assigned to them in the Act."}, "it-spdi-rules-2011:rule_3": {"cite": "SPDI Rules 2011 r.3", "head": "Sensitive personal data or information", "text": "Sensitive personal data or information of a person means such personal information which consists of information relating to;— password; financial information such as Bank account or credit card or debit card or other payment instrument details ; physical, physiological and mental health condition; sexual orientation; medical records and history; Biometric information; any detail relating to the above clauses as provided to body corporate for providing service; and any of the information received under above clauses by body corporate for processing, stored or processed under lawful contract or…"}, "it-spdi-rules-2011:rule_3__subcl_i": {"cite": "SPDI Rules 2011 r.3(i)", "head": "", "text": "password;"}, "it-spdi-rules-2011:rule_3__subcl_ii": {"cite": "SPDI Rules 2011 r.3(ii)", "head": "", "text": "financial information such as Bank account or credit card or debit card or other payment instrument details ;"}, "it-spdi-rules-2011:rule_3__subcl_iii": {"cite": "SPDI Rules 2011 r.3(iii)", "head": "", "text": "physical, physiological and mental health condition;"}, "it-spdi-rules-2011:rule_3__subcl_iv": {"cite": "SPDI Rules 2011 r.3(iv)", "head": "", "text": "sexual orientation;"}, "it-spdi-rules-2011:rule_3__subcl_v": {"cite": "SPDI Rules 2011 r.3(v)", "head": "", "text": "medical records and history;"}, "it-spdi-rules-2011:rule_3__subcl_vi": {"cite": "SPDI Rules 2011 r.3(vi)", "head": "", "text": "Biometric information;"}, "it-spdi-rules-2011:rule_3__subcl_vii": {"cite": "SPDI Rules 2011 r.3(vii)", "head": "", "text": "any detail relating to the above clauses as provided to body corporate for providing service; and"}, "it-spdi-rules-2011:rule_3__subcl_viii": {"cite": "SPDI Rules 2011 r.3(viii)", "head": "", "text": "any of the information received under above clauses by body corporate for processing, stored or processed under lawful contract or otherwise: provided that, any information that is freely available or accessible in public domain or furnished under the Right to Information Act, 2005 or any other law for the time being in force shall not be regarded as sensitive personal data or information for the purposes of these rules."}, "it-spdi-rules-2011:rule_4": {"cite": "SPDI Rules 2011 r.4", "head": "Body corporate to provide policy for privacy and disclosure of information", "text": "The body corporate or any person who on behalf of body corporate collects, receives, possess, stores, deals or handle information of provider of information, shall provide a privacy policy for handling of or dealing in personal information including sensitive personal data or information and ensure that the same are available for view by such providers of information who has provided such information under lawful contract. Such policy shall be published on website of body corporate or any person on its behalf and shall provide for— Clear and easily accessible statements of its practices and po…"}, "it-spdi-rules-2011:rule_4__subrule_1": {"cite": "SPDI Rules 2011 r.4(1)", "head": "", "text": "The body corporate or any person who on behalf of body corporate collects, receives, possess, stores, deals or handle information of provider of information, shall provide a privacy policy for handling of or dealing in personal information including sensitive personal data or information and ensure that the same are available for view by such providers of information who has provided such information under lawful contract. Such policy shall be published on website of body corporate or any person on its behalf and shall provide for— Clear and easily accessible statements of its practices and po…"}, "it-spdi-rules-2011:rule_4__subrule_1__subcl_i": {"cite": "SPDI Rules 2011 r.4(1)(i)", "head": "", "text": "Clear and easily accessible statements of its practices and policies;"}, "it-spdi-rules-2011:rule_4__subrule_1__subcl_ii": {"cite": "SPDI Rules 2011 r.4(1)(ii)", "head": "", "text": "type of personal or sensitive personal data or information collected under rule 3; [ II- 3(i)] :"}, "it-spdi-rules-2011:rule_4__subrule_1__subcl_iii": {"cite": "SPDI Rules 2011 r.4(1)(iii)", "head": "", "text": "purpose of collection and usage of such information;"}, "it-spdi-rules-2011:rule_4__subrule_1__subcl_iv": {"cite": "SPDI Rules 2011 r.4(1)(iv)", "head": "", "text": "disclosure of information including sensitive personal data or information as provided in rule 6;"}, "it-spdi-rules-2011:rule_4__subrule_1__subcl_v": {"cite": "SPDI Rules 2011 r.4(1)(v)", "head": "", "text": "reasonable security practices and procedures as provided under rule 8."}, "it-spdi-rules-2011:rule_5": {"cite": "SPDI Rules 2011 r.5", "head": "Collection of information", "text": "Body corporate or any person on its behalf shall obtain consent in writing through letter or Fax or email from the provider of the sensitive personal data or information regarding purpose of usage before collection of such information. Body corporate or any person on its behalf shall not collect sensitive personal data or information unless — the information is collected for a lawful purpose connected with a function or activity of the body corporate or any person on its behalf; and the collection of the sensitive personal data or information is considered necessary for that purpose. While col…"}, "it-spdi-rules-2011:rule_5__subrule_1": {"cite": "SPDI Rules 2011 r.5(1)", "head": "", "text": "Body corporate or any person on its behalf shall obtain consent in writing through letter or Fax or email from the provider of the sensitive personal data or information regarding purpose of usage before collection of such information."}, "it-spdi-rules-2011:rule_5__subrule_2": {"cite": "SPDI Rules 2011 r.5(2)", "head": "", "text": "Body corporate or any person on its behalf shall not collect sensitive personal data or information unless — the information is collected for a lawful purpose connected with a function or activity of the body corporate or any person on its behalf; and the collection of the sensitive personal data or information is considered necessary for that purpose."}, "it-spdi-rules-2011:rule_5__subrule_2__cl_a": {"cite": "SPDI Rules 2011 r.5(2)(a)", "head": "", "text": "the information is collected for a lawful purpose connected with a function or activity of the body corporate or any person on its behalf; and"}, "it-spdi-rules-2011:rule_5__subrule_2__cl_b": {"cite": "SPDI Rules 2011 r.5(2)(b)", "head": "", "text": "the collection of the sensitive personal data or information is considered necessary for that purpose."}, "it-spdi-rules-2011:rule_5__subrule_3": {"cite": "SPDI Rules 2011 r.5(3)", "head": "", "text": "While collecting information directly from the person concerned, the body corporate or any person on its behalf snail take such steps as are, in the circumstances, reasonable to ensure that the person concerned is having the knowledge of — the fact that the information is being collected; the purpose for which the information is being collected; the intended recipients of the information; and the name and address of — the agency that is collecting the information; and the agency that will retain the information."}, "it-spdi-rules-2011:rule_5__subrule_3__cl_a": {"cite": "SPDI Rules 2011 r.5(3)(a)", "head": "", "text": "the fact that the information is being collected;"}, "it-spdi-rules-2011:rule_5__subrule_3__cl_b": {"cite": "SPDI Rules 2011 r.5(3)(b)", "head": "", "text": "the purpose for which the information is being collected;"}, "it-spdi-rules-2011:rule_5__subrule_3__cl_c": {"cite": "SPDI Rules 2011 r.5(3)(c)", "head": "", "text": "the intended recipients of the information; and"}, "it-spdi-rules-2011:rule_5__subrule_3__cl_d": {"cite": "SPDI Rules 2011 r.5(3)(d)", "head": "", "text": "the name and address of — the agency that is collecting the information; and the agency that will retain the information."}, "it-spdi-rules-2011:rule_5__subrule_3__cl_d__subcl_i": {"cite": "SPDI Rules 2011 r.5(3)(d)(i)", "head": "", "text": "the agency that is collecting the information; and"}, "it-spdi-rules-2011:rule_5__subrule_3__cl_d__subcl_ii": {"cite": "SPDI Rules 2011 r.5(3)(d)(ii)", "head": "", "text": "the agency that will retain the information."}, "it-spdi-rules-2011:rule_5__subrule_4": {"cite": "SPDI Rules 2011 r.5(4)", "head": "", "text": "Body corporate or any person on its behalf holding sensitive personal data or information shall not retain that information for longer than is required for the purposes for which the information may lawfully be used or is otherwise required under any other law for the time being in force.."}, "it-spdi-rules-2011:rule_5__subrule_5": {"cite": "SPDI Rules 2011 r.5(5)", "head": "", "text": "The information collected shall be used for the purpose for which it has been collected."}, "it-spdi-rules-2011:rule_5__subrule_6": {"cite": "SPDI Rules 2011 r.5(6)", "head": "", "text": "Body corporate or any person on its behalf permit the providers of information, as and when requested by them, to review the information they had provided and ensure that any personal information or sensitive personal data or information found to be inaccurate or deficient shall be corrected or amended as feasible:"}, "it-spdi-rules-2011:rule_5__proviso_1": {"cite": "SPDI Rules 2011 r.5", "head": "", "text": "Provided that a body corporate shall not be responsible for the authenticity of the personal information or sensitive personal data or information supplied by THE GAZETTE OF INDIA : EXTRAORDINARY [ PART II-SEC. 3(i)] the provider of information to such boy corporate or any other person acting on behalf of such body corporate."}, "it-spdi-rules-2011:rule_5__subrule_7": {"cite": "SPDI Rules 2011 r.5(7)", "head": "", "text": "Body corporate or any person on its behalf shall, prior to the collection of information including sensitive personal data or information, provide an option to the provider of the information to not to provide the data or information sought to be collected. The provider of information shall, at any time while availing the services or otherwise, also have an option to withdraw its consent given earlier to the body corporate. Such withdrawal of the consent shall be sent in writing to the body corporate. In the case of provider of information not providing or later on withdrawing his consent, the…"}, "it-spdi-rules-2011:rule_5__subrule_8": {"cite": "SPDI Rules 2011 r.5(8)", "head": "", "text": "Body corporate or any person on its behalf shall keep the information secure as provided in rule 8."}, "it-spdi-rules-2011:rule_5__subrule_9": {"cite": "SPDI Rules 2011 r.5(9)", "head": "", "text": "Body corporate shall address any discrepancies and grievances of their provider of the information with respect to processing of information in a time bound manner. For this purpose, the body corporate shall designate a Grievance Officer and publish his name and contact details on its website. The Grievance Officer shall redress the grievances or provider of information expeditiously but within one month ' from the date of receipt of grievance."}, "it-spdi-rules-2011:rule_6": {"cite": "SPDI Rules 2011 r.6", "head": "Disclosure of information", "text": "Disclosure of sensitive personal data or information by body corporate to any third party shall require prior permission from the provider of such information, who has provided such information under lawful contract or otherwise, unless such disclosure has been agreed to in the contract between the body corporate and provider of information, or where the disclosure is necessary for compliance of a legal obligation: Provided that the information shall be shared, without obtaining prior consent from provider of information, with Government agencies mandated under the law to obtain information in…"}, "it-spdi-rules-2011:rule_6__subrule_1": {"cite": "SPDI Rules 2011 r.6(1)", "head": "", "text": "Disclosure of sensitive personal data or information by body corporate to any third party shall require prior permission from the provider of such information, who has provided such information under lawful contract or otherwise, unless such disclosure has been agreed to in the contract between the body corporate and provider of information, or where the disclosure is necessary for compliance of a legal obligation: Provided that the information shall be shared, without obtaining prior consent from provider of information, with Government agencies mandated under the law to obtain information in…"}, "it-spdi-rules-2011:rule_6__subrule_1__proviso_1": {"cite": "SPDI Rules 2011 r.6(1)", "head": "", "text": "Provided that the information shall be shared, without obtaining prior consent from provider of information, with Government agencies mandated under the law to obtain information including sensitive personal data or information for the purpose of verification of identity, or for prevention, detection, investigation including cyber incidents, prosecution, and punishment of offences. The Government agency shall send a request in writing to the body corporate possessing the sensitive personal data or information stating clearly the purpose of seeking such information. The Government agency shall …"}, "it-spdi-rules-2011:rule_6__subrule_2": {"cite": "SPDI Rules 2011 r.6(2)", "head": "", "text": "Notwithstanding anything contain in sub-rule (1), any sensitive personal data on Information shall be disclosed to any third party by an order under the law for the time being in force. [ II- 3(i)] :"}, "it-spdi-rules-2011:rule_6__subrule_3": {"cite": "SPDI Rules 2011 r.6(3)", "head": "", "text": "The body corporate or any person on its behalf shall not publish the sensitive personal data or information."}, "it-spdi-rules-2011:rule_6__subrule_4": {"cite": "SPDI Rules 2011 r.6(4)", "head": "", "text": "The third party receiving the sensitive personal data or information from body corporate or any person on its behalf under sub-rule (1) shall not disclose it further."}, "it-spdi-rules-2011:rule_7": {"cite": "SPDI Rules 2011 r.7", "head": "Transfer of information", "text": "A body corporate or any person on its behalf may transfer sensitive personal data or information including any information, to any other body corporate or a person in India, or located in any other country, that ensures the same level of data protection that is adhered to by the body corporate as provided for under these Rules. The transfer may be allowed only if it is necessary for the performance of the lawful contract between the body corporate or any person on its behalf and provider of information or where such person has consented to data transfer."}, "it-spdi-rules-2011:rule_8": {"cite": "SPDI Rules 2011 r.8", "head": "Reasonable Security Practices and Procedures", "text": "A body corporate or a person on its behalf shall be considered to have complied with reasonable security practices and procedures, if they have implemented such security practices and standards and have a comprehensive documented information security programme and information security policies that contain managerial, technical, operational and physical security control measures that are commensurate with the information assets being protected with the nature of business. In the event of an information security breach, the body corporate or a person on its behalf shall be required to demonstra…"}, "it-spdi-rules-2011:rule_8__subrule_1": {"cite": "SPDI Rules 2011 r.8(1)", "head": "", "text": "A body corporate or a person on its behalf shall be considered to have complied with reasonable security practices and procedures, if they have implemented such security practices and standards and have a comprehensive documented information security programme and information security policies that contain managerial, technical, operational and physical security control measures that are commensurate with the information assets being protected with the nature of business. In the event of an information security breach, the body corporate or a person on its behalf shall be required to demonstra…"}, "it-spdi-rules-2011:rule_8__subrule_2": {"cite": "SPDI Rules 2011 r.8(2)", "head": "", "text": "The international Standard IS/ISO/IEC 27001 on \"Information Technology - Security Techniques - Information Security Management System - Requirements\" is one such standard referred to in sub-rule (1)."}, "it-spdi-rules-2011:rule_8__subrule_3": {"cite": "SPDI Rules 2011 r.8(3)", "head": "", "text": "Any industry association or an entity formed by such an association, whose members are self-regulating by following other than IS/ISO/IEC codes of best practices for data protection as per sub-rule(1), shall get its codes of best practices duly approved and notified by the Central Government for effective implementation."}, "it-spdi-rules-2011:rule_8__subrule_4": {"cite": "SPDI Rules 2011 r.8(4)", "head": "", "text": "The body corporate or a person on its behalf who have implemented either IS/ISO/IEC 27001 standard or the codes of best practices for data protection as approved and notified under sub-rule (3) shall be deemed to have complied with reasonable security practices and procedures provided that such standard or the codes of best practices have been certified or audited on a regular basis by entities through independent auditor, duly approved by the Central Government. The audit of reasonable security practices and procedures shall be carried cut by an auditor at least once a year or as and when the…"}, "indian-stamp-act-1899:chp_I": {"cite": "Stamp Act Chapter I", "head": "PRELIMINARY", "text": "Short title, extent and commencement This Act may be called the Indian Stamp Act, 1899. [It extends to the whole of India ***: Provided that it shall not apply to [the territories which, immediately before the 1st November, 1956, were comprised in Part B States] (excluding the State of Jammu and Kashmir) except to the extent to which the provisions of this Act relate to rates of stamp-duty in respect of the documents specified in Entry 91 of List I in the Seventh Schedule to the Constitution]. It shall come into force on the first day of July, 1899. Definitions In this Act, unless there is som…"}, "indian-stamp-act-1899:sec_1": {"cite": "Stamp Act s.1", "head": "Short title, extent and commencement", "text": "This Act may be called the Indian Stamp Act, 1899. [It extends to the whole of India ***: Provided that it shall not apply to [the territories which, immediately before the 1st November, 1956, were comprised in Part B States] (excluding the State of Jammu and Kashmir) except to the extent to which the provisions of this Act relate to rates of stamp-duty in respect of the documents specified in Entry 91 of List I in the Seventh Schedule to the Constitution]. It shall come into force on the first day of July, 1899."}, "indian-stamp-act-1899:sec_1__subsec_1": {"cite": "Stamp Act s.1(1)", "head": "", "text": "This Act may be called the Indian Stamp Act, 1899."}, "indian-stamp-act-1899:sec_1__subsec_2": {"cite": "Stamp Act s.1(2)", "head": "", "text": "[It extends to the whole of India ***: Provided that it shall not apply to [the territories which, immediately before the 1st November, 1956, were comprised in Part B States] (excluding the State of Jammu and Kashmir) except to the extent to which the provisions of this Act relate to rates of stamp-duty in respect of the documents specified in Entry 91 of List I in the Seventh Schedule to the Constitution]."}, "indian-stamp-act-1899:sec_1__subsec_2__proviso_1": {"cite": "Stamp Act s.1(2)", "head": "", "text": "Provided that it shall not apply to [the territories which, immediately before the 1st November, 1956, were comprised in Part B States] (excluding the State of Jammu and Kashmir) except to the extent to which the provisions of this Act relate to rates of stamp-duty in respect of the documents specified in Entry 91 of List I in the Seventh Schedule to the Constitution]."}, "indian-stamp-act-1899:sec_1__subsec_3": {"cite": "Stamp Act s.1(3)", "head": "", "text": "It shall come into force on the first day of July, 1899."}, "indian-stamp-act-1899:sec_2": {"cite": "Stamp Act s.2", "head": "Definitions", "text": "In this Act, unless there is something repugnant in the subject or context,— [Allotment list.—“allotment list” means a list containing details of allotment of the securities intimated by the issuer to the depository under sub-section (2) of section 8 of the Depositories Act, 1996 (22 of 1996); “banker” includes a bank and any person acting as a banker;] Bill of exchange.—“bill of exchange” means a bill of exchange as defined by the Negotiable Instruments Act, 1881, (26 of 1881), and includes also a hundi, and any other document entitling or purporting to entitle any person, whether named there…"}, "indian-stamp-act-1899:sec_2__subsec_1": {"cite": "Stamp Act s.2(1)", "head": "", "text": "[Allotment list.—“allotment list” means a list containing details of allotment of the securities intimated by the issuer to the depository under sub-section (2) of section 8 of the Depositories Act, 1996 (22 of 1996);"}, "indian-stamp-act-1899:sec_2__subsec_1A": {"cite": "Stamp Act s.2(1A)", "head": "", "text": "“banker” includes a bank and any person acting as a banker;]"}, "indian-stamp-act-1899:sec_2__subsec_2": {"cite": "Stamp Act s.2(2)", "head": "", "text": "Bill of exchange.—“bill of exchange” means a bill of exchange as defined by the Negotiable Instruments Act, 1881, (26 of 1881), and includes also a hundi, and any other document entitling or purporting to entitle any person, whether named therein or not, to payment by any other person of, or to draw upon any other person for, any sum of money;"}, "indian-stamp-act-1899:sec_2__subsec_3": {"cite": "Stamp Act s.2(3)", "head": "", "text": "Bill of exchange payable on demand. —“bill of exchange payable on demand” includes— an order for the payment of any sum of money by a bill of exchange or promissory note, or for the delivery of any bill of exchange or promissory note in satisfaction of any sum of money, or for the payment of any sum of money out of any particular fund which may or may not be available, or upon any condition or contingency which may or may not be performed or happen; an order for the payment of any sum of money weekly, monthly or at any other stated period; and a letter of credit, that is to say, any instrument…"}, "indian-stamp-act-1899:sec_2__subsec_3__cl_a": {"cite": "Stamp Act s.2(3)(a)", "head": "", "text": "an order for the payment of any sum of money by a bill of exchange or promissory note, or for the delivery of any bill of exchange or promissory note in satisfaction of any sum of money, or for the payment of any sum of money out of any particular fund which may or may not be available, or upon any condition or contingency which may or may not be performed or happen;"}, "indian-stamp-act-1899:sec_2__subsec_3__cl_b": {"cite": "Stamp Act s.2(3)(b)", "head": "", "text": "an order for the payment of any sum of money weekly, monthly or at any other stated period; and"}, "indian-stamp-act-1899:sec_2__subsec_3__cl_c": {"cite": "Stamp Act s.2(3)(c)", "head": "", "text": "a letter of credit, that is to say, any instrument by which one person authorises another to give credit to the person in whose favour it is drawn;"}, "indian-stamp-act-1899:sec_2__subsec_4": {"cite": "Stamp Act s.2(4)", "head": "", "text": "Bill of lading.— “bill of lading” includes a “through bill of lading”, but does not include a mate's receipt:"}, "indian-stamp-act-1899:sec_2__subsec_5": {"cite": "Stamp Act s.2(5)", "head": "", "text": "Bond.— “bond” includes— any instrument whereby a person obliges himself to pay money to another, on condition that the obligation shall be void if a specified act is performed, or is not performed, as the case may be; any instrument attested by a witness and not payable to order or bearer, whereby a person obliges himself to pay money to another; and any instrument so attested, whereby a person obliges himself to deliver grain or other agricultural produce to another; [but does not include a debenture;]"}, "indian-stamp-act-1899:sec_2__subsec_5__cl_a": {"cite": "Stamp Act s.2(5)(a)", "head": "", "text": "any instrument whereby a person obliges himself to pay money to another, on condition that the obligation shall be void if a specified act is performed, or is not performed, as the case may be;"}, "indian-stamp-act-1899:sec_2__subsec_5__cl_b": {"cite": "Stamp Act s.2(5)(b)", "head": "", "text": "any instrument attested by a witness and not payable to order or bearer, whereby a person obliges himself to pay money to another; and"}, "indian-stamp-act-1899:sec_2__subsec_5__cl_c": {"cite": "Stamp Act s.2(5)(c)", "head": "", "text": "any instrument so attested, whereby a person obliges himself to deliver grain or other agricultural produce to another; [but does not include a debenture;]"}, "indian-stamp-act-1899:sec_2__subsec_6": {"cite": "Stamp Act s.2(6)", "head": "", "text": "Chargeable.—“chargeable” means, as applied to an instrument executed or first executed after the commencement of this Act, chargeable under this Act, and, as applied to any other instrument, chargeable under the law in force in [India] when such instrument was executed or, where several persons executed the instrument at different times, first executed;"}, "indian-stamp-act-1899:sec_2__subsec_7": {"cite": "Stamp Act s.2(7)", "head": "", "text": "Cheque.—“cheque” means a bill of exchange drawn on a specified banker and not expressed to be payable otherwise than on demand;"}, "indian-stamp-act-1899:sec_2__subsec_7A": {"cite": "Stamp Act s.2(7A)", "head": "", "text": "[“clearance list” means a list of transactions of sale and purchase relating to contracts traded on the stock exchanges submitted to a clearing corporation in accordance with the law for the time being in force in this behalf;"}, "indian-stamp-act-1899:sec_2__subsec_7B": {"cite": "Stamp Act s.2(7B)", "head": "", "text": "“clearing corporation” means an entity established to undertake the activity of clearing and settlement of transactions in securities or other instruments and includes a clearing house of a recognised stock exchange;] * * * * * *"}, "indian-stamp-act-1899:sec_2__subsec_9": {"cite": "Stamp Act s.2(9)", "head": "", "text": "Collector.—“Collector” — means, within the limits of the towns of Calcutta, Madras and Bombay, the Collector of Calcutta, Madras and Bombay, respectively, and, without those limits, the Collector of a district; and includes a Deputy Commissioner and any officer whom [the [State Government]] may, by notification in the Official Gazette, appoint in this behalf;"}, "indian-stamp-act-1899:sec_2__subsec_9__cl_a": {"cite": "Stamp Act s.2(9)(a)", "head": "", "text": "means, within the limits of the towns of Calcutta, Madras and Bombay, the Collector of Calcutta, Madras and Bombay, respectively, and, without those limits, the Collector of a district; and"}, "indian-stamp-act-1899:sec_2__subsec_9__cl_b": {"cite": "Stamp Act s.2(9)(b)", "head": "", "text": "includes a Deputy Commissioner and any officer whom [the [State Government]] may, by notification in the Official Gazette, appoint in this behalf;"}, "indian-stamp-act-1899:sec_2__subsec_10": {"cite": "Stamp Act s.2(10)", "head": "", "text": "Conveyance.—“conveyance” includes a conveyance on sale and every instrument by which property, whether moveable or immovable, is transferred inter vivos and which is not otherwise specifically provided for by schedule I;"}, "indian-stamp-act-1899:sec_2__subsec_10A": {"cite": "Stamp Act s.2(10A)", "head": "", "text": "[debenture.––“debenture” includes–– debenture stock, bonds or any other instrument of a company evidencing a debt, whether constituting a charge on the assets of the company or not; bonds in the nature of debenture issued by any incorporated company or body corporate; certificate of deposit, commercial usance bill, commercial paper and such other debt instrument of original or initial maturity upto one year as the Reserve Bank of India may specify from time to time; securitised debt instruments; and any other debt instruments specified by the Securities and Exchange Board of India from time to…"}, "indian-stamp-act-1899:sec_2__subsec_10A__subcl_i": {"cite": "Stamp Act s.2(10A)(i)", "head": "", "text": "debenture stock, bonds or any other instrument of a company evidencing a debt, whether constituting a charge on the assets of the company or not;"}, "indian-stamp-act-1899:sec_2__subsec_10A__subcl_ii": {"cite": "Stamp Act s.2(10A)(ii)", "head": "", "text": "bonds in the nature of debenture issued by any incorporated company or body corporate;"}, "indian-stamp-act-1899:sec_2__subsec_10A__subcl_iii": {"cite": "Stamp Act s.2(10A)(iii)", "head": "", "text": "certificate of deposit, commercial usance bill, commercial paper and such other debt instrument of original or initial maturity upto one year as the Reserve Bank of India may specify from time to time;"}, "indian-stamp-act-1899:sec_2__subsec_10A__subcl_iv": {"cite": "Stamp Act s.2(10A)(iv)", "head": "", "text": "securitised debt instruments; and"}, "indian-stamp-act-1899:sec_2__subsec_10A__subcl_v": {"cite": "Stamp Act s.2(10A)(v)", "head": "", "text": "any other debt instruments specified by the Securities and Exchange Board of India from time to time;"}, "indian-stamp-act-1899:sec_2__subsec_10B": {"cite": "Stamp Act s.2(10B)", "head": "", "text": "“depository” includes–– a depository as defined in clause (e) of sub-section (1) of section 2 of the Depositories Act, 1996 (22 of 1996); and any other entity declared by the Central Government, by notification in the Official Gazette, to be a depository for the purposes of this Act;]"}, "indian-stamp-act-1899:sec_2__subsec_10B__cl_a": {"cite": "Stamp Act s.2(10B)(a)", "head": "", "text": "a depository as defined in clause (e) of sub-section (1) of section 2 of the Depositories Act, 1996 (22 of 1996); and"}, "indian-stamp-act-1899:sec_2__subsec_10B__cl_b": {"cite": "Stamp Act s.2(10B)(b)", "head": "", "text": "any other entity declared by the Central Government, by notification in the Official Gazette, to be a depository for the purposes of this Act;]"}, "indian-stamp-act-1899:sec_2__subsec_11": {"cite": "Stamp Act s.2(11)", "head": "", "text": "Duly stamped. —“duly stamped”, as applied to an instrument, means that the instrument bears an adhesive or impressed stamp of not less than the proper amount and that such stamp has been affixed or used in accordance with the law for the time being in force in [India]:"}, "indian-stamp-act-1899:sec_2__subsec_12": {"cite": "Stamp Act s.2(12)", "head": "", "text": "Executed and execution. — “executed” and “execution” used with reference to instruments, mean “signed” and “signature” [and includes attribution of electronic record within the meaning of section 11 of the Information Technology Act, 2000 (21 of 2000);]"}, "indian-stamp-act-1899:sec_2__subsec_1_dup": {"cite": "Stamp Act s.2(1)", "head": "", "text": "* * * * *"}, "indian-stamp-act-1899:sec_2__subsec_13": {"cite": "Stamp Act s.2(13)", "head": "", "text": "Impressed stamp. — “impressed stamp” includes— labels affixed and impressed by the proper officer; and stamps embossed or engraved on stamped paper;"}, "indian-stamp-act-1899:sec_2__subsec_13__cl_a": {"cite": "Stamp Act s.2(13)(a)", "head": "", "text": "labels affixed and impressed by the proper officer; and"}, "indian-stamp-act-1899:sec_2__subsec_13__cl_b": {"cite": "Stamp Act s.2(13)(b)", "head": "", "text": "stamps embossed or engraved on stamped paper;"}, "indian-stamp-act-1899:sec_2__subsec_13A": {"cite": "Stamp Act s.2(13A)", "head": "", "text": "[India. — “India” means the territory of India excluding the State of Jammu and Kashmir;]"}, "indian-stamp-act-1899:sec_2__subsec_14": {"cite": "Stamp Act s.2(14)", "head": "", "text": "[“instrument” includes— every document, by which any right or liability is, or purports to be, created, transferred, limited, extended, extinguished or recorded; a document, electronic or otherwise, created for a transaction in a stock exchange or depository by which any right or liability is, or purports to be, created, transferred, limited, extended, extinguished or recorded; and any other document mentioned in Schedule I, but does not include such instruments as may be specified by the Government, by notification in the Official Gazette.] (15) Instrument of partition.— “instrument of partit…"}, "indian-stamp-act-1899:sec_2__subsec_14__cl_a": {"cite": "Stamp Act s.2(14)(a)", "head": "", "text": "every document, by which any right or liability is, or purports to be, created, transferred, limited, extended, extinguished or recorded;"}, "indian-stamp-act-1899:sec_2__subsec_14__cl_b": {"cite": "Stamp Act s.2(14)(b)", "head": "", "text": "a document, electronic or otherwise, created for a transaction in a stock exchange or depository by which any right or liability is, or purports to be, created, transferred, limited, extended, extinguished or recorded; and"}, "indian-stamp-act-1899:sec_2__subsec_14__cl_c": {"cite": "Stamp Act s.2(14)(c)", "head": "", "text": "any other document mentioned in Schedule I,"}, "indian-stamp-act-1899:sec_2__subsec_15A": {"cite": "Stamp Act s.2(15A)", "head": "", "text": "[Issue.— “issue” means any person making an issue of securities;] (16) Lease.— “lease” means a lease of immovable property, and includes also— a patta; a kabuliyat or other undertaking in writing, not being a counterpart of a lease, to cultivate, occupy, or pay or deliver rent for, immovable property; any instrument by which tolls of any description are let; any writing on an application for a lease intended to signify that the application is granted;"}, "indian-stamp-act-1899:sec_2__subsec_15A__cl_a": {"cite": "Stamp Act s.2(15A)(a)", "head": "", "text": "a patta;"}, "indian-stamp-act-1899:sec_2__subsec_15A__cl_b": {"cite": "Stamp Act s.2(15A)(b)", "head": "", "text": "a kabuliyat or other undertaking in writing, not being a counterpart of a lease, to cultivate, occupy, or pay or deliver rent for, immovable property;"}, "indian-stamp-act-1899:sec_2__subsec_15A__cl_c": {"cite": "Stamp Act s.2(15A)(c)", "head": "", "text": "any instrument by which tolls of any description are let;"}, "indian-stamp-act-1899:sec_2__subsec_15A__cl_d": {"cite": "Stamp Act s.2(15A)(d)", "head": "", "text": "any writing on an application for a lease intended to signify that the application is granted;"}, "indian-stamp-act-1899:sec_2__subsec_16A": {"cite": "Stamp Act s.2(16A)", "head": "", "text": "[Marketable security.— “marketable security” means a security capable of being traded in any stock exchange in India;"}, "indian-stamp-act-1899:sec_2__subsec_16B": {"cite": "Stamp Act s.2(16B)", "head": "", "text": "Market value.—“market value”, in relation to an instrument through which— any security is traded in a stock exchange, means the price at which it is so traded; any security which is transferred through a depository but not traded in the stock exchange, means the price or the consideration mentioned in such instrument; any security is dealt otherwise than in the stock exchange or depository, means the price or consideration mentioned in such instrument;] (17) Mortgage-deed.— “mortgage-deed” includes every instrument whereby, for the purpose of securing money advanced, or to be advanced, by way …"}, "indian-stamp-act-1899:sec_2__subsec_16B__cl_a": {"cite": "Stamp Act s.2(16B)(a)", "head": "", "text": "any security is traded in a stock exchange, means the price at which it is so traded;"}, "indian-stamp-act-1899:sec_2__subsec_16B__cl_b": {"cite": "Stamp Act s.2(16B)(b)", "head": "", "text": "any security which is transferred through a depository but not traded in the stock exchange, means the price or the consideration mentioned in such instrument;"}, "indian-stamp-act-1899:sec_2__subsec_16B__cl_c": {"cite": "Stamp Act s.2(16B)(c)", "head": "", "text": "any security is dealt otherwise than in the stock exchange or depository, means the price or consideration mentioned in such instrument;] (17) Mortgage-deed.— “mortgage-deed” includes every instrument whereby, for the purpose of securing money advanced, or to be advanced, by way of loan, or an existing or future debt, or the performance of an engagement, one person transfers, or creates, to, or in favour of, another, a right over or in respect of specified property;"}, "indian-stamp-act-1899:sec_2__subsec_18": {"cite": "Stamp Act s.2(18)", "head": "", "text": "Paper.—“paper” includes vellum, parchment or any other material on which an instrument may be written;"}, "indian-stamp-act-1899:sec_2__subsec_19": {"cite": "Stamp Act s.2(19)", "head": "", "text": "Policy of insurance.—“policy of insurance” includes— any instrument by which one person, in consideration of a premium, engages to indemnify another against loss, damage or liability arising from an unknown or contingent event; a life-policy, and any policy insuring any person against accident or sickness, and any other personal insurance; *** * * * * *"}, "indian-stamp-act-1899:sec_2__subsec_19__cl_a": {"cite": "Stamp Act s.2(19)(a)", "head": "", "text": "any instrument by which one person, in consideration of a premium, engages to indemnify another against loss, damage or liability arising from an unknown or contingent event;"}, "indian-stamp-act-1899:sec_2__subsec_19__cl_b": {"cite": "Stamp Act s.2(19)(b)", "head": "", "text": "a life-policy, and any policy insuring any person against accident or sickness, and any other personal insurance; *** * * * * *"}, "indian-stamp-act-1899:sec_2__subsec_19A": {"cite": "Stamp Act s.2(19A)", "head": "", "text": "[Policy of group insurance.—“policy of group insurance” means any instrument covering not less than fifty or such smaller number as the Central Government may approve, either generally or with reference to any particular case, by which an insurer, in consideration of a premium paid by an employer or by an employer and his employees jointly, engages to cover, with or without medical examination and for the sole benefit of persons other than the employer, the lives of all the employees or of any class of them, determined by conditions pertaining to the employment, for amounts of insurance based …"}, "indian-stamp-act-1899:sec_2__subsec_19A__cl_a": {"cite": "Stamp Act s.2(19A)(a)", "head": "", "text": "means any insurance made upon any ship or vessel (whether for marine or inland navigation), or upon the machinery, tackle or furniture of any ship or vessel, or upon any goods, merchandise or property of any description whatever on board of any ship or vessel, or upon the freight of, or any other interest which may be lawfully insured in, or relating to, any ship or vessel; and"}, "indian-stamp-act-1899:sec_2__subsec_19A__cl_b": {"cite": "Stamp Act s.2(19A)(b)", "head": "", "text": "includes any insurance of goods, merchandise or property for any transit which includes, not only a sea risk within the meaning of clause (a), but also any other risk incidental to the transit insured from the commencement of the transit to the ultimate destination covered by the insurance: Where any person, in consideration of any sum of money paid or to be paid for additional freight or otherwise, agrees to take upon himself any risk attending goods, merchandise or property of any description whatever while on board of any ship or vessel, or engages to indemnify the owner of any such goods, …"}, "indian-stamp-act-1899:sec_2__subsec_21": {"cite": "Stamp Act s.2(21)", "head": "", "text": "Power-of-attorney.—“power-of-attorney” includes any instrument (not chargeable with a fee under the law relating to Court-fees for the time being in force) empowering a specified person to act for and in the name of the person executing it;"}, "indian-stamp-act-1899:sec_2__subsec_22": {"cite": "Stamp Act s.2(22)", "head": "", "text": "Promissory note.—“promissory note” means a promissory note as defined by the Negotiable Instruments Act, 1881 (XXVI of 1881); It also includes a note promising the payment of any sum of money out of any particular fund which may or may not be available, or upon any condition or contingency which may or may not be performed or happen;"}, "indian-stamp-act-1899:sec_2__subsec_23": {"cite": "Stamp Act s.2(23)", "head": "", "text": "Receipt.—“receipt” includes any note, memorandum or writing— where by any money, or any bill of exchange, cheque or promissory note is acknowledged to have been received, or where by any other moveable property is acknowledged to have been received in satisfaction of a debt, or where by any debt or demand, or any part of a debt or demand, is acknowledged to have been satisfied or discharged, or which signifies or imports any such acknowledgment, and whether the same is or is not signed with the name of any person; ***"}, "indian-stamp-act-1899:sec_2__subsec_23__cl_a": {"cite": "Stamp Act s.2(23)(a)", "head": "", "text": "where by any money, or any bill of exchange, cheque or promissory note is acknowledged to have been received, or"}, "indian-stamp-act-1899:sec_2__subsec_23__cl_b": {"cite": "Stamp Act s.2(23)(b)", "head": "", "text": "where by any other moveable property is acknowledged to have been received in satisfaction of a debt, or"}, "indian-stamp-act-1899:sec_2__subsec_23__cl_c": {"cite": "Stamp Act s.2(23)(c)", "head": "", "text": "where by any debt or demand, or any part of a debt or demand, is acknowledged to have been satisfied or discharged, or"}, "indian-stamp-act-1899:sec_2__subsec_23__cl_d": {"cite": "Stamp Act s.2(23)(d)", "head": "", "text": "which signifies or imports any such acknowledgment,"}, "indian-stamp-act-1899:sec_2__subsec_23A": {"cite": "Stamp Act s.2(23A)", "head": "", "text": "[Securities.—“securities” includes— securities as defined in clause (h) of section 2 of the Securities Contracts (Regulation) Act, 1956 (42 of 1956); a “derivative” as defined in clause (a) of section 45U of the Reserve Bank of India Act, 1934 (2 of 1934); a certificate of deposit, commercial usance bill, commercial paper, repo on corporate bonds and such other debt instrument of original or initial maturity upto one year as the Reserve Bank of India ma specify from time to time; and any other instrument declared by the Central Government, by notification in the Official Gazette, to be securit…"}, "indian-stamp-act-1899:sec_2__subsec_23A__subcl_i": {"cite": "Stamp Act s.2(23A)(i)", "head": "", "text": "securities as defined in clause (h) of section 2 of the Securities Contracts (Regulation) Act, 1956 (42 of 1956);"}, "indian-stamp-act-1899:sec_2__subsec_23A__subcl_ii": {"cite": "Stamp Act s.2(23A)(ii)", "head": "", "text": "a “derivative” as defined in clause (a) of section 45U of the Reserve Bank of India Act, 1934 (2 of 1934);"}, "indian-stamp-act-1899:sec_2__subsec_23A__subcl_iii": {"cite": "Stamp Act s.2(23A)(iii)", "head": "", "text": "a certificate of deposit, commercial usance bill, commercial paper, repo on corporate bonds and such other debt instrument of original or initial maturity upto one year as the Reserve Bank of India ma specify from time to time; and"}, "indian-stamp-act-1899:sec_2__subsec_23A__subcl_iv": {"cite": "Stamp Act s.2(23A)(iv)", "head": "", "text": "any other instrument declared by the Central Government, by notification in the Official Gazette, to be securities for the purposes of this Act.]"}, "indian-stamp-act-1899:sec_2__subsec_24": {"cite": "Stamp Act s.2(24)", "head": "", "text": "Settlement.—“settlement” means any non-testamentary disposition, in writing, of moveable or immovable property made— in consideration of marriage, 1. The word “and” omitted by Act 18 of 1928, s. 2 and the First Schedule. for the purpose of distributing property of the settler among his family or those for whom he desires to provide, or for the purpose of providing for some person dependent on him, or for any religious or charitable purpose; and includes an agreement in writing to make such a disposition [and, where any such disposition has not been made in writing, any instrument recording, wh…"}, "indian-stamp-act-1899:sec_2__subsec_24__cl_a": {"cite": "Stamp Act s.2(24)(a)", "head": "", "text": "in consideration of marriage,"}, "indian-stamp-act-1899:sec_2__subsec_24__wrap_1": {"cite": "Stamp Act s.2(24)", "head": "", "text": "1. The word “and” omitted by Act 18 of 1928, s. 2 and the First Schedule."}, "indian-stamp-act-1899:sec_2__subsec_24__cl_b": {"cite": "Stamp Act s.2(24)(b)", "head": "", "text": "for the purpose of distributing property of the settler among his family or those for whom he desires to provide, or for the purpose of providing for some person dependent on him, or"}, "indian-stamp-act-1899:sec_2__subsec_24__cl_c": {"cite": "Stamp Act s.2(24)(c)", "head": "", "text": "for any religious or charitable purpose;"}, "indian-stamp-act-1899:sec_2__subsec_25": {"cite": "Stamp Act s.2(25)", "head": "", "text": "[Soldier. —“soldier” includes any person below the rank of non-commissioned officer who is enrolled under the Indian Army Act, 1911(8 of 1911).]"}, "indian-stamp-act-1899:sec_2__subsec_26": {"cite": "Stamp Act s.2(26)", "head": "", "text": "[Stamp. — “stamp” means any mark, seal or endorsement by any agency or person duly authorised by the State Government, and includes an adhesive or impressed stamp, for the purposes of duty chargeable under this Act.]"}, "indian-stamp-act-1899:sec_2__subsec_27": {"cite": "Stamp Act s.2(27)", "head": "", "text": "[Stock exchange.—“stock exchange” includes— a recognised stock exchange as defined in clause (f) of section 2 of the Securities Contracts (Regulation) Act, 1956 (42 of 1956); and such other platform for trading or reporting a deal in securities, as may be specified by the Central Government, by notification in the Official Gazette, for the purposes of this Act.]"}, "indian-stamp-act-1899:sec_2__subsec_27__subcl_i": {"cite": "Stamp Act s.2(27)(i)", "head": "", "text": "a recognised stock exchange as defined in clause (f) of section 2 of the Securities Contracts (Regulation) Act, 1956 (42 of 1956); and"}, "indian-stamp-act-1899:sec_2__subsec_27__subcl_ii": {"cite": "Stamp Act s.2(27)(ii)", "head": "", "text": "such other platform for trading or reporting a deal in securities, as may be specified by the Central Government, by notification in the Official Gazette, for the purposes of this Act.]"}, "indian-stamp-act-1899:chp_II": {"cite": "Stamp Act Chapter II", "head": "STAMP DUTIES", "text": "A.—Of the liability of instruments to Duty Instruments chargeable with duty Subject to the provisions of this Act and the exemptions contained in Schedule I, the following instruments shall be chargeable with duty of the amount indicated in that Schedule as the proper duty therefore respectively, that is to say— every instrument mentioned in that Schedule which, not having been previously executed by any person, is executed in [India] on or after the first day of July, 1899; every bill of exchange [payable otherwise than on demand] *** or promissory note drawn or made out of [India] on or afte…"}, "indian-stamp-act-1899:crossHeading_1": {"cite": "Stamp Act crossHeading_1", "head": "", "text": ""}, "indian-stamp-act-1899:sec_3": {"cite": "Stamp Act s.3", "head": "Instruments chargeable with duty", "text": "Subject to the provisions of this Act and the exemptions contained in Schedule I, the following instruments shall be chargeable with duty of the amount indicated in that Schedule as the proper duty therefore respectively, that is to say— every instrument mentioned in that Schedule which, not having been previously executed by any person, is executed in [India] on or after the first day of July, 1899; every bill of exchange [payable otherwise than on demand] *** or promissory note drawn or made out of [India] on or after that day and accepted or paid, or presented for acceptance or payment, or …"}, "indian-stamp-act-1899:sec_3__cl_a": {"cite": "Stamp Act s.3(a)", "head": "", "text": "every instrument mentioned in that Schedule which, not having been previously executed by any person, is executed in [India] on or after the first day of July, 1899;"}, "indian-stamp-act-1899:sec_3__cl_b": {"cite": "Stamp Act s.3(b)", "head": "", "text": "every bill of exchange [payable otherwise than on demand] *** or promissory note drawn or made out of [India] on or after that day and accepted or paid, or presented for acceptance or payment, or endorsed, transferred or otherwise negotiated, in [India]; and"}, "indian-stamp-act-1899:sec_3__cl_c": {"cite": "Stamp Act s.3(c)", "head": "", "text": "every instrument (other than a bill of exchange, *** or promissory note) mentioned in that Schedule, which, not having been previously executed by any person, is executed out of [India] on or after that day, relates to any property situate, or to any matter or thing done or to be done, in [India] and is received in [India]:"}, "indian-stamp-act-1899:sec_3__proviso_1": {"cite": "Stamp Act s.3", "head": "", "text": "Provided that no duty shall be chargeable in respect of— any instrument executed by, or on behalf of, or in favour of, the Government in cases where, but for this exemption, the Government would be liable to pay the duty chargeable in respect of such instrument; 1. Subs. by Act 43 of 1955, s. 2, for “the States” (w.e.f. 1-4-1956). any instrument for the sale, transfer or other disposition, either absolutely or byway of mortgage or otherwise, of any ship or vessel, or any part, interest, share or property of or in any ship or vessel registered under the Merchant Shipping Act 1894, Act No. 57 & …"}, "indian-stamp-act-1899:sec_3__proviso_1__subsec_1": {"cite": "Stamp Act s.3(1)", "head": "", "text": "any instrument executed by, or on behalf of, or in favour of, the Government in cases where, but for this exemption, the Government would be liable to pay the duty chargeable in respect of such instrument;"}, "indian-stamp-act-1899:sec_3__proviso_1__wrap_1": {"cite": "Stamp Act s.3", "head": "", "text": "1. Subs. by Act 43 of 1955, s. 2, for “the States” (w.e.f. 1-4-1956)."}, "indian-stamp-act-1899:sec_3__proviso_1__subsec_2": {"cite": "Stamp Act s.3(2)", "head": "", "text": "any instrument for the sale, transfer or other disposition, either absolutely or byway of mortgage or otherwise, of any ship or vessel, or any part, interest, share or property of or in any ship or vessel registered under the Merchant Shipping Act 1894, Act No. 57 & 58 Vict. c. 60 or under Act XIX of 1838 Act No. or the Indian Registration of Ships Act, 1841, (CX of 1841) as amended by subsequent Acts."}, "indian-stamp-act-1899:sec_3A": {"cite": "Stamp Act s.3A", "head": "", "text": "[Instruments chargeable with additional duty.] Omitted by the Refugee Relief Taxes (Abolition) Act, 1973 (13 of 1973), s. 2 (w.e.f. 1-4-1973). Tripura Substitution of section 3B.— For section 3B of the principal Act, as inserted by the Union Territories Taxation Laws (Amendment) Act, 1971, the following shall be substituted, namely: — “3B. Instrument Chargeable with additional duty.—(1) Every instrument chargeable with duty under section 3, read with Schedule 1, not being an instrument mentioned articles Nos. 13, 14, 27, 37, 47, 49, 52, 53 or 62(a), shall, in addition to such duty, be chargeab…"}, "indian-stamp-act-1899:sec_4": {"cite": "Stamp Act s.4", "head": "Several instruments used in single transaction of sale, mortgage or settlement", "text": "Where, in the case of any sale, mortgage or settlement, several instruments are employed for completing the transaction, the principal instrument only shall be chargeable with the duty prescribed in Schedule I, for the conveyance, mortgage or settlement, and each of the other instruments shall be chargeable with a duty of one rupee instead of the duty (if any) prescribed for it in that Schedule. The parties may determine for themselves which of the instrument so employed shall, for the purposes of sub-section (1), be deemed to be the principal instrument: Provided that the duty chargeable on t…"}, "indian-stamp-act-1899:sec_4__subsec_1": {"cite": "Stamp Act s.4(1)", "head": "", "text": "Where, in the case of any sale, mortgage or settlement, several instruments are employed for completing the transaction, the principal instrument only shall be chargeable with the duty prescribed in Schedule I, for the conveyance, mortgage or settlement, and each of the other instruments shall be chargeable with a duty of one rupee instead of the duty (if any) prescribed for it in that Schedule."}, "indian-stamp-act-1899:sec_4__subsec_2": {"cite": "Stamp Act s.4(2)", "head": "", "text": "The parties may determine for themselves which of the instrument so employed shall, for the purposes of sub-section (1), be deemed to be the principal instrument: Provided that the duty chargeable on the instrument so determined shall be the highest duty which would be chargeable in respect of any of the said instruments employed."}, "indian-stamp-act-1899:sec_4__subsec_2__proviso_1": {"cite": "Stamp Act s.4(2)", "head": "", "text": "Provided that the duty chargeable on the instrument so determined shall be the highest duty which would be chargeable in respect of any of the said instruments employed."}, "indian-stamp-act-1899:sec_4__subsec_3": {"cite": "Stamp Act s.4(3)", "head": "", "text": "[Notwithstanding anything contained in sub-sections (1) and (2), in the case of any issue, sale or transfer of securities, the instrument on which stamp-duty is chargeable under section 9A shall be the principal instrument for the purpose of this section and no stamp-duty shall be charged on any other instruments relating to any such transaction.]"}, "indian-stamp-act-1899:sec_5": {"cite": "Stamp Act s.5", "head": "Instruments relating to several distinct matters", "text": "Any instrument comprising or relating to several distinct matters shall be chargeable with the aggregate amount of the duties with which separate instruments, each comprising or relating to one of such matters, would be chargeable under this Act."}, "indian-stamp-act-1899:sec_6": {"cite": "Stamp Act s.6", "head": "Instruments coming within several descriptions in Schedule I", "text": "Subject to the provisions of the last preceding section, an instrument so framed as to come within two or more of the descriptions in Schedule I, shall, where the duties chargeable thereunder are different, be chargeable only with the highest of such duties: Provided that nothing in this Act contained shall render chargeable with duty exceeding one rupee a counterpart or duplicate of any instrument chargeable with duty and in respect of which the proper duty has been paid."}, "indian-stamp-act-1899:sec_6__proviso_1": {"cite": "Stamp Act s.6", "head": "", "text": "Provided that nothing in this Act contained shall render chargeable with duty exceeding one rupee a counterpart or duplicate of any instrument chargeable with duty and in respect of which the proper duty has been paid."}, "indian-stamp-act-1899:sec_7": {"cite": "Stamp Act s.7", "head": "Policies of sea-insurance", "text": "* * * * * Where any sea-insurance is made for or upon a voyage and also for time, or to extend to or cover any time beyond thirty days after the ship shall have arrived at her destination and been there moored at anchor, the policy shall be charged with duty as a policy for or upon a voyage, and also with duty as a policy for time."}, "indian-stamp-act-1899:sec_7__subsec_4": {"cite": "Stamp Act s.7(4)", "head": "", "text": "Where any sea-insurance is made for or upon a voyage and also for time, or to extend to or cover any time beyond thirty days after the ship shall have arrived at her destination and been there moored at anchor, the policy shall be charged with duty as a policy for or upon a voyage, and also with duty as a policy for time."}, "indian-stamp-act-1899:sec_8": {"cite": "Stamp Act s.8", "head": "Bonds, debentures or other securities issued on loans under Act XI of 1879", "text": "Notwithstanding anything in this Act, any local authority raising a loan under the provisions of the Local Authorities Loan Act, 1879 (XI of 1879) or, of any other law for the time being in force, by the issue of bonds, debentures or other securities, shall, in respect of such loan, be chargeable with a duty of [one per centum] on the total amount of the bonds, debentures or other securities issued by it, and such bonds, debentures or other securities need not be stamped and shall not be chargeable with any further duty on renewal, consolidation, sub-division or otherwise. The provisions of su…"}, "indian-stamp-act-1899:sec_8__subsec_1": {"cite": "Stamp Act s.8(1)", "head": "", "text": "Notwithstanding anything in this Act, any local authority raising a loan under the provisions of the Local Authorities Loan Act, 1879 (XI of 1879) or, of any other law for the time being in force, by the issue of bonds, debentures or other securities, shall, in respect of such loan, be chargeable with a duty of [one per centum] on the total amount of the bonds, debentures or other securities issued by it, and such bonds, debentures or other securities need not be stamped and shall not be chargeable with any further duty on renewal, consolidation, sub-division or otherwise."}, "indian-stamp-act-1899:sec_8__subsec_2": {"cite": "Stamp Act s.8(2)", "head": "", "text": "The provisions of sub-section (1) exempting certain bonds, debentures or other securities from being stamped and from being chargeable with certain further duty shall apply to the bonds, debentures or other securities of all outstanding loans of the kind mentioned therein, and all such bonds, debentures or other securities shall be valid, whether the same are stamped or not: Provided that nothing herein contained shall exempt the local authority which has issued such bonds, debentures or other securities from the duty chargeable in respect thereof prior to the twenty-sixth day of March, 1897, …"}, "indian-stamp-act-1899:sec_8__subsec_2__proviso_1": {"cite": "Stamp Act s.8(2)", "head": "", "text": "Provided that nothing herein contained shall exempt the local authority which has issued such bonds, debentures or other securities from the duty chargeable in respect thereof prior to the twenty-sixth day of March, 1897, when such duty has not already been paid or remitted by order issued by the Central Government."}, "indian-stamp-act-1899:sec_8__subsec_3": {"cite": "Stamp Act s.8(3)", "head": "", "text": "In the case of wilful neglect to pay the duty required by this section, the local authority shall be liable to forfeit to the Government a sum equal to ten per centum upon the amount of duty payable, and a like penalty for every month after the first month during which the neglect continues."}, "indian-stamp-act-1899:sec_8A": {"cite": "Stamp Act s.8A", "head": "Securities dealt in depository not liable to stamp duty", "text": "Notwithstanding anything contained in this Act or any other law for the time being in force,— an issuer, by the issue of securities to one or more depositories, shall, in respect of such issue, be chargeable with duty on the total amount of securities issued by it and such securities need not be stamped; the transfer of registered ownership of securities from a person to a depository or from a depository to a beneficial owner shall not be liable to duty; For the purposes of this section, the expression “beneficial ownership” shall have the same meaning as assigned to it in clause (a) of sub-se…"}, "indian-stamp-act-1899:sec_8A__cl_a": {"cite": "Stamp Act s.8A(a)", "head": "", "text": "an issuer, by the issue of securities to one or more depositories, shall, in respect of such issue, be chargeable with duty on the total amount of securities issued by it and such securities need not be stamped;"}, "indian-stamp-act-1899:sec_8A__cl_b": {"cite": "Stamp Act s.8A(b)", "head": "", "text": "the transfer of registered ownership of securities from a person to a depository or from a depository to a beneficial owner shall not be liable to duty;"}, "indian-stamp-act-1899:sec_8A__hcontainer_1": {"cite": "Stamp Act s.8A", "head": "", "text": "For the purposes of this section, the expression “beneficial ownership” shall have the same meaning as assigned to it in clause (a) of sub-section (1) of section 2 of the Depositories Act, 1996 (22 of 1996)] [8B. Corporatisation and demutualisation schemes and related instruments not liable to duty.—Notwithstanding anything contained in this Act or any other law for the time being in force,— a scheme for corporatisation or demutualisation, or both of a recognised stock exchange; or any instrument, including an instrument of, or relating to, transfer of any property, business, asset whether mov…"}, "indian-stamp-act-1899:sec_8A__hcontainer_1__cl_a": {"cite": "Stamp Act s.8A(a)", "head": "", "text": "a scheme for corporatisation or demutualisation, or both of a recognised stock exchange; or"}, "indian-stamp-act-1899:sec_8A__hcontainer_1__cl_b": {"cite": "Stamp Act s.8A(b)", "head": "", "text": "any instrument, including an instrument of, or relating to, transfer of any property, business, asset whether movable or immovable, contract, right, liability and obligation, for the purpose of, or in connection with, the corporatisation or demutualisation, or both of a recognised stock exchange pursuant to a scheme,"}, "indian-stamp-act-1899:sec_8A__hcontainer_2": {"cite": "Stamp Act s.8A", "head": "", "text": "For the purposes of this section,— the expressions “corporatisation”, “demutualisation” and “scheme” shall have the meanings respectively assigned to them in clauses (aa), (ab) and (ga) of section 2 of the Securities Contracts (Regulation) Act, 1956 (42 of 1956); “Securities and Exchange Board of India” means the Securities and Exchange Board of India established under section 3 of the Securities and Exchange Board of India Act, 1992(15 of 1992).] [8C. Negotiable warehouse receipts not liable to stamp-duty.—Notwithstanding anything contained in this Act, negotiable warehouse receipts shall not…"}, "indian-stamp-act-1899:sec_8A__hcontainer_2__cl_a": {"cite": "Stamp Act s.8A(a)", "head": "", "text": "the expressions “corporatisation”, “demutualisation” and “scheme” shall have the meanings respectively assigned to them in clauses (aa), (ab) and (ga) of section 2 of the Securities Contracts (Regulation) Act, 1956 (42 of 1956);"}, "indian-stamp-act-1899:sec_8A__hcontainer_2__cl_b": {"cite": "Stamp Act s.8A(b)", "head": "", "text": "“Securities and Exchange Board of India” means the Securities and Exchange Board of India established under section 3 of the Securities and Exchange Board of India Act, 1992(15 of 1992).]"}, "indian-stamp-act-1899:sec_8A__hcontainer_2__wrap_1": {"cite": "Stamp Act s.8A", "head": "", "text": "[8C. Negotiable warehouse receipts not liable to stamp-duty.—Notwithstanding anything contained in this Act, negotiable warehouse receipts shall not be liable to stamp duty.]"}, "indian-stamp-act-1899:sec_8A__hcontainer_2__wrap_2": {"cite": "Stamp Act s.8A", "head": "", "text": "[8D. Agreement or document for assignment of receivables not liable to stamp-duty.—Notwithstanding anything contained in this Act or any other law for the time being in force, any agreement or other document for assignment of “receivables” as defined in clause (p) of section 2 of the Factoring Regulation Act, 2011 in favour of any “factor” as defined in clause (i) of section 2 of the said Act shall not be liable to duty under this Act or any other law for the time being in force.]"}, "indian-stamp-act-1899:sec_8A__hcontainer_2__wrap_3": {"cite": "Stamp Act s.8A", "head": "", "text": "[8E. Conversion of a branch of any bank into a wholly owned subsidiary of bank or transfer of shareholding of a bank to a holding company of bank not liable to duty. — Notwithstanding anything contained in this Act or any other law for the time being in force, —"}, "indian-stamp-act-1899:sec_8A__hcontainer_2__cl_a_dup": {"cite": "Stamp Act s.8A(a)", "head": "", "text": "conversion of a branch of a bank into a wholly owned subsidiary of the bank or transfer of shareholding of a bank to a holding company of the bank in terms of the scheme or guidelines of the Reserve Bank of India shall not be liable to duty under this Act or any other law for the time being in force; or"}, "indian-stamp-act-1899:sec_8A__hcontainer_2__cl_b_dup": {"cite": "Stamp Act s.8A(b)", "head": "", "text": "any instrument, including an instrument of, or relating to, transfer of any property, business, asset whether movable or immovable, contract, right, liability and obligation, for the purpose of, or in connection with, the conversion of a branch of a bank into a wholly owned subsidiary of the bank or transfer of shareholding of a bank to a holding company of the bank in terms of the scheme or guidelines issued by the Reserve Bank of India in this behalf, shall not be liable to duty under this Act or any other law for the time being in force. For the purposes of this section, the expression “ban…"}, "indian-stamp-act-1899:sec_8A__hcontainer_2__cl_b_dup__hcontainer_1": {"cite": "Stamp Act s.8A(b)", "head": "", "text": "For the purposes of this section, the expression “bank” means— “a banking company” as defined in clause (c) of section 5 of the Banking Regulation Act, 1949(10 of 1949); “a corresponding new bank” as defined in clause (da) of section 5 of the Banking Regulation Act, 1949 (10 of 1949); “State Bank of India” constituted under section 3 of the State Bank of India Act, 1955 (23 of 1955); “a subsidiary bank” as defined in clause (k) of section 2 of the State Bank of India (Subsidiary Banks) Act, 1959 (38 of 1959); “a Regional Rural Bank” established under section 3 of the Regional Rural Banks Act, …"}, "indian-stamp-act-1899:sec_8A__hcontainer_2__cl_b_dup__hcontainer_1__subcl_i": {"cite": "Stamp Act s.8A(b)(i)", "head": "", "text": "For the purposes of this section, the expression “bank” means— “a banking company” as defined in clause (c) of section 5 of the Banking Regulation Act, 1949(10 of 1949); “a corresponding new bank” as defined in clause (da) of section 5 of the Banking Regulation Act, 1949 (10 of 1949); “State Bank of India” constituted under section 3 of the State Bank of India Act, 1955 (23 of 1955); “a subsidiary bank” as defined in clause (k) of section 2 of the State Bank of India (Subsidiary Banks) Act, 1959 (38 of 1959); “a Regional Rural Bank” established under section 3 of the Regional Rural Banks Act, …"}, "indian-stamp-act-1899:sec_8A__hcontainer_2__cl_b_dup__hcontainer_1__subcl_i__cl_a": {"cite": "Stamp Act s.8A(b)(i)(a)", "head": "", "text": "“a banking company” as defined in clause (c) of section 5 of the Banking Regulation Act, 1949(10 of 1949);"}, "indian-stamp-act-1899:sec_8A__hcontainer_2__cl_b_dup__hcontainer_1__subcl_i__cl_b": {"cite": "Stamp Act s.8A(b)(i)(b)", "head": "", "text": "“a corresponding new bank” as defined in clause (da) of section 5 of the Banking Regulation Act, 1949 (10 of 1949);"}, "indian-stamp-act-1899:sec_8A__hcontainer_2__cl_b_dup__hcontainer_1__subcl_i__cl_c": {"cite": "Stamp Act s.8A(b)(i)(c)", "head": "", "text": "“State Bank of India” constituted under section 3 of the State Bank of India Act, 1955 (23 of 1955);"}, "indian-stamp-act-1899:sec_8A__hcontainer_2__cl_b_dup__hcontainer_1__subcl_i__cl_d": {"cite": "Stamp Act s.8A(b)(i)(d)", "head": "", "text": "“a subsidiary bank” as defined in clause (k) of section 2 of the State Bank of India (Subsidiary Banks) Act, 1959 (38 of 1959);"}, "indian-stamp-act-1899:sec_8A__hcontainer_2__cl_b_dup__hcontainer_1__subcl_i__cl_e": {"cite": "Stamp Act s.8A(b)(i)(e)", "head": "", "text": "“a Regional Rural Bank” established under section 3 of the Regional Rural Banks Act, 1976 (21 of 1976);"}, "indian-stamp-act-1899:sec_8A__hcontainer_2__cl_b_dup__hcontainer_1__subcl_i__cl_f": {"cite": "Stamp Act s.8A(b)(i)(f)", "head": "", "text": "“a Co-operative Bank” as defined in clause (cci) of section 5 of the Banking Regulation Act, 1949 (10 of 1949);"}, "indian-stamp-act-1899:sec_8A__hcontainer_2__cl_b_dup__hcontainer_1__subcl_i__cl_g": {"cite": "Stamp Act s.8A(b)(i)(g)", "head": "", "text": "“a multi-State co-operative bank” as defined in clause (cciiia) of section 5 of the Banking Regulation Act, 1949(10 of 1949);"}, "indian-stamp-act-1899:sec_8A__hcontainer_2__cl_b_dup__hcontainer_1__subcl_ii": {"cite": "Stamp Act s.8A(b)(ii)", "head": "", "text": "For the purposes of this section, the expression the “Reserve Bank of India” means the Reserve Bank of India constituted under section 3 of the Reserve Bank of India Act, 1934 (2 of 1934).]"}, "indian-stamp-act-1899:sec_8A__hcontainer_2__cl_b_dup__hcontainer_1__wrap_1": {"cite": "Stamp Act s.8A(b)", "head": "", "text": "[8F. Agreement or document for transfer or assignment of rights or interest in financial assets not liable to stamp-duty.—Notwithstanding anything contained in this Act or any other law for the time being in force, any agreement or other document for transfer or assignment of rights or interest in financial assets of banks or financial institutions under section5 of the Securitisation and Reconstruction of Financial Assets and Enforcement of Security Interest Act, 2002, (54 of 2002) in favour of any asset reconstruction company, as defined in clause (ba) of sub-section (1) of section 2 of that…"}, "indian-stamp-act-1899:sec_8A__hcontainer_2__cl_b_dup__hcontainer_1__wrap_2": {"cite": "Stamp Act s.8A(b)", "head": "", "text": "[8G. Strategic sale, disinvestment, etc., of immovable property by Government company not liable to stamp duty.—Notwithstanding anything contained in this Act or any other law for the time being in force, any instrument for conveyance or transfer of a business or asset or right in any immovable property from a Government company, its subsidiary, unit or joint venture,"}, "indian-stamp-act-1899:sec_8A__hcontainer_2__cl_b_dup__hcontainer_1__subcl_i_dup": {"cite": "Stamp Act s.8A(b)(i)", "head": "", "text": "by way of strategic sale or disinvestment or demerger or any other scheme of arrangements or through any law, to another Government company or to the Central Government or any State Government or to the development financial institution established by any law made by Parliament; or"}, "indian-stamp-act-1899:sec_8A__hcontainer_2__cl_b_dup__hcontainer_1__subcl_ii_dup": {"cite": "Stamp Act s.8A(b)(ii)", "head": "", "text": "which is to be wound up, closed, struck-off, liquidated or otherwise shut down, to another Government company or to the Central Government or any State Government,"}, "indian-stamp-act-1899:sec_8A__hcontainer_3": {"cite": "Stamp Act s.8A", "head": "", "text": "For the purposes of this section, “Government company” shall have the same meaning as assigned to it in clause (45) of section 2 of the Companies Act, 2013 (18 of 2013).]"}, "indian-stamp-act-1899:sec_9": {"cite": "Stamp Act s.9", "head": "Power to reduce, remit or compound duties", "text": "[] [The *** Government] may, by rule or order published in the Official Gazette, — reduce or remit, whether prospectively or retrospectively, in the whole or any part of [the territories under its administration], the duties with which any instruments or any particular class of instruments, or any of the instruments belonging to such class, or any instruments when executed by or in favour of any particular class of persons, or by or in favour of any members of such class, are chargeable, and provide for the composition or consolidation of duties [of policies of insurance and] in the case of is…"}, "indian-stamp-act-1899:sec_9__subsec_1": {"cite": "Stamp Act s.9(1)", "head": "", "text": "[] [The *** Government] may, by rule or order published in the Official Gazette, — reduce or remit, whether prospectively or retrospectively, in the whole or any part of [the territories under its administration], the duties with which any instruments or any particular class of instruments, or any of the instruments belonging to such class, or any instruments when executed by or in favour of any particular class of persons, or by or in favour of any members of such class, are chargeable, and provide for the composition or consolidation of duties [of policies of insurance and] in the case of is…"}, "indian-stamp-act-1899:sec_9__subsec_1__cl_a": {"cite": "Stamp Act s.9(1)(a)", "head": "", "text": "reduce or remit, whether prospectively or retrospectively, in the whole or any part of [the territories under its administration], the duties with which any instruments or any particular class of instruments, or any of the instruments belonging to such class, or any instruments when executed by or in favour of any particular class of persons, or by or in favour of any members of such class, are chargeable, and"}, "indian-stamp-act-1899:sec_9__subsec_1__cl_b": {"cite": "Stamp Act s.9(1)(b)", "head": "", "text": "provide for the composition or consolidation of duties [of policies of insurance and] in the case of issues by any incorporated company or other body corporate [or of transfers (where there is a single transferee, whether incorporated or not)] of debentures, bonds or other marketable securities."}, "indian-stamp-act-1899:sec_9__subsec_2": {"cite": "Stamp Act s.9(2)", "head": "", "text": "[In this section the expression “the Government” means, — in relation to stamp-duty in respect of bills of exchange, cheques, promissory notes, bills of lading, letters of credit, policies of insurance, transfer of shares, debentures, proxies and receipts, and in relation to any other stamp-duty chargeable under this Act and falling within entry 96 in List I in the [Seventh Schedule to the Constitution, expect the subject matters referred to in clause (b) of sub-section (1)]; the Central Government; Save as aforesaid, the State Government.]"}, "indian-stamp-act-1899:sec_9__subsec_2__cl_a": {"cite": "Stamp Act s.9(2)(a)", "head": "", "text": "in relation to stamp-duty in respect of bills of exchange, cheques, promissory notes, bills of lading, letters of credit, policies of insurance, transfer of shares, debentures, proxies and receipts, and in relation to any other stamp-duty chargeable under this Act and falling within entry 96 in List I in the [Seventh Schedule to the Constitution, expect the subject matters referred to in clause (b) of sub-section (1)]; the Central Government;"}, "indian-stamp-act-1899:sec_9__subsec_2__cl_b": {"cite": "Stamp Act s.9(2)(b)", "head": "", "text": "Save as aforesaid, the State Government.]"}, "indian-stamp-act-1899:sec_9A": {"cite": "Stamp Act s.9A", "head": "Power of State Government to consolidate duties in respect of receipts", "text": "Subject to such conditions as may be specified, the State Government may, by order, provide for the consolidation of duties in respect of any receipts or class of receipts given by any person or class of persons including any Government. [Vide Karnataka Act 29 of 1978, s. 2]"}, "indian-stamp-act-1899:crossHeading_2": {"cite": "Stamp Act crossHeading_2", "head": "", "text": "[AA.— Of the liability of instruments of transaction in stock exchanges and depositories to duty"}, "indian-stamp-act-1899:sec_9A_dup": {"cite": "Stamp Act s.9A", "head": "Instruments chargeable with duty for transactions in stock exchanges and depositories", "text": "Notwithstanding anything contained in this Act,— when the sale of any securities, whether delivery based or otherwise, is made through a stock exchange, the stamp-duty on each such sale in the clearance list shall be collected on behalf of the State Government by the stock exchange or a clearing corporation authorised by it, from its buyer on the market value of such securities at the time of settlement of transactions in securities of such buyer, in such manner as the Central Government may, by rules, provide; when any transfer of securities for a consideration, whether delivery based or othe…"}, "indian-stamp-act-1899:sec_9A_dup__subsec_1": {"cite": "Stamp Act s.9A(1)", "head": "", "text": "Notwithstanding anything contained in this Act,— when the sale of any securities, whether delivery based or otherwise, is made through a stock exchange, the stamp-duty on each such sale in the clearance list shall be collected on behalf of the State Government by the stock exchange or a clearing corporation authorised by it, from its buyer on the market value of such securities at the time of settlement of transactions in securities of such buyer, in such manner as the Central Government may, by rules, provide; when any transfer of securities for a consideration, whether delivery based or othe…"}, "indian-stamp-act-1899:sec_9A_dup__subsec_1__cl_a": {"cite": "Stamp Act s.9A(1)(a)", "head": "", "text": "when the sale of any securities, whether delivery based or otherwise, is made through a stock exchange, the stamp-duty on each such sale in the clearance list shall be collected on behalf of the State Government by the stock exchange or a clearing corporation authorised by it, from its buyer on the market value of such securities at the time of settlement of transactions in securities of such buyer, in such manner as the Central Government may, by rules, provide;"}, "indian-stamp-act-1899:sec_9A_dup__subsec_1__cl_b": {"cite": "Stamp Act s.9A(1)(b)", "head": "", "text": "when any transfer of securities for a consideration, whether delivery based or otherwise, is made by a depository otherwise than on the basis of any transaction referred to in clause (a), the stamp-duty on such transfer shall be collected on behalf of the State Government by the depository from the transferor of such securities on the consideration amount specified therein, in such manner as the Central Government may, by rules, provide;"}, "indian-stamp-act-1899:sec_9A_dup__subsec_1__cl_c": {"cite": "Stamp Act s.9A(1)(c)", "head": "", "text": "when pursuant to issue of securities, any creation or change in the records of a depository is made, the stamp-duty on the allotment list shall be collected on behalf of the State Government by the depository from the issuer of securities on the total market value of the securities as contained in such list, in such manner as the Central Government may, by rules, provide."}, "indian-stamp-act-1899:sec_9A_dup__subsec_2": {"cite": "Stamp Act s.9A(2)", "head": "", "text": "Notwithstanding anything contained in this Act, the instruments referred to in sub-section (1) shall be chargeable with duty as provided therein at the rate specified in Schedule I and such instruments need not be stamped. [Provided that no such duty shall be chargeable in respect of the instruments of transaction in stock exchanges and depositories established in any International Financial Services Centre set up under section 18 of the Special Economic Zones Act, 2005 (28 of 2005).]"}, "indian-stamp-act-1899:sec_9A_dup__subsec_3": {"cite": "Stamp Act s.9A(3)", "head": "", "text": "From the date of commencement of this Part, no stamp-duty shall be charged or collected by the State Government on any note or memorandum or any other document, electronic or otherwise, associated with the transactions mentioned in sub-section (1)."}, "indian-stamp-act-1899:sec_9A_dup__subsec_4": {"cite": "Stamp Act s.9A(4)", "head": "", "text": "The stock exchange or a clearing corporation authorised by it or the depository, as the case may be, shall, within three weeks of the end of each month and in accordance with the rules made in this behalf by the Central Government, in consultation with the State Government, transfer the stamp-duty collected under this section to the State Government where the residence of the buyer is located and in case the buyer is located outside India, to the State Government having the registered office of the trading member or broker of such buyer and in case where there is no such trading member of the …"}, "indian-stamp-act-1899:sec_9A_dup__subsec_4__proviso_1": {"cite": "Stamp Act s.9A(4)", "head": "", "text": "Provided that before such transfer, the stock exchange or the clearing corporation authorised by it or the depository shall be entitled to deduct such percentage of stamp-duty towards facilitation charges as may be specified in such rules."}, "indian-stamp-act-1899:sec_9A_dup__subsec_4__hcontainer_1": {"cite": "Stamp Act s.9A(4)", "head": "", "text": "The term “participant” shall have the same meaning as assigned to it in clause (g) of section 2 of the Depositories Act, 1996 (22 of 1996)."}, "indian-stamp-act-1899:sec_9A_dup__subsec_5": {"cite": "Stamp Act s.9A(5)", "head": "", "text": "Every stock exchange or the clearing corporation authorised by it and depository shall submit to the Government details of the transactions referred to in sub-section (1) in such manner as the Central Government may, by rules, provide."}, "indian-stamp-act-1899:sec_9B": {"cite": "Stamp Act s.9B", "head": "Instruments chargeable with duty for transactions otherwise than through stock exchanges and depositories", "text": "Notwithstanding anything contained in this Act,— when any issue of securities is made by an issuer otherwise than through a stock exchange or depository, the stamp-duty on each such issue shall be payable by the issuer, at the place where its registered office is located, on the total market value of the securities so issued at the rate specified in Schedule I; when any sale or transfer or reissue of securities for consideration is made otherwise than through a stock exchange or depository, the stamp-duty on each such sale or transfer or reissue shall be payable by the seller or transferor or …"}, "indian-stamp-act-1899:sec_9B__cl_a": {"cite": "Stamp Act s.9B(a)", "head": "", "text": "when any issue of securities is made by an issuer otherwise than through a stock exchange or depository, the stamp-duty on each such issue shall be payable by the issuer, at the place where its registered office is located, on the total market value of the securities so issued at the rate specified in Schedule I;"}, "indian-stamp-act-1899:sec_9B__cl_b": {"cite": "Stamp Act s.9B(b)", "head": "", "text": "when any sale or transfer or reissue of securities for consideration is made otherwise than through a stock exchange or depository, the stamp-duty on each such sale or transfer or reissue shall be payable by the seller or transferor or issuer, as the case may be, on the consideration amount specified in such instrument at the rate specified in Schedule I.]"}, "indian-stamp-act-1899:crossHeading_3": {"cite": "Stamp Act crossHeading_3", "head": "", "text": ""}, "indian-stamp-act-1899:sec_10": {"cite": "Stamp Act s.10", "head": "Duties how to be paid", "text": "Except as otherwise expressly provided in this Act, all duties with which any instruments are chargeable shall be paid, and such payment shall be indicated on such instruments, by means of stamps — according to the provisions herein contained; or when no such provision is applicable thereto—as the [State Government] may be rule direct. The rules made under sub-section (1) may, among other matters, regulate,— in the case of each kind of instrument—the description of stamps which may be used; 1. Subs. by the A.O. 1950, for “collecting Government”. in the case of instruments stamped with impresse…"}, "indian-stamp-act-1899:sec_10__subsec_1": {"cite": "Stamp Act s.10(1)", "head": "", "text": "Except as otherwise expressly provided in this Act, all duties with which any instruments are chargeable shall be paid, and such payment shall be indicated on such instruments, by means of stamps — according to the provisions herein contained; or when no such provision is applicable thereto—as the [State Government] may be rule direct."}, "indian-stamp-act-1899:sec_10__subsec_1__cl_a": {"cite": "Stamp Act s.10(1)(a)", "head": "", "text": "according to the provisions herein contained; or"}, "indian-stamp-act-1899:sec_10__subsec_1__cl_b": {"cite": "Stamp Act s.10(1)(b)", "head": "", "text": "when no such provision is applicable thereto—as the [State Government] may be rule direct."}, "indian-stamp-act-1899:sec_10__subsec_2": {"cite": "Stamp Act s.10(2)", "head": "", "text": "The rules made under sub-section (1) may, among other matters, regulate,— in the case of each kind of instrument—the description of stamps which may be used; 1. Subs. by the A.O. 1950, for “collecting Government”. in the case of instruments stamped with impressed stamps—the number of stamps which may be used; in the case of bills of exchange or promissory notes *** the size of the paper on which they are written."}, "indian-stamp-act-1899:sec_10__subsec_2__cl_a": {"cite": "Stamp Act s.10(2)(a)", "head": "", "text": "in the case of each kind of instrument—the description of stamps which may be used;"}, "indian-stamp-act-1899:sec_10__subsec_2__wrap_1": {"cite": "Stamp Act s.10(2)", "head": "", "text": "1. Subs. by the A.O. 1950, for “collecting Government”."}, "indian-stamp-act-1899:sec_10__subsec_2__cl_b": {"cite": "Stamp Act s.10(2)(b)", "head": "", "text": "in the case of instruments stamped with impressed stamps—the number of stamps which may be used;"}, "indian-stamp-act-1899:sec_10__subsec_2__cl_c": {"cite": "Stamp Act s.10(2)(c)", "head": "", "text": "in the case of bills of exchange or promissory notes *** the size of the paper on which they are written."}, "indian-stamp-act-1899:sec_11": {"cite": "Stamp Act s.11", "head": "Use of adhesive stamps", "text": "The following instruments may be stamped with adhesive stamps, namely: — instruments chargeable [with a duty not exceeding ten naye paise], except parts of bills of exchange payable otherwise than on demand and drawn in sets; bills of exchange, *** and promissory notes drawn or made out of [India]; entry as an advocate, vakil or attorney on the roll of a High Court; notarial acts; and 1. Subs. by Act 19 of 1958, s. 2, for “with the duty of one anna or half an anna” (w.e.f. 1-10-1958). 2. The word “cheques” omitted by Act 5 of 1927, s. 5. 3. Subs. by Act 43 of 1955, s. 2, for “the States” (w.e.…"}, "indian-stamp-act-1899:sec_11__cl_a": {"cite": "Stamp Act s.11(a)", "head": "", "text": "instruments chargeable [with a duty not exceeding ten naye paise], except parts of bills of exchange payable otherwise than on demand and drawn in sets;"}, "indian-stamp-act-1899:sec_11__cl_b": {"cite": "Stamp Act s.11(b)", "head": "", "text": "bills of exchange, *** and promissory notes drawn or made out of [India];"}, "indian-stamp-act-1899:sec_11__cl_c": {"cite": "Stamp Act s.11(c)", "head": "", "text": "entry as an advocate, vakil or attorney on the roll of a High Court;"}, "indian-stamp-act-1899:sec_11__cl_d": {"cite": "Stamp Act s.11(d)", "head": "", "text": "notarial acts; and"}, "indian-stamp-act-1899:sec_11__wrap_1": {"cite": "Stamp Act s.11", "head": "", "text": "1. Subs. by Act 19 of 1958, s. 2, for “with the duty of one anna or half an anna” (w.e.f. 1-10-1958)."}, "indian-stamp-act-1899:sec_11__wrap_2": {"cite": "Stamp Act s.11", "head": "", "text": "2. The word “cheques” omitted by Act 5 of 1927, s. 5."}, "indian-stamp-act-1899:sec_11__wrap_3": {"cite": "Stamp Act s.11", "head": "", "text": "3. Subs. by Act 43 of 1955, s. 2, for “the States” (w.e.f. 1-4-1956)."}, "indian-stamp-act-1899:sec_11__cl_e": {"cite": "Stamp Act s.11(e)", "head": "", "text": "transfers by endorsement of shares in any incorporated company or other body corporate."}, "indian-stamp-act-1899:sec_12": {"cite": "Stamp Act s.12", "head": "Cancellation of adhesive stamps", "text": "(a) Whoever affixes any adhesive stamp to any instrument chargeable with duty which has been executed by any person shall, when affixing such stamp, cancel the same so that it cannot be used again; and (b) whoever executes any instrument on any paper bearing an adhesive stamp shall, at the time of execution, unless such stamp has been already cancelled in manner aforesaid, cancel the same so that it cannot be used again. Any instrument bearing an adhesive stamp which has not been cancelled so that it cannot be used again, shall, so far as such stamp is concerned, be deemed to be unstamped. The…"}, "indian-stamp-act-1899:sec_12__subsec_1": {"cite": "Stamp Act s.12(1)", "head": "", "text": "(a) Whoever affixes any adhesive stamp to any instrument chargeable with duty which has been executed by any person shall, when affixing such stamp, cancel the same so that it cannot be used again; and (b) whoever executes any instrument on any paper bearing an adhesive stamp shall, at the time of execution, unless such stamp has been already cancelled in manner aforesaid, cancel the same so that it cannot be used again."}, "indian-stamp-act-1899:sec_12__subsec_2": {"cite": "Stamp Act s.12(2)", "head": "", "text": "Any instrument bearing an adhesive stamp which has not been cancelled so that it cannot be used again, shall, so far as such stamp is concerned, be deemed to be unstamped."}, "indian-stamp-act-1899:sec_12__subsec_3": {"cite": "Stamp Act s.12(3)", "head": "", "text": "The person required by sub-section (1) to cancel an adhesive stamp may cancel it by writing on or across the stamp his name or initials or the name or initials of his firm with the true date of his so writing, or in any other effectual manner."}, "indian-stamp-act-1899:sec_13": {"cite": "Stamp Act s.13", "head": "Instruments stamped with impressed stamps how to be written", "text": "Every instrument written upon paper stamped with an impressed stamp shall be written in such manner that the stamp may appear on the face of the instrument and cannot be used for or applied to any other instrument."}, "indian-stamp-act-1899:sec_14": {"cite": "Stamp Act s.14", "head": "Only one instrument to be on same stamp", "text": "No second instrument chargeable with duty shall be written upon a piece of stamped paper upon which an instrument chargeable with duty has already been written: Provided that nothing in this section shall prevent any endorsement which is duly stamped or is not chargeable with duty being made upon any instrument for the purpose of transferring any right created or evidenced thereby, or of acknowledging the receipt of any money or goods the payment or delivery of which is secured thereby."}, "indian-stamp-act-1899:sec_14__proviso_1": {"cite": "Stamp Act s.14", "head": "", "text": "Provided that nothing in this section shall prevent any endorsement which is duly stamped or is not chargeable with duty being made upon any instrument for the purpose of transferring any right created or evidenced thereby, or of acknowledging the receipt of any money or goods the payment or delivery of which is secured thereby."}, "indian-stamp-act-1899:sec_15": {"cite": "Stamp Act s.15", "head": "Instrument written contrary to section 13 or 14 deemed unstamped", "text": "Every instrument written in contravention of section 13 or section 14 shall be deemed to be unstamped."}, "indian-stamp-act-1899:sec_16": {"cite": "Stamp Act s.16", "head": "Denoting duty", "text": "Where the duty with which an instrument is chargeable, or its exemption from duty, depends in any manner upon the duty actually paid in respect of another instrument, the payment of such last-mentioned duty shall, if application is made in writing to the Collector for that purpose, and on production of both the instruments, be denoted upon such first-mentioned instrument by endorsement under the hand of the Collector or in such other manner (if any) as the [State Government] may by rule prescribe."}, "indian-stamp-act-1899:crossHeading_4": {"cite": "Stamp Act crossHeading_4", "head": "", "text": ""}, "indian-stamp-act-1899:sec_17": {"cite": "Stamp Act s.17", "head": "Instruments executed in India", "text": "All instruments chargeable with duty and executed by any person in [India] shall be stamped before or at the time of execution."}, "indian-stamp-act-1899:sec_18": {"cite": "Stamp Act s.18", "head": "Instruments other than bills and notes executed out of India", "text": "Every instrument chargeable with duty executed only out of [India], and not being a bill of exchange *** or promissory note, may be stamped within three months after it has been first received in [India]. Where any such instrument cannot, with reference to the description of stamp prescribed therefore, be duly stamped by a private person, it may be taken within the said period of three months to the Collector, who shall stamp the same, in such manner as the [State Government] may by rule prescribe, with a stamp of such value as the person so taking such instrument may require and pay for."}, "indian-stamp-act-1899:sec_18__subsec_1": {"cite": "Stamp Act s.18(1)", "head": "", "text": "Every instrument chargeable with duty executed only out of [India], and not being a bill of exchange *** or promissory note, may be stamped within three months after it has been first received in [India]."}, "indian-stamp-act-1899:sec_18__subsec_2": {"cite": "Stamp Act s.18(2)", "head": "", "text": "Where any such instrument cannot, with reference to the description of stamp prescribed therefore, be duly stamped by a private person, it may be taken within the said period of three months to the Collector, who shall stamp the same, in such manner as the [State Government] may by rule prescribe, with a stamp of such value as the person so taking such instrument may require and pay for."}, "indian-stamp-act-1899:sec_19": {"cite": "Stamp Act s.19", "head": "Bills and notes drawn out of India", "text": "The first holder in [India] of any bill of exchange [payable otherwise than on demand], *** or promissory note drawn or made out of [India] shall, before he presents the same for acceptance or payment, or endorses, transfers or otherwise negotiates the same in [India], affix thereto the proper stamp and cancel the same: Provided that,— if, at the time any such bill of exchange, *** or note comes into the hands of any holder thereof in [India], the proper adhesive stamp is affixed thereto and cancelled in manner prescribed by section 12 and such holder has no reason to believe that such stamp w…"}, "indian-stamp-act-1899:sec_19__proviso_1": {"cite": "Stamp Act s.19", "head": "", "text": "Provided that,— if, at the time any such bill of exchange, *** or note comes into the hands of any holder thereof in [India], the proper adhesive stamp is affixed thereto and cancelled in manner prescribed by section 12 and such holder has no reason to believe that such stamp was affixed or cancelled otherwise than by the person and at the time required by this Act, such stamp shall, so far as relates to such holder, be deemed to have been duly affixed and cancelled; nothing contained in this proviso shall relieve any person from any penalty incurred by him for omitting to affix or cancel a st…"}, "indian-stamp-act-1899:sec_19__proviso_1__cl_a": {"cite": "Stamp Act s.19(a)", "head": "", "text": "if, at the time any such bill of exchange, *** or note comes into the hands of any holder thereof in [India], the proper adhesive stamp is affixed thereto and cancelled in manner prescribed by section 12 and such holder has no reason to believe that such stamp was affixed or cancelled otherwise than by the person and at the time required by this Act, such stamp shall, so far as relates to such holder, be deemed to have been duly affixed and cancelled;"}, "indian-stamp-act-1899:sec_19__proviso_1__cl_b": {"cite": "Stamp Act s.19(b)", "head": "", "text": "nothing contained in this proviso shall relieve any person from any penalty incurred by him for omitting to affix or cancel a stamp."}, "indian-stamp-act-1899:crossHeading_5": {"cite": "Stamp Act crossHeading_5", "head": "", "text": ""}, "indian-stamp-act-1899:sec_20": {"cite": "Stamp Act s.20", "head": "Conversion of amount expressed in foreign currencies", "text": "Where an instrument is chargeable with ad valorem duty in respect of any money expressed in any currency other than that of [India] such duty shall be calculated on the value of such money in the currency of [India] according to the current rate of exchange on the day of the date of the instrument. The Central Government may, from time to time, by notification in the Official Gazette, prescribe a rate of exchange for the conversion of British or any foreign currency into the currency of [India] for the purposes of calculating stamp-duty, and such rate shall be deemed to be the current rate for…"}, "indian-stamp-act-1899:sec_20__subsec_1": {"cite": "Stamp Act s.20(1)", "head": "", "text": "Where an instrument is chargeable with ad valorem duty in respect of any money expressed in any currency other than that of [India] such duty shall be calculated on the value of such money in the currency of [India] according to the current rate of exchange on the day of the date of the instrument."}, "indian-stamp-act-1899:sec_20__subsec_2": {"cite": "Stamp Act s.20(2)", "head": "", "text": "The Central Government may, from time to time, by notification in the Official Gazette, prescribe a rate of exchange for the conversion of British or any foreign currency into the currency of [India] for the purposes of calculating stamp-duty, and such rate shall be deemed to be the current rate for the purposes of sub-section (1)."}, "indian-stamp-act-1899:sec_21": {"cite": "Stamp Act s.21", "head": "Stock and marketable securities how to be valued", "text": "Where an instrument is chargeable with ad valorem duty in respect of any stock or of any marketable or other security, such duty shall be calculated on [the market value of such stock or security.] [Provided that the market value for calculating the stamp-duty shall be, in the case of— options in any securities, the premium paid by the buyer; repo on corporate bonds, interest paid by the borrower; and swap, only the first leg of the cash flow.]"}, "indian-stamp-act-1899:sec_21__subcl_i": {"cite": "Stamp Act s.21(i)", "head": "", "text": "options in any securities, the premium paid by the buyer;"}, "indian-stamp-act-1899:sec_21__subcl_ii": {"cite": "Stamp Act s.21(ii)", "head": "", "text": "repo on corporate bonds, interest paid by the borrower; and"}, "indian-stamp-act-1899:sec_21__subcl_iii": {"cite": "Stamp Act s.21(iii)", "head": "", "text": "swap, only the first leg of the cash flow.]"}, "indian-stamp-act-1899:sec_22": {"cite": "Stamp Act s.22", "head": "Effect of statement of rate of exchange or average price", "text": "Where an instrument contains a statement of current rate of exchange, or average price, as the case may require, and is stamped in accordance with such statement, it shall, so far as regards the subject-matter of such statement, be presumed, until the contrary is proved, to be duly stamped. 1. Subs. by Act 7 of 2019, s. 16, for “the value of such stock or security according to the average price or the value thereof on the day of the date of the instrument.” (w.e.f. 1-7-2020). [Earlier notified w.e.f. 9-1-2020 followed by 1-4-2020]."}, "indian-stamp-act-1899:sec_23": {"cite": "Stamp Act s.23", "head": "Instruments reserving interest", "text": "Where interest is expressly made payable by the terms of an instrument, such instrument shall not be chargeable with duty higher than that with which it would have been chargeable had no mention of interest been made therein."}, "indian-stamp-act-1899:sec_23A": {"cite": "Stamp Act s.23A", "head": "Certain instruments connected with mortgages of marketable securities to be chargeable as agreements", "text": "[Where an instrument (not being a promissory note or bill of exchange)— is given upon the occasion of the deposit of any marketable security by way of security for money advanced or to be advanced by way of loan, or for an existing or future debt, or makes redeemable or qualifies a duly stamped transfer, intended as a security, of any marketable security, it shall be chargeable with duty as if it were an agreement or memorandum of an agreement chargeable with duty under [Article No. 5 (c)] of Schedule I. A release or discharge of any such instrument shall only be chargeable with the like duty.…"}, "indian-stamp-act-1899:sec_23A__subsec_1": {"cite": "Stamp Act s.23A(1)", "head": "", "text": "[Where an instrument (not being a promissory note or bill of exchange)— is given upon the occasion of the deposit of any marketable security by way of security for money advanced or to be advanced by way of loan, or for an existing or future debt, or makes redeemable or qualifies a duly stamped transfer, intended as a security, of any marketable security, it shall be chargeable with duty as if it were an agreement or memorandum of an agreement chargeable with duty under [Article No. 5 (c)] of Schedule I."}, "indian-stamp-act-1899:sec_23A__subsec_1__cl_a": {"cite": "Stamp Act s.23A(1)(a)", "head": "", "text": "is given upon the occasion of the deposit of any marketable security by way of security for money advanced or to be advanced by way of loan, or for an existing or future debt, or"}, "indian-stamp-act-1899:sec_23A__subsec_1__cl_b": {"cite": "Stamp Act s.23A(1)(b)", "head": "", "text": "makes redeemable or qualifies a duly stamped transfer, intended as a security, of any marketable security,"}, "indian-stamp-act-1899:sec_23A__subsec_2": {"cite": "Stamp Act s.23A(2)", "head": "", "text": "A release or discharge of any such instrument shall only be chargeable with the like duty. ]"}, "indian-stamp-act-1899:sec_24": {"cite": "Stamp Act s.24", "head": "How transfer in consideration of debt, or subject to future payment, etc., to be charged", "text": "Where any property is transferred to any person in consideration, wholly or in part, of any debt due to him, or subject either certainly or contingently to the payment or transfer of any money or stock, whether being or constituting a charge or incumbrance upon the property or not, such debt, money or stock is to be deemed the whole or part, as the case may be, of the consideration in respect whereof the transfer is chargeable with ad valorem duty: Provided that, nothing in this section shall apply to any such certificate of sale as is mentioned in Article No. 18 of Schedule I. In the case of …"}, "indian-stamp-act-1899:sec_24__proviso_1": {"cite": "Stamp Act s.24", "head": "", "text": "Provided that, nothing in this section shall apply to any such certificate of sale as is mentioned in Article No. 18 of Schedule I."}, "indian-stamp-act-1899:sec_24__hcontainer_1": {"cite": "Stamp Act s.24", "head": "", "text": "In the case of a sale of property subject to a mortgage or other incumbrance, any unpaid mortgage money or money charged, together with the interest (if any) due on the same, shall be deemed to be part of the consideration for the sale:"}, "indian-stamp-act-1899:sec_24__proviso_2": {"cite": "Stamp Act s.24", "head": "", "text": "Provided that, where property subject to a mortgage is transferred to the mortgagee, he shall be entitled to deduct from the duty payable on the transfer the amount of any duty already paid in respect of the mortgage. Illustrations (1) A owes B Rs. 1,000. A sells a property to B, the consideration being Rs. 500 and the release of the previous debt of Rs. 1,000. Stamp-duty is payable on Rs. 1,500. (2) A sells a property to B for Rs. 500 which is subject to a mortgage to C for Rs. 1,000 and unpaid interest Rs 200. Stamp-duty is payable on Rs. 1,700. (3) A mortgages a house of the value of Rs. 10…"}, "indian-stamp-act-1899:sec_24__proviso_2__hcontainer_1": {"cite": "Stamp Act s.24", "head": "Illustrations", "text": "(1) A owes B Rs. 1,000. A sells a property to B, the consideration being Rs. 500 and the release of the previous debt of Rs. 1,000. Stamp-duty is payable on Rs. 1,500. (2) A sells a property to B for Rs. 500 which is subject to a mortgage to C for Rs. 1,000 and unpaid interest Rs 200. Stamp-duty is payable on Rs. 1,700. (3) A mortgages a house of the value of Rs. 10,000 to B for Rs. 5,000. B afterwards buys the house from A. Stamp-duty is payable on Rs. 10,000 less the amount of stamp-duty already paid for the mortgage."}, "indian-stamp-act-1899:sec_25": {"cite": "Stamp Act s.25", "head": "Valuation in case of annuity, etc", "text": "Where an instrument is executed to secure the payment of an annuity or other sum payable periodically, or where the consideration for a conveyance is an annuity or other sum payable periodically, the amount secured by such instrument or the consideration for such conveyance, as the case may be, shall, for the purposes of this Act, be deemed to be,— where the sum is payable for a definite period so that the total amount to be paid can be previously ascertained—such total amount; where the sum is payable in perpetuity or for an indefinite time not terminable with any life in being at the date of…"}, "indian-stamp-act-1899:sec_25__cl_a": {"cite": "Stamp Act s.25(a)", "head": "", "text": "where the sum is payable for a definite period so that the total amount to be paid can be previously ascertained—such total amount;"}, "indian-stamp-act-1899:sec_25__cl_b": {"cite": "Stamp Act s.25(b)", "head": "", "text": "where the sum is payable in perpetuity or for an indefinite time not terminable with any life in being at the date of such instrument or conveyance—the total amount which, according to the terms of such instrument or conveyance, will or may be payable during the period of twenty years calculated from the date on which the first payment becomes due; and"}, "indian-stamp-act-1899:sec_25__cl_c": {"cite": "Stamp Act s.25(c)", "head": "", "text": "where the sum is payable for an indefinite time terminable with any life in being at the date of such instrument or conveyance—the maximum amount which will or may be payable as aforesaid during the period of twelve years calculated from the date on which the first payment becomes due."}, "indian-stamp-act-1899:sec_26": {"cite": "Stamp Act s.26", "head": "Stamp where value of subject-matter is indeterminate", "text": "Where the amount or value of the subject-matter of any instrument chargeable with ad valorem duty cannot be, or (in the case of an instrument executed before the commencement of this Act) could not have been, ascertained at the date of its execution or first execution, nothing shall be claimable under such instrument more than the highest amount or value for which, if stated in an instrument of the same description, the stamp actually used would, at the date of such execution, have been sufficient: [Provided that, in the case of the lease of a mine in which royalty or a share of the produce is…"}, "indian-stamp-act-1899:sec_26__cl_a": {"cite": "Stamp Act s.26(a)", "head": "", "text": "when the lease has been granted by or on behalf of [the Government], at such amount or value as the Collector may, having regard to all the circumstances of the case, have estimated as likely to be payable by way of royalty or share to [the Government] under the lease, or"}, "indian-stamp-act-1899:sec_26__cl_b": {"cite": "Stamp Act s.26(b)", "head": "", "text": "when the lease has been granted by any other person, at twenty thousand rupees a year,"}, "indian-stamp-act-1899:sec_26__wrap_1": {"cite": "Stamp Act s.26", "head": "", "text": "and the whole amount of such royalty or share, whatever it may be, shall be claimable under such lease:]"}, "indian-stamp-act-1899:sec_26__proviso_1": {"cite": "Stamp Act s.26", "head": "", "text": "Provided also that where proceedings have been taken in respect of an instrument under section 31 or 41, the amount certified by the Collector shall be deemed to be the stamp actually used at the date of execution."}, "indian-stamp-act-1899:sec_27": {"cite": "Stamp Act s.27", "head": "Facts affecting duty to be set forth in instrument", "text": "The consideration (if any) and all other facts and circumstances affecting the chargeability of any instrument with duty, or the amount of the duty with which it its chargeable, shall be fully and truly set forth therein."}, "indian-stamp-act-1899:sec_28": {"cite": "Stamp Act s.28", "head": "Direction as to duty in case of certain conveyances", "text": "Where any property has been contracted to be sold for one consideration for the whole, and is conveyed to the purchaser in separate parts by different instruments, the consideration shall be apportioned in such manner as the parties think fit, provided that a distinct consideration for each separate part is set forth in the conveyance relating thereto, and such conveyance shall be chargeable with ad valorem duty in respect of such distinct consideration. Where property contracted to be purchased for one consideration for the whole, by two or more persons jointly, or by any person for himself a…"}, "indian-stamp-act-1899:sec_28__subsec_1": {"cite": "Stamp Act s.28(1)", "head": "", "text": "Where any property has been contracted to be sold for one consideration for the whole, and is conveyed to the purchaser in separate parts by different instruments, the consideration shall be apportioned in such manner as the parties think fit, provided that a distinct consideration for each separate part is set forth in the conveyance relating thereto, and such conveyance shall be chargeable with ad valorem duty in respect of such distinct consideration."}, "indian-stamp-act-1899:sec_28__subsec_2": {"cite": "Stamp Act s.28(2)", "head": "", "text": "Where property contracted to be purchased for one consideration for the whole, by two or more persons jointly, or by any person for himself and others, or wholly for others, is conveyed in parts by separate instruments to the persons by or for whom the same was purchased, for distinct parts of the consideration, the conveyance of each separate part shall be chargeable with ad valorem duty in respect of the distinct part of the consideration therein specified."}, "indian-stamp-act-1899:sec_28__subsec_3": {"cite": "Stamp Act s.28(3)", "head": "", "text": "Where a person, having contracted for the purchase of any property but not having obtained a conveyance thereof, contracts to sell the same to any other person and the property is in consequence"}, "indian-stamp-act-1899:sec_28__wrap_1": {"cite": "Stamp Act s.28", "head": "", "text": "conveyed immediately to the sub-purchaser the conveyance shall be chargeable with ad valorem duty in respect of the consideration for the sale by the original purchaser to the sub-purchaser."}, "indian-stamp-act-1899:sec_28__subsec_4": {"cite": "Stamp Act s.28(4)", "head": "", "text": "Where a person, having contracted for the purchase of any property but not having obtained a conveyance thereof, contracts to sell the whole, or any part thereof, to any other person or persons and the property is in consequence conveyed by the original seller to different persons in parts, the conveyance of each part sold to a sub-purchaser shall be chargeable with ad valorem duty in respect only of the consideration paid by such sub-purchaser, without regard to the amount or value of the original consideration; and the conveyance of the residue (if any) of such property to the original purch…"}, "indian-stamp-act-1899:sec_28__subsec_4__proviso_1": {"cite": "Stamp Act s.28(4)", "head": "", "text": "Provided that the duty on such last-mentioned conveyance shall in no case be less than one rupee."}, "indian-stamp-act-1899:sec_28__subsec_5": {"cite": "Stamp Act s.28(5)", "head": "", "text": "Where a sub-purchaser takes an actual conveyance of the interest of the person immediately selling to him, which is chargeable with ad valorem duty in respect of the consideration paid by him and is duly stamped accordingly, any conveyance to be afterwards made to him of the same property by the original seller shall be chargeable with a duty equal to that which would be chargeable on a conveyance for the consideration obtained by such original seller, or, where such duty would exceed five rupees, with a duty of five rupees."}, "indian-stamp-act-1899:crossHeading_6": {"cite": "Stamp Act crossHeading_6", "head": "", "text": ""}, "indian-stamp-act-1899:sec_29": {"cite": "Stamp Act s.29", "head": "Duties by whom payable", "text": "In the absence of an agreement to the contrary, the expense of providing the proper stamp shall be borne — [(b) in the case of a policy of insurance other than fire-insurance—by the person effecting the insurance; (bb) in the case of a policy of fire-insurance— by the person issuing the policy;] (c) in the case of a conveyance (including re-conveyance of mortgaged property) by the grantee: in the case of a lease or agreement to lease—by the lessee or intended lessee: in the case of any instrument described in any of the following Articles of Schedule I, namely:—No. 2. (Administration Bond), [N…"}, "indian-stamp-act-1899:sec_29__cl_a": {"cite": "Stamp Act s.29(a)", "head": "", "text": "in the case of any instrument described in any of the following Articles of Schedule I, namely:—No. 2. (Administration Bond), [No. 6 (Agreement relating to Deposit of Title-deeds, Pawn or Pledge),] No. 13 (Bill of exchange), No. 15 (Bond), No. 16 (Bottomry Bond), No. 26 (Customs Bond), * * * * * No. 32 (Further charge), No. 34 (Indemnity-Bond), No. 40 (Mortgage-deed), No. 49 (Promissory-note), No. 55 (Release), No. 56 (Respondentia Bond), No. 57 (Security-bond or Mortgage-deed), No. 58 (Settlement),"}, "indian-stamp-act-1899:sec_29__cl_b": {"cite": "Stamp Act s.29(b)", "head": "", "text": "* * * * *"}, "indian-stamp-act-1899:sec_29__cl_c": {"cite": "Stamp Act s.29(c)", "head": "", "text": "* * * * * No. 62 (c). (Transfer of any interest secured by a bond, mortgage-deed or policy of insurance),—"}, "indian-stamp-act-1899:sec_29__wrap_1": {"cite": "Stamp Act s.29", "head": "", "text": "by the person drawing, making or executing such instrument:"}, "indian-stamp-act-1899:sec_29__cl_d": {"cite": "Stamp Act s.29(d)", "head": "", "text": "in the case of a counterpart of a lease—by the lessor;"}, "indian-stamp-act-1899:sec_29__cl_e": {"cite": "Stamp Act s.29(e)", "head": "", "text": "in the case of an instrument of exchange [including swap]—by the parties in equal shares,"}, "indian-stamp-act-1899:sec_29__cl_f": {"cite": "Stamp Act s.29(f)", "head": "", "text": "in the case of a certificate of sale—by the purchaser of the property to which such certificate relates; ***"}, "indian-stamp-act-1899:sec_29__cl_g": {"cite": "Stamp Act s.29(g)", "head": "", "text": "in the case of an instrument of partition—by the parties thereto in proportion to their respective shares in the whole property partitioned or, when the partition is made in execution of an order passed by a Revenue-authority or Civil Court or arbitrator, in such proportion as such authority, Court or arbitrator directs."}, "indian-stamp-act-1899:sec_29__cl_h": {"cite": "Stamp Act s.29(h)", "head": "", "text": "[in the case of sale of security through stock exchange, by the buyer of such security;"}, "indian-stamp-act-1899:sec_29__wrap_2": {"cite": "Stamp Act s.29", "head": "", "text": "1. Subs. by Act 15 of 1904, s. 5, for “No. 6 (Agreement to Mortgage)”."}, "indian-stamp-act-1899:sec_29__wrap_3": {"cite": "Stamp Act s.29", "head": "", "text": "2. The words, figures and brackets “No. 27 (Debenture)” omitted by Act 7 of 2019, s. 17 (w.e.f. 1-7-2020). [Earlier notified w.e.f. 9-1-2020 followed by 1-4-2020] 3. The words, figures, brackets and letter “No. 62 (a) (Transfer of shares in an incorporated Company or other body corporate)” omitted by s. 17, ibid. (w.e.f. 1-7-2020). [Earlier notified w.e.f. 9-1-2020 followed by 1-4-2020]"}, "indian-stamp-act-1899:sec_29__cl_i": {"cite": "Stamp Act s.29(i)", "head": "", "text": "in the case of sale of security otherwise than through a stock exchange, by the seller of such security;"}, "indian-stamp-act-1899:sec_29__cl_j": {"cite": "Stamp Act s.29(j)", "head": "", "text": "in the case of transfer of security through a depository, by the transferor of such security;"}, "indian-stamp-act-1899:sec_29__cl_k": {"cite": "Stamp Act s.29(k)", "head": "", "text": "in the case of transfer of security otherwise than through a stock exchange or depository, by the transferor of such security;"}, "indian-stamp-act-1899:sec_29__cl_l": {"cite": "Stamp Act s.29(l)", "head": "", "text": "in the case of issue of security, whether through a stock exchange or a depository or otherwise, by the issuer of such security; and"}, "indian-stamp-act-1899:sec_29__cl_m": {"cite": "Stamp Act s.29(m)", "head": "", "text": "in the case of any other instrument not specified herein, by the person making, drawing or executing such instrument.]"}, "indian-stamp-act-1899:sec_30": {"cite": "Stamp Act s.30", "head": "Obligation to give receipt in certain cases", "text": "Any person receiving any money exceeding twenty rupees in amount, or any bill of exchange, cheque or promissory note for an amount exceeding twenty rupees, or receiving in satisfaction or part satisfaction of a debt any movable property exceeding twenty rupees in value, shall, on demand by the person paying or delivering such money, bill, cheque, note or property, give a duly stamped receipt for the same. [Any person receiving or taking credit for any premium or consideration for any renewal of any contract of fire-insurance, shall, within one month after receiving or taking credit for such pr…"}, "indian-stamp-act-1899:chp_III": {"cite": "Stamp Act Chapter III", "head": "ADJUDICATION AS TO STAMPS", "text": "Adjudication as to proper stamp When any instrument, whether executed or not and whether previously stamped or not, is brought to the Collector, and the person bringing it applies to have the opinion of that officer as to the duty (if any) with which it is chargeable, and pays a fee of such amount (not exceeding five rupees and not less than [fifty naye paise]) as the Collector may in each case direct, the Collector shall determine the duty (if any) with which, in his judgment, the instrument is chargeable. For this purpose the Collector may require to be furnished with an abstract of the inst…"}, "indian-stamp-act-1899:sec_31": {"cite": "Stamp Act s.31", "head": "Adjudication as to proper stamp", "text": "When any instrument, whether executed or not and whether previously stamped or not, is brought to the Collector, and the person bringing it applies to have the opinion of that officer as to the duty (if any) with which it is chargeable, and pays a fee of such amount (not exceeding five rupees and not less than [fifty naye paise]) as the Collector may in each case direct, the Collector shall determine the duty (if any) with which, in his judgment, the instrument is chargeable. For this purpose the Collector may require to be furnished with an abstract of the instrument, and also with such affid…"}, "indian-stamp-act-1899:sec_31__subsec_1": {"cite": "Stamp Act s.31(1)", "head": "", "text": "When any instrument, whether executed or not and whether previously stamped or not, is brought to the Collector, and the person bringing it applies to have the opinion of that officer as to the duty (if any) with which it is chargeable, and pays a fee of such amount (not exceeding five rupees and not less than [fifty naye paise]) as the Collector may in each case direct, the Collector shall determine the duty (if any) with which, in his judgment, the instrument is chargeable."}, "indian-stamp-act-1899:sec_31__subsec_2": {"cite": "Stamp Act s.31(2)", "head": "", "text": "For this purpose the Collector may require to be furnished with an abstract of the instrument, and also with such affidavit or other evidence as he may deem necessary to prove that all the facts and circumstances affecting the chargeability of the instrument with duty, or the amount of the duty with which it is chargeable, are fully and truly set forth therein, and may refuse to proceed upon any such application until such abstract and evidence have been furnished accordingly: Provided that— no evidence furnished in pursuance of this section shall be used against any person in any civil procee…"}, "indian-stamp-act-1899:sec_31__subsec_2__proviso_1": {"cite": "Stamp Act s.31(2)", "head": "", "text": "Provided that— no evidence furnished in pursuance of this section shall be used against any person in any civil proceeding, except in an inquiry as to the duty with which the instrument to which it relates is chargeable; and every person by whom any such evidence is furnished, shall, on payment of the full duty with which the instrument to which it relates, is chargeable, be relieved from any penalty which he may have incurred under this Act by reason of the omission to state truly in such instrument any of the facts or circumstances aforesaid."}, "indian-stamp-act-1899:sec_31__subsec_2__proviso_1__cl_a": {"cite": "Stamp Act s.31(2)(a)", "head": "", "text": "no evidence furnished in pursuance of this section shall be used against any person in any civil proceeding, except in an inquiry as to the duty with which the instrument to which it relates is chargeable; and"}, "indian-stamp-act-1899:sec_31__subsec_2__proviso_1__cl_b": {"cite": "Stamp Act s.31(2)(b)", "head": "", "text": "every person by whom any such evidence is furnished, shall, on payment of the full duty with which the instrument to which it relates, is chargeable, be relieved from any penalty which he may have incurred under this Act by reason of the omission to state truly in such instrument any of the facts or circumstances aforesaid."}, "indian-stamp-act-1899:sec_32": {"cite": "Stamp Act s.32", "head": "Certificate by Collector", "text": "When an instrument brought to the Collector under section 31 is, in his opinion, one of a description chargeable with duty, and the Collector determines that it is already fully stamped, or the duty determined by the Collector under section 31, or such a sum as, with the duty already paid in respect of the instrument, is equal to the duty so determined, has been paid, the Collector shall certify by endorsement on such instrument that the full duty (stating the amount) with which it is chargeable has been paid. When such instrument is, in his opinion, not chargeable with duty, the Collector sha…"}, "indian-stamp-act-1899:sec_32__subsec_1": {"cite": "Stamp Act s.32(1)", "head": "", "text": "When an instrument brought to the Collector under section 31 is, in his opinion, one of a description chargeable with duty, and the Collector determines that it is already fully stamped, or the duty determined by the Collector under section 31, or such a sum as, with the duty already paid in respect of the instrument, is equal to the duty so determined, has been paid, the Collector shall certify by endorsement on such instrument that the full duty (stating the amount) with which it is chargeable has been paid."}, "indian-stamp-act-1899:sec_32__subsec_1__cl_a": {"cite": "Stamp Act s.32(1)(a)", "head": "", "text": "the Collector determines that it is already fully stamped, or"}, "indian-stamp-act-1899:sec_32__subsec_1__cl_b": {"cite": "Stamp Act s.32(1)(b)", "head": "", "text": "the duty determined by the Collector under section 31, or such a sum as, with the duty already paid in respect of the instrument, is equal to the duty so determined, has been paid,"}, "indian-stamp-act-1899:sec_32__subsec_2": {"cite": "Stamp Act s.32(2)", "head": "", "text": "When such instrument is, in his opinion, not chargeable with duty, the Collector shall certify in manner aforesaid that such instrument is not so chargeable."}, "indian-stamp-act-1899:sec_32__subsec_3": {"cite": "Stamp Act s.32(3)", "head": "", "text": "Any instrument upon which an endorsement has been made under this section, shall be deemed to be duly stamped or not chargeable with duty, as the case may be; and, if chargeable with duty, shall be receivable in evidence or otherwise, and may be acted upon and registered as if it had been originally duly stamped: Provided that nothing in this section shall authorize the Collector to endorse— any instrument executed or first executed in [India] and brought to him after the expiration of one month from the date of its execution or first execution, as the case may be; any instrument executed or f…"}, "indian-stamp-act-1899:sec_32__subsec_3__proviso_1": {"cite": "Stamp Act s.32(3)", "head": "", "text": "Provided that nothing in this section shall authorize the Collector to endorse— any instrument executed or first executed in [India] and brought to him after the expiration of one month from the date of its execution or first execution, as the case may be; any instrument executed or first executed out of [India] and brought to him after the expiration of three months after it has been first received in [India]; or any instrument chargeable [with a duty not exceeding ten naye paise], or any bill of exchange or promissory note, when brought to him, after the drawing or execution thereof, on pape…"}, "indian-stamp-act-1899:sec_32__subsec_3__proviso_1__cl_a": {"cite": "Stamp Act s.32(3)(a)", "head": "", "text": "any instrument executed or first executed in [India] and brought to him after the expiration of one month from the date of its execution or first execution, as the case may be;"}, "indian-stamp-act-1899:sec_32__subsec_3__proviso_1__cl_b": {"cite": "Stamp Act s.32(3)(b)", "head": "", "text": "any instrument executed or first executed out of [India] and brought to him after the expiration of three months after it has been first received in [India]; or"}, "indian-stamp-act-1899:sec_32__subsec_3__proviso_1__cl_c": {"cite": "Stamp Act s.32(3)(c)", "head": "", "text": "any instrument chargeable [with a duty not exceeding ten naye paise], or any bill of exchange or promissory note, when brought to him, after the drawing or execution thereof, on paper not duly stamped."}, "indian-stamp-act-1899:chp_IV": {"cite": "Stamp Act Chapter IV", "head": "INSTRUMENTS NOT DULY STAMPED", "text": "Examination and impounding of instruments Every person having by law or consent of parties authority to receive evidence, and every person in charge of a public office, except an officer of police, before whom any instrument, chargeable, in his opinion, with duty, is produced or comes in the performance of his functions, shall, if it appears to him that such instrument is not duly stamped, impound the same. For that purpose every such person shall examine every instrument so chargeable and so produced or coming before him, in order to ascertain whether it is stamped with a stamp of the value a…"}, "indian-stamp-act-1899:sec_33": {"cite": "Stamp Act s.33", "head": "Examination and impounding of instruments", "text": "Every person having by law or consent of parties authority to receive evidence, and every person in charge of a public office, except an officer of police, before whom any instrument, chargeable, in his opinion, with duty, is produced or comes in the performance of his functions, shall, if it appears to him that such instrument is not duly stamped, impound the same. For that purpose every such person shall examine every instrument so chargeable and so produced or coming before him, in order to ascertain whether it is stamped with a stamp of the value and description required by the law in forc…"}, "indian-stamp-act-1899:sec_33__subsec_1": {"cite": "Stamp Act s.33(1)", "head": "", "text": "Every person having by law or consent of parties authority to receive evidence, and every person in charge of a public office, except an officer of police, before whom any instrument, chargeable, in his opinion, with duty, is produced or comes in the performance of his functions, shall, if it appears to him that such instrument is not duly stamped, impound the same."}, "indian-stamp-act-1899:sec_33__subsec_2": {"cite": "Stamp Act s.33(2)", "head": "", "text": "For that purpose every such person shall examine every instrument so chargeable and so produced or coming before him, in order to ascertain whether it is stamped with a stamp of the value and description required by the law in force in [India] when such instrument was executed or first executed: Provided that— nothing herein contained shall be deemed to require any Magistrate or Judge of a Criminal Court to examine or impound, if he does not think fit so to do, any instrument coming before him in the course of any proceeding other than a proceeding under Chapter XII or Chapter XXXVI of the Cod…"}, "indian-stamp-act-1899:sec_33__subsec_2__proviso_1": {"cite": "Stamp Act s.33(2)", "head": "", "text": "Provided that— nothing herein contained shall be deemed to require any Magistrate or Judge of a Criminal Court to examine or impound, if he does not think fit so to do, any instrument coming before him in the course of any proceeding other than a proceeding under Chapter XII or Chapter XXXVI of the Code of Criminal Procedure, 1898 (V of 1898); 1. Subs. by Act 43 of 1955, s. 2, for “the States” (w.e.f. 1-4-1956). 2. Subs. by Act 19 of 1958, s. 4, for “with the Duty of one anna or half an anna” (w.e.f. 1-10-1958). in the case of a Judge of a High Court, the duty of examining and impounding any i…"}, "indian-stamp-act-1899:sec_33__subsec_2__proviso_1__cl_a": {"cite": "Stamp Act s.33(2)(a)", "head": "", "text": "nothing herein contained shall be deemed to require any Magistrate or Judge of a Criminal Court to examine or impound, if he does not think fit so to do, any instrument coming before him in the course of any proceeding other than a proceeding under Chapter XII or Chapter XXXVI of the Code of Criminal Procedure, 1898 (V of 1898);"}, "indian-stamp-act-1899:sec_33__subsec_2__proviso_1__wrap_1": {"cite": "Stamp Act s.33(2)", "head": "", "text": "1. Subs. by Act 43 of 1955, s. 2, for “the States” (w.e.f. 1-4-1956)."}, "indian-stamp-act-1899:sec_33__subsec_2__proviso_1__wrap_2": {"cite": "Stamp Act s.33(2)", "head": "", "text": "2. Subs. by Act 19 of 1958, s. 4, for “with the Duty of one anna or half an anna” (w.e.f. 1-10-1958)."}, "indian-stamp-act-1899:sec_33__subsec_2__proviso_1__cl_b": {"cite": "Stamp Act s.33(2)(b)", "head": "", "text": "in the case of a Judge of a High Court, the duty of examining and impounding any instrument under this section may be delegated to such officer as the Court appoints in this behalf."}, "indian-stamp-act-1899:sec_33__subsec_3": {"cite": "Stamp Act s.33(3)", "head": "", "text": "For the purposes of this section, in cases of doubt, — [the [State Government]] may determine what offices shall be deemed to be public offices; and [the [State Government]] may determine who shall be deemed to be persons in charge of public offices."}, "indian-stamp-act-1899:sec_33__subsec_3__cl_a": {"cite": "Stamp Act s.33(3)(a)", "head": "", "text": "[the [State Government]] may determine what offices shall be deemed to be public offices; and"}, "indian-stamp-act-1899:sec_33__subsec_3__cl_b": {"cite": "Stamp Act s.33(3)(b)", "head": "", "text": "[the [State Government]] may determine who shall be deemed to be persons in charge of public offices."}, "indian-stamp-act-1899:sec_34": {"cite": "Stamp Act s.34", "head": "Special provision as to unstamped receipts", "text": "Where any receipt chargeable [with a duty not exceeding ten nayepaise] is tendered to or produced before any officer unstamped in the course of the audit of any public account, such officer may in his discretion, instead of impounding the instrument, require a duly stamped receipt to be substituted therefore."}, "indian-stamp-act-1899:sec_35": {"cite": "Stamp Act s.35", "head": "Instruments not duly stamped inadmissible in evidence, etc", "text": "No instrument chargeable with duty shall be admitted in evidence for any purpose by any person having by law or consent of parties authority to receive evidence, or shall be acted upon, registered or authenticated by any such person or by any public officer, unless such instrument is duly stamped: Provided that— any such instrument [shall] be admitted in evidence on payment of the duty with which the same is chargeable, or, in the case of any instrument insufficiently stamped, of the amount required to make up such duty, together with a penalty of five rupees, or, when ten times the amount of …"}, "indian-stamp-act-1899:sec_35__proviso_1": {"cite": "Stamp Act s.35", "head": "", "text": "Provided that— any such instrument [shall] be admitted in evidence on payment of the duty with which the same is chargeable, or, in the case of any instrument insufficiently stamped, of the amount required to make up such duty, together with a penalty of five rupees, or, when ten times the amount of the proper duty or deficient portion thereof exceeds five rupees, of a sum equal to ten times such duty or portion; 1. Subs. by Act 19 of 1958, s. 5, for “with a duty of one anna” (w.e.f. 1-10-1958). 2. Subs. by Act 21 of 2006, s. 69, for “not being an instrument chargeable with a duty not exceedin…"}, "indian-stamp-act-1899:sec_35__proviso_1__cl_a": {"cite": "Stamp Act s.35(a)", "head": "", "text": "any such instrument [shall] be admitted in evidence on payment of the duty with which the same is chargeable, or, in the case of any instrument insufficiently stamped, of the amount required to make up such duty, together with a penalty of five rupees, or, when ten times the amount of the proper duty or deficient portion thereof exceeds five rupees, of a sum equal to ten times such duty or portion;"}, "indian-stamp-act-1899:sec_35__proviso_1__wrap_1": {"cite": "Stamp Act s.35", "head": "", "text": "1. Subs. by Act 19 of 1958, s. 5, for “with a duty of one anna” (w.e.f. 1-10-1958)."}, "indian-stamp-act-1899:sec_35__proviso_1__wrap_2": {"cite": "Stamp Act s.35", "head": "", "text": "2. Subs. by Act 21 of 2006, s. 69, for “not being an instrument chargeable with a duty not exceeding ten nayepaise only, or a bill of exchange or promissory note, shall, subject to all just exceptions,”"}, "indian-stamp-act-1899:sec_35__proviso_1__cl_b": {"cite": "Stamp Act s.35(b)", "head": "", "text": "where any person from whom a stamped receipt could have been demanded, has given an unstamped receipt and such receipt, if stamped, would be admissible in evidence against him, then such receipt shall be admitted in evidence against him on payment of a penalty of one rupee by the person tendering it;"}, "indian-stamp-act-1899:sec_35__proviso_1__cl_c": {"cite": "Stamp Act s.35(c)", "head": "", "text": "where a contract or agreement of any kind is effected by correspondence consisting of two or more letters and any one of the letters bears the proper stamp, the contract or agreement shall be deemed to be duly stamped;"}, "indian-stamp-act-1899:sec_35__proviso_1__cl_d": {"cite": "Stamp Act s.35(d)", "head": "", "text": "nothing herein contained shall prevent the admission of any instrument in evidence in any proceeding in a Criminal Court, other than a proceeding under Chapter XII or Chapter XXXVI of the Code of Criminal Procedure 1898 (V of 1898);"}, "indian-stamp-act-1899:sec_35__proviso_1__cl_e": {"cite": "Stamp Act s.35(e)", "head": "", "text": "nothing herein contained shall prevent the admission of any instrument in any Court when such instrument has been executed by or on behalf of the Government, or where it bears the certificate of the Collector as provided by section 32 or any other provision of this Act."}, "indian-stamp-act-1899:sec_36": {"cite": "Stamp Act s.36", "head": "Admission of instrument where not to be questioned", "text": "Where an instrument has been admitted in evidence, such admission shall not, except as provided in section 61, be called in question at any stage of the same suit or proceeding on the ground that the instrument has not been duly stamped."}, "indian-stamp-act-1899:sec_37": {"cite": "Stamp Act s.37", "head": "Admission of improperly stamped instruments", "text": "[The [State Government]] may make rules providing that, where an instrument bears a stamp of sufficient amount but of improper description, it may, on payment of the duty with which the same is chargeable, be certified to be duly stamped, and any instrument so certified shall then be deemed to have been duly stamped as from the date of its execution."}, "indian-stamp-act-1899:sec_38": {"cite": "Stamp Act s.38", "head": "Instruments impounded, how dealt with", "text": "When the person impounding an instrument under section 33 has by law or consent of parties authority to receive evidence and admits such instrument in evidence upon payment of a penalty as provided by section 35 or of duty as provided by section 37, he shall send to the Collector an authenticated copy of such instrument, together with a certificate in writing, stating the amount of duty and penalty levied in respect thereof, and shall send such amount to the Collector, or to such person as he may appoint in this behalf. In every other case, the person so impounding an instrument shall send it …"}, "indian-stamp-act-1899:sec_38__subsec_1": {"cite": "Stamp Act s.38(1)", "head": "", "text": "When the person impounding an instrument under section 33 has by law or consent of parties authority to receive evidence and admits such instrument in evidence upon payment of a penalty as provided by section 35 or of duty as provided by section 37, he shall send to the Collector an authenticated copy of such instrument, together with a certificate in writing, stating the amount of duty and penalty levied in respect thereof, and shall send such amount to the Collector, or to such person as he may appoint in this behalf."}, "indian-stamp-act-1899:sec_38__subsec_2": {"cite": "Stamp Act s.38(2)", "head": "", "text": "In every other case, the person so impounding an instrument shall send it in original to the Collector."}, "indian-stamp-act-1899:sec_39": {"cite": "Stamp Act s.39", "head": "Collector’s power to refund penalty paid under section 38, sub-section (1)\n          ", "text": "When a copy of an instrument is sent to the Collector under section 38, sub-section (1), he may, if he thinks fit, *** refund any portion of the penalty in excess of five rupees which has been paid in respect of such instrument. When such instrument has been impounded only because it has been written in contravention of section 13 or section 14, the Collector may refund the whole penalty so paid."}, "indian-stamp-act-1899:sec_39__subsec_1": {"cite": "Stamp Act s.39(1)", "head": "", "text": "When a copy of an instrument is sent to the Collector under section 38, sub-section (1), he may, if he thinks fit, *** refund any portion of the penalty in excess of five rupees which has been paid in respect of such instrument."}, "indian-stamp-act-1899:sec_39__subsec_2": {"cite": "Stamp Act s.39(2)", "head": "", "text": "When such instrument has been impounded only because it has been written in contravention of section 13 or section 14, the Collector may refund the whole penalty so paid."}, "indian-stamp-act-1899:sec_40": {"cite": "Stamp Act s.40", "head": "Collectors power to stamp instruments impounded", "text": "When the Collector impounds any instrument under section 33, or receives any instrument sent to him under section 38, sub-section (2), not being an instrument chargeable [with a duty not exceeding ten naye paise] only or a bill of exchange or promissory note, he shall adopt the following procedure:— if he is of opinion that such instrument is duly stamped, or is not chargeable with duty, he shall certify by endorsement thereon that it is duly stamped, or that it is not so chargeable, as the case may be; if he is of opinion that such instrument is chargeable with duty and is not duly stamped, h…"}, "indian-stamp-act-1899:sec_40__subsec_1": {"cite": "Stamp Act s.40(1)", "head": "", "text": "When the Collector impounds any instrument under section 33, or receives any instrument sent to him under section 38, sub-section (2), not being an instrument chargeable [with a duty not exceeding ten naye paise] only or a bill of exchange or promissory note, he shall adopt the following procedure:— if he is of opinion that such instrument is duly stamped, or is not chargeable with duty, he shall certify by endorsement thereon that it is duly stamped, or that it is not so chargeable, as the case may be; if he is of opinion that such instrument is chargeable with duty and is not duly stamped, h…"}, "indian-stamp-act-1899:sec_40__subsec_1__cl_a": {"cite": "Stamp Act s.40(1)(a)", "head": "", "text": "if he is of opinion that such instrument is duly stamped, or is not chargeable with duty, he shall certify by endorsement thereon that it is duly stamped, or that it is not so chargeable, as the case may be;"}, "indian-stamp-act-1899:sec_40__subsec_1__cl_b": {"cite": "Stamp Act s.40(1)(b)", "head": "", "text": "if he is of opinion that such instrument is chargeable with duty and is not duly stamped, he shall require the payment of the proper duty or the amount required to make up the same, together with a penalty of five rupees; or, if he thinks fit, [an amount not exceeding] ten times the amount of the proper duty or of the deficient portion thereof, whether such amount exceeds or falls short of five rupees: Provided that, when such instrument has been impounded only because it has been written in contravention of section 13 or section 14, the Collector may, if he thinks fit, remit the whole penalty…"}, "indian-stamp-act-1899:sec_40__subsec_1__cl_b__proviso_1": {"cite": "Stamp Act s.40(1)(b)", "head": "", "text": "Provided that, when such instrument has been impounded only because it has been written in contravention of section 13 or section 14, the Collector may, if he thinks fit, remit the whole penalty prescribed by this section."}, "indian-stamp-act-1899:sec_40__subsec_2": {"cite": "Stamp Act s.40(2)", "head": "", "text": "Every certificate under clause (a) of sub-section (1) shall, for the purposes of this Act, be conclusive evidence of the matters stated therein."}, "indian-stamp-act-1899:sec_40__subsec_3": {"cite": "Stamp Act s.40(3)", "head": "", "text": "Where an instrument has been sent to the Collector under section 38, sub-section (2), the Collector shall, when he has dealt with it as provided by this section, return it to the impounding officer."}, "indian-stamp-act-1899:sec_41": {"cite": "Stamp Act s.41", "head": "Instruments unduly stamped by accident", "text": "If any instrument chargeable with duty and not duly stamped, not being an instrument chargeable [with a duty not exceeding ten nayepaise] only or a bill of exchange or promissory note, is produced by any person of his own motion before the Collector within one year from the date of its execution or first execution, and such person brings to the notice of the Collector the fact that such instrument is not duly stamped and offers to pay to the Collector the amount of the proper duty, or the amount required to make up the same, and the Collector is satisfied that the omission to duly stamp such i…"}, "indian-stamp-act-1899:sec_42": {"cite": "Stamp Act s.42", "head": "Endorsement of instruments on which duty has been paid under section 35, 40 or 41\n          ", "text": "When the duty and penalty (if any), leviable in respect of any instrument have been paid under section 35, section 40 or section 41, the person admitting such instrument in evidence or the Collector, as the case may be, shall certify by endorsement thereon that the proper duty or, as the case may be, the proper duty and penalty (stating the amount of each) have been levied in respect thereof, and the name and residence of the person paying them. Every instrument so endorsed shall thereupon be admissible in evidence, and may be registered and acted upon and authenticated as if it had been duly …"}, "indian-stamp-act-1899:sec_42__subsec_1": {"cite": "Stamp Act s.42(1)", "head": "", "text": "When the duty and penalty (if any), leviable in respect of any instrument have been paid under section 35, section 40 or section 41, the person admitting such instrument in evidence or the Collector, as the case may be, shall certify by endorsement thereon that the proper duty or, as the case may be, the proper duty and penalty (stating the amount of each) have been levied in respect thereof, and the name and residence of the person paying them."}, "indian-stamp-act-1899:sec_42__subsec_2": {"cite": "Stamp Act s.42(2)", "head": "", "text": "Every instrument so endorsed shall thereupon be admissible in evidence, and may be registered and acted upon and authenticated as if it had been duly stamped, and shall be delivered on his application in this behalf to the person from whose possession it came into the hands of the officer impounding it, or as such person may direct: Provided that— no instrument which has been admitted in evidence upon payment of duty and a penalty under section 35, shall be so delivered before the expiration of one month from the date of such impounding, or if the Collector has certified that its further deten…"}, "indian-stamp-act-1899:sec_42__subsec_2__proviso_1": {"cite": "Stamp Act s.42(2)", "head": "", "text": "Provided that— no instrument which has been admitted in evidence upon payment of duty and a penalty under section 35, shall be so delivered before the expiration of one month from the date of such impounding, or if the Collector has certified that its further detention is necessary and has not cancelled such certificate; nothing in this section shall affect the Code of Civil Procedure (XIV of 1882), section 144, clause 3."}, "indian-stamp-act-1899:sec_42__subsec_2__proviso_1__cl_a": {"cite": "Stamp Act s.42(2)(a)", "head": "", "text": "no instrument which has been admitted in evidence upon payment of duty and a penalty under section 35, shall be so delivered before the expiration of one month from the date of such impounding, or if the Collector has certified that its further detention is necessary and has not cancelled such certificate;"}, "indian-stamp-act-1899:sec_42__subsec_2__proviso_1__cl_b": {"cite": "Stamp Act s.42(2)(b)", "head": "", "text": "nothing in this section shall affect the Code of Civil Procedure (XIV of 1882), section 144, clause 3."}, "indian-stamp-act-1899:sec_43": {"cite": "Stamp Act s.43", "head": "Prosecution for offence against Stamp-law", "text": "The taking of proceedings or the payment of a penalty under this Chapter in respect of any instrument shall not bar the prosecution of any person who appears to have committed an offence against the Stamp-law in respect of such instrument: Provided that no such prosecution shall be instituted in the case of any instrument in respect of which such a penalty has been paid, unless it appears to the Collector that the offence was committed with an intention of evading payment of the proper duty."}, "indian-stamp-act-1899:sec_43__proviso_1": {"cite": "Stamp Act s.43", "head": "", "text": "Provided that no such prosecution shall be instituted in the case of any instrument in respect of which such a penalty has been paid, unless it appears to the Collector that the offence was committed with an intention of evading payment of the proper duty."}, "indian-stamp-act-1899:sec_44": {"cite": "Stamp Act s.44", "head": "Persons paying duty or penalty may recover same in certain cases", "text": "When any duty or penalty has been paid under section 35, section 37, section 40 or section 41, by any person in respect of an instrument, and, by agreement or under the provisions of section 29 or any other enactment in force at the time such instrument was executed, some other person was bound to bear the expense of providing the proper stamp for such instrument, the first-mentioned person shall be entitled to recover from such other person the amount of the duty or penalty so paid. For the purpose of such recovery, any certificate granted in respect of such instrument under this Act shall be…"}, "indian-stamp-act-1899:sec_44__subsec_1": {"cite": "Stamp Act s.44(1)", "head": "", "text": "When any duty or penalty has been paid under section 35, section 37, section 40 or section 41, by any person in respect of an instrument, and, by agreement or under the provisions of section 29 or any other enactment in force at the time such instrument was executed, some other person was bound to bear the expense of providing the proper stamp for such instrument, the first-mentioned person shall be entitled to recover from such other person the amount of the duty or penalty so paid."}, "indian-stamp-act-1899:sec_44__subsec_2": {"cite": "Stamp Act s.44(2)", "head": "", "text": "For the purpose of such recovery, any certificate granted in respect of such instrument under this Act shall be conclusive evidence of the matters therein certified."}, "indian-stamp-act-1899:sec_44__subsec_3": {"cite": "Stamp Act s.44(3)", "head": "", "text": "Such amount may, if the Court thinks fit, be included in any order as to costs in any suit or proceeding to which such persons are parties and in which such instrument has been tendered in evidence. If the Court does not include the amount in such order, no further proceedings for the recovery of the amount shall be maintainable."}, "indian-stamp-act-1899:sec_45": {"cite": "Stamp Act s.45", "head": "Power to Revenue-authority to refund penalty or excess duty in certain cases", "text": "Where any penalty is paid under section 35 or section 40, the Chief Controlling Revenue-authority may, upon application in writing made within one year from the date of the payment, refund such penalty wholly or in part. Where, in the opinion of the Chief Controlling Revenue-authority, stamp-duty in excess of that which is legally chargeable has been charged and paid under section 35 or section 40, such authority may, upon application in writing made within three months of the order charging the same, refund the excess."}, "indian-stamp-act-1899:sec_45__subsec_1": {"cite": "Stamp Act s.45(1)", "head": "", "text": "Where any penalty is paid under section 35 or section 40, the Chief Controlling Revenue-authority may, upon application in writing made within one year from the date of the payment, refund such penalty wholly or in part."}, "indian-stamp-act-1899:sec_45__subsec_2": {"cite": "Stamp Act s.45(2)", "head": "", "text": "Where, in the opinion of the Chief Controlling Revenue-authority, stamp-duty in excess of that which is legally chargeable has been charged and paid under section 35 or section 40, such authority may, upon application in writing made within three months of the order charging the same, refund the excess."}, "indian-stamp-act-1899:sec_46": {"cite": "Stamp Act s.46", "head": "Non-liability for loss of instruments sent under section 38\n          ", "text": "If any instrument sent to the Collector under section 38, sub-section (2), is lost, destroyed or damaged during transmission, the person sending the same shall not be liable for such loss, destruction or damage. When any instrument is about to be so sent, the person from whose possession it came into the hands of the person impounding the same, may require a copy thereof to be made at the expense of such first-mentioned person and authenticated by the person impounding such instrument."}, "indian-stamp-act-1899:sec_46__subsec_1": {"cite": "Stamp Act s.46(1)", "head": "", "text": "If any instrument sent to the Collector under section 38, sub-section (2), is lost, destroyed or damaged during transmission, the person sending the same shall not be liable for such loss, destruction or damage."}, "indian-stamp-act-1899:sec_46__subsec_2": {"cite": "Stamp Act s.46(2)", "head": "", "text": "When any instrument is about to be so sent, the person from whose possession it came into the hands of the person impounding the same, may require a copy thereof to be made at the expense of such first-mentioned person and authenticated by the person impounding such instrument."}, "indian-stamp-act-1899:sec_47": {"cite": "Stamp Act s.47", "head": "Power of payer to stamp bills, and promissory notes received by him unstamped", "text": "When any bill of exchange [or promissory note] chargeable [with a duty not exceeding ten nayepaise] is presented for payment unstamped, the person to whom it is so presented, may affix thereto the necessary adhesive stamp, and, upon cancelling the same in manner hereinbefore provided, may pay the sum payable upon such bill [or note], and may charge the duty against the person who ought to have paid the same, or deduct it from the sum payable as aforesaid, and such bill [or note], shall, so far as respects the duty, be deemed good and valid: Provided that nothing herein contained shall relieve …"}, "indian-stamp-act-1899:sec_47__proviso_1": {"cite": "Stamp Act s.47", "head": "", "text": "Provided that nothing herein contained shall relieve any person from any penalty or proceeding to which he may be liable in relation to such bill, [or note]."}, "indian-stamp-act-1899:sec_48": {"cite": "Stamp Act s.48", "head": "Recovery of duties and penalties", "text": "All duties, penalties and other sums required to be paid under this Chapter may be recovered by the Collector by distress and sale of the movable property of the person from whom the same are due, or by any other process for the time being in force for the recovery of arrears of land-revenue."}, "indian-stamp-act-1899:chp_V": {"cite": "Stamp Act Chapter V", "head": "ALLOWANCES FOR STAMPS IN CERTAIN CASES", "text": "Allowance for spoiled stamps Subject to such rules as may be made by [the [State Government]] as to the evidence to be required, or the enquiry to be made, the Collector may, on application made within the period prescribed in section 50, and if he is satisfied as to the facts, make allowance for impressed stamps spoiled in the cases herein after mentioned, namely:— the stamp on any paper inadvertently and undesignedly spoiled, obliterated or by error in writing or any other means rendered unfit for the purpose intended before any instrument written thereon is executed by any person: the stamp…"}, "indian-stamp-act-1899:sec_49": {"cite": "Stamp Act s.49", "head": "Allowance for spoiled stamps", "text": "Subject to such rules as may be made by [the [State Government]] as to the evidence to be required, or the enquiry to be made, the Collector may, on application made within the period prescribed in section 50, and if he is satisfied as to the facts, make allowance for impressed stamps spoiled in the cases herein after mentioned, namely:— the stamp on any paper inadvertently and undesignedly spoiled, obliterated or by error in writing or any other means rendered unfit for the purpose intended before any instrument written thereon is executed by any person: the stamp on any document which is wri…"}, "indian-stamp-act-1899:sec_49__cl_a": {"cite": "Stamp Act s.49(a)", "head": "", "text": "the stamp on any paper inadvertently and undesignedly spoiled, obliterated or by error in writing or any other means rendered unfit for the purpose intended before any instrument written thereon is executed by any person:"}, "indian-stamp-act-1899:sec_49__cl_b": {"cite": "Stamp Act s.49(b)", "head": "", "text": "the stamp on any document which is written out wholly or in part, but which is not signed or executed by any party thereto:"}, "indian-stamp-act-1899:sec_49__cl_c": {"cite": "Stamp Act s.49(c)", "head": "", "text": "in the case of bills of exchange [payable otherwise than on demand] *** or promissory notes— the stamp on [any such bill of exchange] *** signed by or on behalf of the drawer which has not been accepted or made use of in any manner whatever or delivered out of his hands for any purpose other than by way of tender for acceptance: provided that the paper on which any such stamp is impressed, does not bear any signature intended as or for the acceptance of any bill of exchange *** to be afterwards written thereon: 1. Subs. by the A.O. 1937, for “the L.G.”. 2. Subs. by the A.O. 1950, for “collecti…"}, "indian-stamp-act-1899:sec_49__cl_c__subsec_1": {"cite": "Stamp Act s.49(c)(1)", "head": "", "text": "the stamp on [any such bill of exchange] *** signed by or on behalf of the drawer which has not been accepted or made use of in any manner whatever or delivered out of his hands for any purpose other than by way of tender for acceptance: provided that the paper on which any such stamp is impressed, does not bear any signature intended as or for the acceptance of any bill of exchange *** to be afterwards written thereon:"}, "indian-stamp-act-1899:sec_49__cl_c__wrap_1": {"cite": "Stamp Act s.49(c)", "head": "", "text": "1. Subs. by the A.O. 1937, for “the L.G.”."}, "indian-stamp-act-1899:sec_49__cl_c__wrap_2": {"cite": "Stamp Act s.49(c)", "head": "", "text": "2. Subs. by the A.O. 1950, for “collecting Government”."}, "indian-stamp-act-1899:sec_49__cl_c__subsec_2": {"cite": "Stamp Act s.49(c)(2)", "head": "", "text": "the stamp on any promissory note signed by or on behalf of the maker which has not been made use of in any manner whatever or delivered out of his hands:"}, "indian-stamp-act-1899:sec_49__cl_c__subsec_3": {"cite": "Stamp Act s.49(c)(3)", "head": "", "text": "the stamp used or intended to be used for [any such bill of exchange] *** or promissory note signed by, or on behalf of, the drawer thereof, but which from any omission or error has been spoiled or rendered useless, although the same, being a bill of exchange *** may have been presented for acceptance or accepted or endorsed, or, being a promissory note, may have been delivered to the payee: provided that another completed and duly stamped bill of exchange *** or promissory note is produced identical in every particular, except in the correction of such omission or error as aforesaid, with the…"}, "indian-stamp-act-1899:sec_49__cl_d": {"cite": "Stamp Act s.49(d)", "head": "", "text": "the stamp used for an instrument executed by any party thereto which— has been afterwards found to be absolutely void in law from the beginning: has been afterwards found unfit, by reason of any error or mistake therein, for the purpose originally intended: by reason of the death of any person by whom it is necessary that it should be executed, without having executed the same, or of the refusal of any such person to execute the same, cannot be completed so as to effect the intended transaction in the form proposed: for want of the execution thereof by some material party, and his inability or…"}, "indian-stamp-act-1899:sec_49__cl_d__subsec_1": {"cite": "Stamp Act s.49(d)(1)", "head": "", "text": "has been afterwards found to be absolutely void in law from the beginning:"}, "indian-stamp-act-1899:sec_49__cl_d__subsec_2": {"cite": "Stamp Act s.49(d)(2)", "head": "", "text": "has been afterwards found unfit, by reason of any error or mistake therein, for the purpose originally intended:"}, "indian-stamp-act-1899:sec_49__cl_d__subsec_3": {"cite": "Stamp Act s.49(d)(3)", "head": "", "text": "by reason of the death of any person by whom it is necessary that it should be executed, without having executed the same, or of the refusal of any such person to execute the same, cannot be completed so as to effect the intended transaction in the form proposed:"}, "indian-stamp-act-1899:sec_49__cl_d__subsec_4": {"cite": "Stamp Act s.49(d)(4)", "head": "", "text": "for want of the execution thereof by some material party, and his inability or refusal to sign the same, is in fact incomplete and insufficient for the purpose for which it was intended:"}, "indian-stamp-act-1899:sec_49__cl_d__subsec_5": {"cite": "Stamp Act s.49(d)(5)", "head": "", "text": "by reason of the refusal of any person to act under the same, or to advance any money intended to be thereby secured, or by the refusal or non-acceptance of any office thereby granted, totally fails of the intended purpose:"}, "indian-stamp-act-1899:sec_49__cl_d__subsec_6": {"cite": "Stamp Act s.49(d)(6)", "head": "", "text": "becomes useless in consequence of the transaction intended to be thereby effected being effected by some other instrument between the same parties and bearing a stamp of not less value:"}, "indian-stamp-act-1899:sec_49__cl_d__subsec_7": {"cite": "Stamp Act s.49(d)(7)", "head": "", "text": "is deficient in value and the transaction intended to be thereby effected has been effected by some other instrument between the same parties and bearing a stamp of not less value:"}, "indian-stamp-act-1899:sec_49__cl_d__subsec_8": {"cite": "Stamp Act s.49(d)(8)", "head": "", "text": "is inadvertently and undesignedly spoiled, and in lieu whereof another instrument made between the same parties and for the same purpose is executed and duly stamped:"}, "indian-stamp-act-1899:sec_49__cl_d__proviso_1": {"cite": "Stamp Act s.49(d)", "head": "", "text": "Provided that, in the case of an executed instrument, no legal proceeding has been commenced in which the instrument could or would have been given or offered in evidence and that the instrument is given up to be cancelled."}, "indian-stamp-act-1899:sec_49__hcontainer_1": {"cite": "Stamp Act s.49", "head": "", "text": "The certificate of the Collector under section 32 that the full duty with which an instrument is chargeable, has been paid is an impressed stamp within the meaning of this section."}, "indian-stamp-act-1899:sec_50": {"cite": "Stamp Act s.50", "head": "Application for relief under section 49 when to be made", "text": "The application for relief under section 49 shall be made within the following periods, that is to say,— in the cases mentioned in clause (d) (5), within two months of the date of the instrument: in the case of a stamped paper on which no instrument has been executed by any of the parties thereto, within six months after the stamp has been spoiled: 1 Subs. by Act 5 of 1927, s. 5, for “any bill of exchange”. 2. The word “cheque” omitted by s. 5, ibid. in the case of a stamped paper in which an instrument has been executed by any of the parties thereto, within six months after the date of the in…"}, "indian-stamp-act-1899:sec_50__subsec_1": {"cite": "Stamp Act s.50(1)", "head": "", "text": "in the cases mentioned in clause (d) (5), within two months of the date of the instrument:"}, "indian-stamp-act-1899:sec_50__subsec_2": {"cite": "Stamp Act s.50(2)", "head": "", "text": "in the case of a stamped paper on which no instrument has been executed by any of the parties thereto, within six months after the stamp has been spoiled:"}, "indian-stamp-act-1899:sec_50__wrap_1": {"cite": "Stamp Act s.50", "head": "", "text": "1 Subs. by Act 5 of 1927, s. 5, for “any bill of exchange”."}, "indian-stamp-act-1899:sec_50__wrap_2": {"cite": "Stamp Act s.50", "head": "", "text": "2. The word “cheque” omitted by s. 5, ibid."}, "indian-stamp-act-1899:sec_50__subsec_3": {"cite": "Stamp Act s.50(3)", "head": "", "text": "in the case of a stamped paper in which an instrument has been executed by any of the parties thereto, within six months after the date of the instrument, or, if it is not dated, within six months after the execution thereof by the person by whom it was first or alone executed:"}, "indian-stamp-act-1899:sec_50__proviso_1": {"cite": "Stamp Act s.50", "head": "", "text": "Provided that,— when the spoiled instrument has been for sufficient reasons sent out of [India], the application may be made within six months after it has been received back in [India]; when, from unavoidable circumstances, any instrument for which another instrument has been substituted, cannot be given up to be cancelled within the aforesaid period, the application may be made within six months after the date of execution of the substituted instrument."}, "indian-stamp-act-1899:sec_50__proviso_1__cl_a": {"cite": "Stamp Act s.50(a)", "head": "", "text": "when the spoiled instrument has been for sufficient reasons sent out of [India], the application may be made within six months after it has been received back in [India];"}, "indian-stamp-act-1899:sec_50__proviso_1__cl_b": {"cite": "Stamp Act s.50(b)", "head": "", "text": "when, from unavoidable circumstances, any instrument for which another instrument has been substituted, cannot be given up to be cancelled within the aforesaid period, the application may be made within six months after the date of execution of the substituted instrument."}, "indian-stamp-act-1899:sec_51": {"cite": "Stamp Act s.51", "head": "Allowance in case of printed forms no longer required by Corporations", "text": "The Chief Controlling Revenue-authority [or the Collector if empowered by the Chief Controlling Revenue-authority in this behalf] may, without limit of time, make allowance for stamped papers used for printed forms of instruments [by any banker or] by any incorporated company or other body corporate, if for any sufficient reason such forms have ceased to be required by the said [banker], company or body corporate: provided that such authority is satisfied that the duty in respect of such stamped papers has been duly paid."}, "indian-stamp-act-1899:sec_52": {"cite": "Stamp Act s.52", "head": "Allowance for misused stamps", "text": "When any person has inadvertently used for an instrument chargeable with duty, a stamp of a description other than that prescribed for such instrument by the rules made under this Act, or a stamp of greater value than was necessary, or has inadvertently used any stamp for an instrument not chargeable with any duty; or when any stamp used for an instrument has been inadvertently rendered useless under section 15, owing to such instrument having been written in contravention of the provisions of section 13; the Collector may, on application made within six months after the date of the instrument…"}, "indian-stamp-act-1899:sec_52__cl_a": {"cite": "Stamp Act s.52(a)", "head": "", "text": "When any person has inadvertently used for an instrument chargeable with duty, a stamp of a description other than that prescribed for such instrument by the rules made under this Act, or a stamp of greater value than was necessary, or has inadvertently used any stamp for an instrument not chargeable with any duty; or"}, "indian-stamp-act-1899:sec_52__cl_b": {"cite": "Stamp Act s.52(b)", "head": "", "text": "when any stamp used for an instrument has been inadvertently rendered useless under section 15, owing to such instrument having been written in contravention of the provisions of section 13;"}, "indian-stamp-act-1899:sec_53": {"cite": "Stamp Act s.53", "head": "Allowance for spoiled or misused stamps how to be made", "text": "In any case in which allowance is made for spoiled or misused stamps, the Collector may give in lieu thereof — other stamps of the same description and value; or if required and he thinks fit, stamps of any other description to the same amount in value; or at his discretion, the same value in money, deducting [ten nayepaise] for each rupee or fraction of a rupee."}, "indian-stamp-act-1899:sec_53__cl_a": {"cite": "Stamp Act s.53(a)", "head": "", "text": "other stamps of the same description and value; or"}, "indian-stamp-act-1899:sec_53__cl_b": {"cite": "Stamp Act s.53(b)", "head": "", "text": "if required and he thinks fit, stamps of any other description to the same amount in value; or"}, "indian-stamp-act-1899:sec_53__cl_c": {"cite": "Stamp Act s.53(c)", "head": "", "text": "at his discretion, the same value in money, deducting [ten nayepaise] for each rupee or fraction of a rupee."}, "indian-stamp-act-1899:sec_54": {"cite": "Stamp Act s.54", "head": "Allowance for stamps not required for use", "text": "When any person is possessed of a stamp or stamps which have not been spoiled or rendered unfit or useless for the purpose intended, but for which he has no immediate use, the Collector shall repay to such person the value of such stamp or stamps in money, deducting [ten nayepaise] for each rupee or portion of a rupee, upon such person delivering up the same to be cancelled, and proving to the Collector's satisfaction— 1. Subs. by Act 43 of 1955, s. 2, for “the States” (w.e.f. 1-4-1956). that such stamp or stamps were purchased by such person with a bona fide intention to use them; and that he…"}, "indian-stamp-act-1899:sec_54__cl_a": {"cite": "Stamp Act s.54(a)", "head": "", "text": "that such stamp or stamps were purchased by such person with a bona fide intention to use them; and"}, "indian-stamp-act-1899:sec_54__cl_b": {"cite": "Stamp Act s.54(b)", "head": "", "text": "that he has paid the full price thereof; and"}, "indian-stamp-act-1899:sec_54__cl_c": {"cite": "Stamp Act s.54(c)", "head": "", "text": "that they were so purchased within the period of six months next preceding the date on which they were so delivered:"}, "indian-stamp-act-1899:sec_54__proviso_1": {"cite": "Stamp Act s.54", "head": "", "text": "Provided that, where the person is a licensed vendor of stamps, the Collector may, if he thinks fit, make the repayment of the sum actually paid by the vendor without any such deduction as aforesaid."}, "indian-stamp-act-1899:sec_54A": {"cite": "Stamp Act s.54A", "head": "Allowances for stamps in denominations of annas", "text": "Notwithstanding anything contained in section 54, when any person is possessed of a stamp or stamps in any denominations, other than in denominations of annas four of multiples thereof and such stamp or stamps has or have not been spoiled, the Collector shall repay to such person the value of such stamp or stamps in money calculated in accordance with the provisions of sub-section (2) of section 14 of the Indian Coinage Act, 1906, (3 of 1906) upon such person delivering up, within six months from the commencement of the Indian Stamp (Amendment) Act,1958 (19 of 1958), such stamp or stamps to th…"}, "indian-stamp-act-1899:sec_54B": {"cite": "Stamp Act s.54B", "head": "Allowances for Refugee Relief Stamps", "text": "Notwithstanding anything contained in section 54, when any person is possessed of stamps bearing the inscription “Refugee Relief” (being stamps issued in pursuance of section 3A before its omission) and such stamps have not been spoiled, the Collector shall, upon such person delivering up, within six-month, from the commencement of the Refugee Relief Taxes (Abolition) Act, 1973 (13 of 1973), such stamps to the Collector, refund to such person the value of such stamps in money or give in lieu thereof other stamps of the same value: Provided that the State Government may, with a view to facilita…"}, "indian-stamp-act-1899:sec_54B__proviso_1": {"cite": "Stamp Act s.54B", "head": "", "text": "Provided that the State Government may, with a view to facilitating expeditious disposal of claims for such refunds, specify, in such manner as it deems fit, any other procedure which may also be followed for claiming such refunds.]"}, "indian-stamp-act-1899:sec_55": {"cite": "Stamp Act s.55", "head": "Allowance on renewal of certain debentures", "text": "When any duly stamped debenture is renewed by the issue of a new debenture in the same terms, the Collector shall, upon application made within one month, repay to the person issuing such debenture, the value of the stamp on the original or on the new debenture, whichever shall be less: Provided that the original debenture is produced before the Collector and cancelled by him in such manner as [the State Government] may direct. A debenture shall be deemed to be renewed in the same terms within the meaning of this section notwithstanding the following changes:— the issue of two or more debentur…"}, "indian-stamp-act-1899:sec_55__proviso_1": {"cite": "Stamp Act s.55", "head": "", "text": "Provided that the original debenture is produced before the Collector and cancelled by him in such manner as [the State Government] may direct."}, "indian-stamp-act-1899:sec_55__hcontainer_1": {"cite": "Stamp Act s.55", "head": "", "text": "A debenture shall be deemed to be renewed in the same terms within the meaning of this section notwithstanding the following changes:— the issue of two or more debentures in place of one original debenture, the total amount secured being the same; the issue of one debenture in place of two or more original debentures, the total amount secured being the same; the substitution of the name of the holder at the time of renewal for the name of the original holder; and the alteration of the rate of interest or the dates of payment thereof."}, "indian-stamp-act-1899:sec_55__hcontainer_1__cl_a": {"cite": "Stamp Act s.55(a)", "head": "", "text": "the issue of two or more debentures in place of one original debenture, the total amount secured being the same;"}, "indian-stamp-act-1899:sec_55__hcontainer_1__cl_b": {"cite": "Stamp Act s.55(b)", "head": "", "text": "the issue of one debenture in place of two or more original debentures, the total amount secured being the same;"}, "indian-stamp-act-1899:sec_55__hcontainer_1__cl_c": {"cite": "Stamp Act s.55(c)", "head": "", "text": "the substitution of the name of the holder at the time of renewal for the name of the original holder; and"}, "indian-stamp-act-1899:sec_55__hcontainer_1__cl_d": {"cite": "Stamp Act s.55(d)", "head": "", "text": "the alteration of the rate of interest or the dates of payment thereof."}, "indian-stamp-act-1899:chp_VI": {"cite": "Stamp Act Chapter VI", "head": "REFERENCE AND REVISION", "text": "Control of, and statement of case to, Chief Controlling Revenue-authority The powers exercisable by a Collector under Chapter IV and Chapter V [and under clause (a) of the first proviso to section 26] shall in all cases be subject to the control of the Chief Controlling Revenue-authority. If any Collector, acting under section 31, section 40 or section 41, feels doubt as to the amount of duty with which any instrument is chargeable, he may draw up a statement of the case, and refer it, with his own opinion thereon, for the decision of the Chief Controlling Revenue-authority. Such authority sha…"}, "indian-stamp-act-1899:sec_56": {"cite": "Stamp Act s.56", "head": "Control of, and statement of case to, Chief Controlling Revenue-authority", "text": "The powers exercisable by a Collector under Chapter IV and Chapter V [and under clause (a) of the first proviso to section 26] shall in all cases be subject to the control of the Chief Controlling Revenue-authority. If any Collector, acting under section 31, section 40 or section 41, feels doubt as to the amount of duty with which any instrument is chargeable, he may draw up a statement of the case, and refer it, with his own opinion thereon, for the decision of the Chief Controlling Revenue-authority. Such authority shall consider the case and send a copy of its decision to the Collector, who…"}, "indian-stamp-act-1899:sec_56__subsec_1": {"cite": "Stamp Act s.56(1)", "head": "", "text": "The powers exercisable by a Collector under Chapter IV and Chapter V [and under clause (a) of the first proviso to section 26] shall in all cases be subject to the control of the Chief Controlling Revenue-authority."}, "indian-stamp-act-1899:sec_56__subsec_2": {"cite": "Stamp Act s.56(2)", "head": "", "text": "If any Collector, acting under section 31, section 40 or section 41, feels doubt as to the amount of duty with which any instrument is chargeable, he may draw up a statement of the case, and refer it, with his own opinion thereon, for the decision of the Chief Controlling Revenue-authority."}, "indian-stamp-act-1899:sec_56__subsec_3": {"cite": "Stamp Act s.56(3)", "head": "", "text": "Such authority shall consider the case and send a copy of its decision to the Collector, who shall proceed to asses and charge the duty (if any) in conformity with such decision."}, "indian-stamp-act-1899:sec_57": {"cite": "Stamp Act s.57", "head": "Statement of case by Chief-Controlling Revenue-authority to High Court", "text": "The Chief Controlling Revenue-authority may state any case referred to it under section 56, sub-section (2), or otherwise coming to its notice, and refer such case, with its own opinion thereon,— [if it arises in a State, to the High Court for that State; [if it arises in the Union territory of the Delhi, to the High Court of Delhi;] * * * * * [if it arises in the Union territory of the Arunachal Pradesh or Mizoram, to the Gauhati High Court (the High Court of Assam, Nagaland, Meghalaya, Manipur and Tripura;)] if it arises in the Union territory of the Andaman and Nicobar Islands, to the High …"}, "indian-stamp-act-1899:sec_57__subsec_1": {"cite": "Stamp Act s.57(1)", "head": "", "text": "The Chief Controlling Revenue-authority may state any case referred to it under section 56, sub-section (2), or otherwise coming to its notice, and refer such case, with its own opinion thereon,— [if it arises in a State, to the High Court for that State; [if it arises in the Union territory of the Delhi, to the High Court of Delhi;] * * * * * [if it arises in the Union territory of the Arunachal Pradesh or Mizoram, to the Gauhati High Court (the High Court of Assam, Nagaland, Meghalaya, Manipur and Tripura;)] if it arises in the Union territory of the Andaman and Nicobar Islands, to the High …"}, "indian-stamp-act-1899:sec_57__subsec_1__cl_a": {"cite": "Stamp Act s.57(1)(a)", "head": "", "text": "[if it arises in a State, to the High Court for that State;"}, "indian-stamp-act-1899:sec_57__subsec_1__cl_b": {"cite": "Stamp Act s.57(1)(b)", "head": "", "text": "[if it arises in the Union territory of the Delhi, to the High Court of Delhi;] * * * * *"}, "indian-stamp-act-1899:sec_57__subsec_1__cl_c": {"cite": "Stamp Act s.57(1)(c)", "head": "", "text": "[if it arises in the Union territory of the Arunachal Pradesh or Mizoram, to the Gauhati High Court (the High Court of Assam, Nagaland, Meghalaya, Manipur and Tripura;)]"}, "indian-stamp-act-1899:sec_57__subsec_1__cl_d": {"cite": "Stamp Act s.57(1)(d)", "head": "", "text": "if it arises in the Union territory of the Andaman and Nicobar Islands, to the High Court at Calcutta;"}, "indian-stamp-act-1899:sec_57__subsec_1__cl_e": {"cite": "Stamp Act s.57(1)(e)", "head": "", "text": "if it arises in the Union territory of the [Lakshadweep], to the High Court of Kerala;] [(ee) if it arises in the Union territory of the Chandigarh, to the High Court of Punjab and Haryana;]"}, "indian-stamp-act-1899:sec_57__subsec_1__cl_f": {"cite": "Stamp Act s.57(1)(f)", "head": "", "text": "[if it arises in the Union territory of Dadra and Nagar Haveli, to the High Court of Bombay.]"}, "indian-stamp-act-1899:sec_57__subsec_2": {"cite": "Stamp Act s.57(2)", "head": "", "text": "Every such case shall be decided by not less than three Judges of the High Court *** to which it is referred, and in case of difference the opinion of the majority shall prevail."}, "indian-stamp-act-1899:sec_58": {"cite": "Stamp Act s.58", "head": "Power of High Court to call for further particulars as to case stated", "text": "If the High Court *** is not satisfied that the statements contained in the case are sufficient to enable it to determine the questions raised thereby, the Court may refer the case back to the Revenue-authority by which it was stated, to make such additions thereto or alterations therein as the Court may direct in that behalf."}, "indian-stamp-act-1899:sec_59": {"cite": "Stamp Act s.59", "head": "Procedure in disposing of case stated", "text": "The High Court, *** upon the hearing of any such case, shall decide the questions raised thereby, and shall deliver its judgment thereon containing the grounds on which such decision is founded. The Court shall send to the Revenue-authority by which the case was stated, a copy of such judgment under the seal of the Court and the signature of the Registrar; and the Revenue-authority shall, on receiving such copy, dispose of the case conformably to such judgment."}, "indian-stamp-act-1899:sec_59__subsec_1": {"cite": "Stamp Act s.59(1)", "head": "", "text": "The High Court, *** upon the hearing of any such case, shall decide the questions raised thereby, and shall deliver its judgment thereon containing the grounds on which such decision is founded."}, "indian-stamp-act-1899:sec_59__subsec_2": {"cite": "Stamp Act s.59(2)", "head": "", "text": "The Court shall send to the Revenue-authority by which the case was stated, a copy of such judgment under the seal of the Court and the signature of the Registrar; and the Revenue-authority shall, on receiving such copy, dispose of the case conformably to such judgment."}, "indian-stamp-act-1899:sec_60": {"cite": "Stamp Act s.60", "head": "Statement of case by other Courts to High Court", "text": "If any Court, other than a Court mentioned in section 57, feels doubt as to the amount of duty to be paid in respect of any instrument under proviso (a) to section 35, the Judge may draw up a statement of the case and refer it, with his own opinion thereon, for the decision of the High Court *** to which, if he were the Chief Controlling Revenue-authority, he would, under section 57, refer the same. Such Court shall deal with the case as if it had been referred under section 57, and send a copy of its judgment under the seal of the Court and the signature of the Registrar to the Chief Controll…"}, "indian-stamp-act-1899:sec_60__subsec_1": {"cite": "Stamp Act s.60(1)", "head": "", "text": "If any Court, other than a Court mentioned in section 57, feels doubt as to the amount of duty to be paid in respect of any instrument under proviso (a) to section 35, the Judge may draw up a statement of the case and refer it, with his own opinion thereon, for the decision of the High Court *** to which, if he were the Chief Controlling Revenue-authority, he would, under section 57, refer the same."}, "indian-stamp-act-1899:sec_60__subsec_2": {"cite": "Stamp Act s.60(2)", "head": "", "text": "Such Court shall deal with the case as if it had been referred under section 57, and send a copy of its judgment under the seal of the Court and the signature of the Registrar to the Chief Controlling Revenue-authority and another like copy to the Judge making the reference, who shall, on receiving such copy, dispose of the case conformably to such judgment."}, "indian-stamp-act-1899:sec_60__subsec_3": {"cite": "Stamp Act s.60(3)", "head": "", "text": "References made under sub-section (1), when made by a Court subordinate to a District Court, shall be made through the District Court, and, when made by any subordinate Revenue Court, shall be made through the Court immediately superior."}, "indian-stamp-act-1899:sec_61": {"cite": "Stamp Act s.61", "head": "Revision of certain decisions of Courts regarding the sufficiency of stamps", "text": "When any Court in the exercise of its civil or revenue jurisdiction or any Criminal Court in any proceeding under Chapter XII or Chapter XXXVI of the Code of Criminal Procedure, 1898 (V of 1898), makes any order admitting any instrument in evidence as duly stamped or as not requiring a stamp, or upon payment of duty and a penalty under section 35, the Court to which appeals lie from, or references are made by, such first-mentioned Court may, of its own motion or on the application of the Collector, take such order into consideration. If such Court, after such consideration, is of opinion that …"}, "indian-stamp-act-1899:sec_61__subsec_1": {"cite": "Stamp Act s.61(1)", "head": "", "text": "When any Court in the exercise of its civil or revenue jurisdiction or any Criminal Court in any proceeding under Chapter XII or Chapter XXXVI of the Code of Criminal Procedure, 1898 (V of 1898), makes any order admitting any instrument in evidence as duly stamped or as not requiring a stamp, or upon payment of duty and a penalty under section 35, the Court to which appeals lie from, or references are made by, such first-mentioned Court may, of its own motion or on the application of the Collector, take such order into consideration."}, "indian-stamp-act-1899:sec_61__subsec_2": {"cite": "Stamp Act s.61(2)", "head": "", "text": "If such Court, after such consideration, is of opinion that such instrument should not have been admitted in evidence without the payment of duty and penalty under section 35, or without the payment of a higher duty and penalty than those paid, it may record a declaration to that effect, and determine the amount of duty with which such instrument is chargeable, and may require any person in whose possession or power such instrument then is, to produce the same, and may impound the same when produced."}, "indian-stamp-act-1899:sec_61__subsec_3": {"cite": "Stamp Act s.61(3)", "head": "", "text": "When any declaration has been recorded under sub-section (2), the Court recording the same shall send a copy thereof to the Collector, and, where the instrument to which it relates has been impounded or is otherwise in the possession of such Court, shall also send him such instrument."}, "indian-stamp-act-1899:sec_61__subsec_4": {"cite": "Stamp Act s.61(4)", "head": "", "text": "The Collector may thereupon, notwithstanding anything contained in the order admitting such instrument in evidence, or in any certificate granted under section 42, or in section 43, prosecute any person for any offence against the Stamp-law which the Collector considers him to have committed in respect of such instrument:"}, "indian-stamp-act-1899:proviso_1": {"cite": "Stamp Act proviso_1", "head": "", "text": "Provided that, –– no such prosecution shall be instituted where the amount (including duty and penalty) which, according to the determination of such Court, was payable in respect of the instrument under section 35, is paid to the Collector, unless he thinks that the offence was committed with an intention of evading payment of the proper duty; except for the purposes of such prosecution, no declaration made under this section shall affect the validity of any order admitting any instrument in evidence, or of any certificate granted under section 42."}, "indian-stamp-act-1899:proviso_1__cl_a": {"cite": "Stamp Act (a)", "head": "", "text": "no such prosecution shall be instituted where the amount (including duty and penalty) which, according to the determination of such Court, was payable in respect of the instrument under section 35, is paid to the Collector, unless he thinks that the offence was committed with an intention of evading payment of the proper duty;"}, "indian-stamp-act-1899:proviso_1__cl_b": {"cite": "Stamp Act (b)", "head": "", "text": "except for the purposes of such prosecution, no declaration made under this section shall affect the validity of any order admitting any instrument in evidence, or of any certificate granted under section 42."}, "indian-stamp-act-1899:chp_VII": {"cite": "Stamp Act Chapter VII", "head": "CRIMINAL OFFENCES AND PROCEDURE", "text": "Penalty for executing, etc., instrument not duly stamped Any person–– drawing, making, issuing, endorsing or transferring, or signing otherwise than as a witness, or presenting for acceptance or payment, or accepting, paying or receiving payment of, or in any manner negotiating, any bill of exchange [payable otherwise than on demand] *** or promissory note without the same being duly stamped; or executing or signing otherwise than as a witness any other instrument chargeable with duty without the same being duly stamped; or voting or attempting to vote under any proxy not duly stamped, shall f…"}, "indian-stamp-act-1899:sec_62": {"cite": "Stamp Act s.62", "head": "Penalty for executing, etc., instrument not duly stamped", "text": "Any person–– drawing, making, issuing, endorsing or transferring, or signing otherwise than as a witness, or presenting for acceptance or payment, or accepting, paying or receiving payment of, or in any manner negotiating, any bill of exchange [payable otherwise than on demand] *** or promissory note without the same being duly stamped; or executing or signing otherwise than as a witness any other instrument chargeable with duty without the same being duly stamped; or voting or attempting to vote under any proxy not duly stamped, shall for every such offence be punishable with fine which may e…"}, "indian-stamp-act-1899:sec_62__subsec_1": {"cite": "Stamp Act s.62(1)", "head": "", "text": "Any person–– drawing, making, issuing, endorsing or transferring, or signing otherwise than as a witness, or presenting for acceptance or payment, or accepting, paying or receiving payment of, or in any manner negotiating, any bill of exchange [payable otherwise than on demand] *** or promissory note without the same being duly stamped; or executing or signing otherwise than as a witness any other instrument chargeable with duty without the same being duly stamped; or voting or attempting to vote under any proxy not duly stamped, shall for every such offence be punishable with fine which may e…"}, "indian-stamp-act-1899:sec_62__subsec_1__cl_a": {"cite": "Stamp Act s.62(1)(a)", "head": "", "text": "drawing, making, issuing, endorsing or transferring, or signing otherwise than as a witness, or presenting for acceptance or payment, or accepting, paying or receiving payment of, or in any manner negotiating, any bill of exchange [payable otherwise than on demand] *** or promissory note without the same being duly stamped; or"}, "indian-stamp-act-1899:sec_62__subsec_1__cl_b": {"cite": "Stamp Act s.62(1)(b)", "head": "", "text": "executing or signing otherwise than as a witness any other instrument chargeable with duty without the same being duly stamped; or"}, "indian-stamp-act-1899:sec_62__subsec_1__cl_c": {"cite": "Stamp Act s.62(1)(c)", "head": "", "text": "voting or attempting to vote under any proxy not duly stamped,"}, "indian-stamp-act-1899:sec_62__subsec_1__wrap_1": {"cite": "Stamp Act s.62(1)", "head": "", "text": "shall for every such offence be punishable with fine which may extend to five hundred rupees:"}, "indian-stamp-act-1899:sec_62__subsec_1__proviso_1": {"cite": "Stamp Act s.62(1)", "head": "", "text": "Provided that, when any penalty has been paid in respect of any instrument under section 35, section 40 or section 61, the amount of such penalty shall be allowed in reduction of the fine, (if any) subsequently imposed under this section in respect of the same instrument upon the person who paid such penalty."}, "indian-stamp-act-1899:sec_62__subsec_2": {"cite": "Stamp Act s.62(2)", "head": "", "text": "If a share-warrant is issued without being duly stamped, the company issuing the same, and also every person who, at the time when it is issued, is the managing director or secretary or other principal officer of the company, shall be punishable with fine which may extend to five hundred rupees."}, "indian-stamp-act-1899:sec_62A": {"cite": "Stamp Act s.62A", "head": "Penalty for failure to comply with provisions of section 9A\n          ", "text": "[Any person who,–– being required under sub-section (1) of section 9A to collect duty, fails to collect the same; or being required under sub-section (4) of section 9A to transfer the duty to the State Government within fifteen days of the expiry of the time specified therein, fails to transfer within such time, shall be punishable with fine which shall not be less than one lakh rupees, but which may extend up to one per cent. of the collection or transfer so defaulted. Any person who,— being required under sub-section (5) of section 9A to submit details of transactions to the Government, fail…"}, "indian-stamp-act-1899:sec_62A__subsec_1": {"cite": "Stamp Act s.62A(1)", "head": "", "text": "[Any person who,–– being required under sub-section (1) of section 9A to collect duty, fails to collect the same; or being required under sub-section (4) of section 9A to transfer the duty to the State Government within fifteen days of the expiry of the time specified therein, fails to transfer within such time, shall be punishable with fine which shall not be less than one lakh rupees, but which may extend up to one per cent. of the collection or transfer so defaulted."}, "indian-stamp-act-1899:sec_62A__subsec_1__cl_a": {"cite": "Stamp Act s.62A(1)(a)", "head": "", "text": "being required under sub-section (1) of section 9A to collect duty, fails to collect the same; or"}, "indian-stamp-act-1899:sec_62A__subsec_1__cl_b": {"cite": "Stamp Act s.62A(1)(b)", "head": "", "text": "being required under sub-section (4) of section 9A to transfer the duty to the State Government within fifteen days of the expiry of the time specified therein, fails to transfer within such time,"}, "indian-stamp-act-1899:sec_62A__subsec_2": {"cite": "Stamp Act s.62A(2)", "head": "", "text": "Any person who,— being required under sub-section (5) of section 9A to submit details of transactions to the Government, fails to submit the same; or submits a document or makes a declaration which is false or which such person knows or believes to be false, shall be punishable with fine of one lakh rupees for each day during which such failure continues or one crore rupees, whichever is less.] Uttar Pradesh Amendment of section 62.— In section 62 of the principal Act, in sub-section (1), for the words, “shall, for every such offence, be punishable with fine which may extend to five hundred ru…"}, "indian-stamp-act-1899:sec_62A__subsec_2__cl_a": {"cite": "Stamp Act s.62A(2)(a)", "head": "", "text": "being required under sub-section (5) of section 9A to submit details of transactions to the Government, fails to submit the same; or"}, "indian-stamp-act-1899:sec_62A__subsec_2__cl_b": {"cite": "Stamp Act s.62A(2)(b)", "head": "", "text": "submits a document or makes a declaration which is false or which such person knows or believes to be false,"}, "indian-stamp-act-1899:sec_63": {"cite": "Stamp Act s.63", "head": "Penalty for failure to cancel adhesive stamp", "text": "Any person required by section 12 to cancel an adhesive stamp, and failing to cancel such stamp in manner prescribed by that section, shall be punishable with fine which may extend to one hundred rupees."}, "indian-stamp-act-1899:sec_64": {"cite": "Stamp Act s.64", "head": "Penalty for omission to comply with provisions of section 27\n          ", "text": "Any person who, with intent to defraud the Government,–– executes any instrument in which all the facts and circumstances required by section 27 to be set forth in such instrument are not fully and truly set forth; or being employed or concerned in or about the preparation of any instrument, neglects or omits fully and truly to set forth therein all such facts and circumstances; or does any other act calculated to deprive the Government of any duty or penalty under this Act; shall be punishable with fine which may extend to five thousand rupees."}, "indian-stamp-act-1899:sec_64__cl_a": {"cite": "Stamp Act s.64(a)", "head": "", "text": "executes any instrument in which all the facts and circumstances required by section 27 to be set forth in such instrument are not fully and truly set forth; or"}, "indian-stamp-act-1899:sec_64__cl_b": {"cite": "Stamp Act s.64(b)", "head": "", "text": "being employed or concerned in or about the preparation of any instrument, neglects or omits fully and truly to set forth therein all such facts and circumstances; or"}, "indian-stamp-act-1899:sec_64__cl_c": {"cite": "Stamp Act s.64(c)", "head": "", "text": "does any other act calculated to deprive the Government of any duty or penalty under this Act;"}, "indian-stamp-act-1899:sec_65": {"cite": "Stamp Act s.65", "head": "Penalty for refusal to give receipt, and for devices to evade duty on receipts", "text": "Any person who,–– being required under section 30 to give a receipt, refuses or neglects to give the same; or, with intent to defraud the Government of any duty, upon a payment of money or delivery of property exceeding twenty rupees in amount or value, gives a receipt for an amount or value not exceeding twenty rupees, or separates or divides the money or property paid or delivered; shall be punishable with fine which may extend to one hundred rupees."}, "indian-stamp-act-1899:sec_65__cl_a": {"cite": "Stamp Act s.65(a)", "head": "", "text": "being required under section 30 to give a receipt, refuses or neglects to give the same; or,"}, "indian-stamp-act-1899:sec_65__cl_b": {"cite": "Stamp Act s.65(b)", "head": "", "text": "with intent to defraud the Government of any duty, upon a payment of money or delivery of property exceeding twenty rupees in amount or value, gives a receipt for an amount or value not exceeding twenty rupees, or separates or divides the money or property paid or delivered;"}, "indian-stamp-act-1899:sec_66": {"cite": "Stamp Act s.66", "head": "Penalty for not making out policy or making one not duly stamped", "text": "Any person who–– receives, or takes credit for, any premium or consideration for any contract of insurance and does not, within one month after receiving, or taking credit for, such premium or consideration, make out and execute a duly stamped policy of such insurance; or makes, executes or delivers out any policy which is not duly stamped, or pays or allows in account, or agrees to pay or allow in account, any money upon, or in respect of, any such policy; shall be punishable with fine which may extend to two hundred rupees. Arunachal Pradesh Amendment of sections 66,-In section 66, in clause…"}, "indian-stamp-act-1899:sec_66__cl_a": {"cite": "Stamp Act s.66(a)", "head": "", "text": "receives, or takes credit for, any premium or consideration for any contract of insurance and does not, within one month after receiving, or taking credit for, such premium or consideration, make out and execute a duly stamped policy of such insurance; or"}, "indian-stamp-act-1899:sec_66__cl_b": {"cite": "Stamp Act s.66(b)", "head": "", "text": "makes, executes or delivers out any policy which is not duly stamped, or pays or allows in account, or agrees to pay or allow in account, any money upon, or in respect of, any such policy;"}, "indian-stamp-act-1899:sec_67": {"cite": "Stamp Act s.67", "head": "Penalty for not drawing full number of bills or marine policies purporting to be in sets", "text": "Any person drawing or executing a bill of exchange [payable otherwise than on demand] or a policy of marine insurance purporting to be drawn or executed in a set of two or more, and not at the same time drawing or executing on paper duly stamped the whole number of bills or policies of which such bill or policy purports the set to consist, shall be punishable with fine which may extend to one thousand rupees. Arunachal Pradesh Amendment of sections 67,-In section 67, for the words “one thousand rupees” the words “two thousand rupees” shall be substituted. [Vide Arunachal Pradesh 3 of 2010, s. …"}, "indian-stamp-act-1899:sec_68": {"cite": "Stamp Act s.68", "head": "Penalty for post-dating bills, and for other devices to defraud the revenue", "text": "Any person who, –– with intent to defraud the Government of duty, draws, makes or issues any bill of exchange or promissory note bearing a date subsequent to that on which such bill or note is actually drawn or made; or, knowing that such bill or note has been so post-dated, endorses, transfers, presents for acceptance or payment, or accepts, pays or receives payment of, such bill or note, or in any manner negotiate the same; or, with the like intent, practices or is concerned in any act, contrivance or device not specially provided for by this Act or any other law for the time being in force;…"}, "indian-stamp-act-1899:sec_68__cl_a": {"cite": "Stamp Act s.68(a)", "head": "", "text": "with intent to defraud the Government of duty, draws, makes or issues any bill of exchange or promissory note bearing a date subsequent to that on which such bill or note is actually drawn or made; or,"}, "indian-stamp-act-1899:sec_68__cl_b": {"cite": "Stamp Act s.68(b)", "head": "", "text": "knowing that such bill or note has been so post-dated, endorses, transfers, presents for acceptance or payment, or accepts, pays or receives payment of, such bill or note, or in any manner negotiate the same; or,"}, "indian-stamp-act-1899:sec_68__cl_c": {"cite": "Stamp Act s.68(c)", "head": "", "text": "with the like intent, practices or is concerned in any act, contrivance or device not specially provided for by this Act or any other law for the time being in force;"}, "indian-stamp-act-1899:sec_69": {"cite": "Stamp Act s.69", "head": "Penalty for breach of rule relating to sale of stamps and for unauthorised sale", "text": "Any person appointed to sell stamps who disobeys any rule made under section 74; and any person not so appointed who sells or offers for sale any stamp (other than a [ten naye paise or five nayepaise] adhesive stamp); shall be punishable with imprisonment for a term which may extend to six months, or with fine which may extend to five hundred rupees, or with both."}, "indian-stamp-act-1899:sec_69__cl_a": {"cite": "Stamp Act s.69(a)", "head": "", "text": "Any person appointed to sell stamps who disobeys any rule made under section 74; and"}, "indian-stamp-act-1899:sec_69__cl_b": {"cite": "Stamp Act s.69(b)", "head": "", "text": "any person not so appointed who sells or offers for sale any stamp (other than a [ten naye paise or five nayepaise] adhesive stamp);"}, "indian-stamp-act-1899:sec_70": {"cite": "Stamp Act s.70", "head": "Institution and conduct of prosecutions", "text": "No prosecution in respect of any offence punishable under this Act or any Act hereby repealed, shall be instituted without the sanction of the Collector or such other officer as [the [State Government]] generally, or the Collector specially, authorizes in that behalf. The Chief Controlling Revenue-authority, or any officer generally or specially authorized by it in this behalf, may stay any such prosecution or compound any such offence. The amount of any such composition shall be recoverable in the manner provided by section 48."}, "indian-stamp-act-1899:sec_70__subsec_1": {"cite": "Stamp Act s.70(1)", "head": "", "text": "No prosecution in respect of any offence punishable under this Act or any Act hereby repealed, shall be instituted without the sanction of the Collector or such other officer as [the [State Government]] generally, or the Collector specially, authorizes in that behalf."}, "indian-stamp-act-1899:sec_70__subsec_2": {"cite": "Stamp Act s.70(2)", "head": "", "text": "The Chief Controlling Revenue-authority, or any officer generally or specially authorized by it in this behalf, may stay any such prosecution or compound any such offence."}, "indian-stamp-act-1899:sec_70__subsec_3": {"cite": "Stamp Act s.70(3)", "head": "", "text": "The amount of any such composition shall be recoverable in the manner provided by section 48."}, "indian-stamp-act-1899:sec_71": {"cite": "Stamp Act s.71", "head": "Jurisdiction of Magistrate", "text": "No Magistrate other than a Presidency Magistrate or a Magistrate whose powers are not less than those of a Magistrate of the second class, shall try any offence under this Act."}, "indian-stamp-act-1899:sec_72": {"cite": "Stamp Act s.72", "head": "Place of trial", "text": "Every such offence committed in respect of any instrument may be tried in any district or presidency-town in which such instrument is found, as well as in any district or presidency-town in which such offence might be tried under the Code of Criminal Procedure for the time being in force."}, "indian-stamp-act-1899:chp_VIII": {"cite": "Stamp Act Chapter VIII", "head": "SUPPLEMENTAL PROVISIONS", "text": "Books, etc., to be open to inspection Every public officer having in his custody any registers, books, records, papers, documents or proceedings, the inspection whereof may tend to secure any duty, or to prove or lead to the discovery of any fraud or omission in relation to any duty, shall at all reasonable 1. Subs. by Act 19 of 1958, s. 10, for “one anna or half an anna” (w.e.f. 1-10-1958). 2. Subs. by the A.O. 1937, for “the L.G.”. 3. Subs. by the A.O. 1950, for “collecting Government”. times permit any person authorized in writing by the Collector to inspect for such purpose the registers, …"}, "indian-stamp-act-1899:sec_73": {"cite": "Stamp Act s.73", "head": "Books, etc., to be open to inspection", "text": "Every public officer having in his custody any registers, books, records, papers, documents or proceedings, the inspection whereof may tend to secure any duty, or to prove or lead to the discovery of any fraud or omission in relation to any duty, shall at all reasonable 1. Subs. by Act 19 of 1958, s. 10, for “one anna or half an anna” (w.e.f. 1-10-1958). 2. Subs. by the A.O. 1937, for “the L.G.”. 3. Subs. by the A.O. 1950, for “collecting Government”. times permit any person authorized in writing by the Collector to inspect for such purpose the registers, books, papers, documents and proceedin…"}, "indian-stamp-act-1899:sec_73__subsec_2": {"cite": "Stamp Act s.73(2)", "head": "", "text": "Without prejudice to the generality of the provisions of sub-section (1), the Central Government may make rules for all or any of the following matters, namely:–– the manner of collection of stamp-duty on behalf of the State Government by the stock exchange or the clearing corporation authorised by it, from its buyer under clause (a) of sub-section (1) of section 9A; the manner of collection of stamp-duty on behalf of the State Government by the depository from the transferor under clause (b) of sub-section (1) of section 9A; the manner of collection of stamp-duty on behalf of the State Govern…"}, "indian-stamp-act-1899:sec_73__subsec_2__cl_a": {"cite": "Stamp Act s.73(2)(a)", "head": "", "text": "the manner of collection of stamp-duty on behalf of the State Government by the stock exchange or the clearing corporation authorised by it, from its buyer under clause (a) of sub-section (1) of section 9A;"}, "indian-stamp-act-1899:sec_73__subsec_2__cl_b": {"cite": "Stamp Act s.73(2)(b)", "head": "", "text": "the manner of collection of stamp-duty on behalf of the State Government by the depository from the transferor under clause (b) of sub-section (1) of section 9A;"}, "indian-stamp-act-1899:sec_73__subsec_2__cl_c": {"cite": "Stamp Act s.73(2)(c)", "head": "", "text": "the manner of collection of stamp-duty on behalf of the State Government by the depository from the issuer under clause (c) of sub-section (1) of section 9A;"}, "indian-stamp-act-1899:sec_73__subsec_2__cl_d": {"cite": "Stamp Act s.73(2)(d)", "head": "", "text": "the manner of transfer of stamp-duty to the State Government under sub-section (4) of section 9A;"}, "indian-stamp-act-1899:sec_73__subsec_2__cl_e": {"cite": "Stamp Act s.73(2)(e)", "head": "", "text": "any other matter which has to be, or may be, provided by rules.] [73B. Power to issue directions and to authorise certain authorities to issue instructions, etc.––The Central Government may,–– issue directions relating to such matters and subject to such conditions, as it deems necessary; in writing, authorise the Securities and Exchange Board of India established under section 3 of the Securities and Exchange Board of India Act, 1992 (15 of 1992) or the Reserve Bank of India constituted under section 3 of the Reserve Bank of India Act, 1934 (2 of 1934) to issue instructions, circulars or guid…"}, "indian-stamp-act-1899:sec_73__subsec_2__cl_e__cl_a": {"cite": "Stamp Act s.73(2)(e)(a)", "head": "", "text": "issue directions relating to such matters and subject to such conditions, as it deems necessary;"}, "indian-stamp-act-1899:sec_73__subsec_2__cl_e__cl_b": {"cite": "Stamp Act s.73(2)(e)(b)", "head": "", "text": "in writing, authorise the Securities and Exchange Board of India established under section 3 of the Securities and Exchange Board of India Act, 1992 (15 of 1992) or the Reserve Bank of India constituted under section 3 of the Reserve Bank of India Act, 1934 (2 of 1934) to issue instructions, circulars or guidelines,"}, "indian-stamp-act-1899:sec_74": {"cite": "Stamp Act s.74", "head": "Powers to make rules relating to sale of stamps", "text": "The [State Government] *** may make rules for regulating–– the supply and sale of stamps an stamped papers, the persons by whom alone such sale is to be conducted, and the duties and remuneration of such persons: Provided that such rules shall not restrict the sale of [ten nayepaise or five nayapaise] adhesive stamps."}, "indian-stamp-act-1899:sec_74__cl_a": {"cite": "Stamp Act s.74(a)", "head": "", "text": "the supply and sale of stamps an stamped papers,"}, "indian-stamp-act-1899:sec_74__cl_b": {"cite": "Stamp Act s.74(b)", "head": "", "text": "the persons by whom alone such sale is to be conducted, and"}, "indian-stamp-act-1899:sec_74__cl_c": {"cite": "Stamp Act s.74(c)", "head": "", "text": "the duties and remuneration of such persons:"}, "indian-stamp-act-1899:sec_74__proviso_1": {"cite": "Stamp Act s.74", "head": "", "text": "Provided that such rules shall not restrict the sale of [ten nayepaise or five nayapaise] adhesive stamps."}, "indian-stamp-act-1899:sec_75": {"cite": "Stamp Act s.75", "head": "Power to make rules generally to carry out Act", "text": "The [State Government] may make rules to carry out generally the purposes of this Act, and may by such rules prescribe the fines, which shall in no case exceed five hundred rupees, to be incurred on breach thereof."}, "indian-stamp-act-1899:sec_76": {"cite": "Stamp Act s.76", "head": "Publication of rules", "text": "[All rules made under this Act shall be published in the Official Gazette.] All rules published as required by this section shall, upon such publication, have effect as if enacted by this Act. [Every rule made by the Central Government under this Act shall be laid, as soon as may be after it is made, before each House of Parliament, while it is in session, for a total period of thirty days which may be comprised in one session or in two or more successive sessions, and if, before the expiry of the session immediately following the session or the successive sessions aforesaid, both Houses agree…"}, "indian-stamp-act-1899:sec_76__subsec_1": {"cite": "Stamp Act s.76(1)", "head": "", "text": "[All rules made under this Act shall be published in the Official Gazette.]"}, "indian-stamp-act-1899:sec_76__subsec_2": {"cite": "Stamp Act s.76(2)", "head": "", "text": "All rules published as required by this section shall, upon such publication, have effect as if enacted by this Act."}, "indian-stamp-act-1899:sec_76__subsec_2A": {"cite": "Stamp Act s.76(2A)", "head": "", "text": "[Every rule made by the Central Government under this Act shall be laid, as soon as may be after it is made, before each House of Parliament, while it is in session, for a total period of thirty days which may be comprised in one session or in two or more successive sessions, and if, before the expiry of the session immediately following the session or the successive sessions aforesaid, both Houses agree in making any modification in the rule or both Houses agree that the rule should not be made, the rule shall thereafter have effect only in such modified form or be of no effect, as the case m…"}, "indian-stamp-act-1899:sec_76__subsec_3": {"cite": "Stamp Act s.76(3)", "head": "", "text": "[Every rule made by the State Government under this Act shall be laid, as soon as may be after it is made, before the State Legislature.]"}, "indian-stamp-act-1899:sec_76A": {"cite": "Stamp Act s.76A", "head": "Delegation of certain powers", "text": "[ *** The State Government may, by notification in the Official Gazette], delegate–– all or any of the powers conferred on it by sections 2(9), 33(3), (b), 70(1), 74 and 78 to the Chief Controlling Revenue-authority; and all or any of the powers conferred on the Chief Controlling Revenue-authority by sections 45 (1), (2), 56 (1) and 70 (2) to such subordinate Revenue-authority as may be specified in the notification.]"}, "indian-stamp-act-1899:sec_76A__cl_a": {"cite": "Stamp Act s.76A(a)", "head": "", "text": "all or any of the powers conferred on it by sections 2(9), 33(3), (b), 70(1), 74 and 78 to the Chief Controlling Revenue-authority; and"}, "indian-stamp-act-1899:sec_76A__cl_b": {"cite": "Stamp Act s.76A(b)", "head": "", "text": "all or any of the powers conferred on the Chief Controlling Revenue-authority by sections 45 (1), (2), 56 (1) and 70 (2) to such subordinate Revenue-authority as may be specified in the notification.]"}, "indian-stamp-act-1899:sec_77": {"cite": "Stamp Act s.77", "head": "Saving as to court-fees", "text": "Nothing in this Act contained shall be deemed to affect the duties chargeable under any enactment for the time being in force relating to court-fee."}, "indian-stamp-act-1899:sec_77A": {"cite": "Stamp Act s.77A", "head": "Saving as to certain stamps", "text": "All stamps in denominations of annas four or multiples thereof shall be deemed to be stamps of the value of twenty-five nayepaise or, as the case may be, multiples thereof and shall, accordingly, be valid for all the purposes of this Act.]"}, "indian-stamp-act-1899:sec_78": {"cite": "Stamp Act s.78", "head": "Act to be translated, and sold cheaply", "text": "Every State Government shall make provision for the sale of translations of this Act in the principal vernacular languages of the territories administered by it at a price not exceeding [twenty-five nayepaise] per copy."}, "indian-stamp-act-1899:sec_79": {"cite": "Stamp Act s.79", "head": "", "text": "[Repealed.] Rep. by the Repealing and Amending Act, 1914 (10 of 1914) s. 3 and Schedule II. 1. Subs. by Act 19 of 1958, s. 12, “four annas” (w.e.f. 1-10-1958)."}}, "today": "2026-10-29", "files": {"dpdp-act-2023": "data/dpdp-act-2023.xml", "dpdp-rules-2025": "data/dpdp-rules-2025.xml", "it-act-2000": "data/it-act-2000.xml", "it-rules-2021": "data/it-rules-2021.xml", "it-intermediaries-rules-2011": "data/it-intermediaries-rules-2011.xml", "it-spdi-rules-2011": "data/it-spdi-rules-2011.xml", "indian-stamp-act-1899": "data/indian-stamp-act-1899.xml"}};
